// Fragen fürs Forscher-Quiz. Nicht von Hand ändern: Vorlage in tools/quiz/*.json,
// neu erzeugen mit: python3 tools/make_quiz_bank.py
import { Lang } from './i18n';

export type BankText = { q: string; a: string[]; x: string; k: string }; // k: Kurz-Fakt für „Das hast du heute gelernt“
export type BankQuestion = {
  id: string;
  lvl: 1 | 2 | 3; // 1 mittel, 2 schwer, 3 sehr schwer
  type: 'text' | 'tf' | 'pic' | 'duel' | 'rank'; // pic: ein großes Bild, duel: zwei gegeneinander, rank: Rangliste
  right: number; // rank: immer 10123 (richtige Reihenfolge)
  img?: string[]; // pic: Bild aus QuizArt
  t: Record<Lang, BankText>;
};

export const BANK: BankQuestion[] = [
  { id: "f01", lvl: 3, type: "duel", right: 0, t: { de: { q: "Wer hält hohes Tempo länger durch?", a: ["Gabelbock", "Gepard"], x: "Der Gepard ist zwar schneller, sprintet aber nur wenige hundert Meter. Der Gabelbock hält über 50 km/h kilometerweit durch.", k: "Gabelbock: läuft kilometerweit über 50 km/h" }, en: { q: "Who can keep up a high speed for longer?", a: ["Pronghorn", "Cheetah"], x: "The cheetah is faster but only sprints a few hundred metres. The pronghorn can keep up over 50 km/h for kilometres.", k: "Pronghorn: runs over 50 km/h for kilometres" }, fr: { q: "Qui tient une grande vitesse le plus longtemps ?", a: ["Antilope d’Amérique", "Guépard"], x: "Le guépard est plus rapide, mais ne sprinte que quelques centaines de mètres. L’antilope d’Amérique tient plus de 50 km/h sur des kilomètres.", k: "Antilope d’Amérique : plus de 50 km/h sur des km" }, es: { q: "¿Quién aguanta más tiempo a gran velocidad?", a: ["Berrendo", "Guepardo"], x: "El guepardo es más rápido, pero solo esprinta unos cientos de metros. El berrendo mantiene más de 50 km/h durante kilómetros.", k: "Berrendo: más de 50 km/h durante kilómetros" }, pt: { q: "Quem aguenta mais tempo em alta velocidade?", a: ["Antilocapra", "Guepardo"], x: "O guepardo é mais rápido, mas só dispara por algumas centenas de metros. A antilocapra mantém mais de 50 km/h por quilômetros.", k: "Antilocapra: mais de 50 km/h por quilômetros" }, ja: { q: "速いスピードを長く続けられるのはどっち？", a: ["プロングホーン", "チーター"], x: "チーターのほうが速いですが、全力で走れるのは数百メートルだけ。プロングホーンは時速50キロ以上で何キロも走り続けられます。", k: "プロングホーン：時速50キロで何キロも走る" }, it: { q: "Chi riesce a mantenere a lungo un’alta velocità?", a: ["Antilocapra", "Ghepardo"], x: "Il ghepardo è più veloce, ma scatta solo per poche centinaia di metri. L’antilocapra tiene oltre 50 km/h per chilometri.", k: "Antilocapra: oltre 50 km/h per chilometri" } } },
  { id: "f02", lvl: 2, type: "duel", right: 0, t: { de: { q: "Wer ist das größte Raubtier an Land?", a: ["Eisbär", "Sibirischer Tiger"], x: "Eisbär-Männchen wiegen 400 bis 700 kg und sind damit die größten Landraubtiere. Sibirische Tiger erreichen etwa 300 kg.", k: "Eisbär: größtes Raubtier an Land" }, en: { q: "Who is the largest land carnivore?", a: ["Polar bear", "Siberian tiger"], x: "Male polar bears weigh 400 to 700 kg, making them the largest land carnivores. Siberian tigers reach about 300 kg.", k: "Polar bear: largest land carnivore" }, fr: { q: "Qui est le plus grand carnivore terrestre ?", a: ["Ours polaire", "Tigre de Sibérie"], x: "L’ours polaire mâle pèse 400 à 700 kg : c’est le plus grand carnivore terrestre. Le tigre de Sibérie atteint environ 300 kg.", k: "Ours polaire : plus grand carnivore terrestre" }, es: { q: "¿Quién es el mayor carnívoro terrestre?", a: ["Oso polar", "Tigre siberiano"], x: "El oso polar macho pesa de 400 a 700 kg y es el mayor carnívoro terrestre. El tigre siberiano llega a unos 300 kg.", k: "Oso polar: mayor carnívoro terrestre" }, pt: { q: "Quem é o maior carnívoro terrestre?", a: ["Urso-polar", "Tigre-siberiano"], x: "O urso-polar macho pesa de 400 a 700 kg e é o maior carnívoro terrestre. O tigre-siberiano chega a uns 300 kg.", k: "Urso-polar: maior carnívoro terrestre" }, ja: { q: "陸上で最大の肉食動物はどっち？", a: ["ホッキョクグマ", "アムールトラ"], x: "オスのホッキョクグマは400〜700キロ。陸上最大の肉食動物です。アムールトラは約300キロです。", k: "ホッキョクグマ：陸上最大の肉食動物" }, it: { q: "Chi è il più grande carnivoro terrestre?", a: ["Orso polare", "Tigre siberiana"], x: "I maschi di orso polare pesano 400–700 kg: sono i più grandi carnivori terrestri. Le tigri siberiane arrivano a circa 300 kg.", k: "Orso polare: il più grande carnivoro terrestre" } } },
  { id: "f03", lvl: 3, type: "duel", right: 1, t: { de: { q: "Wer ist näher mit dem Hund verwandt?", a: ["Tüpfelhyäne", "Seehund"], x: "Robben gehören zu den „hundeartigen“ Raubtieren, wie Bären und Marder. Hyänen sehen zwar hundeähnlich aus, sind aber näher mit Katzen verwandt.", k: "Hyänen: näher mit Katzen als mit Hunden verwandt" }, en: { q: "Who is more closely related to the dog?", a: ["Spotted hyena", "Harbour seal"], x: "Seals belong to the “dog-like” carnivores, along with bears and weasels. Hyenas look like dogs but are more closely related to cats.", k: "Hyenas: closer to cats than to dogs" }, fr: { q: "Qui est le plus proche parent du chien ?", a: ["Hyène tachetée", "Phoque veau-marin"], x: "Les phoques font partie des carnivores « caniformes », comme les ours et les martres. La hyène ressemble à un chien mais est plus proche des chats.", k: "Hyènes : plus proches des chats que des chiens" }, es: { q: "¿Quién es pariente más cercano del perro?", a: ["Hiena manchada", "Foca común"], x: "Las focas pertenecen a los carnívoros «caniformes», como osos y mustélidos. La hiena parece un perro, pero está más emparentada con los gatos.", k: "Hienas: más cerca de los gatos que de los perros" }, pt: { q: "Quem é parente mais próximo do cachorro?", a: ["Hiena-malhada", "Foca-comum"], x: "As focas pertencem aos carnívoros “caniformes”, como ursos e mustelídeos. A hiena parece um cachorro, mas é mais aparentada com os gatos.", k: "Hienas: mais perto dos gatos que dos cachorros" }, ja: { q: "イヌに近い親せきはどっち？", a: ["ブチハイエナ", "ゼニガタアザラシ"], x: "アザラシはクマやイタチと同じ「イヌ型」の肉食動物です。ハイエナはイヌに似ていますが、ネコに近い親せきです。", k: "ハイエナ：イヌよりネコに近い" }, it: { q: "Chi è più vicino parente del cane?", a: ["Iena maculata", "Foca comune"], x: "Le foche appartengono ai carnivori «simili al cane», insieme a orsi e mustelidi. Le iene sembrano cani, ma sono più vicine ai gatti.", k: "Iene: più vicine ai gatti che ai cani" } } },
  { id: "f04", lvl: 1, type: "duel", right: 1, t: { de: { q: "Wer kann rückwärts fliegen?", a: ["Spatz", "Kolibri"], x: "Kolibris schlagen ihre Flügel bis zu 80-mal pro Sekunde in Achterform. So können sie in der Luft stehen und sogar rückwärts fliegen.", k: "Kolibri: kann rückwärts fliegen" }, en: { q: "Who can fly backwards?", a: ["Sparrow", "Hummingbird"], x: "Hummingbirds beat their wings up to 80 times a second in a figure of eight. That lets them hover and even fly backwards.", k: "Hummingbird: can fly backwards" }, fr: { q: "Qui peut voler en arrière ?", a: ["Moineau", "Colibri"], x: "Le colibri bat des ailes jusqu’à 80 fois par seconde en forme de huit. Il peut ainsi faire du sur-place et même voler en arrière.", k: "Colibri : vole en arrière" }, es: { q: "¿Quién puede volar hacia atrás?", a: ["Gorrión", "Colibrí"], x: "El colibrí bate las alas hasta 80 veces por segundo en forma de ocho. Así puede quedarse quieto en el aire e incluso volar hacia atrás.", k: "Colibrí: vuela hacia atrás" }, pt: { q: "Quem consegue voar para trás?", a: ["Pardal", "Beija-flor"], x: "O beija-flor bate as asas até 80 vezes por segundo, num movimento em forma de oito. Assim ele para no ar e até voa para trás.", k: "Beija-flor: voa para trás" }, ja: { q: "後ろ向きに飛べるのはどっち？", a: ["スズメ", "ハチドリ"], x: "ハチドリは1秒に最大80回、8の字に羽ばたきます。だから空中で止まったり、後ろ向きに飛んだりできます。", k: "ハチドリ：後ろ向きに飛べる" }, it: { q: "Chi sa volare all’indietro?", a: ["Passero", "Colibrì"], x: "I colibrì battono le ali fino a 80 volte al secondo disegnando un otto. Così restano sospesi in aria e volano persino all’indietro.", k: "Colibrì: vola all’indietro" } } },
  { id: "f05", lvl: 3, type: "duel", right: 1, t: { de: { q: "Wer ist näher mit dem Pferd verwandt?", a: ["Kuh", "Nashorn"], x: "Pferde, Nashörner und Tapire sind Unpaarhufer. Kühe sind Paarhufer – und damit näher mit Walen verwandt als mit Pferden.", k: "Kühe: näher mit Walen als mit Pferden verwandt" }, en: { q: "Who is more closely related to the horse?", a: ["Cow", "Rhino"], x: "Horses, rhinos and tapirs are odd-toed ungulates. Cows are even-toed – and so more closely related to whales than to horses.", k: "Cows: closer to whales than to horses" }, fr: { q: "Qui est le plus proche parent du cheval ?", a: ["Vache", "Rhinocéros"], x: "Chevaux, rhinocéros et tapirs sont des périssodactyles. La vache est un artiodactyle – plus proche des baleines que du cheval.", k: "Vaches : plus proches des baleines que des chevaux" }, es: { q: "¿Quién es pariente más cercano del caballo?", a: ["Vaca", "Rinoceronte"], x: "Caballos, rinocerontes y tapires son perisodáctilos. La vaca es un artiodáctilo, más emparentada con las ballenas que con el caballo.", k: "Vacas: más cerca de las ballenas que de los caballos" }, pt: { q: "Quem é parente mais próximo do cavalo?", a: ["Vaca", "Rinoceronte"], x: "Cavalos, rinocerontes e antas são perissodáctilos. A vaca é um artiodáctilo, mais aparentada com as baleias do que com o cavalo.", k: "Vacas: mais perto das baleias que dos cavalos" }, ja: { q: "ウマに近い親せきはどっち？", a: ["ウシ", "サイ"], x: "ウマ、サイ、バクは奇蹄類です。ウシは偶蹄類で、ウマよりクジラのほうに近い親せきです。", k: "ウシ：ウマよりクジラに近い" }, it: { q: "Chi è più vicino parente del cavallo?", a: ["Mucca", "Rinoceronte"], x: "Cavalli, rinoceronti e tapiri sono perissodattili. Le mucche sono artiodattili, e quindi più vicine alle balene che ai cavalli.", k: "Mucche: più vicine alle balene che ai cavalli" } } },
  { id: "f06", lvl: 2, type: "duel", right: 1, t: { de: { q: "Wer hat mehr Knochen?", a: ["Ein Erwachsener", "Ein Neugeborenes"], x: "Babys kommen mit rund 300 Knochen zur Welt. Viele davon wachsen später zusammen – Erwachsene haben 206.", k: "Babys: haben rund 300 Knochen, Erwachsene 206" }, en: { q: "Who has more bones?", a: ["An adult", "A newborn baby"], x: "Babies are born with around 300 bones. Many of them fuse later – adults have 206.", k: "Babies: about 300 bones, adults 206" }, fr: { q: "Qui a le plus d’os ?", a: ["Un adulte", "Un nouveau-né"], x: "Le bébé naît avec environ 300 os. Beaucoup se soudent ensuite – l’adulte en a 206.", k: "Bébés : environ 300 os, adultes 206" }, es: { q: "¿Quién tiene más huesos?", a: ["Un adulto", "Un recién nacido"], x: "Los bebés nacen con unos 300 huesos. Muchos se fusionan después: un adulto tiene 206.", k: "Bebés: unos 300 huesos, adultos 206" }, pt: { q: "Quem tem mais ossos?", a: ["Um adulto", "Um recém-nascido"], x: "Os bebês nascem com cerca de 300 ossos. Muitos se fundem depois: um adulto tem 206.", k: "Bebês: uns 300 ossos, adultos 206" }, ja: { q: "骨の数が多いのはどっち？", a: ["大人", "生まれたての赤ちゃん"], x: "赤ちゃんは約300個の骨をもって生まれます。その多くがあとでくっつき、大人は206個になります。", k: "赤ちゃん：骨は約300個、大人は206個" }, it: { q: "Chi ha più ossa?", a: ["Un adulto", "Un neonato"], x: "I neonati nascono con circa 300 ossa. Molte si saldano in seguito: gli adulti ne hanno 206.", k: "Neonati: circa 300 ossa, adulti 206" } } },
  { id: "f07", lvl: 3, type: "duel", right: 1, t: { de: { q: "Wer kommt länger ohne zu trinken aus?", a: ["Dromedar", "Kängururatte"], x: "Die Kängururatte aus den Wüsten Nordamerikas trinkt oft ihr ganzes Leben lang nicht – sie gewinnt Wasser aus trockenen Samen. Dromedare halten etwa zwei Wochen durch.", k: "Kängururatte: trinkt oft ihr Leben lang nicht" }, en: { q: "Who can go longer without drinking?", a: ["Dromedary camel", "Kangaroo rat"], x: "The kangaroo rat of North American deserts often never drinks in its whole life – it gets water from dry seeds. Camels last about two weeks.", k: "Kangaroo rat: often never drinks in its life" }, fr: { q: "Qui tient le plus longtemps sans boire ?", a: ["Dromadaire", "Rat-kangourou"], x: "Le rat-kangourou des déserts d’Amérique du Nord ne boit souvent jamais de sa vie : il tire l’eau des graines sèches. Le dromadaire tient environ deux semaines.", k: "Rat-kangourou : souvent ne boit jamais" }, es: { q: "¿Quién aguanta más sin beber?", a: ["Dromedario", "Rata canguro"], x: "La rata canguro de los desiertos de Norteamérica a menudo no bebe en toda su vida: saca el agua de semillas secas. El dromedario aguanta unas dos semanas.", k: "Rata canguro: a menudo nunca bebe" }, pt: { q: "Quem aguenta mais tempo sem beber?", a: ["Dromedário", "Rato-canguru"], x: "O rato-canguru dos desertos da América do Norte muitas vezes não bebe a vida inteira: ele tira a água de sementes secas. O dromedário aguenta umas duas semanas.", k: "Rato-canguru: muitas vezes nunca bebe" }, ja: { q: "水を飲まずに長く過ごせるのはどっち？", a: ["ヒトコブラクダ", "カンガルーネズミ"], x: "北アメリカの砂漠にすむカンガルーネズミは、一生水を飲まないことも。かわいた種から水分をとります。ラクダは2週間ほどです。", k: "カンガルーネズミ：一生水を飲まないことも" }, it: { q: "Chi resiste più a lungo senza bere?", a: ["Dromedario", "Ratto canguro"], x: "Il ratto canguro dei deserti nordamericani spesso non beve mai in tutta la vita: ricava l’acqua dai semi secchi. I cammelli resistono circa due settimane.", k: "Ratto canguro: spesso non beve mai" } } },
  { id: "f08", lvl: 2, type: "duel", right: 1, t: { de: { q: "Wer frisst einen Teil seines Kots absichtlich noch einmal?", a: ["Reh", "Wildkaninchen"], x: "Kaninchen fressen weiche Kotkügelchen direkt wieder auf. So holen sie beim zweiten Durchgang die Vitamine und Nährstoffe aus der schwer verdaulichen Pflanzenkost.", k: "Kaninchen: fressen einen Teil ihres Kots" }, en: { q: "Who eats some of its own droppings on purpose?", a: ["Roe deer", "Wild rabbit"], x: "Rabbits eat soft droppings straight away. On the second pass they get the vitamins and nutrients out of their hard-to-digest plant food.", k: "Rabbits: eat some of their own droppings" }, fr: { q: "Qui mange exprès une partie de ses crottes ?", a: ["Chevreuil", "Lapin de garenne"], x: "Le lapin mange tout de suite certaines crottes molles. Au second passage, il tire vitamines et nutriments de sa nourriture végétale difficile à digérer.", k: "Lapins : mangent une partie de leurs crottes" }, es: { q: "¿Quién se come a propósito parte de sus excrementos?", a: ["Corzo", "Conejo silvestre"], x: "El conejo se come enseguida unas bolitas blandas. En la segunda pasada saca las vitaminas y nutrientes de su comida vegetal, difícil de digerir.", k: "Conejos: se comen parte de sus excrementos" }, pt: { q: "Quem come de propósito parte das próprias fezes?", a: ["Corço", "Coelho-selvagem"], x: "O coelho come logo umas bolinhas moles. Na segunda passagem, ele aproveita as vitaminas e os nutrientes da comida vegetal, difícil de digerir.", k: "Coelhos: comem parte das próprias fezes" }, ja: { q: "自分のフンの一部をわざと食べるのはどっち？", a: ["ノロジカ", "アナウサギ"], x: "ウサギはやわらかいフンをすぐに食べます。2回目の消化で、消化しにくい植物からビタミンや栄養をとり出すのです。", k: "ウサギ：自分のフンを食べる" }, it: { q: "Chi mangia di proposito una parte dei propri escrementi?", a: ["Capriolo", "Coniglio selvatico"], x: "I conigli mangiano subito le feci molli. Al secondo passaggio estraggono vitamine e nutrienti dal loro cibo vegetale difficile da digerire.", k: "Conigli: mangiano parte delle loro feci" } } },
  { id: "f09", lvl: 2, type: "duel", right: 1, t: { de: { q: "Wer schluckt absichtlich Steine?", a: ["Löwe", "Krokodil"], x: "Krokodile schlucken Steine. Im Magen helfen sie beim Zerkleinern der Nahrung und vielleicht auch beim Tauchen als Ballast.", k: "Krokodile: schlucken absichtlich Steine" }, en: { q: "Who swallows stones on purpose?", a: ["Lion", "Crocodile"], x: "Crocodiles swallow stones. In the stomach they help grind up food and perhaps act as ballast for diving.", k: "Crocodiles: swallow stones on purpose" }, fr: { q: "Qui avale des pierres exprès ?", a: ["Lion", "Crocodile"], x: "Le crocodile avale des pierres. Dans l’estomac, elles aident à broyer la nourriture et servent peut-être de lest pour plonger.", k: "Crocodiles : avalent des pierres exprès" }, es: { q: "¿Quién se traga piedras a propósito?", a: ["León", "Cocodrilo"], x: "Los cocodrilos tragan piedras. En el estómago ayudan a triturar la comida y quizá sirven de lastre para bucear.", k: "Cocodrilos: tragan piedras a propósito" }, pt: { q: "Quem engole pedras de propósito?", a: ["Leão", "Crocodilo"], x: "Os crocodilos engolem pedras. No estômago elas ajudam a triturar a comida e talvez sirvam de lastro para mergulhar.", k: "Crocodilos: engolem pedras de propósito" }, ja: { q: "わざと石を飲みこむのはどっち？", a: ["ライオン", "ワニ"], x: "ワニは石を飲みこみます。胃の中で食べものをすりつぶすのを助け、潜るときのおもりにもなるのかもしれません。", k: "ワニ：わざと石を飲みこむ" }, it: { q: "Chi inghiotte sassi di proposito?", a: ["Leone", "Coccodrillo"], x: "I coccodrilli inghiottono sassi. Nello stomaco aiutano a sminuzzare il cibo e forse fanno da zavorra per le immersioni.", k: "Coccodrilli: inghiottono sassi apposta" } } },
  { id: "f10", lvl: 1, type: "duel", right: 0, t: { de: { q: "Wer kann im Stehen dösen?", a: ["Pferd", "Hund"], x: "Pferde können ihre Beingelenke einrasten lassen und so im Stehen dösen. Für den Tiefschlaf legen aber auch sie sich hin.", k: "Pferde: dösen im Stehen" }, en: { q: "Who can doze while standing up?", a: ["Horse", "Dog"], x: "Horses can lock their leg joints and doze standing up. For deep sleep, though, they lie down too.", k: "Horses: doze standing up" }, fr: { q: "Qui peut somnoler debout ?", a: ["Cheval", "Chien"], x: "Le cheval peut bloquer ses articulations et somnoler debout. Pour le sommeil profond, il se couche quand même.", k: "Chevaux : somnolent debout" }, es: { q: "¿Quién puede dormitar de pie?", a: ["Caballo", "Perro"], x: "El caballo puede bloquear las articulaciones de las patas y dormitar de pie. Para el sueño profundo, también se tumba.", k: "Caballos: dormitan de pie" }, pt: { q: "Quem consegue cochilar em pé?", a: ["Cavalo", "Cachorro"], x: "O cavalo consegue travar as articulações das pernas e cochilar em pé. Para o sono profundo, ele também se deita.", k: "Cavalos: cochilam em pé" }, ja: { q: "立ったままうとうとできるのはどっち？", a: ["ウマ", "イヌ"], x: "ウマは脚の関節をロックして、立ったままうとうとできます。でも深く眠るときは横になります。", k: "ウマ：立ったまま眠る" }, it: { q: "Chi sa sonnecchiare in piedi?", a: ["Cavallo", "Cane"], x: "I cavalli bloccano le articolazioni delle zampe e sonnecchiano in piedi. Per il sonno profondo però si sdraiano anche loro.", k: "Cavalli: sonnecchiano in piedi" } } },
  { id: "f11", lvl: 1, type: "duel", right: 0, t: { de: { q: "Wer trägt sein Junges in einem Beutel?", a: ["Koala", "Faultier"], x: "Koalas sind Beuteltiere. Das Junge ist bei der Geburt nur so groß wie eine Bohne und wächst im Beutel monatelang weiter.", k: "Koala-Baby: bei der Geburt so groß wie eine Bohne" }, en: { q: "Who carries its baby in a pouch?", a: ["Koala", "Sloth"], x: "Koalas are marsupials. At birth the baby is only the size of a bean and keeps growing in the pouch for months.", k: "Koala baby: born the size of a bean" }, fr: { q: "Qui porte son petit dans une poche ?", a: ["Koala", "Paresseux"], x: "Le koala est un marsupial. À la naissance, le petit est grand comme un haricot et grandit des mois dans la poche.", k: "Bébé koala : naît gros comme un haricot" }, es: { q: "¿Quién lleva a su cría en una bolsa?", a: ["Koala", "Perezoso"], x: "El koala es un marsupial. Al nacer, la cría es del tamaño de una judía y sigue creciendo en la bolsa durante meses.", k: "Bebé koala: nace como una judía" }, pt: { q: "Quem carrega o filhote numa bolsa?", a: ["Coala", "Bicho-preguiça"], x: "O coala é um marsupial. Ao nascer, o filhote tem o tamanho de um feijão e continua crescendo na bolsa por meses.", k: "Bebê coala: nasce do tamanho de um feijão" }, ja: { q: "赤ちゃんを袋に入れて育てるのはどっち？", a: ["コアラ", "ナマケモノ"], x: "コアラは有袋類。生まれたときの赤ちゃんは豆粒ほどで、何か月も袋の中で育ちます。", k: "コアラの赤ちゃん：生まれたときは豆粒ほど" }, it: { q: "Chi porta il piccolo in un marsupio?", a: ["Koala", "Bradipo"], x: "I koala sono marsupiali. Alla nascita il piccolo è grande come un fagiolo e cresce per mesi nel marsupio.", k: "Cucciolo di koala: nasce grande come un fagiolo" } } },
  { id: "f12", lvl: 1, type: "duel", right: 0, t: { de: { q: "Welches Säugetier legt Eier?", a: ["Ameisenigel", "Igel"], x: "Der Ameisenigel aus Australien legt Eier und brütet sie in einer Bauchtasche aus. Trotz Stacheln ist er nicht mit unserem Igel verwandt, der lebende Junge bekommt.", k: "Ameisenigel: Säugetier, das Eier legt" }, en: { q: "Which mammal lays eggs?", a: ["Echidna", "Hedgehog"], x: "The Australian echidna lays eggs and incubates them in a belly pouch. Despite its spines, it isn’t related to the hedgehog, which gives birth to live young.", k: "Echidna: a mammal that lays eggs" }, fr: { q: "Quel mammifère pond des œufs ?", a: ["Échidné", "Hérisson"], x: "L’échidné d’Australie pond des œufs et les couve dans une poche ventrale. Malgré ses piquants, il n’est pas parent du hérisson, qui met au monde des petits vivants.", k: "Échidné : mammifère qui pond des œufs" }, es: { q: "¿Qué mamífero pone huevos?", a: ["Equidna", "Erizo"], x: "El equidna australiano pone huevos y los incuba en una bolsa del vientre. Pese a sus púas, no es pariente del erizo, que pare crías vivas.", k: "Equidna: mamífero que pone huevos" }, pt: { q: "Que mamífero põe ovos?", a: ["Equidna", "Ouriço"], x: "A equidna australiana põe ovos e os choca numa bolsa na barriga. Apesar dos espinhos, não é parente do ouriço, que tem filhotes vivos.", k: "Équidna: mamífero que põe ovos" }, ja: { q: "卵を産む哺乳類はどっち？", a: ["ハリモグラ", "ハリネズミ"], x: "オーストラリアのハリモグラは卵を産み、おなかの袋で温めます。トゲがあってもハリネズミの親せきではありません。ハリネズミは赤ちゃんを産みます。", k: "ハリモグラ：卵を産む哺乳類" }, it: { q: "Quale mammifero depone le uova?", a: ["Echidna", "Riccio"], x: "L’echidna australiana depone uova e le cova in una tasca sulla pancia. Nonostante gli aculei non è parente del riccio, che partorisce piccoli vivi.", k: "Echidna: mammifero che depone uova" } } },
  { id: "f13", lvl: 2, type: "duel", right: 0, t: { de: { q: "Wer ist giftig?", a: ["Schnabeltier-Männchen", "Biber"], x: "Männliche Schnabeltiere haben an den Hinterbeinen einen Giftsporn. Der Stich ist für Menschen extrem schmerzhaft, aber nicht tödlich.", k: "Schnabeltier-Männchen: haben einen Giftsporn" }, en: { q: "Who is venomous?", a: ["Male platypus", "Beaver"], x: "Male platypuses have a venomous spur on their hind legs. The sting is extremely painful for humans, but not deadly.", k: "Male platypus: has a venomous spur" }, fr: { q: "Qui est venimeux ?", a: ["Ornithorynque mâle", "Castor"], x: "L’ornithorynque mâle a un ergot venimeux aux pattes arrière. La piqûre est extrêmement douloureuse pour l’humain, mais pas mortelle.", k: "Ornithorynque mâle : ergot venimeux" }, es: { q: "¿Quién es venenoso?", a: ["Ornitorrinco macho", "Castor"], x: "El ornitorrinco macho tiene un espolón venenoso en las patas traseras. Su picadura es muy dolorosa para los humanos, pero no mortal.", k: "Ornitorrinco macho: espolón venenoso" }, pt: { q: "Quem é venenoso?", a: ["Ornitorrinco macho", "Castor"], x: "O ornitorrinco macho tem um esporão venenoso nas patas traseras. A picada é muito dolorosa para humanos, mas não mata.", k: "Ornitorrinco macho: tem esporão venenoso" }, ja: { q: "毒があるのはどっち？", a: ["カモノハシのオス", "ビーバー"], x: "カモノハシのオスは後ろ脚に毒のけづめがあります。人が刺されるとものすごく痛いですが、命に別状はありません。", k: "カモノハシのオス：毒のけづめがある" }, it: { q: "Chi è velenoso?", a: ["Ornitorinco maschio", "Castoro"], x: "Il maschio di ornitorinco ha uno sperone velenoso sulle zampe posteriori. Per l’uomo la puntura è dolorosissima, ma non mortale.", k: "Ornitorinco maschio: sperone velenoso" } } },
  { id: "f14", lvl: 3, type: "duel", right: 0, t: { de: { q: "Wer hat Fingerabdrücke wie wir?", a: ["Koala", "Hund"], x: "Koala-Fingerabdrücke sehen unseren so ähnlich, dass man sie selbst unter dem Mikroskop kaum unterscheiden kann – obwohl Koalas gar nicht eng mit uns verwandt sind.", k: "Koalas: haben Fingerabdrücke wie wir" }, en: { q: "Who has fingerprints like ours?", a: ["Koala", "Dog"], x: "Koala fingerprints look so much like ours that they’re hard to tell apart even under a microscope – although koalas aren’t closely related to us at all.", k: "Koalas: have fingerprints like ours" }, fr: { q: "Qui a des empreintes digitales comme les nôtres ?", a: ["Koala", "Chien"], x: "Les empreintes du koala ressemblent tant aux nôtres qu’on les distingue à peine au microscope – alors qu’il n’est pas proche parent de l’humain.", k: "Koalas : empreintes digitales comme les nôtres" }, es: { q: "¿Quién tiene huellas dactilares como las nuestras?", a: ["Koala", "Perro"], x: "Las huellas del koala se parecen tanto a las nuestras que cuesta distinguirlas incluso al microscopio, aunque no es pariente cercano nuestro.", k: "Koalas: huellas dactilares como las nuestras" }, pt: { q: "Quem tem impressões digitais como as nossas?", a: ["Coala", "Cachorro"], x: "As digitais do coala são tão parecidas com as nossas que é difícil diferenciá-las até no microscópio – embora ele não seja nosso parente próximo.", k: "Coalas: impressões digitais como as nossas" }, ja: { q: "私たちのような指紋があるのはどっち？", a: ["コアラ", "イヌ"], x: "コアラの指紋は人間とそっくりで、顕微鏡でも見分けにくいほど。私たちとは近い親せきでもないのに、です。", k: "コアラ：人と同じような指紋" }, it: { q: "Chi ha impronte digitali come le nostre?", a: ["Koala", "Cane"], x: "Le impronte dei koala somigliano tanto alle nostre da essere difficili da distinguere anche al microscopio, anche se non siamo affatto parenti stretti.", k: "Koala: impronte digitali come le nostre" } } },
  { id: "f15", lvl: 2, type: "duel", right: 0, t: { de: { q: "Wer schwitzt am ganzen Körper?", a: ["Pferd", "Hund"], x: "Pferde schwitzen wie wir am ganzen Körper. Hunde haben Schweißdrüsen fast nur an den Pfoten und kühlen sich durch Hecheln.", k: "Pferde: schwitzen am ganzen Körper" }, en: { q: "Who sweats all over its body?", a: ["Horse", "Dog"], x: "Horses sweat all over their body like we do. Dogs have sweat glands almost only on their paws and cool down by panting.", k: "Horses: sweat all over their body" }, fr: { q: "Qui transpire de tout son corps ?", a: ["Cheval", "Chien"], x: "Le cheval transpire de tout son corps, comme nous. Le chien n’a des glandes sudoripares presque qu’aux coussinets et se rafraîchit en haletant.", k: "Chevaux : transpirent sur tout le corps" }, es: { q: "¿Quién suda por todo el cuerpo?", a: ["Caballo", "Perro"], x: "El caballo suda por todo el cuerpo como nosotros. El perro casi solo tiene glándulas sudoríparas en las almohadillas y se refresca jadeando.", k: "Caballos: sudan por todo el cuerpo" }, pt: { q: "Quem sua pelo corpo todo?", a: ["Cavalo", "Cachorro"], x: "O cavalo sua pelo corpo todo, como nós. O cachorro tem glândulas de suor quase só nas almofadinhas das patas e se refresca ofegando.", k: "Cavalos: suam no corpo todo" }, ja: { q: "全身で汗をかくのはどっち？", a: ["ウマ", "イヌ"], x: "ウマは人と同じように全身で汗をかきます。イヌの汗腺はほぼ足の裏だけで、ハアハアと息をして体を冷やします。", k: "ウマ：全身で汗をかく" }, it: { q: "Chi suda su tutto il corpo?", a: ["Cavallo", "Cane"], x: "I cavalli sudano su tutto il corpo come noi. I cani hanno ghiandole sudoripare quasi solo sulle zampe e si rinfrescano ansimando.", k: "Cavalli: sudano su tutto il corpo" } } },
  { id: "f16", lvl: 2, type: "duel", right: 0, t: { de: { q: "Wer bleibt länger unter Wasser?", a: ["See-Elefant", "Seelöwe"], x: "See-Elefanten tauchen bis etwa 2 Stunden und über 1.000 m tief. Seelöwen bleiben meist nur wenige Minuten unten.", k: "See-Elefant: taucht bis zu 2 Stunden" }, en: { q: "Who stays underwater longer?", a: ["Elephant seal", "Sea lion"], x: "Elephant seals dive for up to about 2 hours and over 1,000 m deep. Sea lions usually stay down only a few minutes.", k: "Elephant seal: dives for up to 2 hours" }, fr: { q: "Qui reste le plus longtemps sous l’eau ?", a: ["Éléphant de mer", "Otarie"], x: "L’éléphant de mer plonge jusqu’à environ 2 heures et à plus de 1 000 m. L’otarie ne reste en général que quelques minutes.", k: "Éléphant de mer : plonge jusqu’à 2 heures" }, es: { q: "¿Quién aguanta más bajo el agua?", a: ["Elefante marino", "León marino"], x: "El elefante marino bucea hasta unas 2 horas y a más de 1.000 m. El león marino suele quedarse solo unos minutos.", k: "Elefante marino: bucea hasta 2 horas" }, pt: { q: "Quem aguenta mais tempo debaixo d’água?", a: ["Elefante-marinho", "Leão-marinho"], x: "O elefante-marinho mergulha por até cerca de 2 horas e a mais de 1.000 m. O leão-marinho costuma ficar só alguns minutos.", k: "Elefante-marinho: mergulha até 2 horas" }, ja: { q: "水中に長くいられるのはどっち？", a: ["ゾウアザラシ", "アシカ"], x: "ゾウアザラシは最大約2時間、水深1000メートル以上まで潜ります。アシカはふつう数分で上がってきます。", k: "ゾウアザラシ：最大2時間潜る" }, it: { q: "Chi resta più a lungo sott’acqua?", a: ["Elefante marino", "Leone marino"], x: "Gli elefanti marini si immergono fino a circa 2 ore e a oltre 1.000 m di profondità. I leoni marini di solito restano giù solo pochi minuti.", k: "Elefante marino: si immerge fino a 2 ore" } } },
  { id: "f17", lvl: 2, type: "duel", right: 0, t: { de: { q: "Wer fliegt schneller?", a: ["Libelle", "Honigbiene"], x: "Große Libellen erreichen über 50 km/h und fangen ihre Beute im Flug. Honigbienen fliegen etwa 25 bis 30 km/h.", k: "Libellen: fliegen über 50 km/h" }, en: { q: "Who flies faster?", a: ["Dragonfly", "Honeybee"], x: "Large dragonflies reach over 50 km/h and catch their prey in flight. Honeybees fly at about 25 to 30 km/h.", k: "Dragonflies: fly over 50 km/h" }, fr: { q: "Qui vole le plus vite ?", a: ["Libellule", "Abeille"], x: "Les grandes libellules dépassent 50 km/h et attrapent leurs proies en vol. L’abeille vole à environ 25 à 30 km/h.", k: "Libellules : volent à plus de 50 km/h" }, es: { q: "¿Quién vuela más rápido?", a: ["Libélula", "Abeja"], x: "Las libélulas grandes superan los 50 km/h y cazan en pleno vuelo. La abeja vuela a unos 25-30 km/h.", k: "Libélulas: vuelan a más de 50 km/h" }, pt: { q: "Quem voa mais rápido?", a: ["Libélula", "Abelha"], x: "Libélulas grandes passam dos 50 km/h e caçam em pleno voo. A abelha voa a uns 25–30 km/h.", k: "Libélulas: voam a mais de 50 km/h" }, ja: { q: "飛ぶのが速いのはどっち？", a: ["トンボ", "ミツバチ"], x: "大きなトンボは時速50キロ以上で飛び、飛びながら獲物をつかまえます。ミツバチは時速25〜30キロほどです。", k: "トンボ：時速50キロ以上で飛ぶ" }, it: { q: "Chi vola più veloce?", a: ["Libellula", "Ape mellifera"], x: "Le grandi libellule superano i 50 km/h e catturano le prede in volo. Le api volano a circa 25–30 km/h.", k: "Libellule: volano oltre 50 km/h" } } },
  { id: "f18", lvl: 1, type: "duel", right: 1, t: { de: { q: "Wer ist näher mit dem Hai verwandt?", a: ["Delfin", "Rochen"], x: "Rochen sind im Grunde platte Haie – ebenfalls mit Knorpelskelett. Delfine sind Säugetiere und atmen Luft.", k: "Rochen: plattgedrückte Haie" }, en: { q: "Who is more closely related to the shark?", a: ["Dolphin", "Ray"], x: "Rays are basically flattened sharks – also with a cartilage skeleton. Dolphins are mammals and breathe air.", k: "Rays: flattened sharks" }, fr: { q: "Qui est le plus proche parent du requin ?", a: ["Dauphin", "Raie"], x: "La raie est en somme un requin aplati – elle aussi à squelette de cartilage. Le dauphin est un mammifère qui respire de l’air.", k: "Raies : des requins aplatis" }, es: { q: "¿Quién es pariente más cercano del tiburón?", a: ["Delfín", "Raya"], x: "La raya es básicamente un tiburón aplanado, también con esqueleto de cartílago. El delfín es un mamífero y respira aire.", k: "Rayas: tiburones aplastados" }, pt: { q: "Quem é parente mais próximo do tubarão?", a: ["Golfinho", "Raia"], x: "A raia é basicamente um tubarão achatado, também com esqueleto de cartilagem. O golfinho é um mamífero e respira ar.", k: "Raias: tubarões achatados" }, ja: { q: "サメに近い親せきはどっち？", a: ["イルカ", "エイ"], x: "エイは平たくなったサメのようなもの。骨格も同じく軟骨です。イルカは哺乳類で、空気を吸って呼吸します。", k: "エイ：平たくなったサメ" }, it: { q: "Chi è più vicino parente dello squalo?", a: ["Delfino", "Razza"], x: "Le razze sono in pratica squali appiattiti, anche loro con lo scheletro di cartilagine. I delfini sono mammiferi e respirano aria.", k: "Razze: squali appiattiti" } } },
  { id: "f19", lvl: 3, type: "duel", right: 0, t: { de: { q: "Wer hat mehr Arten von Farb-Sinneszellen im Auge?", a: ["Fangschreckenkrebs", "Mensch"], x: "Fangschreckenkrebse haben 12 Sorten Farbrezeptoren, wir nur 3. Trotzdem unterscheiden sie Farben eher schlechter – ihr Gehirn wertet sie anders aus.", k: "Fangschreckenkrebs: 12 Farbrezeptoren, wir nur 3" }, en: { q: "Who has more kinds of colour receptors in its eyes?", a: ["Mantis shrimp", "Human"], x: "Mantis shrimps have 12 kinds of colour receptors, we have only 3. Even so, they’re actually worse at telling colours apart – their brain processes them differently.", k: "Mantis shrimp: 12 colour receptors, we have 3" }, fr: { q: "Qui a le plus de types de cellules des couleurs dans l’œil ?", a: ["Crevette-mante", "Humain"], x: "La crevette-mante a 12 sortes de récepteurs de couleur, nous seulement 3. Pourtant, elle distingue plutôt moins bien les couleurs – son cerveau les traite autrement.", k: "Squille : 12 récepteurs de couleur, nous 3" }, es: { q: "¿Quién tiene más tipos de células del color en el ojo?", a: ["Camarón mantis", "Humano"], x: "El camarón mantis tiene 12 tipos de receptores de color y nosotros solo 3. Aun así, distingue peor los colores: su cerebro los procesa de otra forma.", k: "Galera pavo real: 12 receptores de color, nosotros 3" }, pt: { q: "Quem tem mais tipos de células de cor no olho?", a: ["Tamarutaca", "Humano"], x: "A tamarutaca tem 12 tipos de receptores de cor, e nós só 3. Mesmo assim, ela diferencia cores pior: seu cérebro processa as cores de outro jeito.", k: "Tamarutaca: 12 receptores de cor, nós 3" }, ja: { q: "目の色を感じる細胞の種類が多いのはどっち？", a: ["シャコ", "人間"], x: "シャコには色を感じる細胞が12種類、私たちには3種類しかありません。それでも、色の見分けはむしろ苦手。脳での処理のしかたがちがうのです。", k: "シャコ：色の受容体12種類、人は3種類" }, it: { q: "Chi ha più tipi di recettori del colore negli occhi?", a: ["Canocchia pavone", "Essere umano"], x: "La canocchia pavone ha 12 tipi di recettori del colore, noi solo 3. Eppure distingue i colori peggio: il suo cervello li elabora in modo diverso.", k: "Canocchia pavone: 12 recettori del colore, noi 3" } } },
  { id: "f20", lvl: 3, type: "duel", right: 1, t: { de: { q: "Was wiegt zusammen mehr?", a: ["Alle Ameisen", "Alle Menschen"], x: "Eine Studie von 2022 schätzt: Alle Ameisen der Welt wiegen zusammen etwa ein Fünftel so viel wie alle Menschen. Es sind zwar 20 Billiarden – aber jede ist winzig.", k: "Alle Ameisen: wiegen ein Fünftel aller Menschen" }, en: { q: "What weighs more in total?", a: ["All ants", "All humans"], x: "A 2022 study estimated that all the ants in the world together weigh about a fifth as much as all humans. There are 20 quadrillion of them – but each one is tiny.", k: "All ants: weigh a fifth of all humans" }, fr: { q: "Qu’est-ce qui pèse le plus au total ?", a: ["Toutes les fourmis", "Tous les humains"], x: "Une étude de 2022 estime que toutes les fourmis du monde pèsent ensemble environ un cinquième du poids de tous les humains. Elles sont 20 millions de milliards – mais minuscules.", k: "Toutes les fourmis : un cinquième du poids des humains" }, es: { q: "¿Qué pesa más en total?", a: ["Todas las hormigas", "Todos los humanos"], x: "Un estudio de 2022 calcula que todas las hormigas del mundo juntas pesan una quinta parte que todos los humanos. Son 20.000 billones, pero cada una es diminuta.", k: "Todas las hormigas: pesan un quinto de los humanos" }, pt: { q: "O que pesa mais no total?", a: ["Todas as formigas", "Todos os humanos"], x: "Um estudo de 2022 calcula que todas as formigas do mundo juntas pesam um quinto do peso de todos os humanos. São 20 quatrilhões, mas cada uma é minúscula.", k: "Todas as formigas: pesam um quinto dos humanos" }, ja: { q: "全部合わせると重いのはどっち？", a: ["世界中のアリ", "世界中の人間"], x: "2022年の研究では、世界中のアリを合わせた重さは、人間全体の約5分の1と推定されています。2京匹もいますが、1匹1匹はとても小さいのです。", k: "世界のアリ：人類の5分の1の重さ" }, it: { q: "Cosa pesa di più in totale?", a: ["Tutte le formiche", "Tutti gli esseri umani"], x: "Secondo uno studio del 2022, tutte le formiche del mondo insieme pesano circa un quinto di tutti gli esseri umani. Sono 20 biliardi, ma ognuna è minuscola.", k: "Tutte le formiche: un quinto del peso degli umani" } } },
  { id: "f21", lvl: 2, type: "duel", right: 0, t: { de: { q: "Wer brütet beim Kaiserpinguin das Ei aus?", a: ["Das Männchen", "Das Weibchen"], x: "Das Männchen hält das Ei zwei Monate lang auf den Füßen unter einer Bauchfalte – im antarktischen Winter, ohne zu fressen. Das Weibchen ist so lange auf dem Meer.", k: "Kaiserpinguin: das Männchen brütet das Ei aus" }, en: { q: "Who incubates the egg in emperor penguins?", a: ["The male", "The female"], x: "The male holds the egg on his feet under a fold of belly skin for two months – in the Antarctic winter, without eating. The female is out at sea all that time.", k: "Emperor penguin: the male incubates the egg" }, fr: { q: "Qui couve l’œuf chez le manchot empereur ?", a: ["Le mâle", "La femelle"], x: "Le mâle garde l’œuf deux mois sur ses pattes, sous un repli du ventre – en plein hiver antarctique, sans manger. La femelle est en mer pendant ce temps.", k: "Manchot empereur : le mâle couve l’œuf" }, es: { q: "¿Quién incuba el huevo en el pingüino emperador?", a: ["El macho", "La hembra"], x: "El macho sostiene el huevo dos meses sobre las patas bajo un pliegue del vientre, en pleno invierno antártico y sin comer. La hembra está mientras tanto en el mar.", k: "Pingüino emperador: el macho incuba el huevo" }, pt: { q: "Quem choca o ovo no pinguim-imperador?", a: ["O macho", "A fêmea"], x: "O macho segura o ovo por dois meses sobre os pés, debaixo de uma dobra da barriga, em pleno inverno antártico e sem comer. A fêmea fica enquanto isso no mar.", k: "Pinguim-imperador: o macho choca o ovo" }, ja: { q: "コウテイペンギンで卵を温めるのはどっち？", a: ["オス", "メス"], x: "オスは2か月間、卵を足の上にのせておなかの皮でおおいます。南極の冬に、何も食べずに。その間メスは海にいます。", k: "コウテイペンギン：オスが卵を温める" }, it: { q: "Chi cova l’uovo nel pinguino imperatore?", a: ["Il maschio", "La femmina"], x: "Il maschio tiene l’uovo sui piedi sotto una piega della pancia per due mesi, nell’inverno antartico e senza mangiare. Nel frattempo la femmina è in mare.", k: "Pinguino imperatore: il maschio cova l’uovo" } } },
  { id: "f22", lvl: 3, type: "duel", right: 0, t: { de: { q: "Wer ist näher mit uns Menschen verwandt?", a: ["Seestern", "Tintenfisch"], x: "Kaum zu glauben: Seesterne und Seeigel gehören zu derselben großen Tiergruppe wie die Wirbeltiere. Tintenfische sind Weichtiere und stehen uns ferner.", k: "Seesterne: näher mit uns verwandt als Tintenfische" }, en: { q: "Who is more closely related to us humans?", a: ["Starfish", "Squid"], x: "Hard to believe: starfish and sea urchins belong to the same big animal group as vertebrates. Squids are molluscs and further from us.", k: "Starfish: closer to us than squids are" }, fr: { q: "Qui est le plus proche parent de l’être humain ?", a: ["Étoile de mer", "Calmar"], x: "Incroyable : étoiles de mer et oursins font partie du même grand groupe que les vertébrés. Le calmar est un mollusque, plus éloigné de nous.", k: "Étoiles de mer : plus proches de nous que les calmars" }, es: { q: "¿Quién es pariente más cercano de los humanos?", a: ["Estrella de mar", "Calamar"], x: "Aunque cueste creerlo, estrellas y erizos de mar pertenecen al mismo gran grupo que los vertebrados. El calamar es un molusco, más lejano a nosotros.", k: "Estrellas de mar: más cerca de nosotros que los calamares" }, pt: { q: "Quem é parente mais próximo dos humanos?", a: ["Estrela-do-mar", "Lula"], x: "Parece incrível, mas estrelas-do-mar e ouriços-do-mar pertencem ao mesmo grande grupo que os vertebrados. A lula é um molusco, mais distante de nós.", k: "Estrelas-do-mar: mais perto de nós que as lulas" }, ja: { q: "私たち人間に近い親せきはどっち？", a: ["ヒトデ", "イカ"], x: "信じられないけれど、ヒトデやウニは脊椎動物と同じ大きな動物グループに入ります。イカは軟体動物で、私たちからは遠い存在です。", k: "ヒトデ：イカより人間に近い" }, it: { q: "Chi è più vicino parente di noi esseri umani?", a: ["Stella marina", "Calamaro"], x: "Difficile da credere: stelle e ricci di mare fanno parte dello stesso grande gruppo dei vertebrati. I calamari sono molluschi e più lontani da noi.", k: "Stelle marine: più vicine a noi dei calamari" } } },
  { id: "f23", lvl: 2, type: "duel", right: 0, t: { de: { q: "Wer schläft mit einer Gehirnhälfte?", a: ["Delfin", "Hund"], x: "Delfine schlafen abwechselnd mit einer Gehirnhälfte. Die andere bleibt wach – so atmen sie weiter und achten auf Gefahren.", k: "Delfine: schlafen mit halbem Gehirn" }, en: { q: "Who sleeps with half its brain?", a: ["Dolphin", "Dog"], x: "Dolphins sleep with one half of their brain at a time. The other half stays awake – so they keep breathing and watch for danger.", k: "Dolphins: sleep with half their brain" }, fr: { q: "Qui dort avec une moitié de cerveau ?", a: ["Dauphin", "Chien"], x: "Le dauphin dort avec une moitié du cerveau à la fois. L’autre reste éveillée – il continue ainsi à respirer et à guetter le danger.", k: "Dauphins : dorment d’un demi-cerveau" }, es: { q: "¿Quién duerme con medio cerebro?", a: ["Delfín", "Perro"], x: "El delfín duerme con una mitad del cerebro cada vez. La otra sigue despierta, así sigue respirando y vigila los peligros.", k: "Delfines: duermen con medio cerebro" }, pt: { q: "Quem dorme com metade do cérebro?", a: ["Golfinho", "Cachorro"], x: "O golfinho dorme com uma metade do cérebro de cada vez. A outra continua acordada – assim ele segue respirando e fica atento aos perigos.", k: "Golfinhos: dormem com meio cérebro" }, ja: { q: "脳の半分ずつ眠るのはどっち？", a: ["イルカ", "イヌ"], x: "イルカは脳の半分ずつ眠ります。もう半分は起きていて、呼吸を続け、危険を見張ります。", k: "イルカ：脳の半分ずつ眠る" }, it: { q: "Chi dorme con metà cervello?", a: ["Delfino", "Cane"], x: "I delfini dormono con una metà del cervello alla volta. L’altra resta sveglia: così continuano a respirare e controllano i pericoli.", k: "Delfini: dormono con mezzo cervello" } } },
  { id: "f24", lvl: 2, type: "duel", right: 1, t: { de: { q: "Wer kann über das Wasser rennen?", a: ["Grüner Leguan", "Stirnlappenbasilisk"], x: "Der Basilisk rennt auf den Hinterbeinen übers Wasser: Er schlägt die Füße so schnell auf, dass er nicht einsinkt. Leguane schwimmen.", k: "Basilisk: rennt übers Wasser" }, en: { q: "Who can run across water?", a: ["Green iguana", "Plumed basilisk"], x: "The basilisk runs across water on its hind legs: it slaps its feet down so fast that it doesn’t sink. Iguanas swim.", k: "Basilisk: runs across water" }, fr: { q: "Qui peut courir sur l’eau ?", a: ["Iguane vert", "Basilic vert"], x: "Le basilic court sur l’eau sur ses pattes arrière : il frappe la surface si vite qu’il ne s’enfonce pas. L’iguane, lui, nage.", k: "Basilic : court sur l’eau" }, es: { q: "¿Quién puede correr sobre el agua?", a: ["Iguana verde", "Basilisco verde"], x: "El basilisco corre sobre el agua con las patas traseras: golpea la superficie tan rápido que no se hunde. La iguana nada.", k: "Basilisco: corre sobre el agua" }, pt: { q: "Quem consegue correr sobre a água?", a: ["Iguana-verde", "Basilisco-verde"], x: "O basilisco corre sobre a água com as patas traseiras: bate na superfície tão rápido que não afunda. A iguana nada.", k: "Basilisco: corre sobre a água" }, ja: { q: "水の上を走れるのはどっち？", a: ["グリーンイグアナ", "グリーンバシリスク"], x: "バシリスクは後ろ脚で水の上を走ります。すばやく足をたたきつけるので沈まないのです。イグアナは泳ぎます。", k: "バシリスク：水の上を走る" }, it: { q: "Chi sa correre sull’acqua?", a: ["Iguana verde", "Basilisco piumato"], x: "Il basilisco corre sull’acqua sulle zampe posteriori: batte i piedi così in fretta da non affondare. Le iguane nuotano.", k: "Basilisco: corre sull’acqua" } } },
  { id: "f25", lvl: 2, type: "duel", right: 0, t: { de: { q: "Wer bleibt meist ein Leben lang beim selben Partner?", a: ["Höckerschwan", "Stockente"], x: "Schwanenpaare bleiben meist zusammen, solange beide leben. Stockenten suchen sich jedes Jahr einen neuen Partner.", k: "Schwäne: bleiben meist ein Leben lang zusammen" }, en: { q: "Who usually stays with the same partner for life?", a: ["Mute swan", "Mallard"], x: "Swan pairs usually stay together as long as both are alive. Mallards find a new partner every year.", k: "Swans: usually pair for life" }, fr: { q: "Qui reste en général avec le même partenaire toute sa vie ?", a: ["Cygne tuberculé", "Canard colvert"], x: "Les couples de cygnes restent en général ensemble toute leur vie. Le colvert change de partenaire chaque année.", k: "Cygnes : souvent en couple pour la vie" }, es: { q: "¿Quién suele quedarse con la misma pareja toda la vida?", a: ["Cisne vulgar", "Ánade real"], x: "Las parejas de cisnes suelen seguir juntas mientras viven. El ánade real busca pareja nueva cada año.", k: "Cisnes: suelen ser pareja de por vida" }, pt: { q: "Quem costuma ficar com o mesmo par a vida toda?", a: ["Cisne-branco", "Pato-real"], x: "Os casais de cisnes costumam ficar juntos enquanto vivem. O pato-real procura um novo par todo ano.", k: "Cisnes: costumam ficar juntos a vida toda" }, ja: { q: "ふつう一生同じパートナーといるのはどっち？", a: ["コブハクチョウ", "マガモ"], x: "ハクチョウのペアは、ふつうどちらかが生きている限り一緒です。マガモは毎年新しいパートナーを見つけます。", k: "ハクチョウ：ふつう一生同じパートナー" }, it: { q: "Chi di solito resta con lo stesso partner per tutta la vita?", a: ["Cigno reale", "Germano reale"], x: "Le coppie di cigni di solito restano insieme finché entrambi sono vivi. I germani reali trovano un nuovo partner ogni anno.", k: "Cigni: spesso in coppia per tutta la vita" } } },
  { id: "f26", lvl: 2, type: "duel", right: 1, t: { de: { q: "Wer hat ein drittes Augenlid?", a: ["Mensch", "Katze"], x: "Katzen haben eine Nickhaut, die quer übers Auge wischt und es schützt. Bei uns ist davon nur ein kleiner Rest im Augenwinkel übrig.", k: "Katzen: haben ein drittes Augenlid" }, en: { q: "Who has a third eyelid?", a: ["Human", "Cat"], x: "Cats have a nictitating membrane that sweeps across the eye to protect it. In us, only a tiny remnant is left in the corner of the eye.", k: "Cats: have a third eyelid" }, fr: { q: "Qui a une troisième paupière ?", a: ["Humain", "Chat"], x: "Le chat a une membrane nictitante qui balaie l’œil pour le protéger. Chez nous, il n’en reste qu’un petit vestige au coin de l’œil.", k: "Chats : ont une troisième paupière" }, es: { q: "¿Quién tiene un tercer párpado?", a: ["Humano", "Gato"], x: "El gato tiene una membrana nictitante que barre el ojo para protegerlo. A nosotros solo nos queda un pequeño resto en el rabillo del ojo.", k: "Gatos: tienen un tercer párpado" }, pt: { q: "Quem tem uma terceira pálpebra?", a: ["Humano", "Gato"], x: "O gato tem uma membrana nictitante que passa pelo olho para protegê-lo. Em nós sobrou só um pequeno resto no canto do olho.", k: "Gatos: têm uma terceira pálpebra" }, ja: { q: "3つ目のまぶたがあるのはどっち？", a: ["人間", "ネコ"], x: "ネコには瞬膜があり、目の上をさっと動いて目を守ります。人間には目頭にほんの小さななごりが残っているだけです。", k: "ネコ：3つ目のまぶたがある" }, it: { q: "Chi ha una terza palpebra?", a: ["Essere umano", "Gatto"], x: "I gatti hanno una membrana nittitante che scorre sull’occhio per proteggerlo. In noi ne resta solo un minuscolo residuo nell’angolo dell’occhio.", k: "Gatti: hanno una terza palpebra" } } },
  { id: "e01", lvl: 1, type: "duel", right: 0, t: { de: { q: "Wer ist schneller?", a: ["Adler", "Papagei"], x: "Im Sturzflug erreichen Steinadler über 200 km/h. Papageien fliegen meist mit 30 bis 60 km/h.", k: "Steinadler: im Sturzflug über 200 km/h" }, en: { q: "Who is faster?", a: ["Eagle", "Parrot"], x: "Golden eagles reach over 200 km/h in a dive. Parrots usually fly at 30 to 60 km/h.", k: "Golden eagle: over 200 km/h in a dive" }, fr: { q: "Qui est le plus rapide ?", a: ["Aigle", "Perroquet"], x: "En piqué, l’aigle royal dépasse les 200 km/h. Les perroquets volent en général à 30 à 60 km/h.", k: "Aigle royal : plus de 200 km/h en piqué" }, es: { q: "¿Quién es más rápido?", a: ["Águila", "Loro"], x: "En picado, el águila real supera los 200 km/h. Los loros suelen volar a 30 a 60 km/h.", k: "Águila real: más de 200 km/h en picado" }, pt: { q: "Quem é mais rápido?", a: ["Águia", "Papagaio"], x: "Em mergulho, a águia-real passa dos 200 km/h. Os papagaios costumam voar a 30 a 60 km/h.", k: "Águia-real: mais de 200 km/h em mergulho" }, ja: { q: "速いのはどっち？", a: ["ワシ", "オウム"], x: "イヌワシは急降下で時速200キロ以上。オウムはふつう時速30〜60キロで飛びます。", k: "イヌワシ：急降下で時速200キロ以上" }, it: { q: "Chi è più veloce?", a: ["Aquila", "Pappagallo"], x: "In picchiata l’aquila reale supera i 200 km/h. I pappagalli volano di solito a 30–60 km/h.", k: "Aquila reale: oltre 200 km/h in picchiata" } } },
  { id: "e02", lvl: 2, type: "duel", right: 1, t: { de: { q: "Wer schläft mehr am Tag?", a: ["Giraffe", "Tiger"], x: "Tiger dösen 16 bis 20 Stunden am Tag. Giraffen schlafen nur wenige Stunden, oft im Stehen und in kurzen Nickerchen.", k: "Tiger: dösen bis zu 20 Stunden am Tag" }, en: { q: "Who sleeps more each day?", a: ["Giraffe", "Tiger"], x: "Tigers doze 16 to 20 hours a day. Giraffes sleep only a few hours, often standing and in short naps.", k: "Tigers: doze up to 20 hours a day" }, fr: { q: "Qui dort le plus par jour ?", a: ["Girafe", "Tigre"], x: "Le tigre somnole 16 à 20 heures par jour. La girafe ne dort que quelques heures, souvent debout et par petites siestes.", k: "Tigres : somnolent jusqu’à 20 h par jour" }, es: { q: "¿Quién duerme más al día?", a: ["Jirafa", "Tigre"], x: "Los tigres dormitan de 16 a 20 horas al día. Las jirafas solo duermen unas pocas horas, a menudo de pie y en siestas cortas.", k: "Tigres: dormitan hasta 20 h al día" }, pt: { q: "Quem dorme mais por dia?", a: ["Girafa", "Tigre"], x: "O tigre cochila de 16 a 20 horas por dia. A girafa dorme só poucas horas, muitas vezes em pé e em sonecas curtas.", k: "Tigres: cochilam até 20 h por dia" }, ja: { q: "1日によく眠るのはどっち？", a: ["キリン", "トラ"], x: "トラは1日16〜20時間うとうとします。キリンが眠るのは数時間だけ。立ったまま、短い仮眠を重ねます。", k: "トラ：1日最大20時間うとうと" }, it: { q: "Chi dorme di più al giorno?", a: ["Giraffa", "Tigre"], x: "Le tigri sonnecchiano 16–20 ore al giorno. Le giraffe dormono solo poche ore, spesso in piedi e a brevi riprese.", k: "Tigri: sonnecchiano fino a 20 ore al giorno" } } },
  { id: "e06", lvl: 3, type: "duel", right: 0, t: { de: { q: "Wer ist näher mit den Vögeln verwandt?", a: ["Schildkröte", "Eidechse"], x: "Erbgut-Vergleiche zeigen: Schildkröten sind näher mit Vögeln und Krokodilen verwandt als mit Eidechsen und Schlangen.", k: "Schildkröten: näher mit Vögeln verwandt als mit Echsen" }, en: { q: "Who is more closely related to birds?", a: ["Turtle", "Lizard"], x: "DNA comparisons show that turtles are more closely related to birds and crocodiles than to lizards and snakes.", k: "Turtles: closer to birds than to lizards" }, fr: { q: "Qui est le plus proche parent des oiseaux ?", a: ["Tortue", "Lézard"], x: "L’ADN le montre : les tortues sont plus proches des oiseaux et des crocodiles que des lézards et des serpents.", k: "Tortues : plus proches des oiseaux que des lézards" }, es: { q: "¿Quién es pariente más cercano de las aves?", a: ["Tortuga", "Lagartija"], x: "Las comparaciones de ADN lo muestran: las tortugas están más emparentadas con aves y cocodrilos que con lagartijas y serpientes.", k: "Tortugas: más cerca de las aves que de los lagartos" }, pt: { q: "Quem é parente mais próximo das aves?", a: ["Tartaruga", "Lagarto"], x: "Comparações de DNA mostram: as tartarugas são mais aparentadas com aves e crocodilos do que com lagartos e cobras.", k: "Tartarugas: mais perto das aves que dos lagartos" }, ja: { q: "鳥により近い親せきはどっち？", a: ["カメ", "トカゲ"], x: "DNAを比べると、カメはトカゲやヘビよりも、鳥やワニに近い親せきだとわかります。", k: "カメ：トカゲより鳥に近い" }, it: { q: "Chi è più vicino parente degli uccelli?", a: ["Tartaruga", "Lucertola"], x: "Il confronto del DNA mostra che le tartarughe sono più vicine a uccelli e coccodrilli che a lucertole e serpenti.", k: "Tartarughe: più vicine agli uccelli che alle lucertole" } } },
  { id: "e08", lvl: 2, type: "duel", right: 0, t: { de: { q: "Wer ist näher mit den Insekten verwandt?", a: ["Krabbe", "Schnecke"], x: "Krabben und Insekten sind Gliederfüßer mit Panzer und gegliederten Beinen. Insekten haben sich sogar aus Krebstieren entwickelt.", k: "Insekten: stammen von Krebstieren ab" }, en: { q: "Who is more closely related to insects?", a: ["Crab", "Snail"], x: "Crabs and insects are arthropods with an armour and jointed legs. Insects even evolved from crustaceans.", k: "Insects: evolved from crustaceans" }, fr: { q: "Qui est le plus proche parent des insectes ?", a: ["Crabe", "Escargot"], x: "Crabes et insectes sont des arthropodes, avec carapace et pattes articulées. Les insectes descendent même des crustacés.", k: "Insectes : descendent des crustacés" }, es: { q: "¿Quién es pariente más cercano de los insectos?", a: ["Cangrejo", "Caracol"], x: "Cangrejos e insectos son artrópodos con caparazón y patas articuladas. Los insectos incluso evolucionaron a partir de crustáceos.", k: "Insectos: descienden de los crustáceos" }, pt: { q: "Quem é parente mais próximo dos insetos?", a: ["Caranguejo", "Caracol"], x: "Caranguejos e insetos são artrópodes, com carapaça e patas articuladas. Os insetos até evoluíram a partir de crustáceos.", k: "Insetos: descendem dos crustáceos" }, ja: { q: "昆虫により近い親せきはどっち？", a: ["カニ", "カタツムリ"], x: "カニも昆虫も、かたい殻と節のある脚をもつ節足動物。昆虫は甲殻類から進化したほどです。", k: "昆虫：甲殻類から進化した" }, it: { q: "Chi è più vicino parente degli insetti?", a: ["Granchio", "Chiocciola"], x: "Granchi e insetti sono artropodi, con corazza e zampe articolate. Gli insetti si sono addirittura evoluti dai crostacei.", k: "Insetti: discendono dai crostacei" } } },
  { id: "e10", lvl: 3, type: "duel", right: 0, t: { de: { q: "Wer frisst mehr Kilo Futter am Tag?", a: ["Panda", "Tiger"], x: "Ein Panda frisst täglich 12 bis 38 kg Bambus, weil der kaum Energie liefert. Ein Tiger kommt im Schnitt mit 5 bis 7 kg Fleisch am Tag aus.", k: "Panda: frisst bis zu 38 kg Bambus am Tag" }, en: { q: "Who eats more kilos of food a day?", a: ["Panda", "Tiger"], x: "A panda eats 12 to 38 kg of bamboo a day because it provides so little energy. A tiger gets by on 5 to 7 kg of meat a day on average.", k: "Panda: eats up to 38 kg of bamboo a day" }, fr: { q: "Qui mange le plus de kilos par jour ?", a: ["Panda", "Tigre"], x: "Un panda mange 12 à 38 kg de bambou par jour, car il apporte très peu d’énergie. Un tigre se contente en moyenne de 5 à 7 kg de viande par jour.", k: "Panda : jusqu’à 38 kg de bambou par jour" }, es: { q: "¿Quién come más kilos al día?", a: ["Panda", "Tigre"], x: "Un panda come de 12 a 38 kg de bambú al día, porque aporta muy poca energía. Un tigre se arregla con 5 a 7 kg de carne al día de media.", k: "Panda: hasta 38 kg de bambú al día" }, pt: { q: "Quem come mais quilos por dia?", a: ["Panda", "Tigre"], x: "Um panda come de 12 a 38 kg de bambu por dia, porque ele dá muito pouca energia. Um tigre se vira, em média, com 5 a 7 kg de carne por dia.", k: "Panda: até 38 kg de bambu por dia" }, ja: { q: "1日に食べる量（キロ）が多いのはどっち？", a: ["パンダ", "トラ"], x: "パンダは1日に12〜38キロの竹を食べます。竹はエネルギーが少ないからです。トラは平均すると1日5〜7キロの肉で足ります。", k: "パンダ：1日最大38キロの竹を食べる" }, it: { q: "Chi mangia più chili di cibo al giorno?", a: ["Panda", "Tigre"], x: "Un panda mangia 12–38 kg di bambù al giorno, perché dà pochissima energia. A una tigre bastano in media 5–7 kg di carne al giorno.", k: "Panda: fino a 38 kg di bambù al giorno" } } },
  { id: "e12", lvl: 2, type: "duel", right: 0, t: { de: { q: "Wer riecht mit der Zunge?", a: ["Eidechse", "Frosch"], x: "Eidechsen züngeln, um Duftteilchen aufzunehmen, und bringen sie zu einem Riechorgan im Gaumen. Frösche fangen mit der Zunge nur Beute.", k: "Eidechsen: riechen mit der Zunge" }, en: { q: "Who smells with its tongue?", a: ["Lizard", "Frog"], x: "Lizards flick their tongue to pick up scent particles and carry them to a smell organ in the roof of the mouth. Frogs only use their tongue to catch prey.", k: "Lizards: smell with their tongue" }, fr: { q: "Qui sent avec sa langue ?", a: ["Lézard", "Grenouille"], x: "Le lézard sort la langue pour capter des odeurs et les porte à un organe olfactif dans le palais. La grenouille ne s’en sert que pour attraper ses proies.", k: "Lézards : sentent avec la langue" }, es: { q: "¿Quién huele con la lengua?", a: ["Lagartija", "Rana"], x: "Las lagartijas sacan la lengua para captar olores y los llevan a un órgano olfativo en el paladar. Las ranas solo la usan para cazar.", k: "Lagartos: huelen con la lengua" }, pt: { q: "Quem cheira com a língua?", a: ["Lagarto", "Rã"], x: "Os lagartos põem a língua para fora para captar cheiros e os levam a um órgão do olfato no céu da boca. As rãs usam a língua só para caçar.", k: "Lagartos: sentem cheiro com a língua" }, ja: { q: "舌でにおいをかぐのはどっち？", a: ["トカゲ", "カエル"], x: "トカゲは舌をチロチロ出してにおいの粒をつかまえ、口の天井にあるにおいの器官へ運びます。カエルは舌を獲物をとるためだけに使います。", k: "トカゲ：舌でにおいをかぐ" }, it: { q: "Chi sente gli odori con la lingua?", a: ["Lucertola", "Rana"], x: "Le lucertole guizzano la lingua per raccogliere particelle di odore e portarle a un organo olfattivo nel palato. Le rane usano la lingua solo per catturare le prede.", k: "Lucertole: annusano con la lingua" } } },
  { id: "e13", lvl: 1, type: "duel", right: 0, t: { de: { q: "Wer atmet auch durch die Haut?", a: ["Frosch", "Eidechse"], x: "Frösche nehmen über ihre dünne, feuchte Haut Sauerstoff auf – im Winter am Teichgrund fast nur so. Eidechsen haben trockene Schuppenhaut.", k: "Frösche: atmen auch durch die Haut" }, en: { q: "Who also breathes through its skin?", a: ["Frog", "Lizard"], x: "Frogs take in oxygen through their thin, moist skin – in winter at the bottom of a pond almost only this way. Lizards have dry, scaly skin.", k: "Frogs: also breathe through their skin" }, fr: { q: "Qui respire aussi par la peau ?", a: ["Grenouille", "Lézard"], x: "La grenouille absorbe de l’oxygène par sa peau fine et humide – en hiver, au fond de la mare, presque uniquement ainsi. Le lézard a une peau sèche à écailles.", k: "Grenouilles : respirent aussi par la peau" }, es: { q: "¿Quién respira también por la piel?", a: ["Rana", "Lagartija"], x: "Las ranas absorben oxígeno por su piel fina y húmeda; en invierno, en el fondo del estanque, casi solo así. Las lagartijas tienen piel seca con escamas.", k: "Ranas: también respiran por la piel" }, pt: { q: "Quem também respira pela pele?", a: ["Rã", "Lagarto"], x: "As rãs absorvem oxigênio pela pele fina e úmida; no inverno, no fundo do lago, quase só assim. Os lagartos têm pele seca com escamas.", k: "Rãs: também respiram pela pele" }, ja: { q: "皮ふでも呼吸するのはどっち？", a: ["カエル", "トカゲ"], x: "カエルはうすくしめった皮ふから酸素をとり入れます。冬の池の底では、ほぼ皮ふだけで呼吸します。トカゲの皮ふはかわいたうろこです。", k: "カエル：皮ふでも呼吸する" }, it: { q: "Chi respira anche con la pelle?", a: ["Rana", "Lucertola"], x: "Le rane assorbono ossigeno dalla pelle sottile e umida; d’inverno, sul fondo dello stagno, quasi solo così. Le lucertole hanno la pelle secca e squamosa.", k: "Rane: respirano anche con la pelle" } } },
  { id: "e15", lvl: 1, type: "duel", right: 1, t: { de: { q: "Wer sieht ultraviolettes Licht?", a: ["Braunbär", "Biene"], x: "Bienen sehen UV-Licht. Viele Blüten haben UV-Muster, die wie Landebahnen zum Nektar führen – für uns unsichtbar.", k: "Bienen: sehen UV-Licht" }, en: { q: "Who can see ultraviolet light?", a: ["Brown bear", "Bee"], x: "Bees see UV light. Many flowers have UV patterns that lead to the nectar like runways – invisible to us.", k: "Bees: see UV light" }, fr: { q: "Qui voit la lumière ultraviolette ?", a: ["Ours brun", "Abeille"], x: "Les abeilles voient les UV. Beaucoup de fleurs ont des motifs UV qui mènent au nectar comme des pistes d’atterrissage – invisibles pour nous.", k: "Abeilles : voient les UV" }, es: { q: "¿Quién ve la luz ultravioleta?", a: ["Oso pardo", "Abeja"], x: "Las abejas ven la luz UV. Muchas flores tienen dibujos UV que llevan al néctar como pistas de aterrizaje, invisibles para nosotros.", k: "Abejas: ven la luz UV" }, pt: { q: "Quem enxerga a luz ultravioleta?", a: ["Urso-pardo", "Abelha"], x: "As abelhas veem a luz UV. Muitas flores têm desenhos em UV que levam ao néctar como pistas de pouso – invisíveis para nós.", k: "Abelhas: enxergam luz UV" }, ja: { q: "紫外線が見えるのはどっち？", a: ["ヒグマ", "ミツバチ"], x: "ミツバチには紫外線が見えます。多くの花には、蜜まで導く滑走路のような紫外線の模様があります。私たちには見えません。", k: "ミツバチ：紫外線が見える" }, it: { q: "Chi vede la luce ultravioletta?", a: ["Orso bruno", "Ape"], x: "Le api vedono la luce UV. Molti fiori hanno disegni UV che portano al nettare come piste di atterraggio, invisibili per noi.", k: "Api: vedono la luce UV" } } },
  { id: "e16", lvl: 2, type: "duel", right: 0, t: { de: { q: "Wer hat mehr Augen?", a: ["Biene", "Krabbe"], x: "Bienen haben zwei große Facettenaugen und drei kleine Punktaugen oben auf dem Kopf – zusammen fünf. Krabben haben zwei Stielaugen.", k: "Bienen: haben fünf Augen" }, en: { q: "Who has more eyes?", a: ["Bee", "Crab"], x: "Bees have two large compound eyes and three small simple eyes on top of the head – five in total. Crabs have two eyes on stalks.", k: "Bees: have five eyes" }, fr: { q: "Qui a le plus d’yeux ?", a: ["Abeille", "Crabe"], x: "L’abeille a deux grands yeux à facettes et trois petits ocelles sur le dessus de la tête – cinq en tout. Le crabe a deux yeux pédonculés.", k: "Abeilles : ont cinq yeux" }, es: { q: "¿Quién tiene más ojos?", a: ["Abeja", "Cangrejo"], x: "Las abejas tienen dos grandes ojos compuestos y tres ojillos simples en lo alto de la cabeza: cinco en total. Los cangrejos tienen dos ojos con pedúnculo.", k: "Abejas: tienen cinco ojos" }, pt: { q: "Quem tem mais olhos?", a: ["Abelha", "Caranguejo"], x: "As abelhas têm dois grandes olhos compostos e três olhinhos simples no alto da cabeça – cinco no total. Os caranguejos têm dois olhos em pedúnculos.", k: "Abelhas: têm cinco olhos" }, ja: { q: "目が多いのはどっち？", a: ["ミツバチ", "カニ"], x: "ミツバチには大きな複眼が2つと、頭の上に小さな単眼が3つ。全部で5つです。カニの目は柄の先についた2つです。", k: "ミツバチ：目が5つある" }, it: { q: "Chi ha più occhi?", a: ["Ape", "Granchio"], x: "Le api hanno due grandi occhi composti e tre piccoli occhi semplici sulla testa: cinque in tutto. I granchi hanno due occhi su peduncoli.", k: "Api: hanno cinque occhi" } } },
  { id: "e17", lvl: 3, type: "duel", right: 0, t: { de: { q: "Wer legt mehr Eier auf einmal?", a: ["Krake", "Schildkröte"], x: "Ein Krakenweibchen legt bis zu Hunderttausende Eier und bewacht sie wochenlang, ohne zu fressen. Meeresschildkröten legen etwa 100 Eier pro Gelege.", k: "Krake: legt Hunderttausende Eier" }, en: { q: "Who lays more eggs at once?", a: ["Octopus", "Turtle"], x: "A female octopus lays up to hundreds of thousands of eggs and guards them for weeks without eating. Sea turtles lay about 100 eggs per clutch.", k: "Octopus: lays hundreds of thousands of eggs" }, fr: { q: "Qui pond le plus d’œufs en une fois ?", a: ["Pieuvre", "Tortue"], x: "Une pieuvre femelle pond jusqu’à des centaines de milliers d’œufs et les garde des semaines sans manger. Les tortues marines pondent environ 100 œufs par ponte.", k: "Pieuvre : pond des centaines de milliers d’œufs" }, es: { q: "¿Quién pone más huevos de una vez?", a: ["Pulpo", "Tortuga"], x: "Una hembra de pulpo pone hasta cientos de miles de huevos y los vigila durante semanas sin comer. Las tortugas marinas ponen unos 100 huevos por puesta.", k: "Pulpo: pone cientos de miles de huevos" }, pt: { q: "Quem põe mais ovos de uma vez?", a: ["Polvo", "Tartaruga"], x: "Uma fêmea de polvo põe até centenas de milhares de ovos e os vigia por semanas sem comer. As tartarugas marinhas põem cerca de 100 ovos por ninhada.", k: "Polvo: põe centenas de milhares de ovos" }, ja: { q: "一度に産む卵が多いのはどっち？", a: ["タコ", "ウミガメ"], x: "メスのタコは数十万個もの卵を産み、何週間も何も食べずに守ります。ウミガメは1回に約100個です。", k: "タコ：数十万個の卵を産む" }, it: { q: "Chi depone più uova in una volta?", a: ["Polpo", "Tartaruga marina"], x: "Una femmina di polpo depone fino a centinaia di migliaia di uova e le sorveglia per settimane senza mangiare. Le tartarughe marine ne depongono circa 100 per covata.", k: "Polpo: depone centinaia di migliaia di uova" } } },
  { id: "e18", lvl: 3, type: "duel", right: 0, t: { de: { q: "Wer wird älter?", a: ["Grönlandhai", "Papagei"], x: "Grönlandhaie können mehrere hundert Jahre alt werden – sie sind die ältesten bekannten Wirbeltiere. Große Papageien schaffen 60 bis 80 Jahre.", k: "Grönlandhai: wird mehrere hundert Jahre alt" }, en: { q: "Who lives longer?", a: ["Greenland shark", "Parrot"], x: "Greenland sharks can live several hundred years – the oldest known vertebrates. Large parrots reach 60 to 80 years.", k: "Greenland shark: lives for centuries" }, fr: { q: "Qui vit le plus longtemps ?", a: ["Requin du Groenland", "Perroquet"], x: "Le requin du Groenland peut vivre plusieurs centaines d’années – c’est le plus vieux vertébré connu. Les grands perroquets atteignent 60 à 80 ans.", k: "Requin du Groenland : vit plusieurs siècles" }, es: { q: "¿Quién vive más?", a: ["Tiburón de Groenlandia", "Loro"], x: "El tiburón de Groenlandia puede vivir varios cientos de años: es el vertebrado más longevo conocido. Los loros grandes llegan a 60 u 80 años.", k: "Tiburón de Groenlandia: vive siglos" }, pt: { q: "Quem vive mais?", a: ["Tubarão-da-groenlândia", "Papagaio"], x: "O tubarão-da-groenlândia pode viver várias centenas de anos – é o vertebrado mais longevo conhecido. Os papagaios grandes chegam a 60 ou 80 anos.", k: "Tubarão-da-groenlândia: vive séculos" }, ja: { q: "長生きなのはどっち？", a: ["ニシオンデンザメ", "オウム"], x: "ニシオンデンザメは数百年生きることがあり、知られている中でいちばん長生きな脊椎動物です。大型のオウムは60〜80年です。", k: "ニシオンデンザメ：数百年生きる" }, it: { q: "Chi vive più a lungo?", a: ["Squalo della Groenlandia", "Pappagallo"], x: "Lo squalo della Groenlandia può vivere diversi secoli: è il vertebrato più longevo conosciuto. I grandi pappagalli arrivano a 60–80 anni.", k: "Squalo della Groenlandia: vive secoli" } } },
  { id: "e19", lvl: 2, type: "duel", right: 0, t: { de: { q: "Wen gab es zuerst auf der Erde?", a: ["Hai", "Schildkröte"], x: "Haie gibt es seit über 400 Millionen Jahren – länger als Bäume. Schildkröten erst seit etwa 220 Millionen Jahren.", k: "Haie: älter als Bäume" }, en: { q: "Who was on Earth first?", a: ["Shark", "Turtle"], x: "Sharks have existed for over 400 million years – longer than trees. Turtles only for about 220 million years.", k: "Sharks: older than trees" }, fr: { q: "Qui était sur Terre en premier ?", a: ["Requin", "Tortue"], x: "Les requins existent depuis plus de 400 millions d’années – plus longtemps que les arbres. Les tortues seulement depuis environ 220 millions d’années.", k: "Requins : plus anciens que les arbres" }, es: { q: "¿Quién llegó antes a la Tierra?", a: ["Tiburón", "Tortuga"], x: "Los tiburones existen desde hace más de 400 millones de años, más que los árboles. Las tortugas, solo desde hace unos 220 millones.", k: "Tiburones: más antiguos que los árboles" }, pt: { q: "Quem surgiu antes na Terra?", a: ["Tubarão", "Tartaruga"], x: "Os tubarões existem há mais de 400 milhões de anos – mais tempo que as árvores. As tartarugas, só há cerca de 220 milhões.", k: "Tubarões: mais antigos que as árvores" }, ja: { q: "地球に先に現れたのはどっち？", a: ["サメ", "カメ"], x: "サメは4億年以上前からいます。木よりも昔からです。カメは約2億2000万年前からです。", k: "サメ：木より昔からいる" }, it: { q: "Chi è comparso prima sulla Terra?", a: ["Squalo", "Tartaruga"], x: "Gli squali esistono da oltre 400 milioni di anni, più degli alberi. Le tartarughe solo da circa 220 milioni di anni.", k: "Squali: più antichi degli alberi" } } },
  { id: "e21", lvl: 2, type: "duel", right: 1, t: { de: { q: "Wer schwimmt schneller?", a: ["Fischotter", "Pinguin"], x: "Eselspinguine erreichen unter Wasser rund 35 km/h – schneller als jeder andere Vogel im Wasser. Ein Fischotter schwimmt gut 10 km/h.", k: "Eselspinguin: schwimmt 35 km/h schnell" }, en: { q: "Who swims faster?", a: ["Otter", "Penguin"], x: "Gentoo penguins reach about 35 km/h underwater – faster than any other bird in water. An otter swims a little over 10 km/h.", k: "Gentoo penguin: swims at 35 km/h" }, fr: { q: "Qui nage le plus vite ?", a: ["Loutre", "Manchot"], x: "Le manchot papou atteint environ 35 km/h sous l’eau – plus vite que tout autre oiseau dans l’eau. La loutre nage à un peu plus de 10 km/h.", k: "Manchot papou : nage à 35 km/h" }, es: { q: "¿Quién nada más rápido?", a: ["Nutria", "Pingüino"], x: "El pingüino papúa alcanza unos 35 km/h bajo el agua, más que cualquier otra ave en el agua. La nutria nada a algo más de 10 km/h.", k: "Pingüino papúa: nada a 35 km/h" }, pt: { q: "Quem nada mais rápido?", a: ["Lontra", "Pinguim"], x: "O pinguim-gentoo chega a uns 35 km/h debaixo d’água – mais que qualquer outra ave na água. A lontra nada a pouco mais de 10 km/h.", k: "Pinguim-gentoo: nada a 35 km/h" }, ja: { q: "泳ぐのが速いのはどっち？", a: ["カワウソ", "ペンギン"], x: "ジェンツーペンギンは水中で時速約35キロ。水中ではどの鳥よりも速いです。カワウソは時速10キロちょっとです。", k: "ジェンツーペンギン：時速35キロで泳ぐ" }, it: { q: "Chi nuota più veloce?", a: ["Lontra", "Pinguino"], x: "Il pinguino papua raggiunge sott’acqua circa 35 km/h, più di qualsiasi altro uccello in acqua. La lontra nuota a poco più di 10 km/h.", k: "Pinguino papua: nuota a 35 km/h" } } },
  { id: "e22", lvl: 2, type: "duel", right: 1, t: { de: { q: "Wer übersteht es, fast ganz einzufrieren?", a: ["Igel", "Frosch"], x: "Der nordamerikanische Waldfrosch friert im Winter zu zwei Dritteln ein, Herz und Atmung stehen still. Zucker in den Zellen schützt ihn, im Frühling taut er auf. Der Igel braucht ein frostfreies Nest.", k: "Waldfrosch: übersteht es, halb gefroren zu sein" }, en: { q: "Who can survive being almost frozen solid?", a: ["Hedgehog", "Frog"], x: "The North American wood frog freezes two-thirds solid in winter; its heart and breathing stop. Sugar in its cells protects it, and it thaws in spring. A hedgehog needs a frost-free nest.", k: "Wood frog: survives being half frozen" }, fr: { q: "Qui survit en gelant presque entièrement ?", a: ["Hérisson", "Grenouille"], x: "La grenouille des bois d’Amérique du Nord gèle aux deux tiers en hiver : son cœur et sa respiration s’arrêtent. Du sucre protège ses cellules et elle dégèle au printemps. Le hérisson a besoin d’un nid hors gel.", k: "Grenouille des bois : survit à moitié gelée" }, es: { q: "¿Quién sobrevive a congelarse casi por completo?", a: ["Erizo", "Rana"], x: "La rana de bosque norteamericana se congela en dos tercios en invierno: su corazón y su respiración se detienen. El azúcar protege sus células y en primavera se descongela. El erizo necesita un nido sin heladas.", k: "Rana de bosque: sobrevive medio congelada" }, pt: { q: "Quem sobrevive quase todo congelado?", a: ["Ouriço", "Rã"], x: "A rã-da-floresta da América do Norte congela em dois terços no inverno: o coração e a respiração param. O açúcar protege suas células, e na primavera ela descongela. O ouriço precisa de um ninho sem geada.", k: "Rã-da-floresta: sobrevive meio congelada" }, ja: { q: "ほとんどカチコチに凍っても生きのびられるのはどっち？", a: ["ハリネズミ", "カエル"], x: "北アメリカのアメリカアカガエルは、冬に体の3分の2が凍り、心臓も呼吸も止まります。細胞の中の糖が体を守り、春にとけて元にもどります。ハリネズミには凍らない巣が必要です。", k: "アメリカアカガエル：半分凍っても生きのびる" }, it: { q: "Chi sopravvive anche quasi completamente congelato?", a: ["Riccio", "Rana"], x: "La rana dei boschi nordamericana d’inverno congela per due terzi; cuore e respiro si fermano. Lo zucchero nelle cellule la protegge e in primavera si scongela. Il riccio ha bisogno di un nido al riparo dal gelo.", k: "Rana dei boschi: sopravvive mezza congelata" } } },
  { id: "e23", lvl: 1, type: "duel", right: 1, t: { de: { q: "Wer stammt von den Dinosauriern ab?", a: ["Eidechse", "Papagei"], x: "Vögel sind die heute lebenden Dinosaurier. Eidechsen sehen urzeitlich aus, sind aber nur entfernte Verwandte.", k: "Vögel: die Dinosaurier von heute" }, en: { q: "Who descends from dinosaurs?", a: ["Lizard", "Parrot"], x: "Birds are the dinosaurs living today. Lizards look prehistoric but are only distant relatives.", k: "Birds: today's dinosaurs" }, fr: { q: "Qui descend des dinosaures ?", a: ["Lézard", "Perroquet"], x: "Les oiseaux sont les dinosaures d’aujourd’hui. Les lézards ont l’air préhistoriques mais ne sont que des cousins éloignés.", k: "Oiseaux : les dinosaures d’aujourd’hui" }, es: { q: "¿Quién desciende de los dinosaurios?", a: ["Lagartija", "Loro"], x: "Las aves son los dinosaurios que viven hoy. Las lagartijas parecen prehistóricas, pero solo son parientes lejanas.", k: "Aves: los dinosaurios de hoy" }, pt: { q: "Quem descende dos dinossauros?", a: ["Lagarto", "Papagaio"], x: "As aves são os dinossauros que vivem hoje. Os lagartos parecem pré-históricos, mas são só parentes distantes.", k: "Aves: os dinossauros de hoje" }, ja: { q: "恐竜の子孫はどっち？", a: ["トカゲ", "オウム"], x: "鳥は今も生きている恐竜です。トカゲは大昔の生きものに見えますが、遠い親せきにすぎません。", k: "鳥：いまを生きる恐竜" }, it: { q: "Chi discende dai dinosauri?", a: ["Lucertola", "Pappagallo"], x: "Gli uccelli sono i dinosauri di oggi. Le lucertole sembrano preistoriche, ma sono solo parenti lontane.", k: "Uccelli: i dinosauri di oggi" } } },
  { id: "e25", lvl: 1, type: "duel", right: 0, t: { de: { q: "Wer ist an Land schneller?", a: ["Tiger", "Panda"], x: "Tiger sprinten kurz 50 bis 65 km/h. Pandas schaffen im Notfall etwa 30 km/h.", k: "Tiger: sprintet bis 65 km/h" }, en: { q: "Who is faster on land?", a: ["Tiger", "Panda"], x: "Tigers sprint at 50 to 65 km/h for short distances. Pandas manage about 30 km/h when they have to.", k: "Tiger: sprints up to 65 km/h" }, fr: { q: "Qui est le plus rapide sur terre ?", a: ["Tigre", "Panda"], x: "Le tigre sprinte à 50 à 65 km/h sur de courtes distances. Le panda atteint environ 30 km/h en cas d’urgence.", k: "Tigre : sprinte jusqu’à 65 km/h" }, es: { q: "¿Quién es más rápido en tierra?", a: ["Tigre", "Panda"], x: "El tigre esprinta a 50 o 65 km/h en distancias cortas. El panda llega a unos 30 km/h si hace falta.", k: "Tigre: esprinta hasta 65 km/h" }, pt: { q: "Quem é mais rápido em terra?", a: ["Tigre", "Panda"], x: "O tigre corre a 50 ou 65 km/h em distâncias curtas. O panda chega a uns 30 km/h, se precisar.", k: "Tigre: corre até 65 km/h" }, ja: { q: "陸上で速いのはどっち？", a: ["トラ", "パンダ"], x: "トラは短い距離なら時速50〜65キロで走ります。パンダはいざとなれば時速約30キロです。", k: "トラ：時速65キロでダッシュ" }, it: { q: "Chi è più veloce sulla terraferma?", a: ["Tigre", "Panda"], x: "Le tigri scattano a 50–65 km/h su brevi distanze. I panda, se serve, arrivano a circa 30 km/h.", k: "Tigre: scatta fino a 65 km/h" } } },
  { id: "e26", lvl: 2, type: "duel", right: 0, t: { de: { q: "Wer trägt seine Eier im Maul, bis die Jungen schlüpfen?", a: ["Maulbrüter-Buntbarsch", "Karpfen"], x: "Bei vielen Buntbarschen nimmt ein Elternteil die Eier ins Maul und frisst so lange nichts. Auch die Jungen flüchten bei Gefahr noch zurück ins Maul. Karpfen legen ihre Eier einfach an Pflanzen ab.", k: "Maulbrüter: tragen die Eier im Maul" }, en: { q: "Who carries its eggs in its mouth until the young hatch?", a: ["Mouthbrooding cichlid", "Carp"], x: "In many cichlids one parent takes the eggs into its mouth and eats nothing all that time. Even the young flee back into the mouth when there’s danger. Carp simply lay their eggs on plants.", k: "Mouthbrooders: carry their eggs in their mouth" }, fr: { q: "Qui garde ses œufs dans la bouche jusqu’à l’éclosion ?", a: ["Cichlidé incubateur buccal", "Carpe"], x: "Chez beaucoup de cichlidés, un parent garde les œufs dans la bouche sans rien manger. Même les petits s’y réfugient en cas de danger. La carpe pond simplement sur les plantes.", k: "Incubateurs buccaux : gardent les œufs en bouche" }, es: { q: "¿Quién lleva sus huevos en la boca hasta que nacen las crías?", a: ["Cíclido incubador bucal", "Carpa"], x: "En muchos cíclidos, uno de los padres guarda los huevos en la boca sin comer nada. Las crías incluso vuelven a la boca si hay peligro. La carpa simplemente pone sus huevos en las plantas.", k: "Incubadores bucales: guardan los huevos en la boca" }, pt: { q: "Quem leva os ovos na boca até os filhotes nascerem?", a: ["Ciclídeo incubador bucal", "Carpa"], x: "Em muitos ciclídeos, um dos pais guarda os ovos na boca sem comer nada. Os filhotes até voltam para a boca se houver perigo. A carpa simplesmente põe os ovos nas plantas.", k: "Ciclídeos: guardam os ovos na boca" }, ja: { q: "子どもがかえるまで卵を口の中で守るのはどっち？", a: ["マウスブルーダーのシクリッド", "コイ"], x: "多くのシクリッドでは、親が卵を口に入れ、その間ずっと何も食べません。子どもも危ないときは口の中へ逃げこみます。コイは卵を水草に産みつけるだけです。", k: "マウスブルーダー：卵を口の中で守る" }, it: { q: "Chi tiene le uova in bocca finché i piccoli non nascono?", a: ["Ciclide incubatore orale", "Carpa"], x: "In molti ciclidi un genitore prende le uova in bocca e per tutto quel tempo non mangia. Anche i piccoli, in caso di pericolo, si rifugiano nella sua bocca. Le carpe depongono le uova sulle piante.", k: "Ciclidi incubatori: tengono le uova in bocca" } } },
  { id: "e30", lvl: 3, type: "duel", right: 1, t: { de: { q: "Bei wem steckt der Großteil der Nervenzellen in den Armen?", a: ["Papagei", "Krake"], x: "Rund zwei Drittel der Nervenzellen eines Kraken sitzen in seinen Armen. Jeder Arm kann so tasten, schmecken und greifen, fast wie mit eigenem Kopf.", k: "Krake: denkt zum großen Teil mit den Armen" }, en: { q: "Who has most of its nerve cells in its arms?", a: ["Parrot", "Octopus"], x: "About two-thirds of an octopus’s nerve cells are in its arms. Each arm can feel, taste and grab almost as if it had a mind of its own.", k: "Octopus: does much of its thinking in its arms" }, fr: { q: "Qui a la plupart de ses neurones dans les bras ?", a: ["Perroquet", "Pieuvre"], x: "Environ deux tiers des neurones de la pieuvre se trouvent dans ses bras. Chaque bras peut toucher, goûter et saisir presque comme s’il avait sa propre tête.", k: "Pieuvre : pense en grande partie avec ses bras" }, es: { q: "¿Quién tiene la mayoría de sus neuronas en los brazos?", a: ["Loro", "Pulpo"], x: "Unos dos tercios de las neuronas del pulpo están en sus brazos. Cada brazo puede tocar, saborear y agarrar casi como si tuviera cabeza propia.", k: "Pulpo: piensa en gran parte con los brazos" }, pt: { q: "Quem tem a maioria dos neurônios nos braços?", a: ["Papagaio", "Polvo"], x: "Cerca de dois terços dos neurônios do polvo estão nos braços. Cada braço consegue tocar, sentir sabores e agarrar quase como se tivesse cabeça própria.", k: "Polvo: pensa em boa parte com os braços" }, ja: { q: "神経細胞の大部分が腕にあるのはどっち？", a: ["オウム", "タコ"], x: "タコの神経細胞の約3分の2は腕にあります。それぞれの腕が、まるで自分の考えをもっているかのように、さわり、味わい、つかみます。", k: "タコ：考えの多くを腕でする" }, it: { q: "Chi ha la maggior parte dei neuroni nelle braccia?", a: ["Pappagallo", "Polpo"], x: "Circa due terzi dei neuroni di un polpo sono nelle braccia. Ogni braccio può sentire, gustare e afferrare quasi come se avesse una testa sua.", k: "Polpo: pensa in gran parte con le braccia" } } },
  { id: "e31", lvl: 2, type: "duel", right: 0, t: { de: { q: "Wer ist schwerer?", a: ["Giraffe", "Braunbär"], x: "Eine ausgewachsene Giraffe wiegt 800 bis 1.200 kg. Selbst sehr große Braunbären bringen meist deutlich weniger auf die Waage.", k: "Giraffe: wiegt bis zu 1.200 kg" }, en: { q: "Who is heavier?", a: ["Giraffe", "Brown bear"], x: "An adult giraffe weighs 800 to 1,200 kg. Even very big brown bears usually weigh a lot less.", k: "Giraffe: weighs up to 1,200 kg" }, fr: { q: "Qui est le plus lourd ?", a: ["Girafe", "Ours brun"], x: "Une girafe adulte pèse 800 à 1 200 kg. Même les très grands ours bruns pèsent en général bien moins.", k: "Girafe : jusqu’à 1 200 kg" }, es: { q: "¿Quién pesa más?", a: ["Jirafa", "Oso pardo"], x: "Una jirafa adulta pesa de 800 a 1.200 kg. Incluso los osos pardos muy grandes suelen pesar bastante menos.", k: "Jirafa: hasta 1.200 kg" }, pt: { q: "Quem pesa mais?", a: ["Girafa", "Urso-pardo"], x: "Uma girafa adulta pesa de 800 a 1.200 kg. Mesmo ursos-pardos muito grandes costumam pesar bem menos.", k: "Girafa: até 1.200 kg" }, ja: { q: "重いのはどっち？", a: ["キリン", "ヒグマ"], x: "大人のキリンは800〜1200キロ。とても大きなヒグマでも、ふつうはずっと軽いです。", k: "キリン：最大1200キロ" }, it: { q: "Chi è più pesante?", a: ["Giraffa", "Orso bruno"], x: "Una giraffa adulta pesa 800–1.200 kg. Anche gli orsi bruni molto grandi di solito pesano molto meno.", k: "Giraffa: fino a 1.200 kg" } } },
  { id: "e32", lvl: 1, type: "duel", right: 1, t: { de: { q: "Wer lebt in einem Volk mit Tausenden Geschwistern?", a: ["Marienkäfer", "Biene"], x: "Ein Honigbienenvolk hat im Sommer 30.000 bis 50.000 Bienen, fast alle Töchter der einen Königin. Marienkäfer leben allein.", k: "Bienenvolk: bis zu 50.000 Schwestern" }, en: { q: "Who lives in a colony with thousands of siblings?", a: ["Ladybird", "Bee"], x: "In summer, a honeybee colony has 30,000 to 50,000 bees, almost all daughters of the one queen. Ladybirds live alone.", k: "Bee colony: up to 50,000 sisters" }, fr: { q: "Qui vit dans une colonie avec des milliers de frères et sœurs ?", a: ["Coccinelle", "Abeille"], x: "En été, une colonie d’abeilles compte 30 000 à 50 000 abeilles, presque toutes filles de l’unique reine. La coccinelle vit seule.", k: "Colonie d’abeilles : jusqu’à 50 000 sœurs" }, es: { q: "¿Quién vive en una colonia con miles de hermanas?", a: ["Mariquita", "Abeja"], x: "En verano, una colmena tiene de 30.000 a 50.000 abejas, casi todas hijas de la única reina. Las mariquitas viven solas.", k: "Colmena: hasta 50.000 hermanas" }, pt: { q: "Quem vive em uma colônia com milhares de irmãs?", a: ["Joaninha", "Abelha"], x: "No verão, uma colmeia tem de 30.000 a 50.000 abelhas, quase todas filhas da única rainha. As joaninhas vivem sozinhas.", k: "Colmeia: até 50.000 irmãs" }, ja: { q: "何千匹もの姉妹と一緒に暮らすのはどっち？", a: ["テントウムシ", "ミツバチ"], x: "夏のミツバチの巣には3万〜5万匹。ほぼ全員が1匹の女王バチの娘です。テントウムシは単独で暮らします。", k: "ミツバチの巣：最大5万匹の姉妹" }, it: { q: "Chi vive in una colonia con migliaia di sorelle?", a: ["Coccinella", "Ape"], x: "D’estate un alveare ha 30.000–50.000 api, quasi tutte figlie dell’unica regina. Le coccinelle vivono da sole.", k: "Alveare: fino a 50.000 sorelle" } } },
  { id: "e33", lvl: 2, type: "duel", right: 1, t: { de: { q: "Wessen Herz schlägt schneller?", a: ["Braunbär", "Igel"], x: "Kleine Tiere haben ein schnelles Herz: Beim wachen Igel schlägt es rund 200-mal pro Minute, beim Bären nur etwa 40- bis 50-mal.", k: "Igel: Herz schlägt 200-mal pro Minute" }, en: { q: "Whose heart beats faster?", a: ["Brown bear", "Hedgehog"], x: "Small animals have fast hearts: an awake hedgehog’s heart beats about 200 times a minute, a bear’s only about 40 to 50 times.", k: "Hedgehog: heart beats 200 times a minute" }, fr: { q: "Quel cœur bat le plus vite ?", a: ["Ours brun", "Hérisson"], x: "Les petits animaux ont un cœur rapide : celui du hérisson éveillé bat environ 200 fois par minute, celui de l’ours seulement 40 à 50 fois.", k: "Hérisson : cœur à 200 battements par minute" }, es: { q: "¿Qué corazón late más rápido?", a: ["Oso pardo", "Erizo"], x: "Los animales pequeños tienen el corazón rápido: el del erizo despierto late unas 200 veces por minuto; el del oso, solo unas 40 o 50.", k: "Erizo: corazón a 200 latidos por minuto" }, pt: { q: "Qual coração bate mais rápido?", a: ["Urso-pardo", "Ouriço"], x: "Animais pequenos têm o coração rápido: o do ouriço acordado bate cerca de 200 vezes por minuto; o do urso, só 40 ou 50.", k: "Ouriço: coração a 200 batidas por minuto" }, ja: { q: "心臓が速く打つのはどっち？", a: ["ヒグマ", "ハリネズミ"], x: "小さな動物は心臓が速い。起きているハリネズミは1分に約200回、クマはたった40〜50回ほどです。", k: "ハリネズミ：心臓は1分に200回" }, it: { q: "Il cuore di chi batte più veloce?", a: ["Orso bruno", "Riccio"], x: "Gli animali piccoli hanno il cuore veloce: quello di un riccio sveglio batte circa 200 volte al minuto, quello di un orso solo 40–50.", k: "Riccio: cuore a 200 battiti al minuto" } } },
  { id: "e34", lvl: 1, type: "duel", right: 0, t: { de: { q: "Wer sieht in der Dämmerung besser?", a: ["Eule", "Adler"], x: "Eulenaugen haben besonders viele Stäbchen – Sinneszellen für schwaches Licht. Adler sehen dafür am Tag schärfer.", k: "Eulen: sehen in der Dämmerung am besten" }, en: { q: "Who sees better at dusk?", a: ["Owl", "Eagle"], x: "Owl eyes have a great many rods – sensory cells for dim light. Eagles, on the other hand, see more sharply by day.", k: "Owls: see best at dusk" }, fr: { q: "Qui voit le mieux au crépuscule ?", a: ["Chouette", "Aigle"], x: "Les yeux de la chouette ont énormément de bâtonnets – des cellules pour la faible lumière. L’aigle, lui, voit plus net le jour.", k: "Chouettes : voient le mieux au crépuscule" }, es: { q: "¿Quién ve mejor al anochecer?", a: ["Búho", "Águila"], x: "Los ojos del búho tienen muchísimos bastones, células para la luz tenue. El águila, en cambio, ve con más nitidez de día.", k: "Búhos: ven mejor al anochecer" }, pt: { q: "Quem enxerga melhor ao anoitecer?", a: ["Coruja", "Águia"], x: "Os olhos da coruja têm muitíssimos bastonetes, células para a luz fraca. A águia, por outro lado, enxerga com mais nitidez de dia.", k: "Corujas: enxergam melhor ao anoitecer" }, ja: { q: "夕暮れによく見えるのはどっち？", a: ["フクロウ", "ワシ"], x: "フクロウの目には、暗い光を感じる細胞（桿体）がとてもたくさんあります。ワシは昼間にくっきり見えるタイプです。", k: "フクロウ：夕暮れにいちばんよく見える" }, it: { q: "Chi vede meglio al crepuscolo?", a: ["Gufo", "Aquila"], x: "Gli occhi dei gufi hanno moltissimi bastoncelli, le cellule per la luce debole. Le aquile invece vedono più nitido di giorno.", k: "Gufi: vedono meglio al crepuscolo" } } },
  { id: "e35", lvl: 1, type: "duel", right: 0, t: { de: { q: "Wer wird älter?", a: ["Schildkröte", "Braunbär"], x: "Viele Landschildkröten werden 50 bis über 100 Jahre alt. Braunbären erreichen in freier Natur meist 20 bis 30 Jahre.", k: "Landschildkröten: werden über 100 Jahre alt" }, en: { q: "Who lives longer?", a: ["Turtle", "Brown bear"], x: "Many tortoises live 50 to over 100 years. Brown bears in the wild usually reach 20 to 30 years.", k: "Tortoises: live over 100 years" }, fr: { q: "Qui vit le plus longtemps ?", a: ["Tortue", "Ours brun"], x: "Beaucoup de tortues terrestres vivent de 50 à plus de 100 ans. L’ours brun atteint en général 20 à 30 ans dans la nature.", k: "Tortues terrestres : vivent plus de 100 ans" }, es: { q: "¿Quién vive más?", a: ["Tortuga", "Oso pardo"], x: "Muchas tortugas terrestres viven de 50 a más de 100 años. Los osos pardos en libertad suelen llegar a 20 o 30 años.", k: "Tortugas terrestres: viven más de 100 años" }, pt: { q: "Quem vive mais?", a: ["Tartaruga", "Urso-pardo"], x: "Muitas tartarugas terrestres vivem de 50 a mais de 100 anos. Os ursos-pardos na natureza costumam chegar a 20 ou 30 anos.", k: "Tartarugas terrestres: vivem mais de 100 anos" }, ja: { q: "長生きなのはどっち？", a: ["カメ", "ヒグマ"], x: "リクガメの多くは50年から100年以上生きます。野生のヒグマはふつう20〜30年です。", k: "リクガメ：100年以上生きる" }, it: { q: "Chi vive più a lungo?", a: ["Tartaruga", "Orso bruno"], x: "Molte tartarughe terrestri vivono da 50 a oltre 100 anni. Gli orsi bruni in natura arrivano di solito a 20–30 anni.", k: "Tartarughe terrestri: vivono oltre 100 anni" } } },
  { id: "e36", lvl: 1, type: "duel", right: 1, t: { de: { q: "Wer kann blitzschnell seine Farbe wechseln?", a: ["Papagei", "Krake"], x: "Kraken haben Tausende Farbzellen in der Haut, die sie in Sekundenbruchteilen öffnen und schließen – zum Tarnen und um Stimmung zu zeigen.", k: "Krake: wechselt die Farbe in Sekundenbruchteilen" }, en: { q: "Who can change colour in a flash?", a: ["Parrot", "Octopus"], x: "Octopuses have thousands of colour cells in their skin that they open and close in a fraction of a second – to hide and to show their mood.", k: "Octopus: changes colour in a split second" }, fr: { q: "Qui peut changer de couleur en un éclair ?", a: ["Perroquet", "Pieuvre"], x: "La pieuvre a des milliers de cellules colorées dans la peau qu’elle ouvre et ferme en une fraction de seconde – pour se camoufler et montrer son humeur.", k: "Pieuvre : change de couleur en un éclair" }, es: { q: "¿Quién cambia de color en un instante?", a: ["Loro", "Pulpo"], x: "El pulpo tiene miles de células de color en la piel que abre y cierra en una fracción de segundo, para camuflarse y mostrar su humor.", k: "Pulpo: cambia de color en un instante" }, pt: { q: "Quem muda de cor num instante?", a: ["Papagaio", "Polvo"], x: "O polvo tem milhares de células de cor na pele, que abre e fecha em uma fração de segundo – para se camuflar e mostrar o humor.", k: "Polvo: muda de cor num instante" }, ja: { q: "一瞬で体の色を変えられるのはどっち？", a: ["オウム", "タコ"], x: "タコの皮ふには何千もの色の細胞があり、一瞬で開いたり閉じたりします。かくれたり、気分を表したりするためです。", k: "タコ：一瞬で体の色を変える" }, it: { q: "Chi cambia colore in un lampo?", a: ["Pappagallo", "Polpo"], x: "I polpi hanno nella pelle migliaia di cellule colorate che aprono e chiudono in una frazione di secondo, per nascondersi e mostrare il loro umore.", k: "Polpo: cambia colore in un lampo" } } },
  { id: "b01", lvl: 2, type: "text", right: 2, t: { de: { q: "Wie überwintert der Zitronenfalter?", a: ["Als Raupe im Boden", "Als Puppe an einem Zweig", "Als Falter frei im Gebüsch", "Er zieht in den Süden"], x: "Er überwintert ungeschützt zwischen Blättern. Ein körpereigenes Frostschutzmittel bewahrt ihn vor dem Erfrieren.", k: "Zitronenfalter: überwintert ungeschützt im Freien" }, en: { q: "How does the brimstone butterfly survive winter?", a: ["As a caterpillar in the soil", "As a pupa on a twig", "As an adult, unsheltered in shrubs", "It migrates south"], x: "It overwinters unprotected among leaves. A natural antifreeze in its body keeps it from freezing.", k: "Brimstone: overwinters unsheltered outdoors" }, fr: { q: "Comment le papillon Citron passe-t-il l'hiver ?", a: ["En chenille dans le sol", "En chrysalide sur une branche", "En papillon, à découvert", "Il migre vers le sud"], x: "Il hiverne sans abri parmi les feuilles. Un antigel naturel dans son corps l'empêche de geler.", k: "Citron : hiverne à l’air libre" }, es: { q: "¿Cómo pasa el invierno la mariposa limonera?", a: ["Como oruga en el suelo", "Como crisálida en una rama", "Como adulta, al aire libre", "Migra hacia el sur"], x: "Hiberna sin refugio entre las hojas. Un anticongelante natural en su cuerpo evita que se congele.", k: "Limonera: inverna al aire libre" }, pt: { q: "Como a borboleta-limão passa o inverno?", a: ["Como lagarta no chão", "Como crisálida num galho", "Como adulta, ao ar livre", "Migra para o sul"], x: "Ela hiberna sem abrigo entre as folhas. Um anticongelante natural no corpo impede que congele.", k: "Borboleta-limão: passa o inverno ao ar livre" }, ja: { q: "ヤマキチョウはどうやって冬を越す？", a: ["幼虫で土の中", "さなぎで枝の上", "成虫のまま、むき出しで茂みの中", "南へ渡る"], x: "葉っぱの間で、何にも守られずに冬を越します。体の中の天然の不凍液が、凍るのを防いでいます。", k: "ヤマキチョウ：むき出しで冬を越す" }, it: { q: "Come passa l’inverno la cedronella?", a: ["Da bruco nel terreno", "Da crisalide su un ramo", "Da adulta, allo scoperto tra i cespugli", "Migra a sud"], x: "Sverna senza riparo tra le foglie. Un antigelo naturale nel corpo le impedisce di congelare.", k: "Cedronella: sverna all’aperto" } } },
  { id: "b02", lvl: 1, type: "text", right: 1, t: { de: { q: "Wie lange leben Maikäfer-Larven (Engerlinge) im Boden?", a: ["Etwa 2 Wochen", "Mehrere Jahre", "Nur einen Sommer", "Rund 20 Jahre"], x: "Je nach Klima fressen Engerlinge 3 bis 5 Jahre lang Wurzeln. Der fertige Käfer lebt dann nur wenige Wochen.", k: "Maikäfer-Larven: leben 3 bis 5 Jahre im Boden" }, en: { q: "How long do cockchafer larvae (grubs) live in the soil?", a: ["About 2 weeks", "Several years", "Just one summer", "Around 20 years"], x: "Depending on climate, grubs feed on roots for 3 to 5 years. The adult beetle then lives only a few weeks.", k: "Cockchafer grubs: live 3 to 5 years in the soil" }, fr: { q: "Combien de temps les larves de hanneton (vers blancs) vivent-elles dans le sol ?", a: ["Environ 2 semaines", "Plusieurs années", "Un seul été", "Environ 20 ans"], x: "Selon le climat, les vers blancs mangent des racines pendant 3 à 5 ans. L'adulte ne vit ensuite que quelques semaines.", k: "Larves de hanneton : 3 à 5 ans dans le sol" }, es: { q: "¿Cuánto tiempo viven en el suelo las larvas del escarabajo de mayo?", a: ["Unas 2 semanas", "Varios años", "Solo un verano", "Unos 20 años"], x: "Según el clima, las larvas comen raíces durante 3 a 5 años. El escarabajo adulto vive después solo unas semanas.", k: "Larvas de abejorro sanjuanero: 3 a 5 años bajo tierra" }, pt: { q: "Quanto tempo as larvas do besouro-de-maio vivem no solo?", a: ["Umas 2 semanas", "Vários anos", "Só um verão", "Uns 20 anos"], x: "Conforme o clima, as larvas comem raízes por 3 a 5 anos. O besouro adulto vive depois só algumas semanas.", k: "Larvas de besouro-de-maio: 3 a 5 anos no solo" }, ja: { q: "コフキコガネの幼虫は土の中で何年くらい暮らす？", a: ["約2週間", "数年", "ひと夏だけ", "約20年"], x: "気候によって3〜5年、根を食べて育ちます。成虫になってからは数週間しか生きません。", k: "コフキコガネの幼虫：土の中で3〜5年" }, it: { q: "Quanto vivono nel terreno le larve del maggiolino?", a: ["Circa 2 settimane", "Diversi anni", "Una sola estate", "Circa 20 anni"], x: "A seconda del clima, le larve mangiano radici per 3–5 anni. Il maggiolino adulto poi vive solo poche settimane.", k: "Larve di maggiolino: 3–5 anni nel terreno" } } },
  { id: "b03", lvl: 1, type: "tf", right: 1, t: { de: { q: "Zecken lassen sich meist von Bäumen auf Menschen und Tiere fallen.", a: ["Wahr", "Falsch"], x: "Ein Mythos: Zecken lauern meist in Gras und Büschen bis etwa 1 m Höhe und werden im Vorbeigehen abgestreift.", k: "Zecken: lauern im Gras, nicht auf Bäumen" }, en: { q: "Ticks usually drop onto people and animals from trees.", a: ["True", "False"], x: "A myth: ticks usually wait in grass and shrubs up to about 1 m high and get brushed off as you pass.", k: "Ticks: wait in grass, not in trees" }, fr: { q: "Les tiques se laissent généralement tomber des arbres sur les humains et les animaux.", a: ["Vrai", "Faux"], x: "Un mythe : les tiques attendent surtout dans l'herbe et les buissons jusqu'à 1 m environ et s'accrochent au passage.", k: "Tiques : attendent dans l’herbe, pas dans les arbres" }, es: { q: "Las garrapatas suelen dejarse caer desde los árboles sobre personas y animales.", a: ["Verdadero", "Falso"], x: "Es un mito: suelen esperar en la hierba y los arbustos hasta 1 m de altura y se enganchan al pasar.", k: "Garrapatas: esperan en la hierba, no en los árboles" }, pt: { q: "Os carrapatos costumam cair das árvores sobre pessoas e animais.", a: ["Verdadeiro", "Falso"], x: "É um mito: eles esperam na grama e nos arbustos até 1 m de altura e se agarram quando alguém passa.", k: "Carrapatos: esperam no capim, não nas árvores" }, ja: { q: "正しい？まちがい？ マダニはふつう木の上から人や動物に落ちてくる。", a: ["正しい", "まちがい"], x: "これは俗説。マダニはふつう高さ1メートルくらいまでの草や茂みで待ち、通りかかった人や動物にくっつきます。", k: "マダニ：木ではなく草むらで待つ" }, it: { q: "Vero o falso? Le zecche di solito cadono dagli alberi su persone e animali.", a: ["Vero", "Falso"], x: "Un mito: le zecche aspettano di solito nell’erba e nei cespugli fino a circa 1 m d’altezza e si attaccano a chi passa.", k: "Zecche: aspettano nell’erba, non sugli alberi" } } },
  { id: "b04", lvl: 1, type: "text", right: 3, t: { de: { q: "Welches dieser Tiere ist KEIN Insekt?", a: ["Ohrwurm", "Silberfischchen", "Wasserläufer", "Kellerassel"], x: "Asseln sind Krebstiere, die an Land leben. Sie haben 14 Beine und brauchen feuchte Verstecke.", k: "Asseln: sind Krebse, keine Insekten" }, en: { q: "Which of these animals is NOT an insect?", a: ["Earwig", "Silverfish", "Pond skater", "Woodlouse"], x: "Woodlice are crustaceans that live on land. They have 14 legs and need damp hiding places.", k: "Woodlice: crustaceans, not insects" }, fr: { q: "Lequel de ces animaux n'est PAS un insecte ?", a: ["Perce-oreille", "Poisson d'argent", "Gerris", "Cloporte"], x: "Les cloportes sont des crustacés terrestres. Ils ont 14 pattes et ont besoin de cachettes humides.", k: "Cloportes : des crustacés, pas des insectes" }, es: { q: "¿Cuál de estos animales NO es un insecto?", a: ["Tijereta", "Pececillo de plata", "Zapatero (Gerris)", "Cochinilla de humedad"], x: "Las cochinillas de humedad son crustáceos terrestres. Tienen 14 patas y necesitan escondites húmedos.", k: "Cochinillas: crustáceos, no insectos" }, pt: { q: "Qual destes animais NÃO é um inseto?", a: ["Tesourinha", "Traça-prateada", "Alfaiate (Gerris)", "Tatuzinho-de-jardim"], x: "Os tatuzinhos são crustáceos terrestres. Têm 14 patas e precisam de esconderijos úmidos.", k: "Tatuzinhos: crustáceos, não insetos" }, ja: { q: "昆虫ではないのはどれ？", a: ["ハサミムシ", "シミ", "アメンボ", "ワラジムシ"], x: "ワラジムシは陸にすむ甲殻類。脚は14本で、しめった隠れ家が必要です。", k: "ワラジムシ：昆虫ではなく甲殻類" }, it: { q: "Quale di questi animali NON è un insetto?", a: ["Forbicina", "Pesciolino d’argento", "Gerride", "Porcellino di terra"], x: "I porcellini di terra sono crostacei che vivono sulla terraferma. Hanno 14 zampe e hanno bisogno di nascondigli umidi.", k: "Porcellini di terra: crostacei, non insetti" } } },
  { id: "b05", lvl: 1, type: "text", right: 0, t: { de: { q: "Was ist eine Blindschleiche?", a: ["Eine Eidechse ohne Beine", "Eine kleine Schlange", "Ein großer Regenwurm", "Ein Lurch wie der Molch"], x: "Sie ist eine beinlose Echse: Sie hat Augenlider, kann den Schwanz abwerfen – und blind ist sie auch nicht.", k: "Blindschleiche: eine Echse ohne Beine" }, en: { q: "What is a slow worm?", a: ["A legless lizard", "A small snake", "A large earthworm", "An amphibian like a newt"], x: "It is a legless lizard: it has eyelids and can shed its tail, just like other lizards.", k: "Slow worm: a lizard without legs" }, fr: { q: "Qu'est-ce qu'un orvet ?", a: ["Un lézard sans pattes", "Un petit serpent", "Un gros ver de terre", "Un amphibien comme le triton"], x: "C'est un lézard sans pattes : il a des paupières et peut perdre sa queue, comme les autres lézards.", k: "Orvet : un lézard sans pattes" }, es: { q: "¿Qué es un lución?", a: ["Un lagarto sin patas", "Una pequeña serpiente", "Una lombriz grande", "Un anfibio como el tritón"], x: "Es un lagarto sin patas: tiene párpados y puede soltar la cola, como otros lagartos.", k: "Lución: un lagarto sin patas" }, pt: { q: "O que é um licranço?", a: ["Um lagarto sem patas", "Uma pequena cobra", "Uma minhoca grande", "Um anfíbio como o tritão"], x: "É um lagarto sem patas: tem pálpebras e pode soltar a cauda, como outros lagartos.", k: "Cobra-de-vidro: lagarto sem patas" }, ja: { q: "ヒメアシナシトカゲ（スローワーム）とは何？", a: ["脚のないトカゲ", "小さなヘビ", "大きなミミズ", "イモリのような両生類"], x: "脚のないトカゲです。ほかのトカゲと同じく、まぶたがあり、しっぽを切ることもできます。", k: "スローワーム：脚のないトカゲ" }, it: { q: "Cos’è l’orbettino?", a: ["Una lucertola senza zampe", "Un piccolo serpente", "Un grosso lombrico", "Un anfibio come il tritone"], x: "È una lucertola senza zampe: ha le palpebre e può staccare la coda, proprio come le altre lucertole.", k: "Orbettino: una lucertola senza zampe" } } },
  { id: "b06", lvl: 2, type: "text", right: 3, t: { de: { q: "Wovon ernähren sich erwachsene Eintagsfliegen?", a: ["Von Blütennektar", "Von kleinen Mücken", "Von Algen", "Von gar nichts"], x: "Ihre Mundwerkzeuge sind verkümmert. Erwachsene leben nur Stunden bis wenige Tage – allein zur Fortpflanzung.", k: "Eintagsfliegen: fressen als Erwachsene nichts" }, en: { q: "What do adult mayflies eat?", a: ["Flower nectar", "Small midges", "Algae", "Nothing at all"], x: "Their mouthparts are non-functional. Adults live only hours to a few days – just to reproduce.", k: "Adult mayflies: eat nothing at all" }, fr: { q: "De quoi se nourrissent les éphémères adultes ?", a: ["De nectar", "De petits moucherons", "D'algues", "De rien du tout"], x: "Leurs pièces buccales sont atrophiées. Les adultes vivent de quelques heures à quelques jours, juste pour se reproduire.", k: "Éphémères adultes : ne mangent rien" }, es: { q: "¿De qué se alimentan las efímeras adultas?", a: ["De néctar", "De mosquitos pequeños", "De algas", "De nada"], x: "Sus piezas bucales están atrofiadas. Los adultos viven de horas a pocos días, solo para reproducirse.", k: "Efímeras adultas: no comen nada" }, pt: { q: "De que se alimentam as efêmeras adultas?", a: ["De néctar", "De mosquitinhos", "De algas", "De nada"], x: "Suas peças bucais são atrofiadas. Os adultos vivem de horas a poucos dias, só para se reproduzir.", k: "Efêmeras adultas: não comem nada" }, ja: { q: "カゲロウの成虫は何を食べる？", a: ["花の蜜", "小さな蚊", "藻", "何も食べない"], x: "口がはたらかないのです。成虫の命は数時間から数日だけ。子孫を残すためだけに生きます。", k: "カゲロウの成虫：何も食べない" }, it: { q: "Cosa mangiano le effimere adulte?", a: ["Nettare dei fiori", "Piccoli moscerini", "Alghe", "Proprio niente"], x: "La loro bocca non funziona. Gli adulti vivono solo da poche ore a pochi giorni, solo per riprodursi.", k: "Effimere adulte: non mangiano nulla" } } },
  { id: "b07", lvl: 1, type: "tf", right: 0, t: { de: { q: "Nur die Weibchen der Stechmücken stechen.", a: ["Wahr", "Falsch"], x: "Sie brauchen Blut, damit sich ihre Eier entwickeln. Männchen saugen nur Pflanzensäfte und Nektar.", k: "Mücken: nur die Weibchen stechen" }, en: { q: "Only female mosquitoes bite.", a: ["True", "False"], x: "They need blood for their eggs to develop. Males only feed on plant juices and nectar.", k: "Mosquitoes: only females bite" }, fr: { q: "Seules les femelles moustiques piquent.", a: ["Vrai", "Faux"], x: "Elles ont besoin de sang pour que leurs œufs se développent. Les mâles se nourrissent de nectar et de sève.", k: "Moustiques : seules les femelles piquent" }, es: { q: "Solo las hembras de mosquito pican.", a: ["Verdadero", "Falso"], x: "Necesitan sangre para que se desarrollen sus huevos. Los machos solo toman néctar y jugos vegetales.", k: "Mosquitos: solo pican las hembras" }, pt: { q: "Só as fêmeas dos mosquitos picam.", a: ["Verdadeiro", "Falso"], x: "Elas precisam de sangue para que os ovos se desenvolvam. Os machos tomam só néctar e seiva de plantas.", k: "Mosquitos: só as fêmeas picam" }, ja: { q: "正しい？まちがい？ 人を刺すのはメスの蚊だけ。", a: ["正しい", "まちがい"], x: "メスは卵を育てるために血が必要です。オスは植物の汁や花の蜜だけを吸います。", k: "蚊：刺すのはメスだけ" }, it: { q: "Vero o falso? Pungono solo le zanzare femmine.", a: ["Vero", "Falso"], x: "Hanno bisogno di sangue per far sviluppare le uova. I maschi si nutrono solo di linfa e nettare.", k: "Zanzare: pungono solo le femmine" } } },
  { id: "b08", lvl: 2, type: "text", right: 0, t: { de: { q: "Wo nisten die meisten Wildbienenarten in Deutschland?", a: ["Im Erdboden", "In hohlen Pflanzenstängeln", "In Bohrlöchern im Totholz", "In leeren Schneckenhäusern"], x: "Mehr als die Hälfte nistet im Boden. Offene, sonnige Erdstellen im Garten helfen oft mehr als ein Insektenhotel.", k: "Wildbienen: nisten meist im Boden" }, en: { q: "Where do most wild bee species in Germany nest?", a: ["In the ground", "In hollow plant stems", "In holes in dead wood", "In empty snail shells"], x: "More than half nest in the ground. Bare, sunny patches of soil often help more than a bee hotel.", k: "Wild bees: mostly nest in the ground" }, fr: { q: "Où nichent la plupart des espèces d'abeilles sauvages en Allemagne ?", a: ["Dans le sol", "Dans des tiges creuses", "Dans des trous de bois mort", "Dans des coquilles d'escargot"], x: "Plus de la moitié nichent dans le sol. Des zones de terre nue et ensoleillée aident souvent plus qu'un hôtel à insectes.", k: "Abeilles sauvages : nichent surtout dans le sol" }, es: { q: "¿Dónde anidan la mayoría de las abejas silvestres en Alemania?", a: ["En el suelo", "En tallos huecos", "En agujeros de madera muerta", "En conchas de caracol vacías"], x: "Más de la mitad anida en el suelo. Zonas de tierra desnuda y soleada ayudan a menudo más que un hotel de insectos.", k: "Abejas silvestres: anidan sobre todo en el suelo" }, pt: { q: "Onde faz ninho a maioria das abelhas silvestres na Alemanha?", a: ["No solo", "Em caules ocos", "Em buracos de madeira morta", "Em conchas vazias de caracol"], x: "Mais da metade faz ninho no solo. Pedaços de terra nua e ensolarada muitas vezes ajudam mais que um hotel de insetos.", k: "Abelhas silvestres: fazem ninho no solo" }, ja: { q: "ドイツの野生のハナバチの多くは、どこに巣を作る？", a: ["地面の中", "中が空洞の植物の茎", "枯れ木の穴", "空っぽのカタツムリの殻"], x: "半分以上が地面に巣を作ります。日当たりのよい裸の地面のほうが、ハチホテルより役立つことも多いのです。", k: "野生のハナバチ：多くは地面に巣を作る" }, it: { q: "Dove nidifica la maggior parte delle specie di api selvatiche in Germania?", a: ["Nel terreno", "Negli steli cavi delle piante", "Nei buchi del legno morto", "Nei gusci vuoti di chiocciola"], x: "Più della metà nidifica nel terreno. Spesso un pezzo di terra nuda e soleggiata aiuta più di un hotel per api.", k: "Api selvatiche: nidificano soprattutto nel terreno" } } },
  { id: "b09", lvl: 2, type: "text", right: 2, t: { de: { q: "Wie pflanzt sich der Feuersalamander bei uns fort?", a: ["Er legt Laichballen in Teiche", "Er vergräbt Eier in feuchter Erde", "Das Weibchen setzt Larven in Bächen ab", "Das Männchen trägt die Eier"], x: "Die Eier entwickeln sich im Mutterleib. Im Frühjahr setzt das Weibchen Larven mit Kiemen in kühle Bäche.", k: "Feuersalamander: bringt Larven zur Welt" }, en: { q: "How does the fire salamander reproduce in Central Europe?", a: ["It lays egg clumps in ponds", "It buries eggs in damp soil", "Females release larvae into streams", "The male carries the eggs"], x: "The eggs develop inside the mother. In spring she releases larvae with gills into cool streams.", k: "Fire salamander: gives birth to larvae" }, fr: { q: "Comment la salamandre tachetée se reproduit-elle chez nous ?", a: ["Elle pond des amas d'œufs en mare", "Elle enterre ses œufs", "La femelle dépose des larves en ruisseau", "Le mâle porte les œufs"], x: "Les œufs se développent dans le corps de la mère. Au printemps, elle dépose des larves à branchies dans des ruisseaux frais.", k: "Salamandre tachetée : met au monde des larves" }, es: { q: "¿Cómo se reproduce la salamandra común en Centroeuropa?", a: ["Pone masas de huevos en charcas", "Entierra huevos en tierra húmeda", "La hembra suelta larvas en arroyos", "El macho lleva los huevos"], x: "Los huevos se desarrollan dentro de la madre. En primavera suelta larvas con branquias en arroyos frescos.", k: "Salamandra común: pare larvas" }, pt: { q: "Como a salamandra-de-fogo se reproduz na Europa Central?", a: ["Põe massas de ovos em poças", "Enterra ovos na terra úmida", "A fêmea solta larvas em riachos", "O macho carrega os ovos"], x: "Os ovos se desenvolvem dentro da mãe. Na primavera, ela solta larvas com brânquias em riachos frescos.", k: "Salamandra-de-fogo: dá à luz larvas" }, ja: { q: "中央ヨーロッパのファイアサラマンダーはどうやって子孫を残す？", a: ["池に卵のかたまりを産む", "しめった土に卵を埋める", "メスが小川に幼生を産む", "オスが卵を運ぶ"], x: "卵は母親の体の中で育ちます。春になると、えらのある幼生を冷たい小川に産み出します。", k: "ファイアサラマンダー：幼生を産む" }, it: { q: "Come si riproduce la salamandra pezzata in Europa centrale?", a: ["Depone ammassi di uova negli stagni", "Seppellisce le uova nella terra umida", "Le femmine rilasciano larve nei ruscelli", "Il maschio porta le uova"], x: "Le uova si sviluppano nel corpo della madre. In primavera lei rilascia larve con le branchie nei ruscelli freschi.", k: "Salamandra pezzata: partorisce larve" } } },
  { id: "b10", lvl: 3, type: "text", right: 3, t: { de: { q: "Wie lange ist ein Alpensalamander-Weibchen trächtig?", a: ["Etwa 3 Wochen", "Etwa 3 Monate", "Genau 1 Jahr", "2 bis 4 Jahre"], x: "Je nach Höhenlage 2 bis 4 Jahre. Die Jungen kommen fertig verwandelt zur Welt – ganz ohne Wasser.", k: "Alpensalamander: bis zu 4 Jahre trächtig" }, en: { q: "How long is a female Alpine salamander pregnant?", a: ["About 3 weeks", "About 3 months", "Exactly 1 year", "2 to 4 years"], x: "Depending on altitude, 2 to 4 years. The young are born fully developed – no water needed.", k: "Alpine salamander: pregnant for up to 4 years" }, fr: { q: "Combien de temps dure la gestation de la salamandre noire (alpine) ?", a: ["Environ 3 semaines", "Environ 3 mois", "Exactement 1 an", "De 2 à 4 ans"], x: "Selon l'altitude, 2 à 4 ans. Les petits naissent entièrement formés, sans passer par l'eau.", k: "Salamandre noire : gestation jusqu’à 4 ans" }, es: { q: "¿Cuánto dura la gestación de la salamandra alpina?", a: ["Unas 3 semanas", "Unos 3 meses", "Exactamente 1 año", "De 2 a 4 años"], x: "Según la altitud, de 2 a 4 años. Las crías nacen ya transformadas, sin necesidad de agua.", k: "Salamandra alpina: gestación de hasta 4 años" }, pt: { q: "Quanto dura a gestação da salamandra-alpina?", a: ["Umas 3 semanas", "Uns 3 meses", "Exatamente 1 ano", "De 2 a 4 anos"], x: "Conforme a altitude, de 2 a 4 anos. Os filhotes já nascem transformados, sem precisar de água.", k: "Salamandra-alpina: gestação de até 4 anos" }, ja: { q: "アルプスサラマンダーのメスの妊娠期間は？", a: ["約3週間", "約3か月", "ちょうど1年", "2〜4年"], x: "標高によって2〜4年。子どもは完全に育った姿で生まれるので、水は必要ありません。", k: "アルプスサラマンダー：妊娠は最大4年" }, it: { q: "Quanto dura la gravidanza della salamandra alpina?", a: ["Circa 3 settimane", "Circa 3 mesi", "Esattamente 1 anno", "Da 2 a 4 anni"], x: "A seconda dell’altitudine, da 2 a 4 anni. I piccoli nascono già completamente sviluppati: non serve l’acqua.", k: "Salamandra alpina: gravidanza fino a 4 anni" } } },
  { id: "b11", lvl: 1, type: "tf", right: 0, t: { de: { q: "Erdkröten wandern im Frühjahr meist zu dem Gewässer zurück, in dem sie selbst aufgewachsen sind.", a: ["Wahr", "Falsch"], x: "Dabei überqueren sie oft Straßen. Krötenzäune und Amphibientunnel retten jedes Jahr viele Tiere.", k: "Erdkröten: kehren zu ihrem Heimatteich zurück" }, en: { q: "In spring, common toads usually return to the pond where they grew up.", a: ["True", "False"], x: "On the way they often cross roads. Toad fences and tunnels save many animals every year.", k: "Toads: return to the pond they grew up in" }, fr: { q: "Au printemps, les crapauds communs retournent généralement à la mare où ils ont grandi.", a: ["Vrai", "Faux"], x: "En chemin, ils traversent souvent des routes. Barrières et crapauducs sauvent beaucoup d'animaux chaque année.", k: "Crapauds : retournent à leur mare natale" }, es: { q: "En primavera, los sapos comunes suelen volver a la charca donde crecieron.", a: ["Verdadero", "Falso"], x: "En el camino cruzan a menudo carreteras. Vallas y pasos para anfibios salvan a muchos cada año.", k: "Sapos: vuelven a su charca natal" }, pt: { q: "Na primavera, os sapos-comuns costumam voltar à poça onde cresceram.", a: ["Verdadeiro", "Falso"], x: "No caminho, eles muitas vezes atravessam estradas. Cercas e passagens para anfíbios salvam muitos deles todo ano.", k: "Sapos: voltam à lagoa onde cresceram" }, ja: { q: "正しい？まちがい？ ヒキガエルは春、たいてい自分が育った池にもどる。", a: ["正しい", "まちがい"], x: "その途中で道路を渡ることが多いのです。カエル用の柵やトンネルが、毎年たくさんの命を救っています。", k: "ヒキガエル：生まれた池にもどる" }, it: { q: "Vero o falso? In primavera i rospi comuni tornano di solito nello stagno dove sono cresciuti.", a: ["Vero", "Falso"], x: "Lungo la strada attraversano spesso le carreggiate. Barriere e tunnel per rospi salvano ogni anno molti animali.", k: "Rospi: tornano al loro stagno natale" } } },
  { id: "b12", lvl: 1, type: "text", right: 1, t: { de: { q: "Was sind die geringelten Sandhäufchen im Wattenmeer?", a: ["Eier von Strandkrabben", "Kot des Wattwurms", "Nester von Muscheln", "Bauten von Sandflöhen"], x: "Der Wattwurm frisst Sand, verdaut die Kleinstlebewesen darin und scheidet den Sand als Kringel wieder aus.", k: "Wattwurm: hinterlässt Sandkringel als Kot" }, en: { q: "What are the coiled little sand piles on the Wadden Sea mudflats?", a: ["Shore crab eggs", "Lugworm droppings", "Mussel nests", "Sand hopper burrows"], x: "The lugworm swallows sand, digests the tiny organisms in it and pushes the sand back out as coils.", k: "Lugworm: leaves sand coils as droppings" }, fr: { q: "Que sont les petits tortillons de sable sur les vasières de la mer des Wadden ?", a: ["Des œufs de crabe", "Les excréments de l'arénicole", "Des nids de moules", "Des terriers de puces de mer"], x: "L'arénicole avale du sable, digère les petits organismes qu'il contient et rejette le sable en tortillons.", k: "Arénicole : laisse des tortillons de sable" }, es: { q: "¿Qué son los montoncitos de arena enrollada en las marismas del mar de Wadden?", a: ["Huevos de cangrejo", "Excrementos del gusano Arenicola", "Nidos de mejillones", "Madrigueras de pulgas de mar"], x: "El gusano Arenicola traga arena, digiere los diminutos organismos que contiene y expulsa la arena en forma de rollitos.", k: "Gusano arenícola: deja espirales de arena" }, pt: { q: "O que são os montinhos de areia enrolada nas planícies de maré do mar de Wadden?", a: ["Ovos de caranguejo", "Fezes do verme Arenicola", "Ninhos de mexilhões", "Tocas de pulgas-do-mar"], x: "O verme Arenicola engole areia, digere os organismos minúsculos que ela contém e solta a areia em forma de rolinhos.", k: "Arenícola: deixa espirais de areia" }, ja: { q: "ワッデン海の干潟にある、くるくる巻いた砂の山は何？", a: ["カニの卵", "タマシキゴカイのフン", "貝の巣", "ハマトビムシの穴"], x: "タマシキゴカイは砂を飲みこみ、中の小さな生きものを消化して、砂をくるくると押し出します。", k: "タマシキゴカイ：砂のうずまきのフン" }, it: { q: "Cosa sono i mucchietti di sabbia arrotolati sulle piane fangose del Mare dei Wadden?", a: ["Uova di granchio", "Escrementi del verme arenicola", "Nidi di cozze", "Tane di pulci di mare"], x: "L’arenicola inghiotte sabbia, ne digerisce i piccoli organismi e la spinge fuori in spirali.", k: "Arenicola: lascia spirali di sabbia" } } },
  { id: "b13", lvl: 2, type: "text", right: 0, t: { de: { q: "Wo legt die Gelbbauchunke am liebsten ihren Laich ab?", a: ["In flachen Pfützen und Fahrspuren", "In tiefen Seen", "In schnellen Bergbächen", "Im Brackwasser der Küste"], x: "Sie nutzt kleine, sonnige Tümpel – sogar wassergefüllte Reifenspuren. Dort gibt es kaum Fische oder andere Fressfeinde.", k: "Gelbbauchunke: laicht in Pfützen und Spurrillen" }, en: { q: "Where does the yellow-bellied toad prefer to spawn?", a: ["In shallow puddles and ruts", "In deep lakes", "In fast mountain streams", "In brackish coastal water"], x: "It uses small, sunny pools – even water-filled tyre ruts. There are hardly any fish or other predators there.", k: "Yellow-bellied toad: spawns in puddles and ruts" }, fr: { q: "Où le sonneur à ventre jaune pond-il de préférence ?", a: ["Dans des flaques et ornières", "Dans des lacs profonds", "Dans des torrents de montagne", "Dans l'eau saumâtre côtière"], x: "Il utilise de petites mares ensoleillées, même des ornières pleines d'eau. On n'y trouve presque pas de poissons ni de prédateurs.", k: "Sonneur à ventre jaune : pond dans les flaques" }, es: { q: "¿Dónde prefiere desovar el sapillo de vientre amarillo?", a: ["En charcos y rodadas poco hondos", "En lagos profundos", "En torrentes de montaña", "En aguas salobres costeras"], x: "Usa charcas pequeñas y soleadas, incluso rodadas de neumáticos con agua. Allí casi no hay peces ni depredadores.", k: "Sapillo de vientre amarillo: desova en charcos" }, pt: { q: "Onde o sapinho-de-barriga-amarela prefere desovar?", a: ["Em poças rasas e marcas de pneu", "Em lagos fundos", "Em riachos de montanha", "Em água salobra na costa"], x: "Ele usa poças pequenas e ensolaradas, até marcas de pneu com água. Ali quase não há peixes nem predadores.", k: "Sapinho-de-barriga-amarela: desova em poças" }, ja: { q: "キバラスズガエルが好んで卵を産む場所は？", a: ["浅い水たまりやわだち", "深い湖", "流れの速い山の川", "海沿いの汽水"], x: "日当たりのよい小さな水たまりを使います。水のたまったタイヤのあとでも。そこには魚などの天敵がほとんどいません。", k: "キバラスズガエル：水たまりに卵を産む" }, it: { q: "Dove depone preferibilmente le uova l’ululone dal ventre giallo?", a: ["In pozzanghere basse e solchi", "In laghi profondi", "In torrenti di montagna veloci", "In acqua salmastra costiera"], x: "Usa piccole pozze soleggiate, anche i solchi delle ruote pieni d’acqua. Lì non ci sono quasi pesci o altri predatori.", k: "Ululone: depone nelle pozzanghere" } } },
  { id: "b14", lvl: 3, type: "tf", right: 0, t: { de: { q: "In Deutschland leben zwei heimische Giftschlangenarten.", a: ["Wahr", "Falsch"], x: "Die Kreuzotter und die seltene Aspisviper, die bei uns nur im Südschwarzwald vorkommt.", k: "Deutschland: zwei heimische Giftschlangen" }, en: { q: "Germany has two native species of venomous snake.", a: ["True", "False"], x: "The common adder and the rare asp viper, which in Germany is found only in the southern Black Forest.", k: "Germany: two native venomous snakes" }, fr: { q: "L'Allemagne compte deux espèces indigènes de serpents venimeux.", a: ["Vrai", "Faux"], x: "La vipère péliade et la rare vipère aspic, qui en Allemagne ne vit que dans le sud de la Forêt-Noire.", k: "Allemagne : deux serpents venimeux indigènes" }, es: { q: "En Alemania viven dos especies autóctonas de serpientes venenosas.", a: ["Verdadero", "Falso"], x: "La víbora común europea y la rara víbora áspid, que en Alemania solo vive en el sur de la Selva Negra.", k: "Alemania: dos serpientes venenosas nativas" }, pt: { q: "Na Alemanha vivem duas espécies nativas de cobras venenosas.", a: ["Verdadeiro", "Falso"], x: "A víbora-europeia e a rara víbora-áspide, que na Alemanha só vive no sul da Floresta Negra.", k: "Alemanha: duas cobras venenosas nativas" }, ja: { q: "正しい？まちがい？ ドイツには在来の毒ヘビが2種いる。", a: ["正しい", "まちがい"], x: "ヨーロッパクサリヘビと、めずらしいアスプクサリヘビ。アスプクサリヘビはドイツでは黒い森の南部にしかいません。", k: "ドイツ：在来の毒ヘビは2種" }, it: { q: "Vero o falso? In Germania ci sono due specie autoctone di serpenti velenosi.", a: ["Vero", "Falso"], x: "Il marasso e la rara vipera comune, che in Germania vive solo nella Foresta Nera meridionale.", k: "Germania: due serpenti velenosi autoctoni" } } },
  { id: "b15", lvl: 1, type: "text", right: 3, t: { de: { q: "Woran erkennt man eine Ringelnatter meist?", a: ["Ein Zickzackband auf dem Rücken", "Eine Rassel am Schwanz", "Senkrechte Schlitzpupillen", "Gelbe Halbmondflecken am Hinterkopf"], x: "Die ungiftige Ringelnatter hat runde Pupillen und schwimmt gern. Bei Gefahr stellt sie sich oft tot.", k: "Ringelnatter: harmlos, stellt sich tot" }, en: { q: "How can you usually recognise a grass snake?", a: ["A zigzag band on its back", "A rattle on its tail", "Vertical slit pupils", "Yellow crescents behind the head"], x: "The harmless grass snake has round pupils and loves to swim. When threatened, it often plays dead.", k: "Grass snake: harmless, plays dead" }, fr: { q: "À quoi reconnaît-on généralement la couleuvre à collier ?", a: ["Une bande en zigzag sur le dos", "Une crécelle au bout de la queue", "Des pupilles verticales en fente", "Des croissants jaunes sur la nuque"], x: "Inoffensive, elle a des pupilles rondes et nage volontiers. En cas de danger, elle fait souvent la morte.", k: "Couleuvre à collier : inoffensive, fait la morte" }, es: { q: "¿Cómo se reconoce normalmente una culebra de collar?", a: ["Una banda en zigzag en el lomo", "Un cascabel en la cola", "Pupilas verticales en rendija", "Medias lunas amarillas en la nuca"], x: "Esta culebra inofensiva tiene pupilas redondas y nada muy bien. Ante el peligro, a menudo se hace la muerta.", k: "Culebra de collar: inofensiva, se hace la muerta" }, pt: { q: "Como normalmente se reconhece uma cobra-de-colar?", a: ["Uma faixa em zigue-zague nas costas", "Um chocalho na cauda", "Pupilas verticais em fenda", "Meias-luas amarelas na nuca"], x: "Essa cobra inofensiva tem pupilas redondas e nada muito bem. Em perigo, muitas vezes finge de morta.", k: "Cobra-de-colar: inofensiva, finge-se de morta" }, ja: { q: "ヨーロッパヤマカガシ（グラススネーク）は、ふつう何で見分ける？", a: ["背中のジグザグもよう", "しっぽのガラガラ", "縦長の瞳", "頭の後ろの黄色い三日月もよう"], x: "無害なグラススネークは瞳が丸く、泳ぐのが大好き。おどかされると、よく死んだふりをします。", k: "ヨーロッパヤマカガシ：無害で死んだふり" }, it: { q: "Di solito, come si riconosce la natrice dal collare?", a: ["Una fascia a zigzag sul dorso", "Un sonaglio sulla coda", "Pupille verticali a fessura", "Mezzelune gialle dietro la testa"], x: "L’innocua natrice ha pupille rotonde e adora nuotare. Se minacciata, spesso si finge morta.", k: "Natrice: innocua, si finge morta" } } },
  { id: "b16", lvl: 3, type: "text", right: 1, t: { de: { q: "Was ist beim nachgewachsenen Schwanz einer Eidechse anders?", a: ["Er hat doppelt so viele Wirbel", "Statt Wirbeln stützt ihn ein Knorpelstab", "Er ist immer länger als vorher", "Er enthält eine Giftdrüse"], x: "Der neue Schwanz hat keine Wirbelknochen mehr, nur einen Knorpelstab. Er ist meist kürzer und anders gefärbt.", k: "Eidechsenschwanz: wächst ohne Wirbel nach" }, en: { q: "What is different about a lizard's regrown tail?", a: ["It has twice as many vertebrae", "A cartilage rod replaces the vertebrae", "It is always longer than before", "It contains a venom gland"], x: "The new tail has no vertebrae, only a rod of cartilage. It is usually shorter and coloured differently.", k: "Lizard tail: grows back without vertebrae" }, fr: { q: "Qu'a de différent la queue repoussée d'un lézard ?", a: ["Elle a deux fois plus de vertèbres", "Un cartilage remplace les vertèbres", "Elle est toujours plus longue", "Elle contient une glande à venin"], x: "La nouvelle queue n'a plus de vertèbres, seulement une tige de cartilage. Elle est souvent plus courte et d'une autre couleur.", k: "Queue de lézard : repousse sans vertèbres" }, es: { q: "¿Qué tiene de diferente la cola regenerada de una lagartija?", a: ["Tiene el doble de vértebras", "Un cartílago sustituye a las vértebras", "Siempre es más larga que antes", "Contiene una glándula de veneno"], x: "La nueva cola ya no tiene vértebras, solo una varilla de cartílago. Suele ser más corta y de otro color.", k: "Cola de lagartija: vuelve a crecer sin vértebras" }, pt: { q: "O que a cauda que cresce de novo num lagarto tem de diferente?", a: ["Tem o dobro de vértebras", "Uma cartilagem substitui as vértebras", "É sempre mais longa que antes", "Contém uma glândula de veneno"], x: "A cauda nova não tem mais vértebras, só uma haste de cartilagem. Costuma ser mais curta e de outra cor.", k: "Rabo de lagartixa: cresce de novo sem vértebras" }, ja: { q: "トカゲの生えかわったしっぽは何がちがう？", a: ["背骨が2倍ある", "背骨のかわりに軟骨の棒がある", "必ず前より長い", "毒腺がある"], x: "新しいしっぽには背骨がなく、軟骨の棒が1本あるだけ。ふつう短くて、色もちがいます。", k: "トカゲのしっぽ：背骨なしで生えかわる" }, it: { q: "Cosa ha di diverso la coda ricresciuta di una lucertola?", a: ["Ha il doppio delle vertebre", "Un bastoncino di cartilagine sostituisce le vertebre", "È sempre più lunga di prima", "Contiene una ghiandola velenosa"], x: "La nuova coda non ha vertebre, solo un bastoncino di cartilagine. Di solito è più corta e di colore diverso.", k: "Coda di lucertola: ricresce senza vertebre" } } },
  { id: "b17", lvl: 2, type: "text", right: 2, t: { de: { q: "Wie atmet die Wasserspinne, die fast nur unter Wasser lebt?", a: ["Mit Kiemen am Hinterleib", "Sie hält stundenlang die Luft an", "Aus einer selbst gebauten Luftglocke", "Über die Haut aus dem Wasser"], x: "Sie spinnt zwischen Wasserpflanzen ein Gespinst und füllt es mit Luftblasen von der Oberfläche – eine Taucherglocke.", k: "Wasserspinne: atmet aus einer Luftglocke" }, en: { q: "How does the water spider Argyroneta, which lives almost only underwater, breathe?", a: ["With gills on its abdomen", "It holds its breath for hours", "From an air bell it builds itself", "Through its skin, from the water"], x: "It spins a web between water plants and fills it with air bubbles from the surface – like a diving bell.", k: "Water spider: breathes from an air bell" }, fr: { q: "Comment respire l'argyronète, araignée qui vit presque toujours sous l'eau ?", a: ["Avec des branchies", "Elle retient son souffle des heures", "Dans une cloche d'air qu'elle construit", "Par la peau, dans l'eau"], x: "Elle tisse une toile entre les plantes aquatiques et la remplit de bulles d'air prises en surface : une cloche de plongée.", k: "Argyronète : respire dans une cloche d’air" }, es: { q: "¿Cómo respira la araña de agua, que vive casi siempre bajo el agua?", a: ["Con branquias en el abdomen", "Aguanta la respiración durante horas", "En una campana de aire que construye", "A través de la piel, del agua"], x: "Teje una tela entre plantas acuáticas y la llena de burbujas de aire de la superficie: una campana de buceo.", k: "Araña de agua: respira de una campana de aire" }, pt: { q: "Como respira a aranha-d’água, que vive quase sempre debaixo d’água?", a: ["Com brânquias no abdômen", "Prende a respiração por horas", "Num sino de ar que ela constrói", "Pela pele, tirando ar da água"], x: "Ela tece uma teia entre plantas aquáticas e a enche de bolhas de ar da superfície: um sino de mergulho.", k: "Aranha-d’água: respira de uma bolha de ar" }, ja: { q: "ほぼ水中だけで暮らすミズグモは、どうやって呼吸する？", a: ["おなかのえらで", "何時間も息を止める", "自分で作った空気の部屋から", "水の中から皮ふで"], x: "水草の間に網を張り、水面から運んだ空気の泡をためます。まるで潜水鐘のようです。", k: "ミズグモ：空気の部屋で呼吸する" }, it: { q: "Come respira il ragno palombaro (Argyroneta), che vive quasi solo sott’acqua?", a: ["Con branchie sull’addome", "Trattiene il respiro per ore", "Da una campana d’aria che si costruisce", "Con la pelle, dall’acqua"], x: "Tesse una tela tra le piante acquatiche e la riempie di bolle d’aria prese in superficie, come una campana da palombaro.", k: "Ragno palombaro: respira da una campana d’aria" } } },
  { id: "b18", lvl: 2, type: "tf", right: 0, t: { de: { q: "Der Gelbrandkäfer lebt im Wasser, kann aber auch fliegen.", a: ["Wahr", "Falsch"], x: "Nachts fliegt er oft zu neuen Gewässern. Beim Tauchen nimmt er einen Luftvorrat unter den Flügeldecken mit.", k: "Gelbrandkäfer: lebt im Wasser und kann fliegen" }, en: { q: "The great diving beetle lives in water but can also fly.", a: ["True", "False"], x: "At night it often flies to new ponds. When diving, it carries an air supply under its wing cases.", k: "Diving beetle: lives in water and can fly" }, fr: { q: "Le dytique bordé vit dans l'eau mais peut aussi voler.", a: ["Vrai", "Faux"], x: "La nuit, il s'envole souvent vers de nouvelles mares. En plongée, il garde une réserve d'air sous ses élytres.", k: "Dytique : vit dans l’eau et vole" }, es: { q: "El ditisco vive en el agua, pero también puede volar.", a: ["Verdadero", "Falso"], x: "De noche vuela a menudo a nuevas charcas. Al bucear lleva una reserva de aire bajo los élitros.", k: "Ditisco: vive en el agua y vuela" }, pt: { q: "O besouro-mergulhador vive na água, mas também sabe voar.", a: ["Verdadeiro", "Falso"], x: "À noite, muitas vezes voa para novas lagoas. Ao mergulhar, leva uma reserva de ar debaixo dos élitros.", k: "Besouro-mergulhador: vive na água e voa" }, ja: { q: "正しい？まちがい？ ゲンゴロウの仲間は水中で暮らすが、空も飛べる。", a: ["正しい", "まちがい"], x: "夜にはよく新しい池へ飛んでいきます。潜るときは、羽の下に空気をためて持っていきます。", k: "ゲンゴロウの仲間：水中で暮らし空も飛ぶ" }, it: { q: "Vero o falso? Il ditisco vive in acqua ma sa anche volare.", a: ["Vero", "Falso"], x: "Di notte vola spesso verso nuovi stagni. Quando si immerge porta una riserva d’aria sotto le elitre.", k: "Ditisco: vive in acqua e vola" } } },
  { id: "b19", lvl: 2, type: "text", right: 0, t: { de: { q: "Womit fängt eine Libellenlarve ihre Beute?", a: ["Mit einer ausklappbaren Fangmaske", "Mit einer klebrigen Zunge", "Mit einem Netz aus Seide", "Mit einem Giftstachel"], x: "Die Fangmaske ist eine umgebaute Unterlippe. Sie schnellt blitzschnell vor und packt Kaulquappen, Larven und Co.", k: "Libellenlarve: fängt Beute mit einer Fangmaske" }, en: { q: "How does a dragonfly larva catch its prey?", a: ["With an extendable 'mask'", "With a sticky tongue", "With a silk net", "With a venomous sting"], x: "The mask is a modified lower lip. It shoots forward in a flash and grabs tadpoles, larvae and more.", k: "Dragonfly larva: catches prey with a mask" }, fr: { q: "Comment une larve de libellule attrape-t-elle ses proies ?", a: ["Avec un « masque » dépliable", "Avec une langue collante", "Avec un filet de soie", "Avec un dard venimeux"], x: "Le masque est une lèvre inférieure transformée. Il se détend comme l'éclair pour saisir têtards et larves.", k: "Larve de libellule : chasse avec un masque" }, es: { q: "¿Cómo atrapa una larva de libélula a sus presas?", a: ["Con una «máscara» extensible", "Con una lengua pegajosa", "Con una red de seda", "Con un aguijón venenoso"], x: "La máscara es un labio inferior modificado. Se dispara en un instante y atrapa renacuajos, larvas y más.", k: "Larva de libélula: caza con una máscara" }, pt: { q: "Como a larva da libélula pega suas presas?", a: ["Com uma “máscara” que se estica", "Com uma língua grudenta", "Com uma rede de seda", "Com um ferrão venenoso"], x: "A máscara é um lábio inferior modificado. Ela dispara num instante e pega girinos, larvas e mais.", k: "Larva de libélula: caça com uma máscara" }, ja: { q: "ヤゴはどうやって獲物をつかまえる？", a: ["のびる「マスク」で", "ねばねばの舌で", "糸の網で", "毒針で"], x: "マスクは変化した下くちびるです。一瞬で前に飛び出し、オタマジャクシや幼虫などをつかまえます。", k: "ヤゴ：のびるマスクで獲物をとる" }, it: { q: "Come cattura le prede la larva della libellula?", a: ["Con una «maschera» estensibile", "Con una lingua appiccicosa", "Con una rete di seta", "Con un pungiglione velenoso"], x: "La maschera è un labbro inferiore trasformato. Scatta in avanti in un lampo e afferra girini, larve e altro.", k: "Larva di libellula: caccia con una maschera" } } },
  { id: "b20", lvl: 3, type: "tf", right: 1, t: { de: { q: "Libellen durchlaufen wie Schmetterlinge ein Puppenstadium.", a: ["Wahr", "Falsch"], x: "Libellen haben keine Puppe: Die Larve klettert aus dem Wasser, häutet sich ein letztes Mal, und die Libelle schlüpft.", k: "Libellen: haben kein Puppenstadium" }, en: { q: "Like butterflies, dragonflies go through a pupal stage.", a: ["True", "False"], x: "Dragonflies have no pupa: the larva climbs out of the water, moults one last time and the adult emerges.", k: "Dragonflies: have no pupal stage" }, fr: { q: "Comme les papillons, les libellules passent par un stade de chrysalide (pupe).", a: ["Vrai", "Faux"], x: "Les libellules n'ont pas de pupe : la larve sort de l'eau, mue une dernière fois et l'adulte en émerge.", k: "Libellules : pas de stade nymphe" }, es: { q: "Como las mariposas, las libélulas pasan por una fase de pupa.", a: ["Verdadero", "Falso"], x: "Las libélulas no tienen pupa: la larva sale del agua, muda por última vez y emerge el adulto.", k: "Libélulas: no tienen fase de pupa" }, pt: { q: "Como as borboletas, as libélulas passam por uma fase de pupa.", a: ["Verdadeiro", "Falso"], x: "As libélulas não têm pupa: a larva sai da água, faz a última muda e o adulto emerge.", k: "Libélulas: não têm fase de pupa" }, ja: { q: "正しい？まちがい？ トンボもチョウのように、さなぎの時期がある。", a: ["正しい", "まちがい"], x: "トンボにさなぎの時期はありません。ヤゴが水から上がって最後の脱皮をすると、成虫が出てきます。", k: "トンボ：さなぎにならない" }, it: { q: "Vero o falso? Come le farfalle, anche le libellule passano per lo stadio di crisalide.", a: ["Vero", "Falso"], x: "Le libellule non hanno crisalide: la larva esce dall’acqua, fa l’ultima muta e ne esce l’adulto.", k: "Libellule: niente stadio di pupa" } } },
  { id: "b21", lvl: 2, type: "text", right: 1, t: { de: { q: "Was stimmt beim Großen Leuchtkäfer (Glühwürmchen)?", a: ["Nur die Männchen leuchten", "Die Weibchen können nicht fliegen", "Sein Licht ist heiß wie eine Lampe", "Er ist eigentlich eine Fliege"], x: "Die flügellosen Weibchen leuchten im Gras, um fliegende Männchen anzulocken. Das Licht entsteht chemisch und ist kalt.", k: "Glühwürmchen: die Weibchen können nicht fliegen" }, en: { q: "What is true about the common glow-worm?", a: ["Only the males glow", "The females cannot fly", "Its light is hot like a lamp", "It is actually a fly"], x: "The wingless females glow in the grass to attract flying males. The light is made chemically and is cold.", k: "Glow-worms: females can't fly" }, fr: { q: "Qu'est-ce qui est vrai pour le ver luisant ?", a: ["Seuls les mâles brillent", "Les femelles ne volent pas", "Sa lumière chauffe comme une lampe", "C'est en fait une mouche"], x: "Les femelles sans ailes brillent dans l'herbe pour attirer les mâles volants. Leur lumière est chimique et froide.", k: "Vers luisants : les femelles ne volent pas" }, es: { q: "¿Qué es cierto sobre la luciérnaga común europea?", a: ["Solo brillan los machos", "Las hembras no pueden volar", "Su luz quema como una lámpara", "En realidad es una mosca"], x: "Las hembras sin alas brillan en la hierba para atraer a los machos voladores. La luz es química y fría.", k: "Luciérnagas: las hembras no vuelan" }, pt: { q: "O que é verdade sobre o vaga-lume-comum europeu?", a: ["Só os machos brilham", "As fêmeas não voam", "Sua luz esquenta como uma lâmpada", "Na verdade é uma mosca"], x: "As fêmeas sem asas brilham na grama para atrair os machos voadores. A luz é química e fria.", k: "Vaga-lumes europeus: as fêmeas não voam" }, ja: { q: "ヨーロッパツチボタルについて正しいのは？", a: ["光るのはオスだけ", "メスは飛べない", "光はランプのように熱い", "実はハエの仲間"], x: "羽のないメスが草の中で光り、飛んでいるオスを呼びます。光は化学反応で作られ、熱くありません。", k: "ツチボタル：メスは飛べない" }, it: { q: "Cosa è vero sulla lucciola europea (Lampyris)?", a: ["Solo i maschi brillano", "Le femmine non sanno volare", "La sua luce scotta come una lampadina", "In realtà è una mosca"], x: "Le femmine senza ali brillano nell’erba per attirare i maschi in volo. La luce è prodotta chimicamente ed è fredda.", k: "Lucciole: le femmine non volano" } } },
  { id: "b22", lvl: 3, type: "text", right: 2, t: { de: { q: "Wovon ernähren sich die Larven des Großen Leuchtkäfers?", a: ["Von Blattläusen", "Von Nektar", "Von Schnecken", "Von morschem Holz"], x: "Sie jagen Schnecken, lähmen sie mit einem giftigen Biss und fressen sie. Sie brauchen feuchte, naturnahe Gärten.", k: "Glühwürmchen-Larven: fressen Schnecken" }, en: { q: "What do glow-worm larvae feed on?", a: ["Aphids", "Nectar", "Snails", "Rotting wood"], x: "They hunt snails, paralyse them with a venomous bite and eat them. They need damp, natural gardens.", k: "Glow-worm larvae: eat snails" }, fr: { q: "De quoi se nourrissent les larves de ver luisant ?", a: ["De pucerons", "De nectar", "D'escargots", "De bois pourri"], x: "Elles chassent les escargots, les paralysent d'une morsure venimeuse puis les mangent. Elles aiment les jardins humides et naturels.", k: "Larves de ver luisant : mangent des escargots" }, es: { q: "¿De qué se alimentan las larvas de la luciérnaga común?", a: ["De pulgones", "De néctar", "De caracoles", "De madera podrida"], x: "Cazan caracoles, los paralizan con una mordedura venenosa y se los comen. Necesitan jardines húmedos y naturales.", k: "Larvas de luciérnaga: comen caracoles" }, pt: { q: "De que se alimentam as larvas do vaga-lume-comum europeu?", a: ["De pulgões", "De néctar", "De caracóis", "De madeira podre"], x: "Elas caçam caracóis, paralisam-nos com uma mordida venenosa e os comem. Precisam de jardins úmidos e naturais.", k: "Larvas de vaga-lume: comem caracóis" }, ja: { q: "ツチボタルの幼虫は何を食べる？", a: ["アブラムシ", "花の蜜", "カタツムリ", "くさった木"], x: "カタツムリをつかまえ、毒のある口でまひさせて食べます。しめった自然な庭が必要です。", k: "ツチボタルの幼虫：カタツムリを食べる" }, it: { q: "Di cosa si nutrono le larve della lucciola?", a: ["Afidi", "Nettare", "Chiocciole", "Legno marcio"], x: "Cacciano chiocciole, le paralizzano con un morso velenoso e le mangiano. Hanno bisogno di giardini umidi e naturali.", k: "Larve di lucciola: mangiano chiocciole" } } },
  { id: "b23", lvl: 1, type: "tf", right: 1, t: { de: { q: "An der Zahl der Punkte kann man das Alter eines Marienkäfers ablesen.", a: ["Wahr", "Falsch"], x: "Ein Mythos: Die Punktzahl hängt von der Art ab – etwa beim Siebenpunkt- oder Zweipunkt-Marienkäfer.", k: "Marienkäfer: Punkte verraten nicht das Alter" }, en: { q: "You can tell a ladybird's age by counting its spots.", a: ["True", "False"], x: "A myth: the number of spots depends on the species, e.g. the seven-spot or two-spot ladybird.", k: "Ladybirds: spots don't show their age" }, fr: { q: "On peut connaître l'âge d'une coccinelle en comptant ses points.", a: ["Vrai", "Faux"], x: "Un mythe : le nombre de points dépend de l'espèce, comme chez la coccinelle à sept points ou à deux points.", k: "Coccinelles : les points ne disent pas l’âge" }, es: { q: "Se puede saber la edad de una mariquita contando sus puntos.", a: ["Verdadero", "Falso"], x: "Es un mito: el número de puntos depende de la especie, como la mariquita de siete o de dos puntos.", k: "Mariquitas: los puntos no indican la edad" }, pt: { q: "Dá para saber a idade de uma joaninha contando suas pintas.", a: ["Verdadeiro", "Falso"], x: "É um mito: o número de pintas depende da espécie, como a joaninha-de-sete-pintas ou a de duas pintas.", k: "Joaninhas: as pintas não mostram a idade" }, ja: { q: "正しい？まちがい？ テントウムシの年齢は、星の数でわかる。", a: ["正しい", "まちがい"], x: "これは俗説。星の数は種類で決まっています。たとえばナナホシテントウやフタホシテントウ。", k: "テントウムシ：星の数で年齢はわからない" }, it: { q: "Vero o falso? Si capisce l’età di una coccinella contando i puntini.", a: ["Vero", "Falso"], x: "Un mito: il numero di puntini dipende dalla specie, per esempio coccinella a sette punti o a due punti.", k: "Coccinelle: i puntini non dicono l’età" } } },
  { id: "b24", lvl: 1, type: "text", right: 3, t: { de: { q: "Wer überlebt bei Hummeln den Winter?", a: ["Das ganze Volk im Nest", "Nur die Arbeiterinnen", "Nur die Männchen", "Nur junge Königinnen"], x: "Das Volk stirbt im Herbst. Nur junge, begattete Königinnen überwintern im Boden und gründen im Frühjahr ein neues Volk.", k: "Hummeln: nur junge Königinnen überwintern" }, en: { q: "Which bumblebees survive the winter?", a: ["The whole colony in the nest", "Only the workers", "Only the males", "Only young queens"], x: "The colony dies in autumn. Only young, mated queens overwinter in the ground and start a new colony in spring.", k: "Bumblebees: only young queens overwinter" }, fr: { q: "Quels bourdons survivent à l'hiver ?", a: ["Toute la colonie au nid", "Seulement les ouvrières", "Seulement les mâles", "Seulement les jeunes reines"], x: "La colonie meurt en automne. Seules les jeunes reines fécondées hivernent dans le sol et fondent une colonie au printemps.", k: "Bourdons : seules les jeunes reines hivernent" }, es: { q: "¿Qué abejorros sobreviven al invierno?", a: ["Toda la colonia en el nido", "Solo las obreras", "Solo los machos", "Solo las reinas jóvenes"], x: "La colonia muere en otoño. Solo las reinas jóvenes fecundadas hibernan en el suelo y fundan una colonia en primavera.", k: "Abejorros: solo las reinas jóvenes invernan" }, pt: { q: "Quais mamangavas sobrevivem ao inverno?", a: ["A colônia inteira no ninho", "Só as operárias", "Só os machos", "Só as rainhas jovens"], x: "A colônia morre no outono. Só as rainhas jovens fecundadas hibernam no solo e fundam uma colônia na primavera.", k: "Mamangavas: só rainhas jovens passam o inverno" }, ja: { q: "冬を越すマルハナバチはどれ？", a: ["巣の中の群れ全体", "働きバチだけ", "オスだけ", "若い女王バチだけ"], x: "群れは秋に死んでしまいます。交尾をすませた若い女王バチだけが土の中で冬を越し、春に新しい群れを作ります。", k: "マルハナバチ：冬を越すのは若い女王だけ" }, it: { q: "Quali bombi sopravvivono all’inverno?", a: ["Tutta la colonia nel nido", "Solo le operaie", "Solo i maschi", "Solo le giovani regine"], x: "La colonia muore in autunno. Solo le giovani regine fecondate svernano nel terreno e in primavera fondano una nuova colonia.", k: "Bombi: svernano solo le giovani regine" } } },
  { id: "b25", lvl: 2, type: "tf", right: 1, t: { de: { q: "Drei Hornissenstiche können einen gesunden Erwachsenen töten.", a: ["Wahr", "Falsch"], x: "Ein alter Mythos: Hornissengift ist nicht gefährlicher als Bienengift. Riskant sind Stiche vor allem für Allergiker.", k: "Hornissen: nicht giftiger als Bienen" }, en: { q: "Three hornet stings can kill a healthy adult.", a: ["True", "False"], x: "An old myth: hornet venom is no more dangerous than bee venom. Stings are mainly risky for people with allergies.", k: "Hornets: no more venomous than bees" }, fr: { q: "Trois piqûres de frelon peuvent tuer un adulte en bonne santé.", a: ["Vrai", "Faux"], x: "Un vieux mythe : le venin du frelon n'est pas plus dangereux que celui de l'abeille. Le risque concerne surtout les allergiques.", k: "Frelons : pas plus venimeux que les abeilles" }, es: { q: "Tres picaduras de avispón pueden matar a un adulto sano.", a: ["Verdadero", "Falso"], x: "Es un viejo mito: su veneno no es más peligroso que el de la abeja. El riesgo es sobre todo para personas alérgicas.", k: "Avispones: no más venenosos que las abejas" }, pt: { q: "Três picadas de vespão podem matar um adulto saudável.", a: ["Verdadeiro", "Falso"], x: "É um velho mito: o veneno do vespão não é mais perigoso que o da abelha. O risco é sobretudo para pessoas alérgicas.", k: "Vespões: não mais venenosos que abelhas" }, ja: { q: "正しい？まちがい？ スズメバチに3回刺されると、健康な大人でも死ぬ。", a: ["正しい", "まちがい"], x: "古い俗説です。ヨーロッパのモンスズメバチの毒は、ミツバチの毒より危険なわけではありません。危ないのは主にアレルギーのある人です。", k: "スズメバチ：毒はミツバチ並み" }, it: { q: "Vero o falso? Tre punture di calabrone possono uccidere un adulto sano.", a: ["Vero", "Falso"], x: "Un vecchio mito: il veleno del calabrone non è più pericoloso di quello dell’ape. Le punture sono rischiose soprattutto per chi è allergico.", k: "Calabroni: non più velenosi delle api" } } },
  { id: "b26", lvl: 2, type: "text", right: 0, t: { de: { q: "Warum beschützen manche Ameisen Blattläuse?", a: ["Sie bekommen süßen Honigtau", "Sie fressen deren Eier", "Die Läuse wärmen das Nest", "Die Läuse bauen Nestkammern"], x: "Blattläuse scheiden zuckerhaltigen Honigtau aus. Ameisen 'melken' sie und halten dafür Feinde wie Marienkäfer fern.", k: "Ameisen: melken Blattläuse" }, en: { q: "Why do some ants protect aphids?", a: ["They get sweet honeydew", "They eat the aphids' eggs", "The aphids warm the nest", "The aphids build nest chambers"], x: "Aphids excrete sugary honeydew. Ants 'milk' them and in return keep enemies like ladybirds away.", k: "Ants: milk aphids" }, fr: { q: "Pourquoi certaines fourmis protègent-elles les pucerons ?", a: ["Elles obtiennent du miellat sucré", "Elles mangent leurs œufs", "Les pucerons chauffent le nid", "Les pucerons creusent le nid"], x: "Les pucerons rejettent un miellat sucré. Les fourmis les « traient » et éloignent en échange les coccinelles.", k: "Fourmis : traient les pucerons" }, es: { q: "¿Por qué algunas hormigas protegen a los pulgones?", a: ["Obtienen melaza dulce", "Se comen sus huevos", "Los pulgones calientan el nido", "Los pulgones excavan el nido"], x: "Los pulgones excretan una melaza azucarada. Las hormigas los «ordeñan» y a cambio alejan a enemigos como las mariquitas.", k: "Hormigas: ordeñan pulgones" }, pt: { q: "Por que algumas formigas protegem os pulgões?", a: ["Ganham melada doce", "Comem os ovos deles", "Os pulgões aquecem o ninho", "Os pulgões cavam o ninho"], x: "Os pulgões soltam uma melada açucarada. As formigas os “ordenham” e, em troca, afastam inimigos como as joaninhas.", k: "Formigas: ordenham pulgões" }, ja: { q: "アリがアブラムシを守るのはなぜ？", a: ["甘い甘露がもらえる", "アブラムシの卵を食べる", "アブラムシが巣を温める", "アブラムシが巣の部屋を作る"], x: "アブラムシは甘い甘露を出します。アリはそれを「しぼり」、お返しにテントウムシなどの敵を追いはらいます。", k: "アリ：アブラムシの甘露をしぼる" }, it: { q: "Perché alcune formiche proteggono gli afidi?", a: ["Ricevono melata dolce", "Mangiano le uova degli afidi", "Gli afidi scaldano il nido", "Gli afidi costruiscono le camere del nido"], x: "Gli afidi espellono una melata zuccherina. Le formiche li «mungono» e in cambio tengono lontani nemici come le coccinelle.", k: "Formiche: mungono gli afidi" } } },
  { id: "b27", lvl: 2, type: "tf", right: 1, t: { de: { q: "Molche verbringen das ganze Jahr im Wasser.", a: ["Wahr", "Falsch"], x: "Bergmolch, Teichmolch und Co. gehen meist nur zur Paarungszeit im Frühjahr ins Wasser und leben sonst an Land.", k: "Molche: leben meist an Land" }, en: { q: "Newts spend the whole year in the water.", a: ["True", "False"], x: "Alpine newts, smooth newts and co. mostly enter the water only to breed in spring and otherwise live on land.", k: "Newts: mostly live on land" }, fr: { q: "Les tritons passent toute l'année dans l'eau.", a: ["Vrai", "Faux"], x: "Les tritons alpestres, ponctués et autres ne vont en général à l'eau qu'au printemps pour se reproduire et vivent sinon à terre.", k: "Tritons : vivent surtout sur terre" }, es: { q: "Los tritones pasan todo el año en el agua.", a: ["Verdadero", "Falso"], x: "El tritón alpino y otros suelen ir al agua solo para reproducirse en primavera; el resto del año viven en tierra.", k: "Tritones: viven sobre todo en tierra" }, pt: { q: "Os tritões passam o ano todo na água.", a: ["Verdadeiro", "Falso"], x: "O tritão-alpino e outros costumam ir à água só para se reproduzir na primavera; no resto do ano vivem em terra.", k: "Tritões: vivem mais em terra" }, ja: { q: "正しい？まちがい？ イモリは一年中、水の中で暮らす。", a: ["正しい", "まちがい"], x: "ミヤマイモリやスベイモリなどは、ほとんど春の繁殖期にだけ水に入り、ほかの時期は陸で暮らします。", k: "イモリ：ほとんど陸で暮らす" }, it: { q: "Vero o falso? I tritoni passano tutto l’anno in acqua.", a: ["Vero", "Falso"], x: "Tritone alpestre, tritone punteggiato e simili entrano in acqua per lo più solo per riprodursi in primavera; per il resto vivono sulla terraferma.", k: "Tritoni: vivono soprattutto sulla terra" } } },
  { id: "b28", lvl: 1, type: "text", right: 0, t: { de: { q: "Auf welcher Pflanze fressen die Raupen des Tagpfauenauges?", a: ["Brennnessel", "Kohl", "Eiche", "Löwenzahn"], x: "Brennnesseln sind Kinderstube für Tagpfauenauge, Kleinen Fuchs und Admiral. Lass im Garten eine wilde Ecke stehen!", k: "Brennnessel: Kinderstube für Tagpfauenaugen" }, en: { q: "Which plant do peacock butterfly caterpillars feed on?", a: ["Stinging nettle", "Cabbage", "Oak", "Dandelion"], x: "Nettles are a nursery for the peacock, small tortoiseshell and red admiral. Leave a wild corner in your garden!", k: "Nettles: nursery for peacock butterflies" }, fr: { q: "De quelle plante se nourrissent les chenilles du paon-du-jour ?", a: ["Ortie", "Chou", "Chêne", "Pissenlit"], x: "Les orties sont la nurserie du paon-du-jour, de la petite tortue et du vulcain. Laissez un coin sauvage au jardin !", k: "Ortie : nurserie du paon-du-jour" }, es: { q: "¿De qué planta se alimentan las orugas de la mariposa pavo real?", a: ["Ortiga", "Col", "Roble", "Diente de león"], x: "Las ortigas son la guardería de la pavo real, la ortiguera y la vanesa atalanta. ¡Deja un rincón salvaje en el jardín!", k: "Ortiga: guardería de la mariposa pavo real" }, pt: { q: "De que planta se alimentam as lagartas da borboleta-pavão?", a: ["Urtiga", "Couve", "Carvalho", "Dente-de-leão"], x: "As urtigas são o berçário da borboleta-pavão, da borboleta-da-urtiga e do almirante-vermelho. Deixe um cantinho selvagem no jardim!", k: "Urtiga: berçário da borboleta-pavão" }, ja: { q: "クジャクチョウの幼虫が食べる植物は？", a: ["イラクサ", "キャベツ", "カシ", "タンポポ"], x: "イラクサはクジャクチョウやヒメアカタテハ、ヨーロッパアカタテハのゆりかご。庭に野生のすみっこを残しておこう！", k: "イラクサ：クジャクチョウのゆりかご" }, it: { q: "Di quale pianta si nutrono i bruchi della vanessa occhio di pavone?", a: ["Ortica", "Cavolo", "Quercia", "Tarassaco"], x: "L’ortica è un asilo per occhio di pavone, vanessa dell’ortica e vulcano. Lascia un angolo selvatico in giardino!", k: "Ortica: asilo per la vanessa occhio di pavone" } } },
  { id: "b29", lvl: 3, type: "text", right: 2, t: { de: { q: "Woher stammen viele Distelfalter, die im Frühjahr bei uns auftauchen?", a: ["Aus Skandinavien", "Aus Sibirien", "Aus Nordafrika und Südeuropa", "Aus Nordamerika"], x: "Distelfalter wandern in mehreren Generationen von Afrika bis Nordeuropa – ein Staffellauf über Tausende Kilometer.", k: "Distelfalter: fliegen aus Afrika zu uns" }, en: { q: "Where do many painted ladies that appear in Central Europe in spring come from?", a: ["From Scandinavia", "From Siberia", "From North Africa and southern Europe", "From North America"], x: "Painted ladies migrate over several generations from Africa to northern Europe – a relay over thousands of kilometres.", k: "Painted ladies: fly in from Africa" }, fr: { q: "D'où viennent beaucoup de belles-dames qui arrivent au printemps en Europe centrale ?", a: ["De Scandinavie", "De Sibérie", "D'Afrique du Nord et d'Europe du Sud", "D'Amérique du Nord"], x: "La belle-dame migre sur plusieurs générations de l'Afrique au nord de l'Europe : un relais de milliers de kilomètres.", k: "Belles-dames : arrivent d’Afrique" }, es: { q: "¿De dónde vienen muchas vanesas de los cardos que llegan en primavera a Centroeuropa?", a: ["De Escandinavia", "De Siberia", "Del norte de África y el sur de Europa", "De Norteamérica"], x: "Migran en varias generaciones desde África hasta el norte de Europa: un relevo de miles de kilómetros.", k: "Vanesas de los cardos: llegan desde África" }, pt: { q: "De onde vêm muitas borboletas-dos-cardos que chegam na primavera à Europa Central?", a: ["Da Escandinávia", "Da Sibéria", "Do norte da África e do sul da Europa", "Da América do Norte"], x: "Elas migram em várias gerações da África até o norte da Europa: um revezamento de milhares de quilômetros.", k: "Vanessas: chegam voando da África" }, ja: { q: "春に中央ヨーロッパに現れるヒメアカタテハの多くは、どこから来る？", a: ["スカンジナビアから", "シベリアから", "北アフリカと南ヨーロッパから", "北アメリカから"], x: "ヒメアカタテハは何世代もかけてアフリカから北ヨーロッパへ渡ります。何千キロものリレーです。", k: "ヒメアカタテハ：アフリカから飛んでくる" }, it: { q: "Da dove vengono molte vanesse del cardo che compaiono in Europa centrale in primavera?", a: ["Dalla Scandinavia", "Dalla Siberia", "Dal Nord Africa e dal Sud Europa", "Dal Nord America"], x: "Le vanesse del cardo migrano in più generazioni dall’Africa al Nord Europa: una staffetta di migliaia di chilometri.", k: "Vanesse del cardo: arrivano dall’Africa" } } },
  { id: "b30", lvl: 2, type: "text", right: 0, t: { de: { q: "Wie kümmern sich Wolfspinnen-Weibchen um ihren Nachwuchs?", a: ["Sie tragen die Jungen auf dem Rücken", "Sie füttern sie mit Blütennektar", "Sie legen die Eier ins Wasser", "Sie legen die Eier in Vogelnester"], x: "Erst schleppen sie den Eikokon an den Spinnwarzen mit. Die geschlüpften Jungen reiten dann einige Tage auf ihrem Rücken.", k: "Wolfspinnen: tragen ihre Jungen auf dem Rücken" }, en: { q: "How do female wolf spiders care for their young?", a: ["They carry them on their back", "They feed them flower nectar", "They lay their eggs in water", "They lay their eggs in bird nests"], x: "First they drag the egg sac along on their spinnerets. The hatched young then ride on their back for some days.", k: "Wolf spiders: carry their young on their back" }, fr: { q: "Comment les femelles d'araignée-loup s'occupent-elles de leurs petits ?", a: ["Elles les portent sur le dos", "Elles les nourrissent de nectar", "Elles pondent dans l'eau", "Elles pondent dans des nids d'oiseaux"], x: "Elles traînent d'abord leur cocon accroché aux filières. Puis les petits voyagent quelques jours sur leur dos.", k: "Lycoses : portent leurs petits sur le dos" }, es: { q: "¿Cómo cuidan las hembras de araña lobo a sus crías?", a: ["Las llevan sobre la espalda", "Las alimentan con néctar", "Ponen los huevos en el agua", "Ponen los huevos en nidos de aves"], x: "Primero arrastran el saco de huevos sujeto a las hileras. Luego las crías viajan unos días sobre su espalda.", k: "Arañas lobo: llevan a sus crías a cuestas" }, pt: { q: "Como as fêmeas da aranha-lobo cuidam dos filhotes?", a: ["Carregam-nos nas costas", "Alimentam-nos com néctar", "Põem os ovos na água", "Põem os ovos em ninhos de aves"], x: "Primeiro elas arrastam o saco de ovos preso às fiandeiras. Depois os filhotes viajam alguns dias nas costas da mãe.", k: "Aranhas-lobo: carregam os filhotes nas costas" }, ja: { q: "コモリグモのメスはどうやって子育てする？", a: ["子どもを背中にのせて運ぶ", "花の蜜をあげる", "水の中に卵を産む", "鳥の巣に卵を産む"], x: "まず卵のうを糸いぼにつけて運びます。かえった子どもたちは、何日か母親の背中に乗って過ごします。", k: "コモリグモ：子どもを背中で運ぶ" }, it: { q: "Come si prendono cura dei piccoli le femmine di ragno lupo?", a: ["Li portano sul dorso", "Li nutrono con il nettare", "Depongono le uova in acqua", "Depongono le uova nei nidi degli uccelli"], x: "Prima si trascinano dietro il sacco delle uova attaccato alle filiere. Poi i piccoli appena nati viaggiano qualche giorno sul loro dorso.", k: "Ragni lupo: portano i piccoli sul dorso" } } },
  { id: "b31", lvl: 3, type: "tf", right: 0, t: { de: { q: "Kreuzspinnen fressen ihr altes Netz oft auf, bevor sie ein neues bauen.", a: ["Wahr", "Falsch"], x: "So recyceln sie die wertvollen Eiweiße der Spinnenseide. Viele bauen ihr Netz fast täglich neu.", k: "Kreuzspinnen: fressen ihr altes Netz" }, en: { q: "Garden spiders often eat their old web before building a new one.", a: ["True", "False"], x: "This way they recycle the valuable proteins in the silk. Many rebuild their web almost every day.", k: "Garden spiders: eat their old web" }, fr: { q: "L'épeire diadème mange souvent sa vieille toile avant d'en tisser une nouvelle.", a: ["Vrai", "Faux"], x: "Elle recycle ainsi les précieuses protéines de la soie. Beaucoup refont leur toile presque chaque jour.", k: "Épeires : mangent leur vieille toile" }, es: { q: "La araña de jardín (epeira) suele comerse su vieja tela antes de tejer otra.", a: ["Verdadero", "Falso"], x: "Así recicla las valiosas proteínas de la seda. Muchas rehacen su tela casi a diario.", k: "Arañas de jardín: se comen su vieja tela" }, pt: { q: "A aranha-de-jardim costuma comer sua teia velha antes de tecer outra.", a: ["Verdadeiro", "Falso"], x: "Assim ela recicla as valiosas proteínas da seda. Muitas refazem a teia quase todo dia.", k: "Aranhas-de-jardim: comem a teia velha" }, ja: { q: "正しい？まちがい？ オニグモの仲間は、新しい網を張る前に古い網を食べることが多い。", a: ["正しい", "まちがい"], x: "こうして糸の貴重なたんぱく質を再利用します。多くはほぼ毎日網を張り直します。", k: "オニグモ：古い網を食べる" }, it: { q: "Vero o falso? I ragni crociati spesso mangiano la vecchia tela prima di costruirne una nuova.", a: ["Vero", "Falso"], x: "Così riciclano le preziose proteine della seta. Molti rifanno la tela quasi ogni giorno.", k: "Ragni crociati: mangiano la vecchia tela" } } },
  { id: "b32", lvl: 2, type: "text", right: 2, t: { de: { q: "Was fehlt dem Weberknecht im Gegensatz zu echten Spinnen?", a: ["Augen", "Mundwerkzeuge", "Spinndrüsen", "Beine mit Gelenken"], x: "Weberknechte sind Spinnentiere, aber keine Webspinnen: Sie bauen keine Netze, und ihr Körper wirkt wie aus einem Stück.", k: "Weberknechte: bauen keine Netze" }, en: { q: "What does a harvestman lack, unlike true spiders?", a: ["Eyes", "Mouthparts", "Silk glands", "Jointed legs"], x: "Harvestmen are arachnids but not spiders: they build no webs, and their body looks like one single piece.", k: "Harvestmen: don't build webs" }, fr: { q: "Que n'a pas l'opilion (faucheux), contrairement aux vraies araignées ?", a: ["Des yeux", "Des pièces buccales", "Des glandes à soie", "Des pattes articulées"], x: "Les opilions sont des arachnides mais pas des araignées : ils ne tissent pas de toile et leur corps semble d'une seule pièce.", k: "Opilions : ne tissent pas de toile" }, es: { q: "¿Qué le falta al opilión, a diferencia de las arañas?", a: ["Ojos", "Piezas bucales", "Glándulas de seda", "Patas articuladas"], x: "Los opiliones son arácnidos, pero no arañas: no tejen telas y su cuerpo parece de una sola pieza.", k: "Opiliones: no tejen telas" }, pt: { q: "O que o opilião NÃO tem, ao contrário das aranhas?", a: ["Olhos", "Peças bucais", "Glândulas de seda", "Patas articuladas"], x: "Os opiliões são aracnídeos, mas não aranhas: não tecem teias e o corpo parece de uma peça só.", k: "Opiliões: não tecem teias" }, ja: { q: "ザトウムシには、本物のクモとちがって何がない？", a: ["目", "口", "糸を出す腺", "節のある脚"], x: "ザトウムシはクモの仲間（クモガタ類）ですが、クモではありません。網を張らず、体はひとつのかたまりに見えます。", k: "ザトウムシ：網を張らない" }, it: { q: "Cosa manca a un opilione, a differenza dei veri ragni?", a: ["Gli occhi", "La bocca", "Le ghiandole della seta", "Le zampe articolate"], x: "Gli opilioni sono aracnidi ma non ragni: non costruiscono tele e il loro corpo sembra un pezzo unico.", k: "Opilioni: non tessono tele" } } },
  { id: "b33", lvl: 2, type: "tf", right: 1, t: { de: { q: "Teilt man einen Regenwurm, entstehen daraus zwei vollständige Würmer.", a: ["Wahr", "Falsch"], x: "Meist überlebt höchstens das vordere Stück und bildet ein neues Hinterende. Das hintere Stück stirbt in der Regel.", k: "Regenwurm: aus zwei Hälften werden keine zwei Würmer" }, en: { q: "If you cut an earthworm in two, you get two complete worms.", a: ["True", "False"], x: "Usually only the front part may survive and grow a new rear end. The back part normally dies.", k: "Earthworm: cut in two doesn't make two worms" }, fr: { q: "Si l'on coupe un ver de terre en deux, on obtient deux vers complets.", a: ["Vrai", "Faux"], x: "En général, seule la partie avant peut survivre et refaire une nouvelle queue. La partie arrière meurt le plus souvent.", k: "Ver de terre coupé : pas deux vers" }, es: { q: "Si se corta una lombriz en dos, salen dos lombrices completas.", a: ["Verdadero", "Falso"], x: "Normalmente solo la parte delantera puede sobrevivir y regenerar un nuevo extremo trasero. La trasera suele morir.", k: "Lombriz cortada: no salen dos lombrices" }, pt: { q: "Se cortarmos uma minhoca ao meio, surgem duas minhocas inteiras.", a: ["Verdadeiro", "Falso"], x: "Normalmente só a parte da frente pode sobreviver e regenerar uma nova parte de trás. A parte de trás costuma morrer.", k: "Minhoca cortada: não vira duas minhocas" }, ja: { q: "正しい？まちがい？ ミミズを2つに切ると、2匹の完全なミミズになる。", a: ["正しい", "まちがい"], x: "生きのびられるのはたいてい前の部分だけで、新しいおしりが生えてくることがあります。後ろの部分はふつう死んでしまいます。", k: "ミミズ：切っても2匹にはならない" }, it: { q: "Vero o falso? Se tagli un lombrico in due, ottieni due lombrichi completi.", a: ["Vero", "Falso"], x: "Di solito sopravvive solo la parte anteriore, che può far ricrescere la parte posteriore. La parte dietro di solito muore.", k: "Lombrico tagliato: non diventa due lombrichi" } } },
  { id: "b34", lvl: 3, type: "tf", right: 0, t: { de: { q: "Haie haben keine Schwimmblase.", a: ["Wahr", "Falsch"], x: "Auftrieb gibt Haien vor allem eine große, ölreiche Leber. Viele müssen schwimmen, um nicht abzusinken.", k: "Haie: haben keine Schwimmblase" }, en: { q: "Sharks have no swim bladder.", a: ["True", "False"], x: "Instead, a large oil-rich liver gives sharks buoyancy. Many must keep swimming so they don't sink.", k: "Sharks: have no swim bladder" }, fr: { q: "Les requins n'ont pas de vessie natatoire.", a: ["Vrai", "Faux"], x: "Un grand foie riche en huile les aide à flotter. Beaucoup doivent nager sans cesse pour ne pas couler.", k: "Requins : pas de vessie natatoire" }, es: { q: "Los tiburones no tienen vejiga natatoria.", a: ["Verdadero", "Falso"], x: "Un hígado grande y rico en aceite les ayuda a flotar. Muchos deben nadar para no hundirse.", k: "Tiburones: sin vejiga natatoria" }, pt: { q: "Os tubarões não têm bexiga natatória.", a: ["Verdadeiro", "Falso"], x: "Um fígado grande e cheio de óleo ajuda a flutuar. Muitos precisam nadar para não afundar.", k: "Tubarões: sem bexiga natatória" }, ja: { q: "正しい？まちがい？ サメには浮き袋がない。", a: ["正しい", "まちがい"], x: "かわりに、油をたっぷりふくんだ大きな肝臓で浮力を得ます。沈まないように泳ぎ続けなければならないサメも多いのです。", k: "サメ：浮き袋がない" }, it: { q: "Vero o falso? Gli squali non hanno la vescica natatoria.", a: ["Vero", "Falso"], x: "Al suo posto, un grande fegato ricco d’olio dà agli squali la spinta per galleggiare. Molti devono nuotare sempre per non affondare.", k: "Squali: senza vescica natatoria" } } },
  { id: "b35", lvl: 1, type: "text", right: 1, t: { de: { q: "Wer bringt beim Seepferdchen die Jungen zur Welt?", a: ["Das Weibchen", "Das Männchen", "Beide abwechselnd", "Niemand – Eier liegen im Sand"], x: "Das Weibchen legt die Eier in die Bruttasche des Männchens. Dort entwickeln sie sich, bis er die Jungen 'gebärt'.", k: "Seepferdchen: das Männchen bekommt die Jungen" }, en: { q: "Which seahorse parent gives birth to the young?", a: ["The female", "The male", "Both, taking turns", "Neither – eggs lie in the sand"], x: "The female puts her eggs into the male's brood pouch. They develop there until he 'gives birth' to the young.", k: "Seahorses: the male gives birth" }, fr: { q: "Chez l'hippocampe, qui met les petits au monde ?", a: ["La femelle", "Le mâle", "Les deux à tour de rôle", "Personne : les œufs sont au sol"], x: "La femelle dépose ses œufs dans la poche incubatrice du mâle. Ils s'y développent jusqu'à ce qu'il « accouche ».", k: "Hippocampe : le mâle met bas" }, es: { q: "¿Quién da a luz a las crías del caballito de mar?", a: ["La hembra", "El macho", "Ambos, por turnos", "Nadie: los huevos están en la arena"], x: "La hembra deposita los huevos en la bolsa incubadora del macho. Allí se desarrollan hasta que él «da a luz».", k: "Caballito de mar: el macho da a luz" }, pt: { q: "Quem dá à luz os filhotes do cavalo-marinho?", a: ["A fêmea", "O macho", "Os dois, revezando", "Ninguém: os ovos ficam na areia"], x: "A fêmea deposita os ovos na bolsa incubadora do macho. Ali eles se desenvolvem até que ele “dá à luz”.", k: "Cavalo-marinho: o macho dá à luz" }, ja: { q: "タツノオトシゴで子どもを産むのはどっちの親？", a: ["メス", "オス", "両方が交代で", "どちらでもない。卵は砂の上"], x: "メスがオスのおなかの育児のうに卵を入れます。卵はそこで育ち、オスが子どもを「出産」します。", k: "タツノオトシゴ：オスが出産する" }, it: { q: "Nel cavalluccio marino, quale genitore partorisce i piccoli?", a: ["La femmina", "Il maschio", "Entrambi, a turno", "Nessuno: le uova stanno nella sabbia"], x: "La femmina mette le uova nella tasca incubatrice del maschio. Lì si sviluppano finché lui non «partorisce» i piccoli.", k: "Cavalluccio marino: partorisce il maschio" } } },
  { id: "b36", lvl: 1, type: "text", right: 2, t: { de: { q: "Wozu hängt man im Garten mit Holzwolle gefüllte Tontöpfe kopfüber auf?", a: ["Als Falle für Schnecken", "Als Winterquartier für Igel", "Als Versteck für Ohrwürmer", "Als Futterstelle für Vögel"], x: "Ohrwürmer verstecken sich tagsüber darin und fressen nachts Blattläuse. In Ohren kriechen sie übrigens nicht gezielt.", k: "Ohrwürmer: fressen Blattläuse" }, en: { q: "Why do gardeners hang clay pots filled with wood wool upside down?", a: ["As a trap for slugs", "As a winter home for hedgehogs", "As a shelter for earwigs", "As a bird feeder"], x: "Earwigs hide in them by day and eat aphids at night. And no, they don't deliberately crawl into ears.", k: "Earwigs: eat aphids" }, fr: { q: "Pourquoi suspend-on au jardin des pots en terre remplis de fibre de bois, à l'envers ?", a: ["Pour piéger les limaces", "Pour abriter les hérissons l'hiver", "Pour abriter les perce-oreilles", "Pour nourrir les oiseaux"], x: "Les perce-oreilles s'y cachent le jour et mangent des pucerons la nuit. Ils n'entrent pas exprès dans les oreilles.", k: "Perce-oreilles : mangent les pucerons" }, es: { q: "¿Para qué se cuelgan boca abajo macetas de barro con viruta de madera?", a: ["Como trampa para babosas", "Como refugio invernal para erizos", "Como refugio para tijeretas", "Como comedero para pájaros"], x: "Las tijeretas se esconden en ellas de día y comen pulgones de noche. Y no, no se meten a propósito en los oídos.", k: "Tijeretas: comen pulgones" }, pt: { q: "Para que se penduram vasos de barro de cabeça para baixo, cheios de palha?", a: ["Como armadilha para lesmas", "Como abrigo de inverno para ouriços", "Como abrigo para tesourinhas", "Como comedouro para pássaros"], x: "As tesourinhas se escondem neles de dia e comem pulgões à noite. E não, elas não entram de propósito nos ouvidos.", k: "Tesourinhas: comem pulgões" }, ja: { q: "園芸好きが、木毛をつめた植木鉢を逆さにつるすのはなぜ？", a: ["ナメクジのわなとして", "ハリネズミの冬の家として", "ハサミムシの隠れ家として", "鳥のえさ台として"], x: "ハサミムシは昼間そこにかくれ、夜にアブラムシを食べます。それに、わざと耳に入ってくることはありません。", k: "ハサミムシ：アブラムシを食べる" }, it: { q: "Perché i giardinieri appendono a testa in giù vasi di terracotta pieni di paglia di legno?", a: ["Come trappola per lumache", "Come casa invernale per ricci", "Come rifugio per le forbicine", "Come mangiatoia per uccelli"], x: "Di giorno le forbicine ci si nascondono e di notte mangiano gli afidi. E no, non entrano apposta nelle orecchie.", k: "Forbicine: mangiano afidi" } } },
  { id: "b37", lvl: 1, type: "text", right: 3, t: { de: { q: "Schwebfliegen sehen oft aus wie Wespen. Was stimmt?", a: ["Sie stechen stärker als Wespen", "Sie haben vier Flügel wie Wespen", "Sie sind junge Wespen", "Sie sind harmlos und ahmen Wespen nach"], x: "Die Tarnung schreckt Feinde ab. Die Larven vieler Schwebfliegen fressen Blattläuse – echte Gartenhelfer!", k: "Schwebfliegen: harmlose Wespen-Doubles" }, en: { q: "Hoverflies often look like wasps. What is true?", a: ["They sting harder than wasps", "They have four wings like wasps", "They are young wasps", "They're harmless wasp mimics"], x: "The disguise scares off enemies. The larvae of many hoverflies eat aphids – real garden helpers!", k: "Hoverflies: harmless wasp look-alikes" }, fr: { q: "Les syrphes ressemblent souvent à des guêpes. Qu'est-ce qui est vrai ?", a: ["Ils piquent plus fort que les guêpes", "Ils ont quatre ailes comme les guêpes", "Ce sont de jeunes guêpes", "Inoffensifs, ils imitent les guêpes"], x: "Ce déguisement effraie les ennemis. Les larves de nombreux syrphes mangent des pucerons : de vrais alliés du jardin !", k: "Syrphes : sosies inoffensifs des guêpes" }, es: { q: "Los sírfidos suelen parecer avispas. ¿Qué es cierto?", a: ["Pican más fuerte que las avispas", "Tienen cuatro alas como las avispas", "Son avispas jóvenes", "Son inofensivos e imitan a avispas"], x: "El disfraz asusta a los enemigos. Las larvas de muchos sírfidos comen pulgones: ¡grandes ayudantes del jardín!", k: "Sírfidos: dobles inofensivos de las avispas" }, pt: { q: "As moscas-das-flores muitas vezes parecem vespas. O que é verdade?", a: ["Picam mais forte que as vespas", "Têm quatro asas como as vespas", "São vespas jovens", "São inofensivas e imitam vespas"], x: "O disfarce assusta os inimigos. As larvas de muitas moscas-das-flores comem pulgões – ótimas ajudantes do jardim!", k: "Sirfídeos: sósias inofensivos das vespas" }, ja: { q: "ハナアブはハチによく似ている。正しいのは？", a: ["ハチより強く刺す", "ハチのように羽が4枚ある", "ハチの子ども", "無害なハチのそっくりさん"], x: "変装で敵をこわがらせるのです。多くのハナアブの幼虫はアブラムシを食べます。庭の名助っ人！", k: "ハナアブ：無害なハチのそっくりさん" }, it: { q: "I sirfidi somigliano spesso alle vespe. Cosa è vero?", a: ["Pungono più forte delle vespe", "Hanno quattro ali come le vespe", "Sono vespe giovani", "Sono innocui imitatori delle vespe"], x: "Il travestimento spaventa i nemici. Le larve di molti sirfidi mangiano afidi: veri aiutanti del giardino!", k: "Sirfidi: sosia innocui delle vespe" } } },
  { id: "b38", lvl: 1, type: "text", right: 2, t: { de: { q: "Welche Tiergruppe hat weltweit die meisten bekannten Arten?", a: ["Vögel", "Fische", "Käfer", "Schmetterlinge"], x: "Mit rund 350.000 bis 400.000 beschriebenen Arten sind Käfer die artenreichste Tiergruppe der Erde.", k: "Käfer: die artenreichste Tiergruppe" }, en: { q: "Which animal group has the most known species worldwide?", a: ["Birds", "Fish", "Beetles", "Butterflies and moths"], x: "With around 350,000 to 400,000 described species, beetles are the most species-rich animal group on Earth.", k: "Beetles: the most species-rich animal group" }, fr: { q: "Quel groupe d'animaux compte le plus d'espèces connues au monde ?", a: ["Les oiseaux", "Les poissons", "Les coléoptères", "Les papillons"], x: "Avec environ 350 000 à 400 000 espèces décrites, les coléoptères sont le groupe animal le plus riche en espèces.", k: "Coléoptères : le groupe le plus riche en espèces" }, es: { q: "¿Qué grupo de animales tiene más especies conocidas en el mundo?", a: ["Las aves", "Los peces", "Los escarabajos", "Las mariposas"], x: "Con unas 350.000 a 400.000 especies descritas, los escarabajos son el grupo animal con más especies de la Tierra.", k: "Escarabajos: el grupo con más especies" }, pt: { q: "Qual grupo de animais tem mais espécies conhecidas no mundo?", a: ["As aves", "Os peixes", "Os besouros", "As borboletas"], x: "Com cerca de 350.000 a 400.000 espécies descritas, os besouros são o grupo animal com mais espécies da Terra.", k: "Besouros: o grupo com mais espécies" }, ja: { q: "世界で知られている種の数がいちばん多い動物グループは？", a: ["鳥", "魚", "甲虫", "チョウとガ"], x: "記載されている種は約35万〜40万。甲虫は地球でいちばん種の多い動物グループです。", k: "甲虫：いちばん種の多い動物グループ" }, it: { q: "Quale gruppo di animali ha più specie conosciute al mondo?", a: ["Uccelli", "Pesci", "Coleotteri", "Farfalle e falene"], x: "Con circa 350.000–400.000 specie descritte, i coleotteri sono il gruppo di animali più ricco di specie della Terra.", k: "Coleotteri: il gruppo con più specie" } } },
  { id: "b39", lvl: 2, type: "text", right: 1, t: { de: { q: "Wo laicht der Europäische Aal?", a: ["Im Bodensee", "In der Sargassosee", "Im Wattenmeer", "In Gebirgsbächen"], x: "Aale wandern Tausende Kilometer in die Sargassosee im Atlantik. Ihre Larven treiben mit der Strömung zurück nach Europa.", k: "Aal: laicht in der Sargassosee" }, en: { q: "Where does the European eel spawn?", a: ["In Lake Constance", "In the Sargasso Sea", "In the Wadden Sea", "In mountain streams"], x: "Eels travel thousands of kilometres to the Sargasso Sea in the Atlantic. Their larvae drift back to Europe on currents.", k: "Eel: spawns in the Sargasso Sea" }, fr: { q: "Où se reproduit l'anguille européenne ?", a: ["Dans le lac de Constance", "Dans la mer des Sargasses", "Dans la mer des Wadden", "Dans les torrents de montagne"], x: "Les anguilles parcourent des milliers de kilomètres jusqu'à la mer des Sargasses. Leurs larves dérivent ensuite vers l'Europe.", k: "Anguille : se reproduit dans la mer des Sargasses" }, es: { q: "¿Dónde desova la anguila europea?", a: ["En el lago de Constanza", "En el mar de los Sargazos", "En el mar de Wadden", "En arroyos de montaña"], x: "Las anguilas recorren miles de kilómetros hasta el mar de los Sargazos. Sus larvas vuelven a Europa con las corrientes.", k: "Anguila: desova en el mar de los Sargazos" }, pt: { q: "Onde a enguia-europeia desova?", a: ["No lago de Constança", "No mar dos Sargaços", "No mar de Wadden", "Em riachos de montanha"], x: "As enguias percorrem milhares de quilômetros até o mar dos Sargaços. Suas larvas voltam à Europa com as correntes.", k: "Enguia: desova no Mar dos Sargaços" }, ja: { q: "ヨーロッパウナギはどこで産卵する？", a: ["ボーデン湖", "サルガッソー海", "ワッデン海", "山の川"], x: "ウナギは何千キロも旅して、大西洋のサルガッソー海へ向かいます。幼生は海流に乗ってヨーロッパへもどります。", k: "ウナギ：サルガッソー海で産卵" }, it: { q: "Dove si riproduce l’anguilla europea?", a: ["Nel Lago di Costanza", "Nel Mar dei Sargassi", "Nel Mare dei Wadden", "Nei torrenti di montagna"], x: "Le anguille viaggiano per migliaia di chilometri fino al Mar dei Sargassi, nell’Atlantico. Le larve tornano in Europa trasportate dalle correnti.", k: "Anguilla: si riproduce nel Mar dei Sargassi" } } },
  { id: "b40", lvl: 2, type: "text", right: 2, t: { de: { q: "Woran erkennen Lachse ihren Heimatfluss, um dort zu laichen?", a: ["An der Farbe des Wassers", "Am Rauschen von Wasserfällen", "Am Geruch des Wassers", "Sie folgen den Aalen"], x: "Junge Lachse prägen sich den Geruch ihres Heimatgewässers ein. Jahre später finden sie damit aus dem Meer zurück.", k: "Lachse: finden ihren Fluss am Geruch" }, en: { q: "How do salmon recognise their home river to spawn there?", a: ["By the colour of the water", "By the sound of waterfalls", "By the smell of the water", "They follow the eels"], x: "Young salmon memorise the smell of their home waters. Years later, they use it to find their way back from the sea.", k: "Salmon: find their river by smell" }, fr: { q: "Comment les saumons reconnaissent-ils leur rivière natale pour y frayer ?", a: ["À la couleur de l'eau", "Au bruit des cascades", "À l'odeur de l'eau", "Ils suivent les anguilles"], x: "Les jeunes saumons mémorisent l'odeur de leur rivière natale. Des années plus tard, elle les guide depuis la mer.", k: "Saumons : retrouvent leur rivière à l’odeur" }, es: { q: "¿Cómo reconocen los salmones su río natal para desovar allí?", a: ["Por el color del agua", "Por el ruido de las cascadas", "Por el olor del agua", "Siguen a las anguilas"], x: "Los salmones jóvenes memorizan el olor de su río natal. Años después, lo usan para volver desde el mar.", k: "Salmones: encuentran su río por el olor" }, pt: { q: "Como os salmões reconhecem o rio onde nasceram para desovar lá?", a: ["Pela cor da água", "Pelo barulho das cachoeiras", "Pelo cheiro da água", "Seguem as enguias"], x: "Os salmões jovens memorizam o cheiro do rio natal. Anos depois, usam isso para voltar do mar.", k: "Salmões: acham o rio pelo cheiro" }, ja: { q: "サケは産卵のため、どうやって生まれた川を見分ける？", a: ["水の色で", "滝の音で", "水のにおいで", "ウナギについていく"], x: "若いサケはふるさとの川のにおいを覚えます。何年もあとに、そのにおいをたよりに海からもどってきます。", k: "サケ：においで生まれた川を見つける" }, it: { q: "Come riconoscono i salmoni il fiume natale per deporre le uova?", a: ["Dal colore dell’acqua", "Dal rumore delle cascate", "Dall’odore dell’acqua", "Seguono le anguille"], x: "I giovani salmoni memorizzano l’odore delle acque di casa. Anni dopo lo usano per ritrovare la strada dal mare.", k: "Salmoni: ritrovano il fiume dall’odore" } } },
  { id: "b41", lvl: 2, type: "text", right: 3, t: { de: { q: "Welche Gartenbeleuchtung lockt nachts am wenigsten Insekten an?", a: ["Kaltweißes Licht", "Bläuliches Licht", "Lampen mit UV-Anteil", "Warmweißes, gelbliches Licht"], x: "Insekten fliegen vor allem auf blaues und UV-Licht. Besser: warmweiße, nach unten gerichtete Lampen – oder gar kein Licht.", k: "Warmweißes Licht: lockt kaum Insekten an" }, en: { q: "Which garden lighting attracts the fewest insects at night?", a: ["Cool white light", "Bluish light", "Lamps that emit UV", "Warm white, yellowish light"], x: "Insects are drawn mostly to blue and UV light. Better: warm white lamps pointing downwards – or no light at all.", k: "Warm white light: attracts few insects" }, fr: { q: "Quel éclairage de jardin attire le moins d'insectes la nuit ?", a: ["Lumière blanc froid", "Lumière bleutée", "Lampes émettant des UV", "Lumière blanc chaud, jaunâtre"], x: "Les insectes sont surtout attirés par la lumière bleue et UV. Mieux : des lampes blanc chaud dirigées vers le bas, ou pas de lumière.", k: "Lumière blanc chaud : attire peu d’insectes" }, es: { q: "¿Qué iluminación de jardín atrae menos insectos por la noche?", a: ["Luz blanca fría", "Luz azulada", "Lámparas con luz UV", "Luz blanca cálida, amarillenta"], x: "Los insectos acuden sobre todo a la luz azul y UV. Mejor: lámparas cálidas orientadas hacia abajo, o ninguna luz.", k: "Luz blanca cálida: atrae pocos insectos" }, pt: { q: "Que iluminação de jardim atrai menos insetos à noite?", a: ["Luz branca fria", "Luz azulada", "Lâmpadas com luz UV", "Luz branca quente, amarelada"], x: "Os insetos vêm sobretudo à luz azul e UV. Melhor: lâmpadas quentes voltadas para baixo – ou luz nenhuma.", k: "Luz branca quente: atrai poucos insetos" }, ja: { q: "夜に虫がいちばん集まりにくい庭の明かりは？", a: ["白っぽい冷たい光", "青っぽい光", "紫外線を出すランプ", "暖かい白や黄色っぽい光"], x: "虫は特に青い光や紫外線に引きよせられます。おすすめは、下向きの暖かい白色のランプ。または明かりなし。", k: "暖かい白色の光：虫が集まりにくい" }, it: { q: "Quale luce da giardino attira meno insetti di notte?", a: ["Luce bianca fredda", "Luce bluastra", "Lampade che emettono UV", "Luce bianca calda, giallastra"], x: "Gli insetti sono attratti soprattutto da luce blu e UV. Meglio: lampade bianco caldo rivolte verso il basso, o nessuna luce.", k: "Luce bianca calda: attira pochi insetti" } } },
  { id: "b42", lvl: 2, type: "text", right: 3, t: { de: { q: "Was macht das Männchen des Dreistachligen Stichlings zur Laichzeit?", a: ["Es trägt die Eier im Maul", "Es vergräbt die Eier und schwimmt weg", "Es klebt die Eier an Wasservögel", "Es baut ein Nest und bewacht die Brut"], x: "Das Männchen bekommt einen roten Bauch, baut ein Nest aus Pflanzenteilen und fächelt den Eiern frisches Wasser zu.", k: "Stichling-Männchen: baut ein Nest" }, en: { q: "What does the male three-spined stickleback do in the breeding season?", a: ["Carries the eggs in its mouth", "Buries the eggs and swims off", "Sticks the eggs onto waterbirds", "Builds a nest and guards the brood"], x: "The male turns red-bellied, builds a nest from plant material and fans fresh water over the eggs.", k: "Male stickleback: builds a nest" }, fr: { q: "Que fait le mâle de l'épinoche à trois épines pendant la reproduction ?", a: ["Il porte les œufs dans sa bouche", "Il enterre les œufs et s'en va", "Il colle les œufs sur des oiseaux", "Il construit un nid et garde les œufs"], x: "Le mâle prend un ventre rouge, construit un nid de débris végétaux et ventile les œufs avec de l'eau fraîche.", k: "Épinoche mâle : construit un nid" }, es: { q: "¿Qué hace el macho del espinoso durante la reproducción?", a: ["Lleva los huevos en la boca", "Entierra los huevos y se va", "Pega los huevos a aves acuáticas", "Construye un nido y cuida la puesta"], x: "El macho se vuelve de vientre rojo, construye un nido con restos de plantas y abanica los huevos con agua fresca.", k: "Espinoso macho: construye un nido" }, pt: { q: "O que faz o macho do esgana-gata na reprodução?", a: ["Carrega os ovos na boca", "Enterra os ovos e vai embora", "Gruda os ovos em aves aquáticas", "Constrói um ninho e cuida da desova"], x: "O macho fica com a barriga vermelha, constrói um ninho com restos de plantas e abana os ovos com água fresca.", k: "Esgana-gata macho: constrói um ninho" }, ja: { q: "イトヨのオスは繁殖期に何をする？", a: ["卵を口に入れて運ぶ", "卵を埋めて泳ぎ去る", "卵を水鳥にくっつける", "巣を作って卵を守る"], x: "オスはおなかが赤くなり、植物で巣を作って、卵に新しい水を送り続けます。", k: "イトヨのオス：巣を作る" }, it: { q: "Cosa fa il maschio di spinarello nella stagione riproduttiva?", a: ["Porta le uova in bocca", "Seppellisce le uova e se ne va", "Attacca le uova agli uccelli acquatici", "Costruisce un nido e sorveglia la covata"], x: "Il maschio diventa rosso sul ventre, costruisce un nido con materiale vegetale e sventola acqua fresca sulle uova.", k: "Spinarello maschio: costruisce un nido" } } },
  { id: "b43", lvl: 2, type: "text", right: 0, t: { de: { q: "Wie verschließt die Weinbergschnecke im Winter ihr Haus?", a: ["Mit einem Deckel aus Kalk", "Mit einem eingerollten Blatt", "Mit einem Pfropfen aus Erde", "Gar nicht – es bleibt offen"], x: "Sie gräbt sich ein und verschließt die Öffnung mit einem Kalkdeckel. In Deutschland stehen Weinbergschnecken unter Schutz.", k: "Weinbergschnecke: verschließt ihr Haus mit Kalk" }, en: { q: "How does the Roman snail seal its shell in winter?", a: ["With a lid made of lime", "With a rolled-up leaf", "With a plug of soil", "Not at all – it stays open"], x: "It digs in and seals the opening with a chalky lid. In Germany, Roman snails are a protected species.", k: "Roman snail: seals its shell with chalk" }, fr: { q: "Comment l'escargot de Bourgogne ferme-t-il sa coquille en hiver ?", a: ["Avec un couvercle de calcaire", "Avec une feuille enroulée", "Avec un bouchon de terre", "Il ne la ferme pas"], x: "Il s'enterre et ferme l'ouverture avec un couvercle calcaire. En Allemagne, cette espèce est protégée.", k: "Escargot de Bourgogne : ferme sa coquille au calcaire" }, es: { q: "¿Cómo cierra su concha en invierno el caracol de Borgoña?", a: ["Con una tapa de cal", "Con una hoja enrollada", "Con un tapón de tierra", "No la cierra"], x: "Se entierra y cierra la abertura con una tapa calcárea. En Alemania es una especie protegida.", k: "Caracol de Borgoña: cierra la concha con cal" }, pt: { q: "Como o caracol-de-borgonha fecha a concha no inverno?", a: ["Com uma tampa de cal", "Com uma folha enrolada", "Com um tampão de terra", "Ele não fecha"], x: "Ele se enterra e fecha a abertura com uma tampa de calcário. Na Alemanha é uma espécie protegida.", k: "Caracol-de-borgonha: fecha a concha com cal" }, ja: { q: "エスカルゴ（リンゴマイマイ）は冬にどうやって殻にふたをする？", a: ["石灰のふたで", "丸めた葉っぱで", "土のせんで", "ふたはしない"], x: "土にもぐり、石灰質のふたで殻の口を閉じます。ドイツではリンゴマイマイは保護されています。", k: "エスカルゴ：石灰のふたで殻を閉じる" }, it: { q: "Come chiude il guscio d’inverno la chiocciola degli orti (Helix pomatia)?", a: ["Con un coperchio di calcare", "Con una foglia arrotolata", "Con un tappo di terra", "Non lo chiude"], x: "Si interra e chiude l’apertura con un coperchio calcareo. In Germania la chiocciola degli orti è protetta.", k: "Chiocciola degli orti: chiude il guscio col calcare" } } },
  { id: "b44", lvl: 3, type: "text", right: 1, t: { de: { q: "Was bedroht den heimischen Edelkrebs am stärksten?", a: ["Zu kalte Winter", "Die eingeschleppte Krebspest", "Der Biber", "Zu viele Wasserpflanzen"], x: "Amerikanische Krebse wie der Signalkrebs tragen den Erreger, ohne zu erkranken. Für heimische Krebse ist er meist tödlich.", k: "Edelkrebs: durch eingeschleppte Krebspest bedroht" }, en: { q: "What is the biggest threat to the native noble crayfish?", a: ["Cold winters", "Introduced crayfish plague", "Beavers", "Too many water plants"], x: "American species like the signal crayfish carry the pathogen without falling ill. For native crayfish it is usually fatal.", k: "Noble crayfish: threatened by crayfish plague" }, fr: { q: "Quelle est la plus grande menace pour l'écrevisse à pattes rouges ?", a: ["Les hivers froids", "La peste de l'écrevisse importée", "Le castor", "Trop de plantes aquatiques"], x: "Des écrevisses américaines comme l'écrevisse signal portent le pathogène sans être malades. Il tue souvent les espèces indigènes.", k: "Écrevisse à pattes rouges : menacée par la peste" }, es: { q: "¿Cuál es la mayor amenaza para el cangrejo de río europeo?", a: ["Los inviernos fríos", "La peste del cangrejo introducida", "El castor", "El exceso de plantas acuáticas"], x: "Especies americanas como el cangrejo señal portan el patógeno sin enfermar. Para los cangrejos autóctonos suele ser mortal.", k: "Cangrejo de río europeo: amenazado por la afanomicosis" }, pt: { q: "Qual é a maior ameaça para o lagostim-europeu?", a: ["Os invernos frios", "A peste do lagostim, trazida de fora", "O castor", "Plantas aquáticas demais"], x: "Espécies americanas, como o lagostim-sinal, carregam o patógeno sem adoecer. Para os lagostins nativos costuma ser mortal.", k: "Lagostim-europeu: ameaçado pela peste" }, ja: { q: "在来のヨーロッパザリガニにとって、いちばんの脅威は？", a: ["寒い冬", "持ちこまれたザリガニペスト", "ビーバー", "水草が多すぎること"], x: "シグナルザリガニなどアメリカの種は、病原体を運んでも自分は発病しません。在来のザリガニにはたいてい命取りです。", k: "ヨーロッパザリガニ：ザリガニペストで危機" }, it: { q: "Qual è la minaccia più grande per il gambero di fiume europeo?", a: ["Inverni freddi", "La peste dei gamberi introdotta", "I castori", "Troppe piante acquatiche"], x: "Specie americane come il gambero segnale portano il patogeno senza ammalarsi. Per i gamberi autoctoni di solito è mortale.", k: "Gambero di fiume: minacciato dalla peste" } } },
  { id: "b45", lvl: 3, type: "text", right: 2, t: { de: { q: "Wie frisst ein Seestern eine Miesmuschel?", a: ["Er knackt sie mit Zähnen", "Er schlägt sie gegen Steine", "Er stülpt seinen Magen in die Muschel", "Er saugt sie durch die Arme auf"], x: "Er zieht die Schalen mit seinen Saugfüßchen einen Spalt auf, stülpt den Magen hinein und verdaut die Muschel darin.", k: "Seestern: verdaut Muscheln mit dem Magen von außen" }, en: { q: "How does a starfish eat a mussel?", a: ["It cracks it with its teeth", "It smashes it against rocks", "It pushes its stomach into the mussel", "It sucks it up through its arms"], x: "It pulls the shells slightly apart with its tube feet, pushes its stomach inside and digests the mussel right there.", k: "Starfish: digests mussels with its stomach" }, fr: { q: "Comment une étoile de mer mange-t-elle une moule ?", a: ["Elle la casse avec ses dents", "Elle la frappe contre un rocher", "Elle glisse son estomac dans la moule", "Elle l'aspire par ses bras"], x: "Elle entrouvre les valves avec ses pieds ambulacraires, y glisse son estomac et digère la moule sur place.", k: "Étoile de mer : digère les moules avec son estomac" }, es: { q: "¿Cómo se come una estrella de mar a un mejillón?", a: ["Lo rompe con los dientes", "Lo golpea contra las rocas", "Mete su estómago dentro del mejillón", "Lo absorbe por los brazos"], x: "Abre un poco las valvas con sus pies ambulacrales, introduce el estómago y digiere el mejillón allí mismo.", k: "Estrella de mar: digiere mejillones con el estómago" }, pt: { q: "Como uma estrela-do-mar come um mexilhão?", a: ["Quebra-o com os dentes", "Bate-o contra as pedras", "Coloca o estômago dentro do mexilhão", "Suga-o pelos braços"], x: "Ela abre um pouco as conchas com os pés ambulacrais, coloca o estômago para dentro e digere o mexilhão ali mesmo.", k: "Estrela-do-mar: digere mexilhões com o estômago" }, ja: { q: "ヒトデはどうやって貝を食べる？", a: ["歯で割る", "岩にたたきつける", "胃を貝の中に押しこむ", "腕から吸いこむ"], x: "管足で貝の殻を少しこじあけ、胃を中に押しこんで、その場で貝を消化します。", k: "ヒトデ：胃を出して貝を消化" }, it: { q: "Come mangia una cozza la stella marina?", a: ["La rompe con i denti", "La sbatte contro le rocce", "Spinge lo stomaco dentro la cozza", "La aspira con le braccia"], x: "Con i pedicelli apre un po’ le valve, spinge dentro lo stomaco e digerisce la cozza sul posto.", k: "Stella marina: digerisce le cozze con lo stomaco" } } },
  { id: "b46", lvl: 3, type: "text", right: 0, t: { de: { q: "Wie verbreiten sich die Larven heimischer Großmuscheln wie der Teichmuschel?", a: ["Sie heften sich an Fische", "Sie werden vom Wind verweht", "Sie kriechen durch den Boden", "Sie treiben in Schaumflocken"], x: "Die winzigen Larven (Glochidien) klammern sich an Kiemen oder Flossen von Fischen und lassen sich eine Weile mitnehmen.", k: "Muschellarven: reisen an Fischen mit" }, en: { q: "How do the larvae of native freshwater mussels like the swan mussel spread?", a: ["They attach to fish", "They are blown by the wind", "They crawl through the soil", "They drift in flecks of foam"], x: "The tiny larvae (glochidia) cling to the gills or fins of fish and hitch a ride for a while.", k: "Mussel larvae: hitch a ride on fish" }, fr: { q: "Comment se dispersent les larves des grandes moules d'eau douce comme l'anodonte ?", a: ["Elles s'accrochent aux poissons", "Elles sont portées par le vent", "Elles rampent dans le sol", "Elles flottent dans l'écume"], x: "Les minuscules larves (glochidies) s'accrochent aux branchies ou aux nageoires des poissons et voyagent un moment avec eux.", k: "Larves de moules : voyagent sur les poissons" }, es: { q: "¿Cómo se dispersan las larvas de los grandes mejillones de agua dulce, como la anodonta?", a: ["Se adhieren a peces", "Las lleva el viento", "Se arrastran por el suelo", "Flotan en la espuma"], x: "Las diminutas larvas (gloquidios) se aferran a las branquias o aletas de los peces y viajan con ellos un tiempo.", k: "Larvas de mejillón: viajan en peces" }, pt: { q: "Como se espalham as larvas dos grandes mexilhões de água doce, como a anodonta?", a: ["Prendem-se a peixes", "São levadas pelo vento", "Rastejam pelo fundo", "Flutuam na espuma"], x: "As larvas minúsculas (gloquídios) se agarram às brânquias ou nadadeiras dos peixes e viajam com eles por um tempo.", k: "Larvas de mexilhão: viajam em peixes" }, ja: { q: "ドブガイなど在来の淡水の貝の幼生は、どうやって広がる？", a: ["魚にくっつく", "風に飛ばされる", "土の中をはう", "泡に乗って流れる"], x: "小さな幼生（グロキディウム）は魚のえらやひれにくっつき、しばらくヒッチハイクします。", k: "淡水の貝の幼生：魚にくっついて旅する" }, it: { q: "Come si diffondono le larve delle cozze d’acqua dolce come l’anodonta?", a: ["Si attaccano ai pesci", "Le porta il vento", "Strisciano nel terreno", "Galleggiano nei fiocchi di schiuma"], x: "Le minuscole larve (glochidi) si attaccano alle branchie o alle pinne dei pesci e viaggiano con loro per un po’.", k: "Larve di cozza: viaggiano sui pesci" } } },
  { id: "b47", lvl: 3, type: "text", right: 1, t: { de: { q: "Wie bohrt man Nistlöcher für Wildbienen am besten in Holz?", a: ["Ins Stirnholz (Schnittfläche)", "Seitlich ins Längsholz", "In weiches Fichtenholz", "Mit 3 bis 5 cm Durchmesser"], x: "Löcher im Stirnholz reißen leicht ein, dann kann die Brut verpilzen. Besser: trockenes Hartholz, seitlich, wenige mm breit.", k: "Wildbienen-Löcher: seitlich ins Holz bohren" }, en: { q: "What is the best way to drill nest holes for wild bees in wood?", a: ["Into the end grain (cut face)", "Into the side of the wood", "Into soft spruce wood", "3 to 5 cm wide"], x: "Holes in end grain crack easily and the brood can go mouldy. Better: dry hardwood, drilled from the side, a few mm wide.", k: "Bee hotel holes: drill into the side of the wood" }, fr: { q: "Comment percer au mieux des trous de nidification pour abeilles sauvages dans le bois ?", a: ["Dans le bois de bout (la coupe)", "Sur le côté, dans le fil du bois", "Dans de l'épicéa tendre", "Avec 3 à 5 cm de diamètre"], x: "Les trous dans le bois de bout se fendent et le couvain peut moisir. Mieux : bois dur sec, percé sur le côté, de quelques mm.", k: "Hôtel à abeilles : percer le bois sur le côté" }, es: { q: "¿Cómo se perforan mejor los nidos para abejas silvestres en madera?", a: ["En la testa (cara del corte)", "En el costado de la madera", "En madera blanda de abeto", "Con 3 a 5 cm de diámetro"], x: "Los agujeros en la testa se agrietan y la cría puede enmohecerse. Mejor: madera dura y seca, perforada de lado, de pocos mm.", k: "Hotel de abejas: taladrar la madera de lado" }, pt: { q: "Qual é o melhor jeito de furar ninhos de madeira para abelhas silvestres?", a: ["No topo (face do corte)", "Na lateral da madeira", "Em madeira macia de abeto", "Com 3 a 5 cm de diâmetro"], x: "Furos no topo racham e a cria pode mofar. Melhor: madeira dura e seca, furada pela lateral, com poucos milímetros.", k: "Hotel de abelhas: furar a madeira de lado" }, ja: { q: "野生のハナバチの巣穴を木にあけるとき、いちばんいい方法は？", a: ["木口（切り口）にあける", "木の側面にあける", "やわらかいトウヒ材にあける", "幅3〜5センチ"], x: "木口の穴はひび割れやすく、幼虫がカビることもあります。かわいた堅い木の側面に、直径数ミリの穴をあけよう。", k: "ハチホテル：穴は木の側面にあける" }, it: { q: "Qual è il modo migliore per forare nidi per api selvatiche nel legno?", a: ["Nel legno di testa (taglio)", "Nel lato del legno", "Nel morbido legno di abete rosso", "Larghi 3–5 cm"], x: "I fori nel legno di testa si crepano facilmente e la covata può ammuffire. Meglio: legno duro e secco, forato di lato, largo pochi mm.", k: "Hotel per api: forare il legno di lato" } } },
  { id: "b48", lvl: 3, type: "text", right: 3, t: { de: { q: "Viele Wildbienen sind 'oligolektisch'. Was bedeutet das?", a: ["Sie leben einzeln, ohne Staat", "Sie fliegen nur nachts", "Sie haben keinen Stachel", "Sie sammeln nur an wenigen Pflanzen"], x: "Solche Spezialisten brauchen z. B. Glockenblumen oder Weiden. Fehlen diese Pflanzen, verschwindet auch die Biene.", k: "Viele Wildbienen: brauchen ganz bestimmte Blumen" }, en: { q: "Many wild bees are 'oligolectic'. What does that mean?", a: ["They live alone, without a colony", "They only fly at night", "They have no sting", "They collect pollen from few plants"], x: "Such specialists need e.g. bellflowers or willows. If these plants disappear, so does the bee.", k: "Many wild bees: need specific flowers" }, fr: { q: "Beaucoup d'abeilles sauvages sont « oligolectiques ». Qu'est-ce que cela signifie ?", a: ["Elles vivent seules, sans colonie", "Elles ne volent que la nuit", "Elles n'ont pas de dard", "Elles butinent peu de plantes"], x: "Ces spécialistes ont besoin par exemple de campanules ou de saules. Si ces plantes disparaissent, l'abeille aussi.", k: "Beaucoup d’abeilles sauvages : fleurs spécifiques" }, es: { q: "Muchas abejas silvestres son «oligolécticas». ¿Qué significa?", a: ["Viven solas, sin colonia", "Solo vuelan de noche", "No tienen aguijón", "Recogen polen de pocas plantas"], x: "Estas especialistas necesitan, por ejemplo, campánulas o sauces. Si esas plantas desaparecen, la abeja también.", k: "Muchas abejas silvestres: necesitan flores concretas" }, pt: { q: "Muitas abelhas silvestres são “oligoléticas”. O que isso significa?", a: ["Vivem sozinhas, sem colônia", "Só voam à noite", "Não têm ferrão", "Coletam pólen de poucas plantas"], x: "Essas especialistas precisam, por exemplo, de campânulas ou salgueiros. Se essas plantas somem, a abelha também some.", k: "Muitas abelhas silvestres: precisam de flores certas" }, ja: { q: "多くの野生のハナバチは「狭訪花性」。どういう意味？", a: ["群れを作らず単独で暮らす", "夜だけ飛ぶ", "針がない", "限られた植物からだけ花粉を集める"], x: "こうした専門家には、たとえばホタルブクロやヤナギが必要です。その植物が消えると、ハチも消えてしまいます。", k: "多くの野生のハナバチ：決まった花が必要" }, it: { q: "Molte api selvatiche sono «oligolettiche». Cosa significa?", a: ["Vivono da sole, senza colonia", "Volano solo di notte", "Non hanno pungiglione", "Raccolgono polline da poche piante"], x: "Questi specialisti hanno bisogno per esempio di campanule o salici. Se spariscono queste piante, sparisce anche l’ape.", k: "Molte api selvatiche: servono fiori precisi" } } },
  { id: "b49", lvl: 3, type: "text", right: 2, t: { de: { q: "Wie lange entwickeln sich Hirschkäfer-Larven im morschen Holz?", a: ["Etwa 2 Wochen", "Nur einen Sommer", "Meist 3 bis 8 Jahre", "Rund 30 Jahre"], x: "Die Larven fressen jahrelang morsches Holz, oft von alten Eichen. Der fertige Käfer lebt dann nur wenige Wochen.", k: "Hirschkäfer-Larven: wachsen bis zu 8 Jahre" }, en: { q: "How long do stag beetle larvae develop in rotting wood?", a: ["About 2 weeks", "Just one summer", "Usually 3 to 8 years", "Around 30 years"], x: "The larvae feed on rotting wood, often of old oaks, for years. The adult beetle then lives only a few weeks.", k: "Stag beetle larvae: grow for up to 8 years" }, fr: { q: "Combien de temps les larves de lucane cerf-volant se développent-elles dans le bois mort ?", a: ["Environ 2 semaines", "Un seul été", "En général 3 à 8 ans", "Environ 30 ans"], x: "Les larves mangent du bois pourri, souvent de vieux chênes, pendant des années. L'adulte ne vit ensuite que quelques semaines.", k: "Larves de lucane : jusqu’à 8 ans de croissance" }, es: { q: "¿Cuánto tiempo se desarrollan las larvas del ciervo volante en la madera podrida?", a: ["Unas 2 semanas", "Solo un verano", "Normalmente de 3 a 8 años", "Unos 30 años"], x: "Las larvas comen madera podrida, a menudo de robles viejos, durante años. El adulto vive luego solo unas semanas.", k: "Larvas de ciervo volante: crecen hasta 8 años" }, pt: { q: "Quanto tempo as larvas do besouro-veado se desenvolvem na madeira podre?", a: ["Umas 2 semanas", "Só um verão", "Normalmente de 3 a 8 anos", "Uns 30 anos"], x: "As larvas comem madeira podre, muitas vezes de carvalhos velhos, por anos. O adulto vive depois só algumas semanas.", k: "Larvas de vacaloura: crescem até 8 anos" }, ja: { q: "ヨーロッパミヤマクワガタの幼虫は、くさった木の中で何年育つ？", a: ["約2週間", "ひと夏だけ", "ふつう3〜8年", "約30年"], x: "幼虫は何年もかけて、よく古いカシのくさった木を食べて育ちます。成虫になると数週間しか生きません。", k: "ミヤマクワガタの幼虫：最大8年かけて育つ" }, it: { q: "Quanto si sviluppano nel legno marcio le larve del cervo volante?", a: ["Circa 2 settimane", "Una sola estate", "Di solito da 3 a 8 anni", "Circa 30 anni"], x: "Le larve si nutrono per anni di legno marcio, spesso di vecchie querce. Il coleottero adulto poi vive solo poche settimane.", k: "Larve di cervo volante: crescono fino a 8 anni" } } },
  { id: "b50", lvl: 3, type: "text", right: 3, t: { de: { q: "Wo sitzen die Ohren des Grünen Heupferds?", a: ["Am Kopf", "An den Fühlern", "Am Hinterleib", "An den Vorderbeinen"], x: "Laubheuschrecken hören mit Trommelfellen an den Vorderbeinen. Kurzfühlerschrecken wie Grashüpfer haben sie am Hinterleib.", k: "Laubheuschrecken: hören mit den Vorderbeinen" }, en: { q: "Where are the ears of the great green bush-cricket?", a: ["On its head", "On its antennae", "On its abdomen", "On its front legs"], x: "Bush-crickets hear with eardrums on their front legs. Grasshoppers, by contrast, have theirs on the abdomen.", k: "Bush-crickets: hear with their front legs" }, fr: { q: "Où se trouvent les oreilles de la grande sauterelle verte ?", a: ["Sur la tête", "Sur les antennes", "Sur l'abdomen", "Sur les pattes avant"], x: "Les sauterelles entendent grâce à des tympans sur les pattes avant. Les criquets, eux, les ont sur l'abdomen.", k: "Sauterelles : entendent avec les pattes avant" }, es: { q: "¿Dónde tiene los oídos el saltamontes verde (Tettigonia)?", a: ["En la cabeza", "En las antenas", "En el abdomen", "En las patas delanteras"], x: "Los tetigónidos oyen con tímpanos en las patas delanteras. Los saltamontes de antenas cortas los tienen en el abdomen.", k: "Saltamontes verdes: oyen con las patas delanteras" }, pt: { q: "Onde a esperança-verde (Tettigonia) tem os ouvidos?", a: ["Na cabeça", "Nas antenas", "No abdômen", "Nas patas da frente"], x: "As esperanças ouvem com tímpanos nas patas da frente. Os gafanhotos de antenas curtas os têm no abdômen.", k: "Esperanças: ouvem com as patas da frente" }, ja: { q: "キリギリスの仲間の耳はどこにある？", a: ["頭", "触角", "おなか", "前脚"], x: "キリギリスの仲間は前脚にある鼓膜で音を聞きます。バッタの仲間はおなかにあります。", k: "キリギリス：前脚で音を聞く" }, it: { q: "Dove sono le orecchie della cavalletta verde?", a: ["Sulla testa", "Sulle antenne", "Sull’addome", "Sulle zampe anteriori"], x: "Le tettigonie (cavallette verdi) sentono con timpani sulle zampe anteriori. Gli acrididi (le cavallette comuni) invece li hanno sull’addome.", k: "Cavallette verdi: sentono con le zampe anteriori" } } },
  { id: "k01", lvl: 2, type: "text", right: 1, t: { de: { q: "Welche Aussage ist FALSCH?", a: ["Eulen können ihre Augen nicht bewegen", "Alle Haie müssen ständig schwimmen, um zu atmen", "Kraken haben blaues Blut", "Biber haben orange Zähne"], x: "Viele Haie müssen schwimmen, aber nicht alle: Ammenhaie oder Katzenhaie liegen am Grund und pumpen Wasser über ihre Kiemen.", k: "Ammenhaie: ruhen am Meeresgrund" }, en: { q: "Which statement is FALSE?", a: ["Owls can’t move their eyes", "All sharks must swim constantly to breathe", "Octopuses have blue blood", "Beavers have orange teeth"], x: "Many sharks have to swim, but not all: nurse sharks or catsharks lie on the bottom and pump water over their gills.", k: "Nurse sharks: rest on the seabed" }, fr: { q: "Quelle affirmation est FAUSSE ?", a: ["Les chouettes ne peuvent pas bouger les yeux", "Tous les requins doivent nager sans arrêt pour respirer", "Les pieuvres ont le sang bleu", "Les castors ont les dents orange"], x: "Beaucoup de requins doivent nager, mais pas tous : le requin-nourrice ou la roussette restent au fond et pompent l’eau sur leurs branchies.", k: "Requins-nourrices : se reposent au fond" }, es: { q: "¿Qué afirmación es FALSA?", a: ["Los búhos no pueden mover los ojos", "Todos los tiburones deben nadar sin parar para respirar", "Los pulpos tienen sangre azul", "Los castores tienen los dientes naranjas"], x: "Muchos tiburones tienen que nadar, pero no todos: el tiburón nodriza o la pintarroja descansan en el fondo y bombean agua por sus branquias.", k: "Tiburones nodriza: descansan en el fondo" }, pt: { q: "Qual afirmação é FALSA?", a: ["As corujas não conseguem mexer os olhos", "Todos os tubarões precisam nadar sem parar para respirar", "Os polvos têm sangue azul", "Os castores têm dentes laranja"], x: "Muitos tubarões precisam nadar, mas não todos: o tubarão-lixa ou o cação-pintado descansam no fundo e bombeiam água pelas brânquias.", k: "Tubarões-lixa: descansam no fundo" }, ja: { q: "まちがっているのはどれ？", a: ["フクロウは目玉を動かせない", "サメはみんな、呼吸のために泳ぎ続けなければならない", "タコの血は青い", "ビーバーの歯はオレンジ色"], x: "泳ぎ続けなければならないサメは多いですが、全部ではありません。コモリザメやトラザメの仲間は海底で休み、えらに水を送ります。", k: "コモリザメ：海底で休む" }, it: { q: "Quale affermazione è FALSA?", a: ["I gufi non possono muovere gli occhi", "Tutti gli squali devono nuotare sempre per respirare", "I polpi hanno il sangue blu", "I castori hanno i denti arancioni"], x: "Molti squali devono nuotare, ma non tutti: lo squalo nutrice o il gattuccio si posano sul fondo e pompano acqua sulle branchie.", k: "Squali nutrice: riposano sul fondo" } } },
  { id: "k02", lvl: 1, type: "text", right: 2, t: { de: { q: "Welche Aussage ist FALSCH?", a: ["Ameisen tragen ein Vielfaches ihres Gewichts", "Spechte trommeln über 10-mal pro Sekunde", "Fledermäuse sind blind", "Hummeln fliegen auch bei Kälte"], x: "Fledermäuse sehen gut. Nachts orientieren sie sich aber zusätzlich mit Ultraschall-Echos.", k: "Fledermäuse: können gut sehen" }, en: { q: "Which statement is FALSE?", a: ["Ants carry many times their own weight", "Woodpeckers drum over 10 times a second", "Bats are blind", "Bumblebees fly even in the cold"], x: "Bats can see well. At night, they also find their way using ultrasound echoes.", k: "Bats: can see well" }, fr: { q: "Quelle affirmation est FAUSSE ?", a: ["Les fourmis portent plusieurs fois leur poids", "Le pic tambourine plus de 10 fois par seconde", "Les chauves-souris sont aveugles", "Les bourdons volent même par temps froid"], x: "Les chauves-souris voient bien. La nuit, elles s’orientent en plus grâce à l’écho des ultrasons.", k: "Chauves-souris : voient bien" }, es: { q: "¿Qué afirmación es FALSA?", a: ["Las hormigas cargan varias veces su peso", "Los pájaros carpinteros tamborilean más de 10 veces por segundo", "Los murciélagos son ciegos", "Los abejorros vuelan incluso con frío"], x: "Los murciélagos ven bien. De noche se orientan además con el eco de los ultrasonidos.", k: "Murciélagos: ven bien" }, pt: { q: "Qual afirmação é FALSA?", a: ["As formigas carregam várias vezes o próprio peso", "Os pica-paus batucam mais de 10 vezes por segundo", "Os morcegos são cegos", "As mamangavas voam até no frio"], x: "Os morcegos enxergam bem. À noite, eles se orientam também pelo eco dos ultrassons.", k: "Morcegos: enxergam bem" }, ja: { q: "まちがっているのはどれ？", a: ["アリは自分の体重の何倍もの重さを運ぶ", "キツツキは1秒に10回以上たたく", "コウモリは目が見えない", "マルハナバチは寒くても飛ぶ"], x: "コウモリはちゃんと目が見えます。夜は超音波のこだまも使って道を見つけます。", k: "コウモリ：目もちゃんと見える" }, it: { q: "Quale affermazione è FALSA?", a: ["Le formiche portano molte volte il proprio peso", "I picchi tamburellano più di 10 volte al secondo", "I pipistrelli sono ciechi", "I bombi volano anche al freddo"], x: "I pipistrelli ci vedono bene. Di notte si orientano anche con l’eco degli ultrasuoni.", k: "Pipistrelli: ci vedono bene" } } },
  { id: "k03", lvl: 2, type: "text", right: 0, t: { de: { q: "Schätzfrage: Wie viel Honig sammelt eine Arbeitsbiene in ihrem ganzen Leben?", a: ["Etwa 1/12 Teelöffel", "Etwa 1 Teelöffel", "Etwa 1 Esslöffel", "Etwa ein halbes Glas"], x: "Nur etwa ein Zwölftel Teelöffel! Für ein Glas Honig fliegen Bienen zusammen eine Strecke, die mehrmals um die Erde reicht.", k: "Biene: macht im Leben 1/12 Teelöffel Honig" }, en: { q: "Guess: how much honey does a worker bee make in her whole life?", a: ["About 1/12 teaspoon", "About 1 teaspoon", "About 1 tablespoon", "About half a jar"], x: "Only about a twelfth of a teaspoon! For one jar of honey, bees together fly a distance that would go around the Earth several times.", k: "Bee: makes 1/12 teaspoon of honey in its life" }, fr: { q: "Devine : combien de miel une abeille ouvrière produit-elle dans toute sa vie ?", a: ["Environ 1/12 de cuillère à café", "Environ 1 cuillère à café", "Environ 1 cuillère à soupe", "Environ un demi-pot"], x: "Seulement un douzième de cuillère à café ! Pour un pot de miel, les abeilles parcourent ensemble une distance de plusieurs fois le tour de la Terre.", k: "Abeille : 1/12 de cuillère de miel dans sa vie" }, es: { q: "Adivina: ¿cuánta miel produce una abeja obrera en toda su vida?", a: ["Una doceava parte de cucharadita", "Una cucharadita", "Una cucharada", "Medio tarro"], x: "¡Solo una doceava parte de cucharadita! Para un tarro de miel, las abejas recorren juntas una distancia de varias vueltas a la Tierra.", k: "Abeja: 1/12 de cucharadita de miel en su vida" }, pt: { q: "Adivinhe: quanto mel uma abelha operária produz na vida toda?", a: ["Um doze avos de colher de chá", "Uma colher de chá", "Uma colher de sopa", "Meio pote"], x: "Só um doze avos de colher de chá! Para um pote de mel, as abelhas voam juntas uma distância de várias voltas ao redor da Terra.", k: "Abelha: 1/12 de colher de chá de mel na vida" }, ja: { q: "予想してみよう：働きバチ1匹が一生に作るハチミツの量は？", a: ["小さじ約12分の1", "小さじ約1杯", "大さじ約1杯", "びん半分くらい"], x: "たった小さじ12分の1ほど！ハチミツ1びんのために、ハチたちは合わせて地球を何周もする距離を飛びます。", k: "ミツバチ：一生でハチミツ小さじ12分の1" }, it: { q: "Indovina: quanto miele produce un’ape operaia in tutta la vita?", a: ["Circa 1/12 di cucchiaino", "Circa 1 cucchiaino", "Circa 1 cucchiaio", "Circa mezzo vasetto"], x: "Solo un dodicesimo di cucchiaino! Per un vasetto di miele, le api insieme volano una distanza pari a diversi giri della Terra.", k: "Ape: 1/12 di cucchiaino di miele in tutta la vita" } } },
  { id: "k04", lvl: 2, type: "text", right: 2, t: { de: { q: "Schätzfrage: Wie viele Insekten frisst eine kleine Zwergfledermaus in einer Nacht?", a: ["Etwa 5", "Etwa 50", "Mehrere Hundert bis über tausend", "Etwa eine Million"], x: "Eine Zwergfledermaus wiegt nur rund 5 Gramm, fängt aber pro Nacht Hunderte bis über tausend Mücken und andere kleine Insekten.", k: "Zwergfledermaus: frisst über 1.000 Mücken pro Nacht" }, en: { q: "Guess: how many insects does a tiny pipistrelle bat eat in one night?", a: ["About 5", "About 50", "Several hundred to over a thousand", "About a million"], x: "A pipistrelle weighs only about 5 grams, but catches hundreds to over a thousand midges and other small insects in one night.", k: "Pipistrelle: eats over 1,000 midges a night" }, fr: { q: "Devine : combien d’insectes une petite pipistrelle mange-t-elle en une nuit ?", a: ["Environ 5", "Environ 50", "Plusieurs centaines à plus de mille", "Environ un million"], x: "Une pipistrelle ne pèse qu’environ 5 grammes, mais attrape en une nuit des centaines, voire plus de mille moucherons et autres petits insectes.", k: "Pipistrelle : plus de 1 000 moustiques par nuit" }, es: { q: "Adivina: ¿cuántos insectos come un pequeño murciélago enano en una noche?", a: ["Unos 5", "Unos 50", "De varios cientos a más de mil", "Un millón"], x: "Un murciélago enano pesa solo unos 5 gramos, pero en una noche caza de cientos a más de mil mosquitos y otros insectos pequeños.", k: "Murciélago enano: más de 1.000 mosquitos por noche" }, pt: { q: "Adivinhe: quantos insetos um pequeno morcego-anão come numa noite?", a: ["Uns 5", "Uns 50", "De centenas a mais de mil", "Um milhão"], x: "Um morcego-anão pesa só uns 5 gramas, mas numa noite caça de centenas a mais de mil mosquitos e outros insetos pequenos.", k: "Morcego-anão: mais de 1.000 mosquitos por noite" }, ja: { q: "予想してみよう：小さなアブラコウモリは一晩に何匹の虫を食べる？", a: ["約5匹", "約50匹", "数百〜1000匹以上", "約100万匹"], x: "アブラコウモリの仲間は体重わずか約5グラムなのに、一晩で数百から1000匹以上の蚊や小さな虫をつかまえます。", k: "アブラコウモリ：一晩に1000匹以上の虫" }, it: { q: "Indovina: quanti insetti mangia in una notte un piccolo pipistrello nano?", a: ["Circa 5", "Circa 50", "Da centinaia a oltre mille", "Circa un milione"], x: "Un pipistrello nano pesa solo circa 5 grammi, ma in una notte cattura da centinaia a oltre mille moscerini e altri piccoli insetti.", k: "Pipistrello nano: oltre 1.000 moscerini a notte" } } },
  { id: "k05", lvl: 2, type: "text", right: 1, t: { de: { q: "Schätzfrage: Wie schwer ist ein Igelbaby bei der Geburt?", a: ["Etwa 2 Gramm", "Etwa 20 Gramm", "Etwa 200 Gramm", "Etwa 1 Kilo"], x: "Neugeborene Igel wiegen 12 bis 25 Gramm. Ihre Stacheln sind weich und stecken unter einer Hautschicht, damit die Geburt nicht wehtut – nach einigen Stunden kommen sie heraus.", k: "Igel-Baby: wiegt 12 bis 25 g" }, en: { q: "Guess: how much does a baby hedgehog weigh at birth?", a: ["About 2 grams", "About 20 grams", "About 200 grams", "About 1 kilo"], x: "Newborn hedgehogs weigh 12 to 25 grams. Their spines are soft and covered by a layer of skin so birth doesn’t hurt – they come out after a few hours.", k: "Baby hedgehog: weighs 12 to 25 g" }, fr: { q: "Devine : combien pèse un bébé hérisson à la naissance ?", a: ["Environ 2 grammes", "Environ 20 grammes", "Environ 200 grammes", "Environ 1 kilo"], x: "Un hérisson nouveau-né pèse 12 à 25 grammes. Ses piquants sont mous et couverts d’une couche de peau pour que la naissance ne fasse pas mal – ils sortent après quelques heures.", k: "Bébé hérisson : 12 à 25 g" }, es: { q: "Adivina: ¿cuánto pesa un erizo al nacer?", a: ["Unos 2 gramos", "Unos 20 gramos", "Unos 200 gramos", "Un kilo"], x: "Un erizo recién nacido pesa de 12 a 25 gramos. Sus púas son blandas y están cubiertas por una capa de piel para que el parto no duela; salen a las pocas horas.", k: "Cría de erizo: 12 a 25 g" }, pt: { q: "Adivinhe: quanto pesa um ouriço ao nascer?", a: ["Uns 2 gramas", "Uns 20 gramas", "Uns 200 gramas", "Um quilo"], x: "Um ouriço recém-nascido pesa de 12 a 25 gramas. Os espinhos são moles e cobertos por uma camada de pele, para o parto não doer; eles saem em poucas horas.", k: "Filhote de ouriço: 12 a 25 g" }, ja: { q: "予想してみよう：生まれたてのハリネズミの体重は？", a: ["約2グラム", "約20グラム", "約200グラム", "約1キロ"], x: "生まれたてのハリネズミは12〜25グラム。トゲはやわらかく、皮ふの膜におおわれているので出産は痛くありません。トゲは数時間で出てきます。", k: "ハリネズミの赤ちゃん：12〜25グラム" }, it: { q: "Indovina: quanto pesa un riccio appena nato?", a: ["Circa 2 grammi", "Circa 20 grammi", "Circa 200 grammi", "Circa 1 chilo"], x: "I ricci appena nati pesano 12–25 grammi. Gli aculei sono morbidi e coperti da uno strato di pelle, così il parto non fa male: spuntano dopo poche ore.", k: "Riccio neonato: 12–25 g" } } },
  { id: "k06", lvl: 3, type: "text", right: 1, t: { de: { q: "Schätzfrage: Wie viele Federn hat ein Höckerschwan?", a: ["Etwa 2.500", "Etwa 25.000", "Etwa 250.000", "Etwa 2,5 Millionen"], x: "Rund 25.000 – die meisten Federn aller Vögel, ein großer Teil davon am langen Hals. Ein Kolibri hat nur etwa 1.000.", k: "Höckerschwan: rund 25.000 Federn" }, en: { q: "Guess: how many feathers does a mute swan have?", a: ["About 2,500", "About 25,000", "About 250,000", "About 2.5 million"], x: "Around 25,000 – the most feathers of any bird, many of them on the long neck. A hummingbird has only about 1,000.", k: "Mute swan: about 25,000 feathers" }, fr: { q: "Devine : combien de plumes a un cygne tuberculé ?", a: ["Environ 2 500", "Environ 25 000", "Environ 250 000", "Environ 2,5 millions"], x: "Environ 25 000 – le record chez les oiseaux, dont une grande partie sur le long cou. Un colibri n’en a qu’environ 1 000.", k: "Cygne tuberculé : environ 25 000 plumes" }, es: { q: "Adivina: ¿cuántas plumas tiene un cisne vulgar?", a: ["Unas 2.500", "Unas 25.000", "Unas 250.000", "Unos 2,5 millones"], x: "Unas 25.000, el récord entre las aves, muchas de ellas en el largo cuello. Un colibrí tiene solo unas 1.000.", k: "Cisne vulgar: unas 25.000 plumas" }, pt: { q: "Adivinhe: quantas penas tem um cisne-branco?", a: ["Umas 2.500", "Umas 25.000", "Umas 250.000", "Uns 2,5 milhões"], x: "Cerca de 25.000 – o recorde entre as aves, muitas delas no pescoço comprido. Um beija-flor tem só umas 1.000.", k: "Cisne-branco: cerca de 25.000 penas" }, ja: { q: "予想してみよう：コブハクチョウの羽は何枚？", a: ["約2500枚", "約2万5000枚", "約25万枚", "約250万枚"], x: "約2万5000枚。鳥の中でいちばん多く、その多くは長い首にあります。ハチドリはたった約1000枚です。", k: "コブハクチョウ：羽は約2万5000枚" }, it: { q: "Indovina: quante piume ha un cigno reale?", a: ["Circa 2.500", "Circa 25.000", "Circa 250.000", "Circa 2,5 milioni"], x: "Circa 25.000: il record tra gli uccelli, molte sul lungo collo. Un colibrì ne ha solo circa 1.000.", k: "Cigno reale: circa 25.000 piume" } } },
  { id: "k07", lvl: 1, type: "text", right: 0, t: { de: { q: "Was wächst einer Kaulquappe zuerst?", a: ["Die Hinterbeine", "Die Vorderbeine", "Die Zunge zum Fliegenfangen", "Ein längerer Schwanz für das Leben an Land"], x: "Zuerst wachsen die Hinterbeine, dann die Vorderbeine. Zum Schluss wird der Schwanz abgebaut – und als Baumaterial wiederverwertet.", k: "Kaulquappe: zuerst wachsen die Hinterbeine" }, en: { q: "What does a tadpole grow first?", a: ["Its back legs", "Its front legs", "A tongue for catching flies", "A longer tail for life on land"], x: "The back legs grow first, then the front legs. Finally the tail is absorbed – and recycled as building material.", k: "Tadpole: back legs grow first" }, fr: { q: "Qu’est-ce qui pousse en premier chez le têtard ?", a: ["Les pattes arrière", "Les pattes avant", "Une langue pour attraper les mouches", "Une queue plus longue pour la vie sur terre"], x: "Les pattes arrière poussent d’abord, puis les pattes avant. Enfin, la queue est résorbée – et recyclée comme matériau.", k: "Têtard : les pattes arrière poussent d’abord" }, es: { q: "¿Qué le crece primero a un renacuajo?", a: ["Las patas traseras", "Las patas delanteras", "Una lengua para cazar moscas", "Una cola más larga para vivir en tierra"], x: "Primero crecen las patas traseras y luego las delanteras. Al final la cola se reabsorbe y se recicla como material.", k: "Renacuajo: primero le crecen las patas traseras" }, pt: { q: "O que cresce primeiro num girino?", a: ["As patas de trás", "As patas da frente", "Uma língua para pegar moscas", "Uma cauda mais longa para viver em terra"], x: "Primeiro crescem as patas de trás, depois as da frente. No fim, a cauda é reabsorvida e reciclada como material.", k: "Girino: primeiro crescem as patas de trás" }, ja: { q: "オタマジャクシに最初に生えるのは？", a: ["後ろ脚", "前脚", "ハエをとる舌", "陸で暮らすための長いしっぽ"], x: "まず後ろ脚、次に前脚が生えます。最後にしっぽが体に吸収され、材料として再利用されます。", k: "オタマジャクシ：まず後ろ脚が生える" }, it: { q: "Cosa cresce per prima cosa a un girino?", a: ["Le zampe posteriori", "Le zampe anteriori", "Una lingua per catturare mosche", "Una coda più lunga per la terraferma"], x: "Prima crescono le zampe posteriori, poi quelle anteriori. Alla fine la coda viene riassorbita e riciclata come materiale.", k: "Girino: crescono prima le zampe posteriori" } } },
  { id: "k08", lvl: 2, type: "text", right: 1, t: { de: { q: "Welches Tier hat die größten Augen der Welt?", a: ["Blauwal", "Koloss-Kalmar", "Strauß", "Uhu"], x: "Kalmare der Tiefsee haben Augen so groß wie ein Fußball, etwa 27 cm. Damit erkennen sie im Dunkeln die Pottwale, die sie jagen.", k: "Riesenkalmar: Augen so groß wie ein Fußball" }, en: { q: "Which animal has the largest eyes in the world?", a: ["Blue whale", "Colossal squid", "Ostrich", "Eagle owl"], x: "Deep-sea squids have eyes as big as a football, about 27 cm. They use them to spot the sperm whales that hunt them in the dark.", k: "Colossal squid: eyes as big as a football" }, fr: { q: "Quel animal a les plus grands yeux du monde ?", a: ["Baleine bleue", "Calmar colossal", "Autruche", "Grand-duc"], x: "Les calmars des abysses ont des yeux grands comme un ballon de foot, environ 27 cm. Ils repèrent ainsi dans le noir les cachalots qui les chassent.", k: "Calmar colossal : yeux grands comme un ballon" }, es: { q: "¿Qué animal tiene los ojos más grandes del mundo?", a: ["Ballena azul", "Calamar colosal", "Avestruz", "Búho real"], x: "Los calamares de las profundidades tienen ojos del tamaño de un balón, unos 27 cm. Así ven en la oscuridad a los cachalotes que los cazan.", k: "Calamar colosal: ojos como un balón" }, pt: { q: "Que animal tem os maiores olhos do mundo?", a: ["Baleia-azul", "Lula-colossal", "Avestruz", "Bufo-real"], x: "As lulas das profundezas têm olhos do tamanho de uma bola, uns 27 cm. Assim elas enxergam no escuro os cachalotes que as caçam.", k: "Lula-colossal: olhos do tamanho de uma bola" }, ja: { q: "世界でいちばん大きな目をもつ動物は？", a: ["シロナガスクジラ", "ダイオウホウズキイカ", "ダチョウ", "ワシミミズク"], x: "深海のイカの目はサッカーボールほど、約27センチ。暗やみで自分を狙うマッコウクジラを見つけるためです。", k: "ダイオウホウズキイカ：目はボールほど" }, it: { q: "Quale animale ha gli occhi più grandi del mondo?", a: ["Balenottera azzurra", "Calamaro colossale", "Struzzo", "Gufo reale"], x: "I calamari degli abissi hanno occhi grandi come un pallone, circa 27 cm. Li usano per vedere al buio i capodogli che li cacciano.", k: "Calamaro colossale: occhi grandi come un pallone" } } },
  { id: "k09", lvl: 2, type: "text", right: 0, t: { de: { q: "Wer gräbt oft den Bau, in dem später ein Fuchs wohnt?", a: ["Dachs", "Kaninchen", "Wildschwein", "Maulwurf"], x: "Füchse ziehen gern in Dachsbaue ein. Manchmal wohnen beide sogar gleichzeitig darin – in verschiedenen Röhren.", k: "Füchse: wohnen gern im Dachsbau" }, en: { q: "Who often digs the den that a fox later lives in?", a: ["Badger", "Rabbit", "Wild boar", "Mole"], x: "Foxes like to move into badger setts. Sometimes both even live there at the same time – in different tunnels.", k: "Foxes: like to live in badger setts" }, fr: { q: "Qui creuse souvent le terrier où vivra ensuite un renard ?", a: ["Le blaireau", "Le lapin", "Le sanglier", "La taupe"], x: "Le renard s’installe volontiers dans un terrier de blaireau. Parfois, les deux y vivent même en même temps – dans des galeries différentes.", k: "Renards : aiment les terriers de blaireau" }, es: { q: "¿Quién suele cavar la madriguera donde después vive un zorro?", a: ["El tejón", "El conejo", "El jabalí", "El topo"], x: "Los zorros se mudan con gusto a madrigueras de tejón. A veces viven los dos a la vez, en túneles distintos.", k: "Zorros: viven a gusto en tejoneras" }, pt: { q: "Quem costuma cavar a toca onde depois mora uma raposa?", a: ["O texugo", "O coelho", "O javali", "A toupeira"], x: "As raposas adoram se mudar para tocas de texugo. Às vezes os dois moram lá ao mesmo tempo, em túneis diferentes.", k: "Raposas: gostam de tocas de texugo" }, ja: { q: "あとでキツネがすむ巣穴を、よく掘っているのは？", a: ["アナグマ", "アナウサギ", "イノシシ", "モグラ"], x: "キツネはアナグマの巣穴に引っこすのが好き。ときには両方が同時に、別々のトンネルで暮らしていることも。", k: "キツネ：アナグマの巣穴に住みたがる" }, it: { q: "Chi scava spesso la tana in cui poi vive una volpe?", a: ["Il tasso", "Il coniglio", "Il cinghiale", "La talpa"], x: "Le volpi si trasferiscono volentieri nelle tane dei tassi. A volte ci vivono tutti e due insieme, in gallerie diverse.", k: "Volpi: amano le tane dei tassi" } } },
  { id: "k10", lvl: 2, type: "text", right: 0, t: { de: { q: "Warum stehen Flamingos oft auf einem Bein?", a: ["Es spart Kraft und Wärme", "Das andere Bein ist müde vom Laufen", "So sehen sie Fische besser", "Damit Feinde sie für Äste halten"], x: "Auf einem Bein halten Flamingos die Balance fast ohne Muskelkraft. Über das eingezogene Bein verlieren sie außerdem weniger Wärme.", k: "Flamingos: auf einem Bein spart Kraft und Wärme" }, en: { q: "Why do flamingos often stand on one leg?", a: ["It saves energy and warmth", "The other leg is tired from walking", "They can see fish better", "So enemies think they are branches"], x: "On one leg, flamingos keep their balance with almost no muscle effort. They also lose less heat through the tucked-up leg.", k: "Flamingos: one leg saves energy and heat" }, fr: { q: "Pourquoi les flamants se tiennent-ils souvent sur une patte ?", a: ["Ça économise force et chaleur", "L’autre patte est fatiguée", "Ils voient mieux les poissons", "Pour que les ennemis les prennent pour des branches"], x: "Sur une patte, le flamant garde l’équilibre presque sans effort musculaire. Et il perd moins de chaleur par la patte repliée.", k: "Flamants : une patte économise énergie et chaleur" }, es: { q: "¿Por qué los flamencos se apoyan a menudo en una pata?", a: ["Ahorran fuerza y calor", "La otra pata está cansada", "Ven mejor los peces", "Para que los enemigos los tomen por ramas"], x: "Sobre una pata, el flamenco mantiene el equilibrio casi sin esfuerzo muscular. Además pierde menos calor por la pata recogida.", k: "Flamencos: una pata ahorra energía y calor" }, pt: { q: "Por que os flamingos muitas vezes ficam numa perna só?", a: ["Economizam força e calor", "A outra perna está cansada", "Enxergam melhor os peixes", "Para os inimigos acharem que são galhos"], x: "Numa perna só, o flamingo se equilibra quase sem esforço muscular. Além disso, perde menos calor pela perna recolhida.", k: "Flamingos: uma perna poupa energia e calor" }, ja: { q: "フラミンゴがよく片脚で立つのはなぜ？", a: ["力と体温を節約できる", "もう片方の脚が歩きつかれた", "魚がよく見える", "敵に枝だと思わせる"], x: "片脚だと、フラミンゴは筋肉をほとんど使わずにバランスをとれます。さらに、引っこめた脚から熱が逃げにくくなります。", k: "フラミンゴ：片脚で力と熱を節約" }, it: { q: "Perché i fenicotteri stanno spesso su una zampa sola?", a: ["Risparmiano energia e calore", "L’altra zampa è stanca", "Vedono meglio i pesci", "Per sembrare rami ai nemici"], x: "Su una zampa sola il fenicottero sta in equilibrio quasi senza sforzo muscolare. In più perde meno calore dalla zampa raccolta.", k: "Fenicotteri: una zampa risparmia energia e calore" } } },
  { id: "k13", lvl: 2, type: "text", right: 2, t: { de: { q: "Welches Tier ist KEIN Fisch?", a: ["Seepferdchen", "Aal", "Tintenfisch", "Hai"], x: "Tintenfische sind Weichtiere, verwandt mit Schnecken. Seepferdchen und Aale sehen ungewöhnlich aus, sind aber echte Fische.", k: "Tintenfisch: kein Fisch, sondern Weichtier" }, en: { q: "Which animal is NOT a fish?", a: ["Seahorse", "Eel", "Squid", "Shark"], x: "Squids are molluscs, related to snails. Seahorses and eels look unusual, but they are real fish.", k: "Squid: not a fish but a mollusc" }, fr: { q: "Quel animal n’est PAS un poisson ?", a: ["Hippocampe", "Anguille", "Calmar", "Requin"], x: "Le calmar est un mollusque, parent de l’escargot. L’hippocampe et l’anguille ont l’air étranges, mais ce sont de vrais poissons.", k: "Calmar : pas un poisson mais un mollusque" }, es: { q: "¿Qué animal NO es un pez?", a: ["Caballito de mar", "Anguila", "Calamar", "Tiburón"], x: "El calamar es un molusco, pariente del caracol. El caballito de mar y la anguila parecen raros, pero son peces de verdad.", k: "Calamar: no es un pez, es un molusco" }, pt: { q: "Que animal NÃO é um peixe?", a: ["Cavalo-marinho", "Enguia", "Lula", "Tubarão"], x: "A lula é um molusco, parente do caracol. O cavalo-marinho e a enguia parecem estranhos, mas são peixes de verdade.", k: "Lula: não é peixe, é molusco" }, ja: { q: "魚ではないのはどれ？", a: ["タツノオトシゴ", "ウナギ", "イカ", "サメ"], x: "イカは軟体動物で、カタツムリの親せき。タツノオトシゴやウナギは変わった姿ですが、れっきとした魚です。", k: "イカ：魚ではなく軟体動物" }, it: { q: "Quale animale NON è un pesce?", a: ["Cavalluccio marino", "Anguilla", "Calamaro", "Squalo"], x: "Il calamaro è un mollusco, parente della chiocciola. Cavallucci marini e anguille sembrano strani, ma sono veri pesci.", k: "Calamaro: non è un pesce ma un mollusco" } } },
  { id: "k14", lvl: 2, type: "text", right: 3, t: { de: { q: "Welches Tier ist KEIN Säugetier?", a: ["Fledermaus", "Delfin", "Schnabeltier", "Pinguin"], x: "Pinguine sind Vögel, die nicht fliegen können. Das Schnabeltier legt zwar Eier, säugt seine Jungen aber und ist ein Säugetier.", k: "Pinguin: Vogel, kein Säugetier" }, en: { q: "Which animal is NOT a mammal?", a: ["Bat", "Dolphin", "Platypus", "Penguin"], x: "Penguins are birds that can’t fly. The platypus lays eggs, but it feeds its young with milk and is a mammal.", k: "Penguin: a bird, not a mammal" }, fr: { q: "Quel animal n’est PAS un mammifère ?", a: ["Chauve-souris", "Dauphin", "Ornithorynque", "Manchot"], x: "Le manchot est un oiseau qui ne vole pas. L’ornithorynque pond des œufs, mais il allaite ses petits : c’est un mammifère.", k: "Manchot : un oiseau, pas un mammifère" }, es: { q: "¿Qué animal NO es un mamífero?", a: ["Murciélago", "Delfín", "Ornitorrinco", "Pingüino"], x: "El pingüino es un ave que no vuela. El ornitorrinco pone huevos, pero amamanta a sus crías y es un mamífero.", k: "Pingüino: un ave, no un mamífero" }, pt: { q: "Que animal NÃO é um mamífero?", a: ["Morcego", "Golfinho", "Ornitorrinco", "Pinguim"], x: "O pinguim é uma ave que não voa. O ornitorrinco põe ovos, mas amamenta os filhotes e é um mamífero.", k: "Pinguim: ave, não mamífero" }, ja: { q: "哺乳類ではないのはどれ？", a: ["コウモリ", "イルカ", "カモノハシ", "ペンギン"], x: "ペンギンは飛べない鳥。カモノハシは卵を産みますが、子どもをお乳で育てる哺乳類です。", k: "ペンギン：哺乳類ではなく鳥" }, it: { q: "Quale animale NON è un mammifero?", a: ["Pipistrello", "Delfino", "Ornitorinco", "Pinguino"], x: "Il pinguino è un uccello che non vola. L’ornitorinco depone uova, ma allatta i piccoli ed è un mammifero.", k: "Pinguino: un uccello, non un mammifero" } } },
  { id: "k17", lvl: 2, type: "text", right: 2, t: { de: { q: "Schätzfrage: Wie weit springt ein Floh im Verhältnis zu seiner Größe?", a: ["Etwa doppelt so weit", "Etwa 10-mal so weit", "Über 100-mal so weit", "Etwa 10.000-mal so weit"], x: "Ein Floh springt rund 30 cm weit – über hundertmal seine Körperlänge. Ein Mensch müsste dafür weiter springen als ein Fußballfeld lang ist.", k: "Floh: springt 100-mal so weit, wie er lang ist" }, en: { q: "Guess: how far does a flea jump compared to its size?", a: ["About twice as far", "About 10 times as far", "Over 100 times as far", "About 10,000 times as far"], x: "A flea jumps about 30 cm – over a hundred times its body length. A human would have to jump further than a football pitch is long.", k: "Flea: jumps 100 times its body length" }, fr: { q: "Devine : à quelle distance une puce saute-t-elle par rapport à sa taille ?", a: ["Environ deux fois sa taille", "Environ 10 fois", "Plus de 100 fois", "Environ 10 000 fois"], x: "Une puce saute environ 30 cm – plus de cent fois la longueur de son corps. Un humain devrait sauter plus loin que la longueur d’un terrain de foot.", k: "Puce : saute 100 fois sa longueur" }, es: { q: "Adivina: ¿cuánto salta una pulga en relación con su tamaño?", a: ["El doble de su tamaño", "Unas 10 veces", "Más de 100 veces", "Unas 10.000 veces"], x: "Una pulga salta unos 30 cm, más de cien veces su longitud. Un humano tendría que saltar más que lo que mide un campo de fútbol.", k: "Pulga: salta 100 veces su longitud" }, pt: { q: "Adivinhe: quanto pula uma pulga em relação ao seu tamanho?", a: ["O dobro do tamanho", "Umas 10 vezes", "Mais de 100 vezes", "Umas 10.000 vezes"], x: "Uma pulga pula uns 30 cm – mais de cem vezes o seu comprimento. Um humano teria de pular mais que o comprimento de um campo de futebol.", k: "Pulga: salta 100 vezes seu tamanho" }, ja: { q: "予想してみよう：ノミは体の大きさの何倍跳ぶ？", a: ["約2倍", "約10倍", "100倍以上", "約1万倍"], x: "ノミは約30センチ跳びます。体長の100倍以上です。人間なら、サッカー場の長さより遠くまで跳ぶことになります。", k: "ノミ：体長の100倍跳ぶ" }, it: { q: "Indovina: quanto salta una pulce rispetto alla sua taglia?", a: ["Circa il doppio", "Circa 10 volte", "Oltre 100 volte", "Circa 10.000 volte"], x: "Una pulce salta circa 30 cm, oltre cento volte la sua lunghezza. Una persona dovrebbe saltare più di un campo da calcio.", k: "Pulce: salta 100 volte la sua lunghezza" } } },
  { id: "k18", lvl: 1, type: "text", right: 0, t: { de: { q: "Welche Reihenfolge stimmt beim Schmetterling?", a: ["Ei – Raupe – Puppe – Falter", "Ei – Puppe – Raupe – Falter", "Raupe – Ei – Puppe – Falter", "Ei – Raupe – Falter – Puppe"], x: "Aus dem Ei schlüpft die Raupe, sie frisst und wächst, verpuppt sich, und in der Puppe wird ihr ganzer Körper zum Falter umgebaut.", k: "Schmetterling: Ei – Raupe – Puppe – Falter" }, en: { q: "Which order is right for a butterfly?", a: ["Egg – caterpillar – pupa – butterfly", "Egg – pupa – caterpillar – butterfly", "Caterpillar – egg – pupa – butterfly", "Egg – caterpillar – butterfly – pupa"], x: "A caterpillar hatches from the egg, eats and grows, turns into a pupa, and inside the pupa its whole body is rebuilt into a butterfly.", k: "Butterfly: egg – caterpillar – pupa – butterfly" }, fr: { q: "Quel est le bon ordre chez le papillon ?", a: ["Œuf – chenille – chrysalide – papillon", "Œuf – chrysalide – chenille – papillon", "Chenille – œuf – chrysalide – papillon", "Œuf – chenille – papillon – chrysalide"], x: "La chenille sort de l’œuf, mange et grandit, devient chrysalide, et dans la chrysalide tout son corps se transforme en papillon.", k: "Papillon : œuf – chenille – chrysalide – papillon" }, es: { q: "¿Qué orden es el correcto en la mariposa?", a: ["Huevo – oruga – crisálida – mariposa", "Huevo – crisálida – oruga – mariposa", "Oruga – huevo – crisálida – mariposa", "Huevo – oruga – mariposa – crisálida"], x: "Del huevo sale la oruga, que come y crece, se convierte en crisálida, y dentro todo su cuerpo se transforma en mariposa.", k: "Mariposa: huevo – oruga – crisálida – mariposa" }, pt: { q: "Qual é a ordem certa na borboleta?", a: ["Ovo – lagarta – crisálida – borboleta", "Ovo – crisálida – lagarta – borboleta", "Lagarta – ovo – crisálida – borboleta", "Ovo – lagarta – borboleta – crisálida"], x: "Do ovo sai a lagarta, que come e cresce, vira crisálida, e lá dentro todo o corpo se transforma em borboleta.", k: "Borboleta: ovo – lagarta – crisálida – borboleta" }, ja: { q: "チョウの正しい順番はどれ？", a: ["卵 – 幼虫 – さなぎ – チョウ", "卵 – さなぎ – 幼虫 – チョウ", "幼虫 – 卵 – さなぎ – チョウ", "卵 – 幼虫 – チョウ – さなぎ"], x: "卵から幼虫がかえり、食べて大きくなってさなぎになります。さなぎの中で、体全体がチョウに作りかえられます。", k: "チョウ：卵→幼虫→さなぎ→成虫" }, it: { q: "Qual è l’ordine giusto per una farfalla?", a: ["Uovo – bruco – crisalide – farfalla", "Uovo – crisalide – bruco – farfalla", "Bruco – uovo – crisalide – farfalla", "Uovo – bruco – farfalla – crisalide"], x: "Dall’uovo esce il bruco, che mangia e cresce, diventa crisalide, e dentro la crisalide tutto il corpo si trasforma in farfalla.", k: "Farfalla: uovo – bruco – crisalide – farfalla" } } },
  { id: "t04", lvl: 1, type: "tf", right: 1, t: { de: { q: "Stimmt’s? Goldfische haben ein Gedächtnis von nur drei Sekunden.", a: ["Wahr", "Falsch"], x: "Ein Mythos! Goldfische können sich Dinge monatelang merken und lassen sich sogar auf Töne oder Farben trainieren.", k: "Goldfische: erinnern sich monatelang" }, en: { q: "True or false? Goldfish have a memory of only three seconds.", a: ["True", "False"], x: "A myth! Goldfish can remember things for months and can even be trained to respond to sounds or colours.", k: "Goldfish: remember things for months" }, fr: { q: "Vrai ou faux ? Le poisson rouge n’a que trois secondes de mémoire.", a: ["Vrai", "Faux"], x: "Un mythe ! Le poisson rouge se souvient de choses pendant des mois et peut même être dressé à réagir à des sons ou des couleurs.", k: "Poissons rouges : se souviennent des mois" }, es: { q: "¿Verdadero o falso? Los peces de colores solo tienen tres segundos de memoria.", a: ["Verdadero", "Falso"], x: "¡Un mito! Los peces de colores recuerdan cosas durante meses e incluso se les puede entrenar con sonidos o colores.", k: "Peces de colores: recuerdan durante meses" }, pt: { q: "Verdadeiro ou falso? O peixinho-dourado tem memória de só três segundos.", a: ["Verdadeiro", "Falso"], x: "Um mito! Os peixinhos-dourados lembram coisas por meses e podem até ser treinados com sons ou cores.", k: "Peixinhos-dourados: lembram por meses" }, ja: { q: "正しい？まちがい？ 金魚の記憶はたった3秒しかもたない。", a: ["正しい", "まちがい"], x: "これは俗説！金魚は何か月も物事を覚えていられ、音や色に反応するよう訓練することもできます。", k: "金魚：何か月も覚えている" }, it: { q: "Vero o falso? I pesci rossi hanno una memoria di soli tre secondi.", a: ["Vero", "Falso"], x: "Un mito! I pesci rossi ricordano le cose per mesi e possono persino essere addestrati a rispondere a suoni o colori.", k: "Pesci rossi: ricordano per mesi" } } },
  { id: "k19", lvl: 1, type: "text", right: 3, t: { de: { q: "Welche Aussage ist FALSCH?", a: ["Krokodile lebten schon zur Zeit der Dinosaurier", "Eine Schnecke kriecht auf einem einzigen Fuß", "Hummeln können stechen", "Strauße stecken bei Gefahr den Kopf in den Sand"], x: "Ein Mythos: Strauße legen sich bei Gefahr flach auf den Boden – oder rennen mit bis zu 70 km/h davon.", k: "Strauß: steckt den Kopf nicht in den Sand" }, en: { q: "Which statement is FALSE?", a: ["Crocodiles already lived in the time of the dinosaurs", "A snail crawls on a single foot", "Bumblebees can sting", "Ostriches bury their heads in the sand when in danger"], x: "A myth: in danger, ostriches lie flat on the ground – or run away at up to 70 km/h.", k: "Ostrich: doesn't bury its head in the sand" }, fr: { q: "Quelle affirmation est FAUSSE ?", a: ["Les crocodiles vivaient déjà à l’époque des dinosaures", "L’escargot rampe sur un seul pied", "Les bourdons peuvent piquer", "L’autruche cache sa tête dans le sable en cas de danger"], x: "Un mythe : en cas de danger, l’autruche se couche à plat sur le sol – ou s’enfuit à 70 km/h.", k: "Autruche : ne met pas la tête dans le sable" }, es: { q: "¿Qué afirmación es FALSA?", a: ["Los cocodrilos ya vivían en tiempos de los dinosaurios", "El caracol se arrastra sobre un solo pie", "Los abejorros pueden picar", "El avestruz esconde la cabeza en la arena ante el peligro"], x: "Un mito: ante el peligro, el avestruz se tumba en el suelo o huye corriendo a hasta 70 km/h.", k: "Avestruz: no esconde la cabeza en la arena" }, pt: { q: "Qual afirmação é FALSA?", a: ["Os crocodilos já viviam na época dos dinossauros", "O caracol rasteja sobre um único pé", "As mamangavas podem picar", "O avestruz enterra a cabeça na areia quando há perigo"], x: "Um mito: em perigo, o avestruz se deita no chão ou foge correndo a até 70 km/h.", k: "Avestruz: não enterra a cabeça na areia" }, ja: { q: "まちがっているのはどれ？", a: ["ワニは恐竜の時代にもういた", "カタツムリはひとつの足ではう", "マルハナバチは刺すことがある", "ダチョウは危ないと頭を砂にうめる"], x: "これは俗説。ダチョウは危ないときは地面にふせるか、時速70キロで走って逃げます。", k: "ダチョウ：頭を砂にうめない" }, it: { q: "Quale affermazione è FALSA?", a: ["I coccodrilli vivevano già al tempo dei dinosauri", "La chiocciola striscia su un solo piede", "I bombi possono pungere", "Lo struzzo nasconde la testa nella sabbia quando c’è pericolo"], x: "Un mito: in caso di pericolo lo struzzo si sdraia a terra, oppure scappa correndo fino a 70 km/h.", k: "Struzzo: non nasconde la testa nella sabbia" } } },
  { id: "k20", lvl: 2, type: "text", right: 2, t: { de: { q: "Schätzfrage: Wie weit kann ein Chamäleon seine Zunge herausschnellen?", a: ["Halb so weit, wie es lang ist", "Etwa so weit, wie es lang ist", "Bis zu doppelt so weit, wie es lang ist", "Zehnmal so weit, wie es lang ist"], x: "Bis zur doppelten Körperlänge (ohne Schwanz) – und das in einem Bruchteil einer Sekunde. Die klebrige Zungenspitze hält auch große Insekten fest.", k: "Chamäleon: Zunge doppelt so lang wie der Körper" }, en: { q: "Guess: how far can a chameleon shoot out its tongue?", a: ["Half its body length", "About its body length", "Up to twice its body length", "Ten times its body length"], x: "Up to twice its body length (without the tail) – in a fraction of a second. The sticky tongue tip holds even large insects.", k: "Chameleon: tongue twice its body length" }, fr: { q: "Devine : jusqu’où un caméléon peut-il projeter sa langue ?", a: ["La moitié de sa longueur", "Environ sa longueur", "Jusqu’à deux fois sa longueur", "Dix fois sa longueur"], x: "Jusqu’à deux fois la longueur de son corps (sans la queue) – en une fraction de seconde. Le bout collant retient même de gros insectes.", k: "Caméléon : langue deux fois son corps" }, es: { q: "Adivina: ¿hasta dónde lanza un camaleón su lengua?", a: ["La mitad de su longitud", "Más o menos su longitud", "Hasta el doble de su longitud", "Diez veces su longitud"], x: "Hasta el doble de la longitud de su cuerpo (sin la cola), en una fracción de segundo. La punta pegajosa sujeta incluso insectos grandes.", k: "Camaleón: lengua el doble de su cuerpo" }, pt: { q: "Adivinhe: até onde o camaleão lança a língua?", a: ["Metade do comprimento dele", "Mais ou menos o comprimento dele", "Até o dobro do comprimento dele", "Dez vezes o comprimento dele"], x: "Até o dobro do comprimento do corpo (sem a cauda), numa fração de segundo. A ponta grudenta segura até insetos grandes.", k: "Camaleão: língua com o dobro do corpo" }, ja: { q: "予想してみよう：カメレオンは舌をどこまでのばせる？", a: ["体長の半分", "体長と同じくらい", "体長の2倍まで", "体長の10倍"], x: "体長（しっぽをのぞく）の2倍まで、一瞬でのばします。ねばねばの舌の先は、大きな虫もしっかりつかまえます。", k: "カメレオン：舌は体の2倍" }, it: { q: "Indovina: fin dove arriva la lingua del camaleonte?", a: ["Metà della sua lunghezza", "Circa la sua lunghezza", "Fino al doppio della sua lunghezza", "Dieci volte la sua lunghezza"], x: "Fino al doppio della lunghezza del corpo (senza coda), in una frazione di secondo. La punta appiccicosa trattiene anche insetti grandi.", k: "Camaleonte: lingua lunga il doppio del corpo" } } },
  { id: "k21", lvl: 3, type: "text", right: 3, t: { de: { q: "Schätzfrage: Wie viele Ameisen leben ungefähr auf der Erde?", a: ["Etwa 20 Millionen", "Etwa 20 Milliarden", "Etwa 20 Billionen", "Etwa 20 Billiarden"], x: "Forscher schätzten 2022: rund 20 Billiarden – eine 2 mit 16 Nullen. Das sind etwa 2,5 Millionen Ameisen pro Mensch.", k: "Ameisen: 20 Billiarden auf der Erde" }, en: { q: "Guess: roughly how many ants live on Earth?", a: ["About 20 million", "About 20 billion", "About 20 trillion", "About 20 quadrillion"], x: "Researchers estimated in 2022: around 20 quadrillion – a 2 with 16 zeros. That’s about 2.5 million ants per person.", k: "Ants: 20 quadrillion on Earth" }, fr: { q: "Devine : combien de fourmis vivent environ sur Terre ?", a: ["Environ 20 millions", "Environ 20 milliards", "Environ 20 000 milliards", "Environ 20 millions de milliards"], x: "Selon une estimation de 2022 : environ 20 millions de milliards – un 2 suivi de 16 zéros. Soit environ 2,5 millions de fourmis par personne.", k: "Fourmis : 20 millions de milliards sur Terre" }, es: { q: "Adivina: ¿cuántas hormigas viven aproximadamente en la Tierra?", a: ["Unos 20 millones", "Unos 20.000 millones", "Unos 20 billones", "Unos 20.000 billones"], x: "Según una estimación de 2022: unos 20.000 billones, un 2 seguido de 16 ceros. Son unos 2,5 millones de hormigas por persona.", k: "Hormigas: 20.000 billones en la Tierra" }, pt: { q: "Adivinhe: quantas formigas vivem mais ou menos na Terra?", a: ["Uns 20 milhões", "Uns 20 bilhões", "Uns 20 trilhões", "Uns 20 quatrilhões"], x: "Segundo uma estimativa de 2022: uns 20 quatrilhões – um 2 com 16 zeros. São cerca de 2,5 milhões de formigas por pessoa.", k: "Formigas: 20 quatrilhões na Terra" }, ja: { q: "予想してみよう：地球にはアリがだいたい何匹いる？", a: ["約2000万匹", "約200億匹", "約2京匹", "約2000京匹"], x: "2022年の研究の推定では約2京匹。2のあとに0が16個です。1人あたり約250万匹になります。", k: "アリ：地球に約2京匹" }, it: { q: "Indovina: quante formiche vivono più o meno sulla Terra?", a: ["Circa 20 milioni", "Circa 20 miliardi", "Circa 20.000 miliardi", "Circa 20 biliardi"], x: "Secondo una stima del 2022: circa 20 biliardi, cioè un 2 seguito da 16 zeri. Sono circa 2,5 milioni di formiche per persona.", k: "Formiche: 20 biliardi sulla Terra" } } },
  { id: "k22", lvl: 3, type: "text", right: 0, t: { de: { q: "Wofür sind die Streifen des Zebras nach heutigem Wissen am wahrscheinlichsten gut?", a: ["Sie halten stechende Fliegen fern", "Tarnung im hohen Gras", "Damit Löwen sie nicht von Felsen unterscheiden", "Gegen Sonnenbrand"], x: "Versuche zeigen: Bremsen landen auf gestreiften Flächen viel seltener – das Muster bringt sie beim Anflug durcheinander.", k: "Zebrastreifen: halten Bremsen fern" }, en: { q: "According to current knowledge, what are zebra stripes most likely good for?", a: ["Keeping biting flies away", "Camouflage in tall grass", "So lions can’t tell them from rocks", "Against sunburn"], x: "Experiments show that horseflies land far less often on striped surfaces – the pattern confuses them as they approach.", k: "Zebra stripes: keep horseflies away" }, fr: { q: "Selon les connaissances actuelles, à quoi servent le plus probablement les rayures du zèbre ?", a: ["À éloigner les mouches piqueuses", "À se camoufler dans les hautes herbes", "À ressembler à des rochers pour les lions", "À éviter les coups de soleil"], x: "Des expériences le montrent : les taons se posent bien plus rarement sur des surfaces rayées – le motif les désoriente à l’approche.", k: "Rayures du zèbre : éloignent les taons" }, es: { q: "Según lo que se sabe hoy, ¿para qué sirven probablemente las rayas de la cebra?", a: ["Para alejar a las moscas que pican", "Para camuflarse en la hierba alta", "Para que los leones las confundan con rocas", "Contra las quemaduras del sol"], x: "Los experimentos muestran que los tábanos se posan mucho menos en superficies rayadas: el dibujo los confunde al acercarse.", k: "Rayas de la cebra: alejan a los tábanos" }, pt: { q: "Pelo que se sabe hoje, para que servem provavelmente as listras da zebra?", a: ["Para afastar as moscas que picam", "Para se camuflar no capim alto", "Para os leões as confundirem com pedras", "Contra queimaduras de sol"], x: "Experimentos mostram que as mutucas pousam muito menos em superfícies listradas: o desenho as confunde na aproximação.", k: "Listras da zebra: afastam mutucas" }, ja: { q: "いまわかっている中で、シマウマのしまもようはたぶん何の役に立つ？", a: ["血を吸うハエを寄せつけない", "高い草の中でかくれる", "ライオンに岩とまちがえさせる", "日焼けを防ぐ"], x: "実験では、アブはしまもようの面にずっととまりにくいことがわかっています。近づくとき、もようで混乱するのです。", k: "シマウマのしま：アブを寄せつけない" }, it: { q: "Secondo le conoscenze attuali, a cosa servono probabilmente le strisce della zebra?", a: ["A tenere lontane le mosche che pungono", "A mimetizzarsi nell’erba alta", "A farsi scambiare per rocce dai leoni", "Contro le scottature"], x: "Gli esperimenti mostrano che i tafani si posano molto meno sulle superfici a strisce: il disegno li confonde mentre si avvicinano.", k: "Strisce della zebra: tengono lontani i tafani" } } },
  { id: "k23", lvl: 2, type: "text", right: 0, t: { de: { q: "Wie verständigen sich Elefanten über viele Kilometer?", a: ["Mit sehr tiefen Tönen, die wir nicht hören", "Mit Ohrenwedeln als Lichtzeichen", "Mit Duftwolken im Wind", "Gar nicht – nur aus der Nähe"], x: "Elefanten brummen im Infraschall. Diese tiefen Töne reichen kilometerweit – andere Elefanten spüren sie sogar über die Füße im Boden.", k: "Elefanten: reden per Infraschall über Kilometer" }, en: { q: "How do elephants communicate over many kilometres?", a: ["With very low sounds we can’t hear", "By flapping their ears as light signals", "With clouds of scent in the wind", "They don’t – only up close"], x: "Elephants rumble in infrasound. These deep sounds travel for kilometres – other elephants even feel them through their feet in the ground.", k: "Elephants: talk by infrasound over kilometres" }, fr: { q: "Comment les éléphants communiquent-ils sur des kilomètres ?", a: ["Avec des sons très graves que nous n’entendons pas", "En agitant les oreilles comme des signaux lumineux", "Avec des nuages d’odeurs dans le vent", "Pas du tout – seulement de près"], x: "Les éléphants grondent en infrasons. Ces sons graves portent sur des kilomètres – les autres éléphants les sentent même par les pieds, dans le sol.", k: "Éléphants : parlent en infrasons sur des km" }, es: { q: "¿Cómo se comunican los elefantes a muchos kilómetros?", a: ["Con sonidos muy graves que no oímos", "Moviendo las orejas como señales", "Con nubes de olor en el viento", "No lo hacen: solo de cerca"], x: "Los elefantes emiten infrasonidos. Esos sonidos graves llegan a kilómetros, y otros elefantes los notan incluso con las patas a través del suelo.", k: "Elefantes: hablan por infrasonido a kilómetros" }, pt: { q: "Como os elefantes se comunicam a muitos quilômetros?", a: ["Com sons muito graves que não ouvimos", "Mexendo as orelhas como sinais", "Com nuvens de cheiro no vento", "Não se comunicam: só de perto"], x: "Os elefantes emitem infrassons. Esses sons graves chegam a quilômetros, e outros elefantes os sentem até pelas patas, através do chão.", k: "Elefantes: falam por infrassom a quilômetros" }, ja: { q: "ゾウは何キロもはなれた仲間と、どうやって連絡をとる？", a: ["人には聞こえないとても低い音で", "耳をパタパタさせて合図する", "風に乗せたにおいで", "とらない。近くだけ"], x: "ゾウは低周波の音でゴロゴロと鳴きます。この低い音は何キロも届き、ほかのゾウは地面を通して足でも感じとります。", k: "ゾウ：低周波で何キロも会話" }, it: { q: "Come comunicano gli elefanti a molti chilometri di distanza?", a: ["Con suoni gravissimi che non sentiamo", "Sventolando le orecchie come segnali", "Con nuvole di odore nel vento", "Non lo fanno: solo da vicino"], x: "Gli elefanti emettono infrasuoni. Questi suoni gravi arrivano a chilometri, e gli altri elefanti li sentono persino con le zampe, attraverso il terreno.", k: "Elefanti: comunicano a infrasuoni per km" } } },
  { id: "t06", lvl: 2, type: "tf", right: 0, t: { de: { q: "Stimmt’s? Viele Schmetterlinge können erst fliegen, wenn sie sich aufgewärmt haben.", a: ["Wahr", "Falsch"], x: "Ihre Flugmuskeln brauchen Wärme. Darum sonnen sich Tagfalter morgens mit ausgebreiteten Flügeln oder zittern sich warm.", k: "Schmetterlinge: fliegen erst warm" }, en: { q: "True or false? Many butterflies can only fly once they have warmed up.", a: ["True", "False"], x: "Their flight muscles need warmth. That’s why butterflies sunbathe with open wings in the morning or shiver to warm up.", k: "Butterflies: only fly once warm" }, fr: { q: "Vrai ou faux ? Beaucoup de papillons ne peuvent voler qu’après s’être réchauffés.", a: ["Vrai", "Faux"], x: "Leurs muscles de vol ont besoin de chaleur. C’est pourquoi les papillons se chauffent au soleil, ailes ouvertes, le matin, ou frissonnent pour se réchauffer.", k: "Papillons : volent seulement une fois réchauffés" }, es: { q: "¿Verdadero o falso? Muchas mariposas solo pueden volar cuando se han calentado.", a: ["Verdadero", "Falso"], x: "Sus músculos de vuelo necesitan calor. Por eso, por la mañana, toman el sol con las alas abiertas o tiritan para calentarse.", k: "Mariposas: vuelan cuando se calientan" }, pt: { q: "Verdadeiro ou falso? Muitas borboletas só conseguem voar depois de se aquecer.", a: ["Verdadeiro", "Falso"], x: "Os músculos de voo precisam de calor. Por isso, de manhã, elas tomam sol de asas abertas ou tremem para se aquecer.", k: "Borboletas: só voam depois de aquecer" }, ja: { q: "正しい？まちがい？ 多くのチョウは体が温まってからでないと飛べない。", a: ["正しい", "まちがい"], x: "飛ぶための筋肉には温かさが必要です。だからチョウは朝、羽を広げて日光浴をしたり、ふるえて体を温めたりします。", k: "チョウ：体が温まってから飛ぶ" }, it: { q: "Vero o falso? Molte farfalle possono volare solo dopo essersi scaldate.", a: ["Vero", "Falso"], x: "I muscoli del volo hanno bisogno di calore. Per questo al mattino le farfalle prendono il sole ad ali aperte o tremano per scaldarsi.", k: "Farfalle: volano solo da calde" } } },
  { id: "t07", lvl: 3, type: "tf", right: 0, t: { de: { q: "Stimmt’s? Im Fell von Faultieren wachsen Algen.", a: ["Wahr", "Falsch"], x: "Ja – sie geben dem Fell einen grünlichen Schimmer, eine gute Tarnung im Regenwald. Sogar eigene Mottenarten leben darin.", k: "Faultier: im Fell wachsen Algen" }, en: { q: "True or false? Algae grow in sloths’ fur.", a: ["True", "False"], x: "Yes – they give the fur a greenish tint, good camouflage in the rainforest. Even special kinds of moths live in it.", k: "Sloth: algae grow in its fur" }, fr: { q: "Vrai ou faux ? Des algues poussent dans la fourrure des paresseux.", a: ["Vrai", "Faux"], x: "Oui – elles donnent au pelage un reflet verdâtre, un bon camouflage dans la forêt tropicale. Des papillons de nuit spéciaux y vivent même.", k: "Paresseux : des algues poussent dans son pelage" }, es: { q: "¿Verdadero o falso? En el pelo de los perezosos crecen algas.", a: ["Verdadero", "Falso"], x: "Sí, le dan al pelo un tono verdoso, buen camuflaje en la selva. Hasta viven en él polillas especiales.", k: "Perezoso: le crecen algas en el pelo" }, pt: { q: "Verdadeiro ou falso? No pelo do bicho-preguiça crescem algas.", a: ["Verdadeiro", "Falso"], x: "Sim, elas dão ao pelo um tom esverdeado – boa camuflagem na floresta. Até mariposas especiais vivem nele.", k: "Bicho-preguiça: tem algas no pelo" }, ja: { q: "正しい？まちがい？ ナマケモノの毛には藻が生えている。", a: ["正しい", "まちがい"], x: "そう！藻で毛が緑っぽくなり、熱帯雨林でいいカモフラージュになります。毛の中には専用のガまですんでいます。", k: "ナマケモノ：毛に藻が生える" }, it: { q: "Vero o falso? Nel pelo dei bradipi crescono alghe.", a: ["Vero", "Falso"], x: "Sì: danno al pelo una sfumatura verde, un buon mimetismo nella foresta pluviale. Ci vivono perfino falene particolari.", k: "Bradipo: nel pelo crescono alghe" } } },
  { id: "t08", lvl: 3, type: "tf", right: 0, t: { de: { q: "Stimmt’s? Krokodile können ihre Zunge nicht herausstrecken.", a: ["Wahr", "Falsch"], x: "Ihre Zunge ist am Mundboden festgewachsen. Sie hilft beim Schlucken und dichtet zusammen mit einer Klappe den Rachen ab, wenn sie unter Wasser das Maul öffnen.", k: "Krokodile: können die Zunge nicht rausstrecken" }, en: { q: "True or false? Crocodiles can’t stick out their tongue.", a: ["True", "False"], x: "Their tongue is attached to the floor of the mouth. It helps with swallowing and, together with a flap, seals the throat when they open their mouth underwater.", k: "Crocodiles: can't stick out their tongue" }, fr: { q: "Vrai ou faux ? Les crocodiles ne peuvent pas tirer la langue.", a: ["Vrai", "Faux"], x: "Leur langue est fixée au plancher de la bouche. Elle aide à avaler et, avec un clapet, ferme la gorge quand ils ouvrent la gueule sous l’eau.", k: "Crocodiles : ne peuvent pas tirer la langue" }, es: { q: "¿Verdadero o falso? Los cocodrilos no pueden sacar la lengua.", a: ["Verdadero", "Falso"], x: "Su lengua está unida al suelo de la boca. Ayuda a tragar y, junto con una válvula, cierra la garganta cuando abren la boca bajo el agua.", k: "Cocodrilos: no pueden sacar la lengua" }, pt: { q: "Verdadeiro ou falso? Os crocodilos não conseguem pôr a língua para fora.", a: ["Verdadeiro", "Falso"], x: "A língua é presa ao fundo da boca. Ela ajuda a engolir e, junto com uma válvula, fecha a garganta quando abrem a boca debaixo d’água.", k: "Crocodilos: não conseguem pôr a língua para fora" }, ja: { q: "正しい？まちがい？ ワニは舌を外に出せない。", a: ["正しい", "まちがい"], x: "舌は口の底にくっついています。飲みこむのを助け、弁と一緒に、水中で口を開けたときにのどをふさぎます。", k: "ワニ：舌を外に出せない" }, it: { q: "Vero o falso? I coccodrilli non possono tirare fuori la lingua.", a: ["Vero", "Falso"], x: "La lingua è attaccata al fondo della bocca. Aiuta a deglutire e, con una valvola, chiude la gola quando aprono la bocca sott’acqua.", k: "Coccodrilli: non possono tirare fuori la lingua" } } },
  { id: "r01", lvl: 2, type: "rank", right: 10123, t: { de: { q: "Wer rennt am schnellsten? Schnellstes zuerst.", a: ["Gepard", "Gabelbock", "Feldhase", "Mensch"], x: "Gepard bis etwa 110 km/h, Gabelbock fast 90, Feldhase rund 70 – und der schnellste Mensch knapp 45 km/h.", k: "Gepard: schnellstes Landtier, 110 km/h" }, en: { q: "Who runs fastest? Fastest first.", a: ["Cheetah", "Pronghorn", "Brown hare", "Human"], x: "Cheetah up to about 110 km/h, pronghorn almost 90, brown hare around 70 – and the fastest human just under 45 km/h.", k: "Cheetah: fastest land animal, 110 km/h" }, fr: { q: "Qui court le plus vite ? Le plus rapide d’abord.", a: ["Guépard", "Antilope d’Amérique", "Lièvre d’Europe", "Humain"], x: "Guépard jusqu’à environ 110 km/h, antilope d’Amérique près de 90, lièvre environ 70 – et l’humain le plus rapide un peu moins de 45 km/h.", k: "Guépard : le plus rapide sur terre, 110 km/h" }, es: { q: "¿Quién corre más rápido? El más rápido primero.", a: ["Guepardo", "Berrendo", "Liebre europea", "Humano"], x: "Guepardo hasta unos 110 km/h, berrendo casi 90, liebre unos 70, y el humano más rápido algo menos de 45 km/h.", k: "Guepardo: el más rápido en tierra, 110 km/h" }, pt: { q: "Quem corre mais rápido? O mais rápido primeiro.", a: ["Guepardo", "Antilocapra", "Lebre-europeia", "Humano"], x: "Guepardo até uns 110 km/h, antilocapra quase 90, lebre uns 70, e o humano mais rápido pouco menos de 45 km/h.", k: "Guepardo: o mais rápido em terra, 110 km/h" }, ja: { q: "走るのが速いのは？ 速い順に。", a: ["チーター", "プロングホーン", "ヤブノウサギ", "人間"], x: "チーターは時速約110キロ、プロングホーンは90キロ近く、ノウサギは約70キロ。いちばん速い人間でも45キロ弱です。", k: "チーター：陸上最速、時速110キロ" }, it: { q: "Chi corre più veloce? Il più veloce per primo.", a: ["Ghepardo", "Antilocapra", "Lepre europea", "Essere umano"], x: "Ghepardo fino a circa 110 km/h, antilocapra quasi 90, lepre circa 70, e l’essere umano più veloce poco meno di 45 km/h.", k: "Ghepardo: il più veloce sulla terra, 110 km/h" } } },
  { id: "r02", lvl: 2, type: "rank", right: 10123, t: { de: { q: "Wer ist in der Luft am schnellsten? Schnellstes zuerst.", a: ["Wanderfalke (Sturzflug)", "Steinadler (Sturzflug)", "Mauersegler", "Haussperling"], x: "Wanderfalke über 300 km/h, Steinadler rund 240 km/h im Sturzflug, Mauersegler über 100 km/h im Flug, Spatz etwa 40 km/h.", k: "Wanderfalke: über 300 km/h im Sturzflug" }, en: { q: "Who is fastest in the air? Fastest first.", a: ["Peregrine falcon (dive)", "Golden eagle (dive)", "Common swift", "House sparrow"], x: "Peregrine falcon over 300 km/h, golden eagle around 240 km/h in a dive, swift over 100 km/h in flight, sparrow about 40 km/h.", k: "Peregrine falcon: over 300 km/h in a dive" }, fr: { q: "Qui est le plus rapide dans les airs ? Le plus rapide d’abord.", a: ["Faucon pèlerin (en piqué)", "Aigle royal (en piqué)", "Martinet noir", "Moineau domestique"], x: "Faucon pèlerin plus de 300 km/h, aigle royal environ 240 km/h en piqué, martinet plus de 100 km/h en vol, moineau environ 40 km/h.", k: "Faucon pèlerin : plus de 300 km/h en piqué" }, es: { q: "¿Quién es más rápido en el aire? El más rápido primero.", a: ["Halcón peregrino (en picado)", "Águila real (en picado)", "Vencejo común", "Gorrión común"], x: "Halcón peregrino más de 300 km/h, águila real unos 240 km/h en picado, vencejo más de 100 km/h volando, gorrión unos 40 km/h.", k: "Halcón peregrino: más de 300 km/h en picado" }, pt: { q: "Quem é mais rápido no ar? O mais rápido primeiro.", a: ["Falcão-peregrino (em mergulho)", "Águia-real (em mergulho)", "Andorinhão-preto", "Pardal"], x: "Falcão-peregrino mais de 300 km/h, águia-real uns 240 km/h em mergulho, andorinhão mais de 100 km/h voando, pardal uns 40 km/h.", k: "Falcão-peregrino: mais de 300 km/h em mergulho" }, ja: { q: "空でいちばん速いのは？ 速い順に。", a: ["ハヤブサ（急降下）", "イヌワシ（急降下）", "ヨーロッパアマツバメ", "イエスズメ"], x: "ハヤブサは時速300キロ以上、イヌワシは急降下で約240キロ、アマツバメは飛行中100キロ以上、スズメは約40キロ。", k: "ハヤブサ：急降下で時速300キロ以上" }, it: { q: "Chi è più veloce in aria? Il più veloce per primo.", a: ["Falco pellegrino (in picchiata)", "Aquila reale (in picchiata)", "Rondone comune", "Passera europea"], x: "Falco pellegrino oltre 300 km/h, aquila reale circa 240 km/h in picchiata, rondone oltre 100 km/h in volo, passera circa 40 km/h.", k: "Falco pellegrino: oltre 300 km/h in picchiata" } } },
  { id: "r03", lvl: 3, type: "rank", right: 10123, t: { de: { q: "Wer schwimmt am schnellsten? Schnellstes zuerst.", a: ["Schwertwal", "Kalifornischer Seelöwe", "Fischotter", "Mensch"], x: "Schwertwale schaffen gut 50 km/h, Seelöwen um 40, Fischotter gut 10 km/h. Die besten Schwimmer unter den Menschen kommen auf knapp 9 km/h.", k: "Orca: schwimmt über 50 km/h" }, en: { q: "Who swims fastest? Fastest first.", a: ["Orca", "California sea lion", "Eurasian otter", "Human"], x: "Orcas reach over 50 km/h, sea lions around 40, otters just over 10 km/h. The best human swimmers manage just under 9 km/h.", k: "Orca: swims over 50 km/h" }, fr: { q: "Qui nage le plus vite ? Le plus rapide d’abord.", a: ["Orque", "Otarie de Californie", "Loutre d’Europe", "Humain"], x: "L’orque dépasse 50 km/h, l’otarie environ 40, la loutre un peu plus de 10 km/h. Les meilleurs nageurs humains atteignent à peine 9 km/h.", k: "Orque : nage à plus de 50 km/h" }, es: { q: "¿Quién nada más rápido? El más rápido primero.", a: ["Orca", "León marino de California", "Nutria europea", "Humano"], x: "La orca supera los 50 km/h, el león marino unos 40 y la nutria algo más de 10 km/h. Los mejores nadadores humanos llegan a casi 9 km/h.", k: "Orca: nada a más de 50 km/h" }, pt: { q: "Quem nada mais rápido? O mais rápido primeiro.", a: ["Orca", "Leão-marinho-da-califórnia", "Lontra-europeia", "Humano"], x: "A orca passa dos 50 km/h, o leão-marinho uns 40 e a lontra pouco mais de 10 km/h. Os melhores nadadores humanos chegam a quase 9 km/h.", k: "Orca: nada a mais de 50 km/h" }, ja: { q: "泳ぐのが速いのは？ 速い順に。", a: ["シャチ", "カリフォルニアアシカ", "ユーラシアカワウソ", "人間"], x: "シャチは時速50キロ以上、アシカは約40キロ、カワウソは10キロちょっと。トップスイマーの人間でも9キロ弱です。", k: "シャチ：時速50キロ以上で泳ぐ" }, it: { q: "Chi nuota più veloce? Il più veloce per primo.", a: ["Orca", "Leone marino della California", "Lontra europea", "Essere umano"], x: "Le orche superano i 50 km/h, i leoni marini circa 40, le lontre poco più di 10 km/h. I migliori nuotatori umani arrivano a poco meno di 9 km/h.", k: "Orca: nuota oltre 50 km/h" } } },
  { id: "r04", lvl: 1, type: "rank", right: 10123, t: { de: { q: "Wer ist am schwersten? Schwerstes zuerst.", a: ["Blauwal", "Afrikanischer Elefant", "Flusspferd", "Eisbär"], x: "Blauwal bis etwa 150 Tonnen, Elefantenbulle rund 6 Tonnen, Flusspferd 1,5 bis 3 Tonnen, Eisbär-Männchen 400 bis 700 kg.", k: "Blauwal: bis zu 150 Tonnen schwer" }, en: { q: "Who is heaviest? Heaviest first.", a: ["Blue whale", "African elephant", "Hippo", "Polar bear"], x: "Blue whale up to about 150 tonnes, bull elephant around 6 tonnes, hippo 1.5 to 3 tonnes, male polar bear 400 to 700 kg.", k: "Blue whale: up to 150 tonnes" }, fr: { q: "Qui est le plus lourd ? Le plus lourd d’abord.", a: ["Baleine bleue", "Éléphant d’Afrique", "Hippopotame", "Ours polaire"], x: "Baleine bleue jusqu’à environ 150 tonnes, éléphant mâle environ 6 tonnes, hippopotame 1,5 à 3 tonnes, ours polaire mâle 400 à 700 kg.", k: "Baleine bleue : jusqu’à 150 tonnes" }, es: { q: "¿Quién pesa más? El más pesado primero.", a: ["Ballena azul", "Elefante africano", "Hipopótamo", "Oso polar"], x: "Ballena azul hasta unas 150 toneladas, elefante macho unas 6 toneladas, hipopótamo de 1,5 a 3 toneladas, oso polar macho de 400 a 700 kg.", k: "Ballena azul: hasta 150 toneladas" }, pt: { q: "Quem pesa mais? O mais pesado primeiro.", a: ["Baleia-azul", "Elefante-africano", "Hipopótamo", "Urso-polar"], x: "Baleia-azul até umas 150 toneladas, elefante macho umas 6 toneladas, hipopótamo de 1,5 a 3 toneladas, urso-polar macho de 400 a 700 kg.", k: "Baleia-azul: até 150 toneladas" }, ja: { q: "重いのは？ 重い順に。", a: ["シロナガスクジラ", "アフリカゾウ", "カバ", "ホッキョクグマ"], x: "シロナガスクジラは約150トン、オスのゾウは約6トン、カバは1.5〜3トン、オスのホッキョクグマは400〜700キロ。", k: "シロナガスクジラ：最大150トン" }, it: { q: "Chi è più pesante? Il più pesante per primo.", a: ["Balenottera azzurra", "Elefante africano", "Ippopotamo", "Orso polare"], x: "Balenottera azzurra fino a circa 150 tonnellate, elefante maschio circa 6 tonnellate, ippopotamo 1,5–3 tonnellate, orso polare maschio 400–700 kg.", k: "Balenottera azzurra: fino a 150 tonnellate" } } },
  { id: "r05", lvl: 2, type: "rank", right: 10123, t: { de: { q: "Wer wird am ältesten? Ältestes zuerst.", a: ["Grönlandhai", "Riesenschildkröte", "Asiatischer Elefant", "Hund"], x: "Grönlandhai mehrere hundert Jahre, Riesenschildkröten weit über 100, Elefanten bis etwa 70, Hunde meist 10 bis 15 Jahre.", k: "Grönlandhai: lebt mehrere hundert Jahre" }, en: { q: "Who lives longest? Oldest first.", a: ["Greenland shark", "Giant tortoise", "Asian elephant", "Dog"], x: "Greenland shark several hundred years, giant tortoises well over 100, elephants up to about 70, dogs usually 10 to 15 years.", k: "Greenland shark: lives for centuries" }, fr: { q: "Qui vit le plus longtemps ? Le plus âgé d’abord.", a: ["Requin du Groenland", "Tortue géante", "Éléphant d’Asie", "Chien"], x: "Requin du Groenland plusieurs siècles, tortue géante bien plus de 100 ans, éléphant jusqu’à environ 70, chien en général 10 à 15 ans.", k: "Requin du Groenland : vit plusieurs siècles" }, es: { q: "¿Quién vive más años? El más longevo primero.", a: ["Tiburón de Groenlandia", "Tortuga gigante", "Elefante asiático", "Perro"], x: "Tiburón de Groenlandia varios siglos, tortuga gigante mucho más de 100 años, elefante hasta unos 70, perro normalmente de 10 a 15 años.", k: "Tiburón de Groenlandia: vive siglos" }, pt: { q: "Quem vive mais anos? O mais longevo primeiro.", a: ["Tubarão-da-groenlândia", "Tartaruga-gigante", "Elefante-asiático", "Cachorro"], x: "Tubarão-da-groenlândia vários séculos, tartaruga-gigante bem mais de 100 anos, elefante até uns 70, cachorro normalmente de 10 a 15 anos.", k: "Tubarão-da-groenlândia: vive séculos" }, ja: { q: "長生きなのは？ 長生きな順に。", a: ["ニシオンデンザメ", "ゾウガメ", "アジアゾウ", "イヌ"], x: "ニシオンデンザメは数百年、ゾウガメは100年をゆうに超え、ゾウは約70年まで、イヌはふつう10〜15年です。", k: "ニシオンデンザメ：数百年生きる" }, it: { q: "Chi vive più a lungo? Il più longevo per primo.", a: ["Squalo della Groenlandia", "Tartaruga gigante", "Elefante asiatico", "Cane"], x: "Squalo della Groenlandia diversi secoli, tartaruga gigante ben oltre 100 anni, elefante fino a circa 70, cane di solito 10–15 anni.", k: "Squalo della Groenlandia: vive secoli" } } },
  { id: "r06", lvl: 2, type: "rank", right: 10123, t: { de: { q: "Wer schläft am längsten pro Tag? Längster Schlaf zuerst.", a: ["Koala", "Hauskatze", "Mensch", "Giraffe"], x: "Koalas schlafen bis zu 20 Stunden, Katzen 12 bis 16, Erwachsene etwa 8 – und Giraffen oft weniger als 4 Stunden, in kurzen Häppchen.", k: "Koala: schläft bis zu 20 Stunden" }, en: { q: "Who sleeps longest each day? Longest sleep first.", a: ["Koala", "Pet cat", "Human", "Giraffe"], x: "Koalas sleep up to 20 hours, cats 12 to 16, adults about 8 – and giraffes often less than 4 hours, in short bits.", k: "Koala: sleeps up to 20 hours" }, fr: { q: "Qui dort le plus par jour ? Le plus gros dormeur d’abord.", a: ["Koala", "Chat domestique", "Humain", "Girafe"], x: "Le koala dort jusqu’à 20 heures, le chat 12 à 16, l’adulte environ 8 – et la girafe souvent moins de 4 heures, par petits morceaux.", k: "Koala : dort jusqu’à 20 heures" }, es: { q: "¿Quién duerme más al día? El más dormilón primero.", a: ["Koala", "Gato doméstico", "Humano", "Jirafa"], x: "El koala duerme hasta 20 horas, el gato de 12 a 16, un adulto unas 8, y la jirafa a menudo menos de 4 horas, a ratos.", k: "Koala: duerme hasta 20 horas" }, pt: { q: "Quem dorme mais por dia? O mais dorminhoco primeiro.", a: ["Coala", "Gato doméstico", "Humano", "Girafa"], x: "O coala dorme até 20 horas, o gato de 12 a 16, um adulto umas 8, e a girafa muitas vezes menos de 4 horas, aos pouquinhos.", k: "Coala: dorme até 20 horas" }, ja: { q: "1日によく眠るのは？ 長く眠る順に。", a: ["コアラ", "飼いネコ", "人間", "キリン"], x: "コアラは最大20時間、ネコは12〜16時間、大人の人間は約8時間。キリンは細切れで4時間未満のことも多いです。", k: "コアラ：最大20時間眠る" }, it: { q: "Chi dorme di più al giorno? Il più dormiglione per primo.", a: ["Koala", "Gatto domestico", "Essere umano", "Giraffa"], x: "Il koala dorme fino a 20 ore, il gatto 12–16, un adulto circa 8, e la giraffa spesso meno di 4 ore, a brevi riprese.", k: "Koala: dorme fino a 20 ore" } } },
  { id: "r07", lvl: 1, type: "rank", right: 10123, t: { de: { q: "Wer ist am höchsten (vom Boden bis zum Scheitel)? Höchstes zuerst.", a: ["Giraffe", "Afrikanischer Elefant", "Strauß", "Mensch"], x: "Giraffe bis 5,5 m, Elefant rund 4 m, Strauß bis etwa 2,7 m – der größte Vogel der Welt. Ein Mensch misst im Schnitt 1,70 m.", k: "Giraffe: bis 5,5 m hoch" }, en: { q: "Who is tallest (from the ground to the top of the head)? Tallest first.", a: ["Giraffe", "African elephant", "Ostrich", "Human"], x: "Giraffe up to 5.5 m, elephant around 4 m, ostrich up to about 2.7 m – the biggest bird in the world. A human averages 1.70 m.", k: "Giraffe: up to 5.5 m tall" }, fr: { q: "Qui est le plus haut (du sol au sommet de la tête) ? Le plus haut d’abord.", a: ["Girafe", "Éléphant d’Afrique", "Autruche", "Humain"], x: "Girafe jusqu’à 5,5 m, éléphant environ 4 m, autruche jusqu’à 2,7 m environ – le plus grand oiseau du monde. Un humain mesure en moyenne 1,70 m.", k: "Girafe : jusqu’à 5,5 m" }, es: { q: "¿Quién es más alto (del suelo a la coronilla)? El más alto primero.", a: ["Jirafa", "Elefante africano", "Avestruz", "Humano"], x: "Jirafa hasta 5,5 m, elefante unos 4 m, avestruz hasta unos 2,7 m (el ave más grande del mundo). Un humano mide de media 1,70 m.", k: "Jirafa: hasta 5,5 m" }, pt: { q: "Quem é mais alto (do chão ao topo da cabeça)? O mais alto primeiro.", a: ["Girafa", "Elefante-africano", "Avestruz", "Humano"], x: "Girafa até 5,5 m, elefante uns 4 m, avestruz até uns 2,7 m (a maior ave do mundo). Um humano mede em média 1,70 m.", k: "Girafa: até 5,5 m" }, ja: { q: "背が高いのは（地面から頭のてっぺんまで）？ 高い順に。", a: ["キリン", "アフリカゾウ", "ダチョウ", "人間"], x: "キリンは最大5.5メートル、ゾウは約4メートル、ダチョウは約2.7メートル（世界最大の鳥）。人間は平均1.7メートルです。", k: "キリン：高さ最大5.5メートル" }, it: { q: "Chi è più alto (da terra alla cima della testa)? Il più alto per primo.", a: ["Giraffa", "Elefante africano", "Struzzo", "Essere umano"], x: "Giraffa fino a 5,5 m, elefante circa 4 m, struzzo fino a circa 2,7 m, il più grande uccello del mondo. Una persona misura in media 1,70 m.", k: "Giraffa: fino a 5,5 m" } } },
  { id: "r08", lvl: 1, type: "rank", right: 10123, t: { de: { q: "Wessen Ei ist am schwersten? Schwerstes zuerst.", a: ["Strauß", "Emu", "Haushuhn", "Kolibri"], x: "Ein Straußenei wiegt rund 1,5 kg – so viel wie über 20 Hühnereier. Emu-Eier etwa 600 g, Hühnereier 60 g, Kolibri-Eier nur rund ein halbes Gramm.", k: "Straußenei: so schwer wie 20 Hühnereier" }, en: { q: "Whose egg is heaviest? Heaviest first.", a: ["Ostrich", "Emu", "Chicken", "Hummingbird"], x: "An ostrich egg weighs about 1.5 kg – as much as over 20 hen’s eggs. Emu eggs about 600 g, hen’s eggs 60 g, hummingbird eggs only about half a gram.", k: "Ostrich egg: as heavy as 20 hen's eggs" }, fr: { q: "Quel œuf est le plus lourd ? Le plus lourd d’abord.", a: ["Autruche", "Émeu", "Poule", "Colibri"], x: "Un œuf d’autruche pèse environ 1,5 kg – autant que plus de 20 œufs de poule. Œuf d’émeu environ 600 g, de poule 60 g, de colibri un demi-gramme à peine.", k: "Œuf d’autruche : pèse comme 20 œufs de poule" }, es: { q: "¿De quién es el huevo más pesado? El más pesado primero.", a: ["Avestruz", "Emú", "Gallina", "Colibrí"], x: "Un huevo de avestruz pesa unos 1,5 kg, tanto como más de 20 huevos de gallina. El de emú unos 600 g, el de gallina 60 g y el de colibrí apenas medio gramo.", k: "Huevo de avestruz: pesa como 20 de gallina" }, pt: { q: "De quem é o ovo mais pesado? O mais pesado primeiro.", a: ["Avestruz", "Emu", "Galinha", "Beija-flor"], x: "Um ovo de avestruz pesa uns 1,5 kg – tanto quanto mais de 20 ovos de galinha. O de emu uns 600 g, o de galinha 60 g e o de beija-flor só meio grama.", k: "Ovo de avestruz: pesa como 20 de galinha" }, ja: { q: "卵が重いのは？ 重い順に。", a: ["ダチョウ", "エミュー", "ニワトリ", "ハチドリ"], x: "ダチョウの卵は約1.5キロ。ニワトリの卵20個以上分です。エミューは約600グラム、ニワトリは60グラム、ハチドリはたった約0.5グラム。", k: "ダチョウの卵：ニワトリの卵20個分" }, it: { q: "Di chi è l’uovo più pesante? Il più pesante per primo.", a: ["Struzzo", "Emù", "Gallina", "Colibrì"], x: "Un uovo di struzzo pesa circa 1,5 kg, quanto oltre 20 uova di gallina. Uovo di emù circa 600 g, di gallina 60 g, di colibrì solo mezzo grammo.", k: "Uovo di struzzo: pesa come 20 di gallina" } } },
  { id: "r09", lvl: 1, type: "rank", right: 10123, t: { de: { q: "Wer hat die meisten Beine? Die meisten zuerst.", a: ["Tausendfüßer", "Krabbe", "Kreuzspinne", "Maikäfer"], x: "Tausendfüßer haben je nach Art Dutzende bis Hunderte Beine (nie ganz 1000 – bis auf eine Art mit über 1300). Krabben haben 10, Spinnen 8, Käfer 6.", k: "Tausendfüßer: manche haben über 1.300 Beine" }, en: { q: "Who has the most legs? Most first.", a: ["Millipede", "Crab", "Garden spider", "Cockchafer"], x: "Depending on the species, millipedes have dozens to hundreds of legs (one species has over 1,300). Crabs have 10, spiders 8, beetles 6.", k: "Millipedes: some have over 1,300 legs" }, fr: { q: "Qui a le plus de pattes ? Le plus d’abord.", a: ["Mille-pattes", "Crabe", "Épeire diadème", "Hanneton"], x: "Selon l’espèce, le mille-pattes a des dizaines à des centaines de pattes (une espèce en a plus de 1300). Le crabe en a 10, l’araignée 8, le coléoptère 6.", k: "Mille-pattes : certains ont plus de 1 300 pattes" }, es: { q: "¿Quién tiene más patas? El que más primero.", a: ["Milpiés", "Cangrejo", "Araña de jardín", "Abejorro sanjuanero"], x: "Según la especie, el milpiés tiene de decenas a cientos de patas (una especie tiene más de 1.300). El cangrejo tiene 10, la araña 8 y el escarabajo 6.", k: "Milpiés: algunos tienen más de 1.300 patas" }, pt: { q: "Quem tem mais patas? Quem tem mais primeiro.", a: ["Piolho-de-cobra", "Caranguejo", "Aranha-de-jardim", "Besouro-de-junho"], x: "Conforme a espécie, o piolho-de-cobra tem de dezenas a centenas de patas (uma espécie tem mais de 1.300). O caranguejo tem 10, a aranha 8 e o besouro 6.", k: "Piolhos-de-cobra: alguns têm mais de 1.300 patas" }, ja: { q: "脚が多いのは？ 多い順に。", a: ["ヤスデ", "カニ", "オニグモ", "コフキコガネ"], x: "ヤスデは種類によって数十本から数百本（1300本以上の種も）。カニは10本、クモは8本、甲虫は6本です。", k: "ヤスデ：1300本以上の脚をもつ種も" }, it: { q: "Chi ha più zampe? Chi ne ha di più per primo.", a: ["Millepiedi", "Granchio", "Ragno crociato", "Maggiolino"], x: "A seconda della specie, i millepiedi hanno da decine a centinaia di zampe (una specie oltre 1.300). Il granchio ne ha 10, il ragno 8, il coleottero 6.", k: "Millepiedi: alcuni hanno oltre 1.300 zampe" } } },
  { id: "r10", lvl: 2, type: "rank", right: 10123, t: { de: { q: "Wer ist am längsten schwanger? Längste Tragzeit zuerst.", a: ["Afrikanischer Elefant", "Giraffe", "Mensch", "Hund"], x: "Elefanten tragen ihr Junges rund 22 Monate, Giraffen etwa 15, Menschen 9 – und Hunde nur gut 2 Monate.", k: "Elefant: 22 Monate trächtig" }, en: { q: "Who is pregnant the longest? Longest pregnancy first.", a: ["African elephant", "Giraffe", "Human", "Dog"], x: "Elephants carry their baby for about 22 months, giraffes about 15, humans 9 – and dogs only just over 2 months.", k: "Elephant: pregnant for 22 months" }, fr: { q: "Qui porte son petit le plus longtemps ? La plus longue gestation d’abord.", a: ["Éléphant d’Afrique", "Girafe", "Humain", "Chien"], x: "L’éléphante porte son petit environ 22 mois, la girafe environ 15, l’humain 9 – et la chienne à peine plus de 2 mois.", k: "Éléphant : 22 mois de gestation" }, es: { q: "¿Quién tiene el embarazo más largo? El más largo primero.", a: ["Elefante africano", "Jirafa", "Humano", "Perro"], x: "La elefanta lleva a su cría unos 22 meses, la jirafa unos 15, el humano 9 y la perra solo algo más de 2 meses.", k: "Elefanta: 22 meses de gestación" }, pt: { q: "Quem tem a gestação mais longa? A mais longa primeiro.", a: ["Elefante-africano", "Girafa", "Humano", "Cachorro"], x: "A elefanta carrega o filhote por uns 22 meses, a girafa uns 15, o humano 9 e a cadela pouco mais de 2 meses.", k: "Elefanta: 22 meses de gestação" }, ja: { q: "妊娠期間が長いのは？ 長い順に。", a: ["アフリカゾウ", "キリン", "人間", "イヌ"], x: "ゾウは約22か月、キリンは約15か月、人間は9か月、イヌはたった2か月ちょっとです。", k: "ゾウ：妊娠22か月" }, it: { q: "Chi ha la gravidanza più lunga? La più lunga per prima.", a: ["Elefante africano", "Giraffa", "Essere umano", "Cane"], x: "L’elefantessa porta il piccolo per circa 22 mesi, la giraffa circa 15, l’essere umano 9, e la cagna solo poco più di 2 mesi.", k: "Elefantessa: 22 mesi di gravidanza" } } },
  { id: "r11", lvl: 2, type: "rank", right: 10123, t: { de: { q: "Wessen Herz schlägt am schnellsten? Schnellstes zuerst.", a: ["Etruskerspitzmaus", "Hausmaus", "Mensch", "Blauwal"], x: "Die winzige Etruskerspitzmaus kommt auf über 1000 Schläge pro Minute, eine Maus auf 500 bis 600, ein Mensch auf etwa 70 – ein Blauwal beim Tauchen nur auf 2 bis 10.", k: "Etruskerspitzmaus: Herz schlägt 1.000-mal pro Minute" }, en: { q: "Whose heart beats fastest? Fastest first.", a: ["Etruscan shrew", "House mouse", "Human", "Blue whale"], x: "The tiny Etruscan shrew reaches over 1,000 beats a minute, a mouse 500 to 600, a human about 70 – a diving blue whale only 2 to 10.", k: "Etruscan shrew: heart beats 1,000 times a minute" }, fr: { q: "Quel cœur bat le plus vite ? Le plus rapide d’abord.", a: ["Pachyure étrusque", "Souris domestique", "Humain", "Baleine bleue"], x: "La minuscule pachyure étrusque dépasse 1000 battements par minute, la souris 500 à 600, l’humain environ 70 – la baleine bleue en plongée seulement 2 à 10.", k: "Pachyure étrusque : cœur à 1 000 battements/min" }, es: { q: "¿Qué corazón late más rápido? El más rápido primero.", a: ["Musgaño enano", "Ratón doméstico", "Humano", "Ballena azul"], x: "El diminuto musgaño enano supera los 1.000 latidos por minuto, el ratón de 500 a 600, el humano unos 70 y la ballena azul al bucear solo de 2 a 10.", k: "Musgaño enano: corazón a 1.000 latidos/min" }, pt: { q: "Qual coração bate mais rápido? O mais rápido primeiro.", a: ["Musaranho-pigmeu", "Camundongo", "Humano", "Baleia-azul"], x: "O minúsculo musaranho-pigmeu passa de 1.000 batidas por minuto, o camundongo de 500 a 600, o humano umas 70 e a baleia-azul, mergulhando, só de 2 a 10.", k: "Musaranho-pigmeu: coração a 1.000 batidas/min" }, ja: { q: "心臓が速く打つのは？ 速い順に。", a: ["コビトジャコウネズミ", "ハツカネズミ", "人間", "シロナガスクジラ"], x: "小さなコビトジャコウネズミは1分に1000回以上、ネズミは500〜600回、人間は約70回。潜っているシロナガスクジラはたった2〜10回です。", k: "コビトジャコウネズミ：心臓は1分に1000回" }, it: { q: "Il cuore di chi batte più veloce? Il più veloce per primo.", a: ["Mustiolo etrusco", "Topo domestico", "Essere umano", "Balenottera azzurra"], x: "Il minuscolo mustiolo supera i 1.000 battiti al minuto, il topo 500–600, l’essere umano circa 70, la balenottera azzurra in immersione solo 2–10.", k: "Mustiolo: cuore a 1.000 battiti al minuto" } } },
  { id: "r12", lvl: 2, type: "rank", right: 10123, t: { de: { q: "Wessen Baby ist bei der Geburt am schwersten? Schwerstes zuerst.", a: ["Blauwal", "Afrikanischer Elefant", "Mensch", "Großer Panda"], x: "Ein Blauwalkalb wiegt rund 2,5 Tonnen, ein Elefantenbaby etwa 100 kg, ein Menschenbaby 3,5 kg – ein Pandababy nur rund 100 Gramm.", k: "Blauwal-Baby: wiegt 2,5 Tonnen" }, en: { q: "Whose baby is heaviest at birth? Heaviest first.", a: ["Blue whale", "African elephant", "Human", "Giant panda"], x: "A blue whale calf weighs about 2.5 tonnes, a baby elephant about 100 kg, a human baby 3.5 kg – a panda cub only around 100 grams.", k: "Blue whale calf: weighs 2.5 tonnes" }, fr: { q: "Quel bébé est le plus lourd à la naissance ? Le plus lourd d’abord.", a: ["Baleine bleue", "Éléphant d’Afrique", "Humain", "Panda géant"], x: "Un baleineau bleu pèse environ 2,5 tonnes, un éléphanteau environ 100 kg, un bébé humain 3,5 kg – un bébé panda à peine 100 grammes.", k: "Baleineau bleu : pèse 2,5 tonnes" }, es: { q: "¿Qué cría pesa más al nacer? La más pesada primero.", a: ["Ballena azul", "Elefante africano", "Humano", "Panda gigante"], x: "Una cría de ballena azul pesa unas 2,5 toneladas, la de elefante unos 100 kg, un bebé humano 3,5 kg y una cría de panda solo unos 100 gramos.", k: "Cría de ballena azul: 2,5 toneladas" }, pt: { q: "Qual filhote pesa mais ao nascer? O mais pesado primeiro.", a: ["Baleia-azul", "Elefante-africano", "Humano", "Panda-gigante"], x: "Um filhote de baleia-azul pesa umas 2,5 toneladas, o de elefante uns 100 kg, um bebê humano 3,5 kg e um filhote de panda só uns 100 gramas.", k: "Filhote de baleia-azul: 2,5 toneladas" }, ja: { q: "生まれたときの赤ちゃんが重いのは？ 重い順に。", a: ["シロナガスクジラ", "アフリカゾウ", "人間", "ジャイアントパンダ"], x: "シロナガスクジラの赤ちゃんは約2.5トン、ゾウは約100キロ、人間は3.5キロ。パンダの赤ちゃんはたった約100グラムです。", k: "シロナガスクジラの赤ちゃん：2.5トン" }, it: { q: "Di chi è il piccolo più pesante alla nascita? Il più pesante per primo.", a: ["Balenottera azzurra", "Elefante africano", "Essere umano", "Panda gigante"], x: "Un piccolo di balenottera azzurra pesa circa 2,5 tonnellate, un elefantino circa 100 kg, un neonato 3,5 kg, e un cucciolo di panda solo circa 100 grammi.", k: "Piccolo di balenottera azzurra: 2,5 tonnellate" } } },
  { id: "r13", lvl: 3, type: "rank", right: 10123, t: { de: { q: "Wer fliegt am höchsten? Höchstes zuerst.", a: ["Sperbergeier", "Streifengans", "Weißstorch", "Amsel"], x: "Ein Sperbergeier stieß 1973 in über 11.000 m Höhe mit einem Flugzeug zusammen. Streifengänse überqueren den Himalaya in 7.000 bis 8.000 m. Störche ziehen meist in einigen hundert bis tausend Metern, Amseln bleiben nah am Boden.", k: "Sperbergeier: flog über 11.000 m hoch" }, en: { q: "Who flies highest? Highest first.", a: ["Rüppell’s vulture", "Bar-headed goose", "White stork", "Blackbird"], x: "In 1973 a Rüppell’s vulture collided with a plane at over 11,000 m. Bar-headed geese cross the Himalayas at 7,000 to 8,000 m. Storks usually migrate at a few hundred to a thousand metres; blackbirds stay close to the ground.", k: "Rüppell's vulture: flew over 11,000 m high" }, fr: { q: "Qui vole le plus haut ? Le plus haut d’abord.", a: ["Vautour de Rüppell", "Oie à tête barrée", "Cigogne blanche", "Merle noir"], x: "En 1973, un vautour de Rüppell a percuté un avion à plus de 11 000 m. L’oie à tête barrée franchit l’Himalaya à 7 000–8 000 m. La cigogne migre en général à quelques centaines ou milliers de mètres, le merle reste près du sol.", k: "Vautour de Rüppell : vol à plus de 11 000 m" }, es: { q: "¿Quién vuela más alto? El más alto primero.", a: ["Buitre moteado", "Ánsar indio", "Cigüeña blanca", "Mirlo"], x: "En 1973 un buitre moteado chocó con un avión a más de 11.000 m. El ánsar indio cruza el Himalaya a 7.000-8.000 m. La cigüeña migra normalmente a unos cientos o mil metros; el mirlo se queda cerca del suelo.", k: "Buitre de Rüppell: voló a más de 11.000 m" }, pt: { q: "Quem voa mais alto? O mais alto primeiro.", a: ["Abutre-de-rüppell", "Ganso-de-cabeça-listrada", "Cegonha-branca", "Melro"], x: "Em 1973, um abutre-de-rüppell bateu num avião a mais de 11.000 m. O ganso-de-cabeça-listrada cruza o Himalaia a 7.000–8.000 m. A cegonha migra normalmente a algumas centenas ou mil metros; o melro fica perto do chão.", k: "Abutre-de-rüppell: voou a mais de 11.000 m" }, ja: { q: "高く飛ぶのは？ 高い順に。", a: ["マダラハゲワシ", "インドガン", "シュバシコウ", "クロウタドリ"], x: "1973年、マダラハゲワシが高度1万1000メートル以上で飛行機にぶつかりました。インドガンは7000〜8000メートルでヒマラヤを越えます。コウノトリはふつう数百〜1000メートルで渡り、クロウタドリは地面の近くにいます。", k: "マダラハゲワシ：高度1万1000メートル以上" }, it: { q: "Chi vola più in alto? Il più alto per primo.", a: ["Grifone di Rüppell", "Oca indiana", "Cicogna bianca", "Merlo"], x: "Nel 1973 un grifone di Rüppell si scontrò con un aereo a oltre 11.000 m. L’oca indiana attraversa l’Himalaya a 7.000–8.000 m. La cicogna migra di solito a poche centinaia fino a mille metri; il merlo resta vicino al suolo.", k: "Grifone di Rüppell: volò oltre 11.000 m" } } },
  { id: "r14", lvl: 3, type: "rank", right: 10123, t: { de: { q: "Wer taucht am tiefsten? Tiefstes zuerst.", a: ["Cuvier-Schnabelwal", "Pottwal", "Kaiserpinguin", "Mensch (ohne Gerät)"], x: "Cuvier-Schnabelwale tauchen fast 3.000 m tief, Pottwale über 2.000 m, Kaiserpinguine über 500 m. Freitaucher schaffen gut 100 m.", k: "Cuvier-Schnabelwal: taucht fast 3.000 m tief" }, en: { q: "Who dives deepest? Deepest first.", a: ["Cuvier’s beaked whale", "Sperm whale", "Emperor penguin", "Human (no equipment)"], x: "Cuvier’s beaked whales dive almost 3,000 m deep, sperm whales over 2,000 m, emperor penguins over 500 m. Free divers manage just over 100 m.", k: "Cuvier's beaked whale: dives almost 3,000 m" }, fr: { q: "Qui plonge le plus profond ? Le plus profond d’abord.", a: ["Baleine de Cuvier", "Cachalot", "Manchot empereur", "Humain (sans matériel)"], x: "La baleine de Cuvier plonge à près de 3 000 m, le cachalot à plus de 2 000 m, le manchot empereur à plus de 500 m. Les apnéistes dépassent à peine 100 m.", k: "Baleine de Cuvier : plonge à près de 3 000 m" }, es: { q: "¿Quién bucea más hondo? El más profundo primero.", a: ["Zifio de Cuvier", "Cachalote", "Pingüino emperador", "Humano (sin equipo)"], x: "El zifio de Cuvier baja a casi 3.000 m, el cachalote a más de 2.000 m, el pingüino emperador a más de 500 m. Los apneístas pasan por poco de 100 m.", k: "Zifio de Cuvier: bucea casi a 3.000 m" }, pt: { q: "Quem mergulha mais fundo? O mais fundo primeiro.", a: ["Baleia-bicuda-de-cuvier", "Cachalote", "Pinguim-imperador", "Humano (sem equipamento)"], x: "A baleia-bicuda-de-cuvier desce a quase 3.000 m, o cachalote a mais de 2.000 m, o pinguim-imperador a mais de 500 m. Os mergulhadores livres passam por pouco dos 100 m.", k: "Baleia-bicuda-de-cuvier: mergulha quase 3.000 m" }, ja: { q: "深く潜るのは？ 深い順に。", a: ["アカボウクジラ", "マッコウクジラ", "コウテイペンギン", "人間（道具なし）"], x: "アカボウクジラは3000メートル近く、マッコウクジラは2000メートル以上、コウテイペンギンは500メートル以上。素潜りの人間は100メートルちょっとです。", k: "アカボウクジラ：深さ3000メートル近く潜る" }, it: { q: "Chi si immerge più a fondo? Il più profondo per primo.", a: ["Zifio", "Capodoglio", "Pinguino imperatore", "Essere umano (senza attrezzatura)"], x: "Lo zifio scende a quasi 3.000 m, il capodoglio a oltre 2.000 m, il pinguino imperatore a oltre 500 m. Gli apneisti superano di poco i 100 m.", k: "Zifio: si immerge a quasi 3.000 m" } } },
  { id: "r15", lvl: 2, type: "rank", right: 10123, t: { de: { q: "Wer hat die meisten Zähne? Die meisten zuerst.", a: ["Großer Tümmler", "Hund", "Mensch", "Großer Ameisenbär"], x: "Große Tümmler haben 80 bis 100 Zähne, Hunde 42, erwachsene Menschen 32. Der Ameisenbär hat gar keine – er schleckt Ameisen mit seiner langen Zunge auf.", k: "Großer Tümmler: bis zu 100 Zähne" }, en: { q: "Who has the most teeth? Most first.", a: ["Bottlenose dolphin", "Dog", "Human", "Giant anteater"], x: "Bottlenose dolphins have 80 to 100 teeth, dogs 42, adult humans 32. The anteater has none at all – it licks up ants with its long tongue.", k: "Bottlenose dolphin: up to 100 teeth" }, fr: { q: "Qui a le plus de dents ? Le plus d’abord.", a: ["Grand dauphin", "Chien", "Humain", "Grand fourmilier"], x: "Le grand dauphin a 80 à 100 dents, le chien 42, l’humain adulte 32. Le fourmilier n’en a aucune – il lape les fourmis avec sa longue langue.", k: "Grand dauphin : jusqu’à 100 dents" }, es: { q: "¿Quién tiene más dientes? El que más primero.", a: ["Delfín mular", "Perro", "Humano", "Oso hormiguero gigante"], x: "El delfín mular tiene de 80 a 100 dientes, el perro 42 y el humano adulto 32. El oso hormiguero no tiene ninguno: atrapa las hormigas con su larga lengua.", k: "Delfín mular: hasta 100 dientes" }, pt: { q: "Quem tem mais dentes? Quem tem mais primeiro.", a: ["Golfinho-nariz-de-garrafa", "Cachorro", "Humano", "Tamanduá-bandeira"], x: "O golfinho-nariz-de-garrafa tem de 80 a 100 dentes, o cachorro 42 e o humano adulto 32. O tamanduá não tem nenhum: pega as formigas com a língua comprida.", k: "Golfinho-nariz-de-garrafa: até 100 dentes" }, ja: { q: "歯が多いのは？ 多い順に。", a: ["ハンドウイルカ", "イヌ", "人間", "オオアリクイ"], x: "ハンドウイルカは80〜100本、イヌは42本、大人の人間は32本。オオアリクイは0本。長い舌でアリをなめとります。", k: "ハンドウイルカ：歯は最大100本" }, it: { q: "Chi ha più denti? Chi ne ha di più per primo.", a: ["Tursiope", "Cane", "Essere umano", "Formichiere gigante"], x: "Il tursiope ha 80–100 denti, il cane 42, l’essere umano adulto 32. Il formichiere non ne ha nessuno: lecca le formiche con la lunga lingua.", k: "Tursiope: fino a 100 denti" } } },
  { id: "r16", lvl: 3, type: "rank", right: 10123, t: { de: { q: "Wer beißt am stärksten zu? Stärkstes zuerst.", a: ["Leistenkrokodil", "Flusspferd", "Löwe", "Mensch"], x: "Das Leistenkrokodil hat den stärksten je gemessenen Biss, etwa doppelt so stark wie ein Flusspferd. Ein Löwe beißt deutlich schwächer, ein Mensch nur mit einem Bruchteil davon.", k: "Leistenkrokodil: stärkster Biss der Welt" }, en: { q: "Who has the strongest bite? Strongest first.", a: ["Saltwater crocodile", "Hippo", "Lion", "Human"], x: "The saltwater crocodile has the strongest bite ever measured, about twice as strong as a hippo’s. A lion bites much more weakly, a human with just a fraction of that.", k: "Saltwater crocodile: strongest bite on Earth" }, fr: { q: "Qui a la morsure la plus puissante ? La plus forte d’abord.", a: ["Crocodile marin", "Hippopotame", "Lion", "Humain"], x: "Le crocodile marin a la morsure la plus forte jamais mesurée, environ deux fois celle de l’hippopotame. Le lion mord bien moins fort, l’humain avec une fraction seulement.", k: "Crocodile marin : morsure la plus forte" }, es: { q: "¿Quién muerde con más fuerza? El más fuerte primero.", a: ["Cocodrilo marino", "Hipopótamo", "León", "Humano"], x: "El cocodrilo marino tiene la mordida más fuerte jamás medida, unas dos veces la del hipopótamo. El león muerde mucho más flojo y el humano con solo una fracción.", k: "Cocodrilo marino: la mordida más fuerte" }, pt: { q: "Quem morde mais forte? O mais forte primeiro.", a: ["Crocodilo-de-água-salgada", "Hipopótamo", "Leão", "Humano"], x: "O crocodilo-de-água-salgada tem a mordida mais forte já medida, umas duas vezes a do hipopótamo. O leão morde bem mais fraco, e o humano com só uma fração disso.", k: "Crocodilo-de-água-salgada: a mordida mais forte" }, ja: { q: "かむ力が強いのは？ 強い順に。", a: ["イリエワニ", "カバ", "ライオン", "人間"], x: "イリエワニのかむ力はこれまで測った中で最強で、カバの約2倍。ライオンはずっと弱く、人間はそのほんの一部です。", k: "イリエワニ：最強のかむ力" }, it: { q: "Chi morde più forte? Il più forte per primo.", a: ["Coccodrillo marino", "Ippopotamo", "Leone", "Essere umano"], x: "Il coccodrillo marino ha il morso più forte mai misurato, circa il doppio di quello dell’ippopotamo. Il leone morde molto più debole, l’essere umano con una piccola frazione.", k: "Coccodrillo marino: il morso più forte" } } },
  { id: "r17", lvl: 2, type: "rank", right: 10123, t: { de: { q: "Wer hat die größte Flügelspannweite? Größte zuerst.", a: ["Wanderalbatros", "Andenkondor", "Weißstorch", "Amsel"], x: "Wanderalbatrosse messen bis 3,5 m von Flügelspitze zu Flügelspitze, Andenkondore gut 3 m, Störche etwa 2 m, Amseln knapp 40 cm.", k: "Wanderalbatros: Flügel bis 3,5 m" }, en: { q: "Who has the largest wingspan? Largest first.", a: ["Wandering albatross", "Andean condor", "White stork", "Blackbird"], x: "Wandering albatrosses measure up to 3.5 m from wingtip to wingtip, Andean condors just over 3 m, storks about 2 m, blackbirds just under 40 cm.", k: "Wandering albatross: wings up to 3.5 m" }, fr: { q: "Qui a la plus grande envergure ? La plus grande d’abord.", a: ["Albatros hurleur", "Condor des Andes", "Cigogne blanche", "Merle noir"], x: "L’albatros hurleur mesure jusqu’à 3,5 m d’une pointe d’aile à l’autre, le condor un peu plus de 3 m, la cigogne environ 2 m, le merle à peine 40 cm.", k: "Albatros hurleur : ailes jusqu’à 3,5 m" }, es: { q: "¿Quién tiene mayor envergadura? La mayor primero.", a: ["Albatros viajero", "Cóndor andino", "Cigüeña blanca", "Mirlo"], x: "El albatros viajero mide hasta 3,5 m de punta a punta de ala, el cóndor andino algo más de 3 m, la cigüeña unos 2 m y el mirlo poco menos de 40 cm.", k: "Albatros viajero: alas de hasta 3,5 m" }, pt: { q: "Quem tem a maior envergadura? A maior primeiro.", a: ["Albatroz-errante", "Condor-dos-andes", "Cegonha-branca", "Melro"], x: "O albatroz-errante mede até 3,5 m de ponta a ponta das asas, o condor-dos-andes pouco mais de 3 m, a cegonha uns 2 m e o melro pouco menos de 40 cm.", k: "Albatroz-errante: asas de até 3,5 m" }, ja: { q: "翼を広げた長さが大きいのは？ 大きい順に。", a: ["ワタリアホウドリ", "アンデスコンドル", "シュバシコウ", "クロウタドリ"], x: "ワタリアホウドリは翼の端から端まで最大3.5メートル、アンデスコンドルは3メートルちょっと、コウノトリは約2メートル、クロウタドリは40センチ弱です。", k: "ワタリアホウドリ：翼を広げて最大3.5メートル" }, it: { q: "Chi ha l’apertura alare più grande? La più grande per prima.", a: ["Albatro urlatore", "Condor delle Ande", "Cicogna bianca", "Merlo"], x: "L’albatro urlatore misura fino a 3,5 m da un’ala all’altra, il condor poco più di 3 m, la cicogna circa 2 m, il merlo poco meno di 40 cm.", k: "Albatro urlatore: ali fino a 3,5 m" } } },
  { id: "r18", lvl: 1, type: "rank", right: 10123, t: { de: { q: "Wer ist am längsten? Längstes zuerst.", a: ["Blauwal", "Walhai", "Weißer Hai", "Großer Tümmler"], x: "Blauwale werden bis 30 m lang, Walhaie – die größten Fische – über 12 m, Weiße Haie bis etwa 6 m, Große Tümmler 2 bis 4 m.", k: "Blauwal: bis 30 m lang" }, en: { q: "Who is longest? Longest first.", a: ["Blue whale", "Whale shark", "Great white shark", "Bottlenose dolphin"], x: "Blue whales grow up to 30 m long, whale sharks – the biggest fish – over 12 m, great whites up to about 6 m, bottlenose dolphins 2 to 4 m.", k: "Blue whale: up to 30 m long" }, fr: { q: "Qui est le plus long ? Le plus long d’abord.", a: ["Baleine bleue", "Requin-baleine", "Grand requin blanc", "Grand dauphin"], x: "La baleine bleue atteint 30 m, le requin-baleine – le plus grand poisson – plus de 12 m, le grand requin blanc environ 6 m, le grand dauphin 2 à 4 m.", k: "Baleine bleue : jusqu’à 30 m" }, es: { q: "¿Quién es más largo? El más largo primero.", a: ["Ballena azul", "Tiburón ballena", "Tiburón blanco", "Delfín mular"], x: "La ballena azul llega a 30 m, el tiburón ballena (el pez más grande) a más de 12 m, el tiburón blanco a unos 6 m y el delfín mular a 2-4 m.", k: "Ballena azul: hasta 30 m" }, pt: { q: "Quem é mais comprido? O mais comprido primeiro.", a: ["Baleia-azul", "Tubarão-baleia", "Tubarão-branco", "Golfinho-nariz-de-garrafa"], x: "A baleia-azul chega a 30 m, o tubarão-baleia (o maior peixe) a mais de 12 m, o tubarão-branco a uns 6 m e o golfinho a 2–4 m.", k: "Baleia-azul: até 30 m" }, ja: { q: "体が長いのは？ 長い順に。", a: ["シロナガスクジラ", "ジンベエザメ", "ホホジロザメ", "ハンドウイルカ"], x: "シロナガスクジラは最大30メートル、ジンベエザメ（最大の魚）は12メートル以上、ホホジロザメは約6メートル、ハンドウイルカは2〜4メートル。", k: "シロナガスクジラ：最大30メートル" }, it: { q: "Chi è più lungo? Il più lungo per primo.", a: ["Balenottera azzurra", "Squalo balena", "Squalo bianco", "Tursiope"], x: "La balenottera azzurra arriva a 30 m, lo squalo balena (il pesce più grande) a oltre 12 m, lo squalo bianco a circa 6 m, il tursiope a 2–4 m.", k: "Balenottera azzurra: fino a 30 m" } } },
  { id: "r19", lvl: 1, type: "rank", right: 10123, t: { de: { q: "Wer ist am LANGSAMSTEN unterwegs? Langsamstes zuerst.", a: ["Gartenschnecke", "Dreifingerfaultier", "Spazierender Mensch", "Galoppierendes Pferd"], x: "Eine Schnecke schafft nur ein paar Meter pro Stunde, ein Faultier etwa 200 bis 250 m. Ein Mensch spaziert mit rund 5 km/h, ein Pferd galoppiert mit über 40 km/h.", k: "Schnecke: schafft nur wenige Meter pro Stunde" }, en: { q: "Who moves the SLOWEST? Slowest first.", a: ["Garden snail", "Three-toed sloth", "Walking human", "Galloping horse"], x: "A snail manages only a few metres an hour, a sloth about 200 to 250 m. A human walks at about 5 km/h, a horse gallops at over 40 km/h.", k: "Snail: only a few metres an hour" }, fr: { q: "Qui avance le plus LENTEMENT ? Le plus lent d’abord.", a: ["Escargot des jardins", "Paresseux à trois doigts", "Humain qui se promène", "Cheval au galop"], x: "L’escargot ne fait que quelques mètres par heure, le paresseux environ 200 à 250 m. L’humain marche à environ 5 km/h, le cheval galope à plus de 40 km/h.", k: "Escargot : quelques mètres à l’heure" }, es: { q: "¿Quién va más LENTO? El más lento primero.", a: ["Caracol de jardín", "Perezoso de tres dedos", "Humano paseando", "Caballo al galope"], x: "Un caracol solo avanza unos metros por hora, un perezoso unos 200-250 m. Un humano pasea a unos 5 km/h y un caballo galopa a más de 40 km/h.", k: "Caracol: solo unos metros por hora" }, pt: { q: "Quem é mais LENTO? O mais lento primeiro.", a: ["Caracol-de-jardim", "Preguiça-de-três-dedos", "Humano passeando", "Cavalo a galope"], x: "Um caracol avança só alguns metros por hora, uma preguiça uns 200–250 m. Um humano passeia a uns 5 km/h e um cavalo galopa a mais de 40 km/h.", k: "Caracol: só alguns metros por hora" }, ja: { q: "いちばん「おそい」のは？ おそい順に。", a: ["カタツムリ", "ミユビナマケモノ", "散歩中の人間", "ギャロップする馬"], x: "カタツムリは1時間に数メートル、ナマケモノは約200〜250メートル。人間は時速約5キロで歩き、ウマは時速40キロ以上でかけます。", k: "カタツムリ：1時間に数メートル" }, it: { q: "Chi è il più LENTO? Il più lento per primo.", a: ["Chiocciola", "Bradipo tridattilo", "Persona a passeggio", "Cavallo al galoppo"], x: "Una chiocciola fa solo pochi metri all’ora, un bradipo circa 200–250 m. Una persona cammina a circa 5 km/h, un cavallo galoppa a oltre 40 km/h.", k: "Chiocciola: pochi metri all’ora" } } },
  { id: "r20", lvl: 3, type: "rank", right: 10123, t: { de: { q: "Wer hört die höchsten Töne? Höchste zuerst.", a: ["Fledermaus", "Delfin", "Hund", "Mensch"], x: "Manche Fledermäuse hören über 200.000 Schwingungen pro Sekunde (200 kHz), Delfine bis etwa 150 kHz, Hunde rund 45 kHz. Menschen hören höchstens bis 20 kHz – im Alter weniger.", k: "Fledermäuse: hören bis 200 kHz" }, en: { q: "Who hears the highest sounds? Highest first.", a: ["Bat", "Dolphin", "Dog", "Human"], x: "Some bats hear over 200,000 vibrations a second (200 kHz), dolphins up to about 150 kHz, dogs around 45 kHz. Humans hear up to 20 kHz at most – less with age.", k: "Bats: hear up to 200 kHz" }, fr: { q: "Qui entend les sons les plus aigus ? Le plus aigu d’abord.", a: ["Chauve-souris", "Dauphin", "Chien", "Humain"], x: "Certaines chauves-souris entendent plus de 200 000 vibrations par seconde (200 kHz), le dauphin jusqu’à environ 150 kHz, le chien environ 45 kHz. L’humain entend au mieux jusqu’à 20 kHz – moins avec l’âge.", k: "Chauves-souris : entendent jusqu’à 200 kHz" }, es: { q: "¿Quién oye los sonidos más agudos? El más agudo primero.", a: ["Murciélago", "Delfín", "Perro", "Humano"], x: "Algunos murciélagos oyen más de 200.000 vibraciones por segundo (200 kHz), el delfín hasta unos 150 kHz, el perro unos 45 kHz. El humano oye como mucho hasta 20 kHz, y menos con la edad.", k: "Murciélagos: oyen hasta 200 kHz" }, pt: { q: "Quem ouve os sons mais agudos? O mais agudo primeiro.", a: ["Morcego", "Golfinho", "Cachorro", "Humano"], x: "Alguns morcegos ouvem mais de 200.000 vibrações por segundo (200 kHz), o golfinho até uns 150 kHz, o cachorro uns 45 kHz. O humano ouve no máximo até 20 kHz – e menos com a idade.", k: "Morcegos: ouvem até 200 kHz" }, ja: { q: "高い音が聞こえるのは？ 高い順に。", a: ["コウモリ", "イルカ", "イヌ", "人間"], x: "1秒に20万回以上の振動（200キロヘルツ）が聞こえるコウモリもいます。イルカは約150キロヘルツ、イヌは約45キロヘルツ。人間は最大20キロヘルツで、年をとると下がります。", k: "コウモリ：200キロヘルツまで聞こえる" }, it: { q: "Chi sente i suoni più acuti? Il più acuto per primo.", a: ["Pipistrello", "Delfino", "Cane", "Essere umano"], x: "Alcuni pipistrelli sentono oltre 200.000 vibrazioni al secondo (200 kHz), il delfino fino a circa 150 kHz, il cane circa 45 kHz. L’essere umano al massimo 20 kHz, e meno con l’età.", k: "Pipistrelli: sentono fino a 200 kHz" } } },
  { id: "r21", lvl: 3, type: "rank", right: 10123, t: { de: { q: "Wessen Körper ist am wärmsten? Wärmster zuerst.", a: ["Haushuhn", "Hund", "Mensch", "Schnabeltier"], x: "Vögel sind besonders warm: Hühner um 41 °C. Hunde haben etwa 38,5 °C, Menschen 37 °C, das Schnabeltier nur rund 32 °C.", k: "Huhn: 41 °C Körpertemperatur" }, en: { q: "Whose body is warmest? Warmest first.", a: ["Chicken", "Dog", "Human", "Platypus"], x: "Birds are especially warm: chickens around 41 °C. Dogs are about 38.5 °C, humans 37 °C, the platypus only around 32 °C.", k: "Chicken: 41 °C body temperature" }, fr: { q: "Quel corps est le plus chaud ? Le plus chaud d’abord.", a: ["Poule", "Chien", "Humain", "Ornithorynque"], x: "Les oiseaux sont très chauds : la poule environ 41 °C. Le chien a environ 38,5 °C, l’humain 37 °C, l’ornithorynque à peine 32 °C.", k: "Poule : 41 °C de température" }, es: { q: "¿Qué cuerpo está más caliente? El más caliente primero.", a: ["Gallina", "Perro", "Humano", "Ornitorrinco"], x: "Las aves son muy calientes: la gallina unos 41 °C. El perro tiene unos 38,5 °C, el humano 37 °C y el ornitorrinco solo unos 32 °C.", k: "Gallina: 41 °C de temperatura" }, pt: { q: "Qual corpo é mais quente? O mais quente primeiro.", a: ["Galinha", "Cachorro", "Humano", "Ornitorrinco"], x: "As aves são bem quentes: a galinha uns 41 °C. O cachorro tem uns 38,5 °C, o humano 37 °C e o ornitorrinco só uns 32 °C.", k: "Galinha: 41 °C de temperatura" }, ja: { q: "体温が高いのは？ 高い順に。", a: ["ニワトリ", "イヌ", "人間", "カモノハシ"], x: "鳥は体温が特に高く、ニワトリは約41℃。イヌは約38.5℃、人間は37℃、カモノハシはたった約32℃です。", k: "ニワトリ：体温41℃" }, it: { q: "Il corpo di chi è più caldo? Il più caldo per primo.", a: ["Gallina", "Cane", "Essere umano", "Ornitorinco"], x: "Gli uccelli sono molto caldi: la gallina circa 41 °C. Il cane circa 38,5 °C, l’essere umano 37 °C, l’ornitorinco solo circa 32 °C.", k: "Gallina: 41 °C di temperatura" } } },
  { id: "r22", lvl: 2, type: "rank", right: 10123, t: { de: { q: "Wer war zuerst auf der Erde? Ältestes zuerst.", a: ["Quallen", "Haie", "Dinosaurier", "Menschen"], x: "Quallen gibt es seit über 500 Millionen Jahren, Haie seit über 400 Millionen, Dinosaurier tauchten vor rund 230 Millionen Jahren auf – unsere Art erst vor etwa 300.000 Jahren.", k: "Quallen: seit über 500 Millionen Jahren da" }, en: { q: "Who was on Earth first? Oldest first.", a: ["Jellyfish", "Sharks", "Dinosaurs", "Humans"], x: "Jellyfish have existed for over 500 million years, sharks for over 400 million, dinosaurs appeared about 230 million years ago – our species only about 300,000 years ago.", k: "Jellyfish: around for over 500 million years" }, fr: { q: "Qui était sur Terre en premier ? Le plus ancien d’abord.", a: ["Méduses", "Requins", "Dinosaures", "Humains"], x: "Les méduses existent depuis plus de 500 millions d’années, les requins depuis plus de 400 millions, les dinosaures sont apparus il y a environ 230 millions d’années – notre espèce il y a environ 300 000 ans.", k: "Méduses : là depuis plus de 500 millions d’années" }, es: { q: "¿Quién llegó antes a la Tierra? El más antiguo primero.", a: ["Medusas", "Tiburones", "Dinosaurios", "Humanos"], x: "Las medusas existen desde hace más de 500 millones de años, los tiburones desde hace más de 400 millones, los dinosaurios aparecieron hace unos 230 millones y nuestra especie hace solo unos 300.000 años.", k: "Medusas: existen hace más de 500 millones de años" }, pt: { q: "Quem surgiu antes na Terra? O mais antigo primeiro.", a: ["Águas-vivas", "Tubarões", "Dinossauros", "Humanos"], x: "As águas-vivas existem há mais de 500 milhões de anos, os tubarões há mais de 400 milhões, os dinossauros surgiram há uns 230 milhões e nossa espécie há só uns 300.000 anos.", k: "Águas-vivas: existem há mais de 500 milhões de anos" }, ja: { q: "地球に先に現れたのは？ 古い順に。", a: ["クラゲ", "サメ", "恐竜", "人類"], x: "クラゲは5億年以上前から、サメは4億年以上前から。恐竜は約2億3000万年前に現れ、私たちの種はたった約30万年前からです。", k: "クラゲ：5億年以上前からいる" }, it: { q: "Chi è comparso prima sulla Terra? Il più antico per primo.", a: ["Meduse", "Squali", "Dinosauri", "Esseri umani"], x: "Le meduse esistono da oltre 500 milioni di anni, gli squali da oltre 400 milioni, i dinosauri comparvero circa 230 milioni di anni fa, la nostra specie solo circa 300.000 anni fa.", k: "Meduse: esistono da oltre 500 milioni di anni" } } },
  { id: "r23", lvl: 2, type: "rank", right: 10123, t: { de: { q: "Wer bekommt pro Jahr die meisten Jungen? Die meisten zuerst.", a: ["Hausmaus", "Wildkaninchen", "Rotfuchs", "Afrikanischer Elefant"], x: "Hausmäuse schaffen bis zu 50 Junge im Jahr, Wildkaninchen 20 bis 30, Füchse einen Wurf mit 4 bis 6. Eine Elefantenkuh bekommt nur etwa alle 4 bis 5 Jahre ein Kalb.", k: "Hausmaus: bis zu 50 Junge im Jahr" }, en: { q: "Who has the most babies per year? Most first.", a: ["House mouse", "Wild rabbit", "Red fox", "African elephant"], x: "House mice can have up to 50 young a year, wild rabbits 20 to 30, foxes one litter of 4 to 6. An elephant cow has a calf only about every 4 to 5 years.", k: "House mouse: up to 50 young a year" }, fr: { q: "Qui a le plus de petits par an ? Le plus d’abord.", a: ["Souris domestique", "Lapin de garenne", "Renard roux", "Éléphant d’Afrique"], x: "La souris peut avoir jusqu’à 50 petits par an, le lapin de garenne 20 à 30, le renard une portée de 4 à 6. Une éléphante n’a un petit qu’environ tous les 4 à 5 ans.", k: "Souris : jusqu’à 50 petits par an" }, es: { q: "¿Quién tiene más crías al año? El que más primero.", a: ["Ratón doméstico", "Conejo silvestre", "Zorro rojo", "Elefante africano"], x: "El ratón puede tener hasta 50 crías al año, el conejo de 20 a 30 y el zorro una camada de 4 a 6. Una elefanta solo tiene una cría cada 4 o 5 años.", k: "Ratón: hasta 50 crías al año" }, pt: { q: "Quem tem mais filhotes por ano? Quem tem mais primeiro.", a: ["Camundongo", "Coelho-selvagem", "Raposa-vermelha", "Elefante-africano"], x: "O camundongo pode ter até 50 filhotes por ano, o coelho de 20 a 30 e a raposa uma ninhada de 4 a 6. Uma elefanta tem só um filhote a cada 4 ou 5 anos.", k: "Camundongo: até 50 filhotes por ano" }, ja: { q: "1年に生まれる子どもが多いのは？ 多い順に。", a: ["ハツカネズミ", "アナウサギ", "アカギツネ", "アフリカゾウ"], x: "ハツカネズミは1年に最大50匹、アナウサギは20〜30匹、キツネは1回に4〜6匹。ゾウは4〜5年に1頭だけです。", k: "ハツカネズミ：1年に最大50匹" }, it: { q: "Chi ha più piccoli all’anno? Chi ne ha di più per primo.", a: ["Topo domestico", "Coniglio selvatico", "Volpe rossa", "Elefante africano"], x: "Il topo domestico può avere fino a 50 piccoli all’anno, il coniglio 20–30, la volpe una cucciolata di 4–6. Un’elefantessa ha un piccolo solo ogni 4–5 anni.", k: "Topo: fino a 50 piccoli all’anno" } } },
  { id: "r24", lvl: 2, type: "rank", right: 10123, t: { de: { q: "Welcher Vogel ist am schwersten? Schwerster zuerst.", a: ["Strauß", "Kaiserpinguin", "Höckerschwan", "Steinadler"], x: "Strauße wiegen über 100 kg, Kaiserpinguine 20 bis 40 kg, Höckerschwäne um 10 kg – einer der schwersten fliegenden Vögel. Steinadler bringen 3 bis 6 kg auf die Waage.", k: "Strauß: wiegt über 100 kg" }, en: { q: "Which bird is heaviest? Heaviest first.", a: ["Ostrich", "Emperor penguin", "Mute swan", "Golden eagle"], x: "Ostriches weigh over 100 kg, emperor penguins 20 to 40 kg, mute swans around 10 kg – one of the heaviest flying birds. Golden eagles weigh 3 to 6 kg.", k: "Ostrich: weighs over 100 kg" }, fr: { q: "Quel oiseau est le plus lourd ? Le plus lourd d’abord.", a: ["Autruche", "Manchot empereur", "Cygne tuberculé", "Aigle royal"], x: "L’autruche dépasse 100 kg, le manchot empereur pèse 20 à 40 kg, le cygne environ 10 kg – l’un des plus lourds oiseaux volants. L’aigle royal pèse 3 à 6 kg.", k: "Autruche : plus de 100 kg" }, es: { q: "¿Qué ave pesa más? La más pesada primero.", a: ["Avestruz", "Pingüino emperador", "Cisne vulgar", "Águila real"], x: "El avestruz supera los 100 kg, el pingüino emperador pesa de 20 a 40 kg, el cisne unos 10 kg (una de las aves voladoras más pesadas). El águila real pesa de 3 a 6 kg.", k: "Avestruz: más de 100 kg" }, pt: { q: "Qual ave pesa mais? A mais pesada primeiro.", a: ["Avestruz", "Pinguim-imperador", "Cisne-branco", "Águia-real"], x: "O avestruz passa dos 100 kg, o pinguim-imperador pesa de 20 a 40 kg, o cisne uns 10 kg (uma das aves voadoras mais pesadas). A águia-real pesa de 3 a 6 kg.", k: "Avestruz: mais de 100 kg" }, ja: { q: "重い鳥は？ 重い順に。", a: ["ダチョウ", "コウテイペンギン", "コブハクチョウ", "イヌワシ"], x: "ダチョウは100キロ以上、コウテイペンギンは20〜40キロ、コブハクチョウは約10キロ（飛べる鳥ではトップクラス）。イヌワシは3〜6キロです。", k: "ダチョウ：100キロ以上" }, it: { q: "Quale uccello è più pesante? Il più pesante per primo.", a: ["Struzzo", "Pinguino imperatore", "Cigno reale", "Aquila reale"], x: "Lo struzzo supera i 100 kg, il pinguino imperatore pesa 20–40 kg, il cigno reale circa 10 kg, uno degli uccelli volanti più pesanti. L’aquila reale pesa 3–6 kg.", k: "Struzzo: oltre 100 kg" } } },
  { id: "r25", lvl: 2, type: "rank", right: 10123, t: { de: { q: "Wer lebt als erwachsenes Tier am KÜRZESTEN? Kürzestes Leben zuerst.", a: ["Eintagsfliege", "Sommer-Arbeitsbiene", "Hausmaus", "Hauskatze"], x: "Erwachsene Eintagsfliegen leben oft nur Stunden bis wenige Tage – als Larve aber bis zu drei Jahre. Arbeitsbienen im Sommer etwa 6 Wochen, Mäuse 1 bis 2 Jahre, Katzen um 15 Jahre.", k: "Eintagsfliege: lebt als Erwachsene oft nur Stunden" }, en: { q: "Who lives the SHORTEST as an adult? Shortest life first.", a: ["Mayfly", "Summer worker bee", "House mouse", "Pet cat"], x: "Adult mayflies often live only hours to a few days – but up to three years as larvae. Summer worker bees about 6 weeks, mice 1 to 2 years, cats around 15 years.", k: "Mayfly: adults often live only hours" }, fr: { q: "Qui vit le moins longtemps à l’âge adulte ? La vie la plus courte d’abord.", a: ["Éphémère", "Abeille ouvrière d’été", "Souris domestique", "Chat domestique"], x: "L’éphémère adulte ne vit souvent que quelques heures à quelques jours – mais jusqu’à trois ans à l’état de larve. L’ouvrière d’été environ 6 semaines, la souris 1 à 2 ans, le chat environ 15 ans.", k: "Éphémère : adulte, vit souvent quelques heures" }, es: { q: "¿Quién vive MENOS de adulto? La vida más corta primero.", a: ["Efímera", "Abeja obrera de verano", "Ratón doméstico", "Gato doméstico"], x: "La efímera adulta suele vivir de horas a pocos días, pero como larva hasta tres años. La obrera de verano unas 6 semanas, el ratón de 1 a 2 años y el gato unos 15 años.", k: "Efímera: de adulta vive a menudo horas" }, pt: { q: "Quem vive MENOS como adulto? A vida mais curta primeiro.", a: ["Efêmera", "Abelha operária de verão", "Camundongo", "Gato doméstico"], x: "A efêmera adulta costuma viver de horas a poucos dias, mas como larva até três anos. A operária de verão umas 6 semanas, o camundongo de 1 a 2 anos e o gato uns 15 anos.", k: "Efêmera: adulta vive muitas vezes só horas" }, ja: { q: "大人になってからの命が「短い」のは？ 短い順に。", a: ["カゲロウ", "夏の働きバチ", "ハツカネズミ", "飼いネコ"], x: "カゲロウの成虫は数時間から数日だけ。でも幼虫としては最大3年生きます。夏の働きバチは約6週間、ネズミは1〜2年、ネコは約15年です。", k: "カゲロウ：成虫は数時間しか生きないことも" }, it: { q: "Chi vive MENO da adulto? La vita più breve per prima.", a: ["Effimera", "Ape operaia estiva", "Topo domestico", "Gatto domestico"], x: "L’effimera adulta vive spesso da poche ore a pochi giorni, ma come larva fino a tre anni. L’operaia estiva circa 6 settimane, il topo 1–2 anni, il gatto circa 15 anni.", k: "Effimera: da adulta vive spesso poche ore" } } },
  { id: "r26", lvl: 2, type: "rank", right: 10123, t: { de: { q: "Wer legt auf einmal die meisten Eier? Die meisten zuerst.", a: ["Mondfisch", "Erdkröte", "Meeresschildkröte", "Kaiserpinguin"], x: "Ein Mondfisch-Weibchen kann rund 300 Millionen Eier tragen, eine Erdkröte legt Schnüre mit einigen tausend, Meeresschildkröten etwa 100 pro Gelege, Kaiserpinguine genau eins.", k: "Mondfisch: 300 Millionen Eier" }, en: { q: "Who lays the most eggs at once? Most first.", a: ["Ocean sunfish", "Common toad", "Sea turtle", "Emperor penguin"], x: "A female ocean sunfish can carry around 300 million eggs, a common toad lays strings with a few thousand, sea turtles about 100 per clutch, emperor penguins exactly one.", k: "Ocean sunfish: 300 million eggs" }, fr: { q: "Qui pond le plus d’œufs en une fois ? Le plus d’abord.", a: ["Poisson-lune", "Crapaud commun", "Tortue marine", "Manchot empereur"], x: "Une femelle poisson-lune peut porter environ 300 millions d’œufs, le crapaud pond des cordons de quelques milliers, la tortue marine environ 100 par ponte, le manchot empereur un seul.", k: "Poisson-lune : 300 millions d’œufs" }, es: { q: "¿Quién pone más huevos de una vez? El que más primero.", a: ["Pez luna", "Sapo común", "Tortuga marina", "Pingüino emperador"], x: "Una hembra de pez luna puede llevar unos 300 millones de huevos, el sapo pone cordones con unos miles, la tortuga marina unos 100 por puesta y el pingüino emperador, uno solo.", k: "Pez luna: 300 millones de huevos" }, pt: { q: "Quem põe mais ovos de uma vez? Quem põe mais primeiro.", a: ["Peixe-lua", "Sapo-comum", "Tartaruga-marinha", "Pinguim-imperador"], x: "Uma fêmea de peixe-lua pode carregar uns 300 milhões de ovos, o sapo põe cordões com alguns milhares, a tartaruga-marinha uns 100 por ninhada e o pinguim-imperador só um.", k: "Peixe-lua: 300 milhões de ovos" }, ja: { q: "一度に産む卵が多いのは？ 多い順に。", a: ["マンボウ", "ヒキガエル", "ウミガメ", "コウテイペンギン"], x: "マンボウのメスは約3億個の卵をもつことがあります。ヒキガエルは数千個のひも状の卵、ウミガメは1回に約100個、コウテイペンギンはたった1個。", k: "マンボウ：卵は3億個" }, it: { q: "Chi depone più uova in una volta? Chi ne depone di più per primo.", a: ["Pesce luna", "Rospo comune", "Tartaruga marina", "Pinguino imperatore"], x: "Una femmina di pesce luna può portare circa 300 milioni di uova, il rospo depone cordoni con qualche migliaio, la tartaruga marina circa 100 per covata, il pinguino imperatore uno solo.", k: "Pesce luna: 300 milioni di uova" } } },
  { id: "r27", lvl: 1, type: "rank", right: 10123, t: { de: { q: "Wer ist am kleinsten? Kleinstes zuerst.", a: ["Bienenelfe (Kolibri)", "Feldmaus", "Eichhörnchen", "Rotfuchs"], x: "Die Bienenelfe ist mit gut 5 cm der kleinste Vogel der Welt. Eine Feldmaus misst etwa 10 cm, ein Eichhörnchen gut 20 cm (ohne Schwanz), ein Fuchs rund 70 cm.", k: "Bienenelfe: kleinster Vogel der Welt" }, en: { q: "Who is smallest? Smallest first.", a: ["Bee hummingbird", "Common vole", "Red squirrel", "Red fox"], x: "At just over 5 cm, the bee hummingbird is the smallest bird in the world. A vole is about 10 cm, a squirrel just over 20 cm (without tail), a fox around 70 cm.", k: "Bee hummingbird: smallest bird in the world" }, fr: { q: "Qui est le plus petit ? Le plus petit d’abord.", a: ["Colibri d’Elena", "Campagnol des champs", "Écureuil roux", "Renard roux"], x: "Avec à peine plus de 5 cm, le colibri d’Elena est le plus petit oiseau du monde. Le campagnol mesure environ 10 cm, l’écureuil un peu plus de 20 cm (sans la queue), le renard environ 70 cm.", k: "Colibri d’Elena : plus petit oiseau du monde" }, es: { q: "¿Quién es más pequeño? El más pequeño primero.", a: ["Colibrí zunzuncito", "Topillo campesino", "Ardilla roja", "Zorro rojo"], x: "Con algo más de 5 cm, el zunzuncito es el ave más pequeña del mundo. Un topillo mide unos 10 cm, una ardilla algo más de 20 cm (sin cola) y un zorro unos 70 cm.", k: "Colibrí zunzuncito: el ave más pequeña" }, pt: { q: "Quem é menor? O menor primeiro.", a: ["Beija-flor-abelha", "Rato-do-campo", "Esquilo-vermelho", "Raposa-vermelha"], x: "Com pouco mais de 5 cm, o beija-flor-abelha é a menor ave do mundo. Um rato-do-campo mede uns 10 cm, um esquilo pouco mais de 20 cm (sem cauda) e uma raposa uns 70 cm.", k: "Beija-flor-abelha: a menor ave do mundo" }, ja: { q: "小さいのは？ 小さい順に。", a: ["マメハチドリ", "ハタネズミ", "キタリス", "アカギツネ"], x: "5センチちょっとのマメハチドリは世界最小の鳥。ハタネズミは約10センチ、リスは20センチちょっと（しっぽなし）、キツネは約70センチです。", k: "マメハチドリ：世界最小の鳥" }, it: { q: "Chi è più piccolo? Il più piccolo per primo.", a: ["Colibrì di Elena", "Arvicola campestre", "Scoiattolo rosso", "Volpe rossa"], x: "Con poco più di 5 cm, il colibrì di Elena è l’uccello più piccolo del mondo. Un’arvicola misura circa 10 cm, uno scoiattolo poco più di 20 cm (senza coda), una volpe circa 70 cm.", k: "Colibrì di Elena: l’uccello più piccolo del mondo" } } },
  { id: "r28", lvl: 3, type: "rank", right: 10123, t: { de: { q: "Wer kann am längsten unter Wasser bleiben? Längste Zeit zuerst.", a: ["Cuvier-Schnabelwal", "Südlicher See-Elefant", "Großer Tümmler", "Fischotter"], x: "Rekord: ein Cuvier-Schnabelwal blieb fast 4 Stunden unten. See-Elefanten schaffen bis etwa 2 Stunden, Große Tümmler meist unter 10 Minuten, Fischotter wenige Minuten.", k: "Cuvier-Schnabelwal: fast 4 Stunden unter Wasser" }, en: { q: "Who can stay underwater longest? Longest first.", a: ["Cuvier’s beaked whale", "Southern elephant seal", "Bottlenose dolphin", "Eurasian otter"], x: "Record: a Cuvier’s beaked whale stayed down for almost 4 hours. Elephant seals manage up to about 2 hours, bottlenose dolphins usually under 10 minutes, otters a few minutes.", k: "Cuvier's beaked whale: almost 4 hours underwater" }, fr: { q: "Qui peut rester le plus longtemps sous l’eau ? Le plus long d’abord.", a: ["Baleine de Cuvier", "Éléphant de mer du Sud", "Grand dauphin", "Loutre d’Europe"], x: "Record : une baleine de Cuvier est restée près de 4 heures sous l’eau. L’éléphant de mer tient jusqu’à environ 2 heures, le grand dauphin en général moins de 10 minutes, la loutre quelques minutes.", k: "Baleine de Cuvier : près de 4 heures sous l’eau" }, es: { q: "¿Quién aguanta más bajo el agua? El que más primero.", a: ["Zifio de Cuvier", "Elefante marino del sur", "Delfín mular", "Nutria europea"], x: "Récord: un zifio de Cuvier estuvo casi 4 horas sumergido. El elefante marino aguanta hasta unas 2 horas, el delfín mular normalmente menos de 10 minutos y la nutria unos minutos.", k: "Zifio de Cuvier: casi 4 horas bajo el agua" }, pt: { q: "Quem aguenta mais tempo debaixo d’água? Quem aguenta mais primeiro.", a: ["Baleia-bicuda-de-cuvier", "Elefante-marinho-do-sul", "Golfinho-nariz-de-garrafa", "Lontra-europeia"], x: "Recorde: uma baleia-bicuda-de-cuvier ficou quase 4 horas submersa. O elefante-marinho aguenta até umas 2 horas, o golfinho normalmente menos de 10 minutos e a lontra alguns minutos.", k: "Baleia-bicuda-de-cuvier: quase 4 horas submersa" }, ja: { q: "水中に長くいられるのは？ 長い順に。", a: ["アカボウクジラ", "ミナミゾウアザラシ", "ハンドウイルカ", "ユーラシアカワウソ"], x: "記録ではアカボウクジラが4時間近く潜りました。ゾウアザラシは最大約2時間、ハンドウイルカはふつう10分未満、カワウソは数分です。", k: "アカボウクジラ：4時間近く水中に" }, it: { q: "Chi resta più a lungo sott’acqua? Chi resiste di più per primo.", a: ["Zifio", "Elefante marino del sud", "Tursiope", "Lontra europea"], x: "Record: uno zifio è rimasto sott’acqua quasi 4 ore. L’elefante marino resiste fino a circa 2 ore, il tursiope di solito meno di 10 minuti, la lontra pochi minuti.", k: "Zifio: quasi 4 ore sott’acqua" } } },
  { id: "r29", lvl: 2, type: "rank", right: 10123, t: { de: { q: "Wer ist an Land am schnellsten? Schnellstes zuerst.", a: ["Strauß", "Rotfuchs", "Eichhörnchen", "Igel"], x: "Strauße laufen bis 70 km/h – der schnellste Vogel zu Fuß. Füchse schaffen etwa 50, Eichhörnchen gut 20 km/h. Ein Igel trippelt höchstens rund 9 km/h.", k: "Strauß: läuft 70 km/h" }, en: { q: "Who is fastest on land? Fastest first.", a: ["Ostrich", "Red fox", "Red squirrel", "Hedgehog"], x: "Ostriches run up to 70 km/h – the fastest bird on foot. Foxes manage about 50, squirrels just over 20 km/h. A hedgehog scurries at about 9 km/h at most.", k: "Ostrich: runs 70 km/h" }, fr: { q: "Qui est le plus rapide sur terre ? Le plus rapide d’abord.", a: ["Autruche", "Renard roux", "Écureuil roux", "Hérisson"], x: "L’autruche court jusqu’à 70 km/h – l’oiseau le plus rapide à pied. Le renard atteint environ 50, l’écureuil un peu plus de 20 km/h. Le hérisson trottine à 9 km/h au plus.", k: "Autruche : court à 70 km/h" }, es: { q: "¿Quién es más rápido en tierra? El más rápido primero.", a: ["Avestruz", "Zorro rojo", "Ardilla roja", "Erizo"], x: "El avestruz corre hasta 70 km/h, el ave más rápida a pie. El zorro llega a unos 50 y la ardilla a algo más de 20 km/h. El erizo trota como mucho a unos 9 km/h.", k: "Avestruz: corre a 70 km/h" }, pt: { q: "Quem é mais rápido em terra? O mais rápido primeiro.", a: ["Avestruz", "Raposa-vermelha", "Esquilo-vermelho", "Ouriço"], x: "O avestruz corre até 70 km/h, a ave mais rápida a pé. A raposa chega a uns 50 e o esquilo a pouco mais de 20 km/h. O ouriço trota no máximo a uns 9 km/h.", k: "Avestruz: corre a 70 km/h" }, ja: { q: "陸で速いのは？ 速い順に。", a: ["ダチョウ", "アカギツネ", "キタリス", "ハリネズミ"], x: "ダチョウは時速70キロで走る、走る鳥でいちばんの俊足。キツネは約50キロ、リスは20キロちょっと。ハリネズミは最大でも時速約9キロです。", k: "ダチョウ：時速70キロで走る" }, it: { q: "Chi è più veloce sulla terraferma? Il più veloce per primo.", a: ["Struzzo", "Volpe rossa", "Scoiattolo rosso", "Riccio"], x: "Lo struzzo corre fino a 70 km/h, l’uccello più veloce a piedi. La volpe arriva a circa 50, lo scoiattolo a poco più di 20 km/h. Il riccio trotterella al massimo a circa 9 km/h.", k: "Struzzo: corre a 70 km/h" } } },
  { id: "r30", lvl: 3, type: "rank", right: 10123, t: { de: { q: "Wessen Gehirn ist am schwersten? Schwerstes zuerst.", a: ["Pottwal", "Afrikanischer Elefant", "Mensch", "Schimpanse"], x: "Das Pottwal-Gehirn wiegt rund 8 kg – das schwerste im Tierreich. Elefanten haben etwa 5 kg, Menschen 1,3 bis 1,4 kg, Schimpansen knapp 400 g.", k: "Pottwal: Gehirn wiegt 8 kg" }, en: { q: "Whose brain is heaviest? Heaviest first.", a: ["Sperm whale", "African elephant", "Human", "Chimpanzee"], x: "A sperm whale’s brain weighs about 8 kg – the heaviest in the animal kingdom. Elephants have about 5 kg, humans 1.3 to 1.4 kg, chimpanzees just under 400 g.", k: "Sperm whale: brain weighs 8 kg" }, fr: { q: "Quel cerveau est le plus lourd ? Le plus lourd d’abord.", a: ["Cachalot", "Éléphant d’Afrique", "Humain", "Chimpanzé"], x: "Le cerveau du cachalot pèse environ 8 kg – le plus lourd du règne animal. L’éléphant en a environ 5 kg, l’humain 1,3 à 1,4 kg, le chimpanzé à peine 400 g.", k: "Cachalot : cerveau de 8 kg" }, es: { q: "¿Qué cerebro pesa más? El más pesado primero.", a: ["Cachalote", "Elefante africano", "Humano", "Chimpancé"], x: "El cerebro del cachalote pesa unos 8 kg, el más pesado del reino animal. El del elefante unos 5 kg, el humano de 1,3 a 1,4 kg y el del chimpancé poco menos de 400 g.", k: "Cachalote: cerebro de 8 kg" }, pt: { q: "Qual cérebro pesa mais? O mais pesado primeiro.", a: ["Cachalote", "Elefante-africano", "Humano", "Chimpanzé"], x: "O cérebro do cachalote pesa uns 8 kg, o mais pesado do reino animal. O do elefante uns 5 kg, o humano de 1,3 a 1,4 kg e o do chimpanzé pouco menos de 400 g.", k: "Cachalote: cérebro de 8 kg" }, ja: { q: "脳が重いのは？ 重い順に。", a: ["マッコウクジラ", "アフリカゾウ", "人間", "チンパンジー"], x: "マッコウクジラの脳は約8キロで、動物界でいちばん重い。ゾウは約5キロ、人間は1.3〜1.4キロ、チンパンジーは400グラム弱です。", k: "マッコウクジラ：脳は8キロ" }, it: { q: "Il cervello di chi pesa di più? Il più pesante per primo.", a: ["Capodoglio", "Elefante africano", "Essere umano", "Scimpanzé"], x: "Il cervello del capodoglio pesa circa 8 kg, il più pesante del regno animale. Quello dell’elefante circa 5 kg, dell’essere umano 1,3–1,4 kg, dello scimpanzé poco meno di 400 g.", k: "Capodoglio: cervello di 8 kg" } } },
  { id: "a01", lvl: 1, type: "text", right: 1, t: { de: { q: "Welcher heimische Vogel kann kopfüber einen Baumstamm hinunterlaufen?", a: ["Buntspecht", "Kleiber", "Gartenbaumläufer", "Kohlmeise"], x: "Der Kleiber klettert als einziger heimischer Vogel auch kopfüber abwärts. Spechte und Baumläufer klettern nur aufwärts.", k: "Kleiber: klettert kopfüber den Stamm hinab" }, en: { q: "Which bird native to Central Europe can walk head-first down a tree trunk?", a: ["Great spotted woodpecker", "Nuthatch", "Short-toed treecreeper", "Great tit"], x: "The nuthatch is the only native bird that also climbs head-first downwards. Woodpeckers and treecreepers only climb up.", k: "Nuthatch: climbs down trunks head-first" }, fr: { q: "Quel oiseau d'Europe centrale peut descendre un tronc la tête en bas ?", a: ["Pic épeiche", "Sittelle torchepot", "Grimpereau des jardins", "Mésange charbonnière"], x: "La sittelle est le seul oiseau de chez nous à descendre les troncs tête en bas. Pics et grimpereaux ne font que monter.", k: "Sittelle : descend les troncs tête en bas" }, es: { q: "¿Qué ave de Europa central puede bajar por un tronco cabeza abajo?", a: ["Pico picapinos", "Trepador azul", "Agateador europeo", "Carbonero común"], x: "El trepador azul es la única ave autóctona que baja por los troncos cabeza abajo. Pájaros carpinteros y agateadores solo suben.", k: "Trepador azul: baja los troncos cabeza abajo" }, pt: { q: "Qual ave da Europa Central consegue descer um tronco de cabeça para baixo?", a: ["Pica-pau-malhado-grande", "Trepadeira-azul", "Trepadeira-comum", "Chapim-real"], x: "A trepadeira-azul é a única ave nativa que desce os troncos de cabeça para baixo. Pica-paus e trepadeiras só sobem.", k: "Trepadeira-azul: desce troncos de cabeça para baixo" }, ja: { q: "中央ヨーロッパの鳥で、頭を下にして木の幹を下りられるのはどれ？", a: ["アカゲラ", "ゴジュウカラ", "タンシキバシリ", "シジュウカラ"], x: "頭を下にして下りられる在来の鳥はゴジュウカラだけ。キツツキやキバシリは上にしか登れません。", k: "ゴジュウカラ：頭を下にして幹を下りる" }, it: { q: "Quale uccello dell’Europa centrale sa scendere lungo un tronco a testa in giù?", a: ["Picchio rosso maggiore", "Picchio muratore", "Rampichino comune", "Cinciallegra"], x: "Il picchio muratore è l’unico uccello nostrano che si arrampica anche a testa in giù. Picchi e rampichini salgono solo verso l’alto.", k: "Picchio muratore: scende i tronchi a testa in giù" } } },
  { id: "a02", lvl: 1, type: "tf", right: 1, t: { de: { q: "Milch ist ein gutes Futter für Igel.", a: ["Wahr", "Falsch"], x: "Igel vertragen keinen Milchzucker und bekommen von Milch Durchfall. Wasser ist das richtige Getränk für sie.", k: "Igel: vertragen keine Milch" }, en: { q: "Milk is good food for hedgehogs.", a: ["True", "False"], x: "Hedgehogs can't digest milk sugar (lactose); milk gives them diarrhoea. Water is the right drink for them.", k: "Hedgehogs: can't digest milk" }, fr: { q: "Le lait est une bonne nourriture pour les hérissons.", a: ["Vrai", "Faux"], x: "Les hérissons ne digèrent pas le lactose : le lait leur donne la diarrhée. L'eau est la bonne boisson pour eux.", k: "Hérissons : ne digèrent pas le lait" }, es: { q: "La leche es un buen alimento para los erizos.", a: ["Verdadero", "Falso"], x: "Los erizos no toleran la lactosa y la leche les provoca diarrea. Lo adecuado es darles agua.", k: "Erizos: no digieren la leche" }, pt: { q: "Leite é um bom alimento para ouriços.", a: ["Verdadeiro", "Falso"], x: "Os ouriços não toleram lactose, e o leite causa diarreia neles. O certo é dar água.", k: "Ouriços: não digerem leite" }, ja: { q: "正しい？まちがい？ 牛乳はハリネズミにとってよい食べもの。", a: ["正しい", "まちがい"], x: "ハリネズミは乳糖を消化できず、牛乳を飲むとおなかをこわします。あげるなら水がいちばんです。", k: "ハリネズミ：牛乳を消化できない" }, it: { q: "Vero o falso? Il latte è un buon cibo per i ricci.", a: ["Vero", "Falso"], x: "I ricci non digeriscono il lattosio; il latte gli dà la diarrea. La bevanda giusta per loro è l’acqua.", k: "Ricci: non digeriscono il latte" } } },
  { id: "a03", lvl: 1, type: "tf", right: 0, t: { de: { q: "Fledermäuse sind die einzigen Säugetiere, die aktiv fliegen können.", a: ["Wahr", "Falsch"], x: "Stimmt! Flughörnchen gleiten nur. Fledermäuse fliegen mit echten Flügeln aus Flughaut zwischen ihren langen Fingern.", k: "Fledermäuse: einzige Säugetiere, die richtig fliegen" }, en: { q: "Bats are the only mammals capable of true powered flight.", a: ["True", "False"], x: "True! Flying squirrels only glide. Bats fly with real wings made of skin stretched between their long fingers.", k: "Bats: the only mammals that truly fly" }, fr: { q: "Les chauves-souris sont les seuls mammifères capables de vrai vol battu.", a: ["Vrai", "Faux"], x: "Vrai ! Les écureuils volants ne font que planer. Les chauves-souris volent avec une membrane tendue entre leurs longs doigts.", k: "Chauves-souris : seuls mammifères qui volent vraiment" }, es: { q: "Los murciélagos son los únicos mamíferos capaces de volar activamente.", a: ["Verdadero", "Falso"], x: "¡Cierto! Las ardillas voladoras solo planean. Los murciélagos vuelan con una membrana de piel entre sus largos dedos.", k: "Murciélagos: únicos mamíferos que vuelan de verdad" }, pt: { q: "Os morcegos são os únicos mamíferos capazes de voar de verdade.", a: ["Verdadeiro", "Falso"], x: "Certo! Os esquilos-voadores só planam. Os morcegos voam com uma membrana de pele entre os dedos longos.", k: "Morcegos: únicos mamíferos que voam de verdade" }, ja: { q: "正しい？まちがい？ 自分の力で本当に飛べる哺乳類はコウモリだけ。", a: ["正しい", "まちがい"], x: "正しい！モモンガやムササビは滑空するだけ。コウモリは長い指の間に張った皮ふのつばさで、本当に飛びます。", k: "コウモリ：本当に飛べる唯一の哺乳類" }, it: { q: "Vero o falso? I pipistrelli sono gli unici mammiferi capaci di volare davvero.", a: ["Vero", "Falso"], x: "Vero! Gli scoiattoli volanti planano soltanto. I pipistrelli volano con vere ali di pelle tesa tra le lunghe dita.", k: "Pipistrelli: unici mammiferi che volano davvero" } } },
  { id: "a04", lvl: 1, type: "text", right: 2, t: { de: { q: "Um wie viel Grad kann eine Eule ihren Kopf etwa drehen?", a: ["90 Grad", "180 Grad", "270 Grad", "360 Grad"], x: "Eulen drehen den Kopf bis etwa 270 Grad. Das gleicht aus, dass sie ihre großen Augen kaum bewegen können.", k: "Eulen: drehen den Kopf um 270 Grad" }, en: { q: "About how far can an owl turn its head?", a: ["90 degrees", "180 degrees", "270 degrees", "360 degrees"], x: "Owls can turn their heads about 270 degrees. This makes up for their large eyes, which can barely move.", k: "Owls: turn their head 270 degrees" }, fr: { q: "De combien de degrés une chouette peut-elle tourner la tête environ ?", a: ["90 degrés", "180 degrés", "270 degrés", "360 degrés"], x: "Les chouettes tournent la tête d'environ 270 degrés, car leurs grands yeux ne bougent presque pas.", k: "Chouettes : tournent la tête à 270°" }, es: { q: "¿Aproximadamente cuántos grados puede girar la cabeza un búho?", a: ["90 grados", "180 grados", "270 grados", "360 grados"], x: "Los búhos giran la cabeza unos 270 grados, porque sus grandes ojos apenas pueden moverse.", k: "Búhos: giran la cabeza 270 grados" }, pt: { q: "Mais ou menos quantos graus uma coruja consegue girar a cabeça?", a: ["90 graus", "180 graus", "270 graus", "360 graus"], x: "As corujas giram a cabeça uns 270 graus, porque os olhos grandes quase não se mexem.", k: "Corujas: giram a cabeça 270 graus" }, ja: { q: "フクロウは首をだいたい何度まで回せる？", a: ["90度", "180度", "270度", "360度"], x: "フクロウは首を約270度回せます。大きな目がほとんど動かないので、そのかわりです。", k: "フクロウ：首を270度回せる" }, it: { q: "Di quanto può girare la testa un gufo, più o meno?", a: ["90 gradi", "180 gradi", "270 gradi", "360 gradi"], x: "I gufi girano la testa di circa 270 gradi. Così compensano i grandi occhi, che quasi non si muovono.", k: "Gufi: girano la testa di 270 gradi" } } },
  { id: "a05", lvl: 1, type: "text", right: 1, t: { de: { q: "Welcher Vogel erreicht im Sturzflug mehr als 300 km/h?", a: ["Turmfalke", "Wanderfalke", "Mauersegler", "Habicht"], x: "Der Wanderfalke stößt mit über 300 km/h auf Beute herab und gilt damit als schnellstes Tier der Welt.", k: "Wanderfalke: schnellstes Tier der Welt" }, en: { q: "Which bird reaches over 300 km/h in a hunting dive?", a: ["Kestrel", "Peregrine falcon", "Common swift", "Goshawk"], x: "The peregrine falcon dives at prey at over 300 km/h, making it the fastest animal in the world.", k: "Peregrine falcon: fastest animal in the world" }, fr: { q: "Quel oiseau dépasse 300 km/h en piqué ?", a: ["Faucon crécerelle", "Faucon pèlerin", "Martinet noir", "Autour des palombes"], x: "Le faucon pèlerin fond sur ses proies à plus de 300 km/h : c'est l'animal le plus rapide du monde.", k: "Faucon pèlerin : l’animal le plus rapide" }, es: { q: "¿Qué ave supera los 300 km/h en picado?", a: ["Cernícalo vulgar", "Halcón peregrino", "Vencejo común", "Azor común"], x: "El halcón peregrino se lanza sobre sus presas a más de 300 km/h: es el animal más rápido del mundo.", k: "Halcón peregrino: el animal más rápido" }, pt: { q: "Qual ave passa dos 300 km/h em mergulho?", a: ["Peneireiro", "Falcão-peregrino", "Andorinhão-preto", "Açor"], x: "O falcão-peregrino se lança sobre as presas a mais de 300 km/h: é o animal mais rápido do mundo.", k: "Falcão-peregrino: o animal mais rápido" }, ja: { q: "狩りの急降下で時速300キロを超える鳥は？", a: ["チョウゲンボウ", "ハヤブサ", "ヨーロッパアマツバメ", "オオタカ"], x: "ハヤブサは時速300キロ以上で獲物に向かって急降下します。世界一速い動物です。", k: "ハヤブサ：世界一速い動物" }, it: { q: "Quale uccello supera i 300 km/h in picchiata di caccia?", a: ["Gheppio", "Falco pellegrino", "Rondone comune", "Astore"], x: "Il falco pellegrino si getta sulle prede a oltre 300 km/h: è l’animale più veloce del mondo.", k: "Falco pellegrino: l’animale più veloce" } } },
  { id: "a06", lvl: 1, type: "text", right: 3, t: { de: { q: "Welches ist das größte Nagetier der Welt?", a: ["Biber", "Stachelschwein", "Murmeltier", "Wasserschwein"], x: "Das südamerikanische Wasserschwein (Capybara) kann über 50 kg wiegen. Der Biber ist das größte Nagetier Europas.", k: "Wasserschwein: größtes Nagetier der Welt" }, en: { q: "Which is the largest rodent in the world?", a: ["Beaver", "Porcupine", "Marmot", "Capybara"], x: "The South American capybara can weigh over 50 kg. The beaver is Europe's largest rodent.", k: "Capybara: largest rodent in the world" }, fr: { q: "Quel est le plus grand rongeur du monde ?", a: ["Castor", "Porc-épic", "Marmotte", "Capybara"], x: "Le capybara d'Amérique du Sud peut dépasser 50 kg. Le castor est le plus grand rongeur d'Europe.", k: "Capybara : plus grand rongeur du monde" }, es: { q: "¿Cuál es el roedor más grande del mundo?", a: ["Castor", "Puercoespín", "Marmota", "Capibara"], x: "El capibara sudamericano puede superar los 50 kg. El castor es el roedor más grande de Europa.", k: "Capibara: mayor roedor del mundo" }, pt: { q: "Qual é o maior roedor do mundo?", a: ["Castor", "Porco-espinho", "Marmota", "Capivara"], x: "A capivara sul-americana pode passar dos 50 kg. O castor é o maior roedor da Europa.", k: "Capivara: maior roedor do mundo" }, ja: { q: "世界最大のネズミの仲間（げっ歯類）は？", a: ["ビーバー", "ヤマアラシ", "マーモット", "カピバラ"], x: "南アメリカのカピバラは50キロ以上になることも。ヨーロッパ最大のげっ歯類はビーバーです。", k: "カピバラ：世界最大のげっ歯類" }, it: { q: "Qual è il roditore più grande del mondo?", a: ["Castoro", "Istrice", "Marmotta", "Capibara"], x: "Il capibara sudamericano può superare i 50 kg. Il castoro è il roditore più grande d’Europa.", k: "Capibara: il roditore più grande del mondo" } } },
  { id: "a07", lvl: 1, type: "text", right: 0, t: { de: { q: "Was macht ein frisch geschlüpftes Kuckucksküken mit den anderen Eiern im Nest?", a: ["Es wirft sie aus dem Nest", "Es wärmt sie mit", "Es frisst sie auf", "Es lässt sie liegen"], x: "Das Kuckucksküken schiebt Eier und Küken der Wirtsvögel aus dem Nest. So bekommt es das ganze Futter allein.", k: "Kuckucksküken: wirft die anderen Eier raus" }, en: { q: "What does a newly hatched cuckoo chick do with the other eggs in the nest?", a: ["Pushes them out of the nest", "Keeps them warm", "Eats them", "Leaves them alone"], x: "The cuckoo chick pushes the host's eggs and chicks out of the nest so it gets all the food for itself.", k: "Cuckoo chick: pushes the other eggs out" }, fr: { q: "Que fait un poussin de coucou fraîchement éclos des autres œufs du nid ?", a: ["Il les pousse hors du nid", "Il les couve aussi", "Il les mange", "Il les ignore"], x: "Le jeune coucou pousse les œufs et oisillons de ses hôtes hors du nid pour garder toute la nourriture.", k: "Poussin de coucou : éjecte les autres œufs" }, es: { q: "¿Qué hace un pollo de cuco recién nacido con los otros huevos del nido?", a: ["Los empuja fuera del nido", "Los mantiene calientes", "Se los come", "Los deja en paz"], x: "El pollo de cuco empuja fuera del nido los huevos y pollos de sus anfitriones para quedarse con toda la comida.", k: "Pollo de cuco: echa fuera los otros huevos" }, pt: { q: "O que um filhote de cuco recém-nascido faz com os outros ovos do ninho?", a: ["Empurra-os para fora do ninho", "Mantém-nos aquecidos", "Come-os", "Deixa-os em paz"], x: "O filhote de cuco empurra para fora do ninho os ovos e filhotes dos anfitriões, para ficar com toda a comida.", k: "Filhote de cuco: joga fora os outros ovos" }, ja: { q: "かえったばかりのカッコウのひなは、巣のほかの卵をどうする？", a: ["巣の外に押し出す", "温める", "食べる", "そのままにする"], x: "カッコウのひなは、仮親の卵やひなを巣の外に押し出し、えさをひとりじめします。", k: "カッコウのひな：ほかの卵を巣から押し出す" }, it: { q: "Cosa fa il pulcino di cuculo appena nato con le altre uova del nido?", a: ["Le spinge fuori dal nido", "Le tiene al caldo", "Le mangia", "Le lascia stare"], x: "Il pulcino di cuculo spinge fuori dal nido uova e pulcini dei genitori adottivi, così riceve tutto il cibo.", k: "Pulcino di cuculo: butta fuori le altre uova" } } },
  { id: "a08", lvl: 1, type: "text", right: 2, t: { de: { q: "Welche Farbe hat das Gefieder eines Amselweibchens?", a: ["Schwarz", "Grau mit roter Brust", "Dunkelbraun", "Schwarz-weiß gefleckt"], x: "Nur das Männchen ist schwarz mit gelbem Schnabel. Das Weibchen ist dunkelbraun und dadurch beim Brüten gut getarnt.", k: "Amsel-Weibchen: braun, nicht schwarz" }, en: { q: "What colour is a female blackbird?", a: ["Black", "Grey with a red breast", "Dark brown", "Black-and-white spotted"], x: "Only the male is black with a yellow bill. The female is dark brown, which camouflages her on the nest.", k: "Female blackbird: brown, not black" }, fr: { q: "De quelle couleur est la femelle du merle noir ?", a: ["Noire", "Grise à poitrine rouge", "Brun foncé", "Tachetée noir et blanc"], x: "Seul le mâle est noir à bec jaune. La femelle est brun foncé, ce qui la camoufle quand elle couve.", k: "Merle femelle : brune, pas noire" }, es: { q: "¿De qué color es la hembra del mirlo común?", a: ["Negra", "Gris con pecho rojo", "Marrón oscuro", "Moteada de blanco y negro"], x: "Solo el macho es negro con pico amarillo. La hembra es marrón oscuro, lo que la camufla al incubar.", k: "Mirlo hembra: marrón, no negra" }, pt: { q: "De que cor é a fêmea do melro?", a: ["Preta", "Cinza com peito vermelho", "Marrom-escura", "Pintada de branco e preto"], x: "Só o macho é preto com bico amarelo. A fêmea é marrom-escura, o que a camufla ao chocar.", k: "Melro fêmea: marrom, não preta" }, ja: { q: "クロウタドリのメスは何色？", a: ["黒", "灰色で胸が赤い", "こげ茶色", "白黒のまだら"], x: "黒くて黄色いくちばしなのはオスだけ。メスはこげ茶色で、巣の上で目立ちません。", k: "クロウタドリのメス：黒ではなく茶色" }, it: { q: "Di che colore è la femmina del merlo?", a: ["Nera", "Grigia con il petto rosso", "Marrone scuro", "A macchie bianche e nere"], x: "Solo il maschio è nero con il becco giallo. La femmina è marrone scuro, così è mimetizzata sul nido.", k: "Merlo femmina: marrone, non nera" } } },
  { id: "a09", lvl: 1, type: "text", right: 1, t: { de: { q: "Was ist ein „Gewölle“ bei Eulen?", a: ["Ein Nest aus Federn", "Ausgewürgte Knochen und Haare", "Ein Balzruf", "Das weiche Daunengefieder"], x: "Eulen schlucken Mäuse ganz und würgen Unverdauliches wie Knochen und Fell später als Ballen wieder aus.", k: "Gewölle: ausgewürgte Knochen und Haare" }, en: { q: "What is an owl pellet?", a: ["A nest made of feathers", "Coughed-up bones and fur", "A courtship call", "Soft down feathers"], x: "Owls swallow mice whole and later cough up the indigestible bones and fur as a compact pellet.", k: "Owl pellet: coughed-up bones and fur" }, fr: { q: "Qu'est-ce qu'une pelote de réjection chez la chouette ?", a: ["Un nid de plumes", "Des os et poils régurgités", "Un chant nuptial", "Le duvet des poussins"], x: "Les chouettes avalent les souris entières, puis recrachent les os et poils non digérés en boulette.", k: "Pelote de réjection : os et poils recrachés" }, es: { q: "¿Qué es una egagrópila de búho?", a: ["Un nido de plumas", "Huesos y pelos regurgitados", "Un canto de cortejo", "El plumón suave"], x: "Los búhos tragan los ratones enteros y luego regurgitan los huesos y pelos no digeridos en una bola.", k: "Egagrópila: huesos y pelo regurgitados" }, pt: { q: "O que é uma egagrópila de coruja?", a: ["Um ninho de penas", "Ossos e pelos regurgitados", "Um canto de corte", "A penugem macia"], x: "As corujas engolem os ratos inteiros e depois regurgitam numa bola os ossos e pelos não digeridos.", k: "Egagrópila: ossos e pelos regurgitados" }, ja: { q: "フクロウのペリット（吐きもどし）とは何？", a: ["羽で作った巣", "吐き出した骨と毛", "求愛の鳴き声", "やわらかい綿毛"], x: "フクロウはネズミを丸飲みし、消化できない骨や毛をあとでかたまりにして吐き出します。", k: "ペリット：吐き出した骨と毛" }, it: { q: "Cos’è una borra di gufo?", a: ["Un nido di piume", "Ossa e pelo rigurgitati", "Un richiamo di corteggiamento", "Piumino morbido"], x: "I gufi inghiottono i topi interi e poi rigurgitano ossa e pelo indigeribili in una pallottola compatta.", k: "Borra: ossa e pelo rigurgitati" } } },
  { id: "a10", lvl: 1, type: "text", right: 3, t: { de: { q: "Welcher ist der häufigste Greifvogel in Deutschland?", a: ["Rotmilan", "Habicht", "Seeadler", "Mäusebussard"], x: "Der Mäusebussard ist der häufigste Greifvogel Deutschlands. Man sieht ihn oft auf Zaunpfählen an Feldern sitzen.", k: "Mäusebussard: häufigster Greifvogel bei uns" }, en: { q: "Which is the most common bird of prey in Germany?", a: ["Red kite", "Goshawk", "White-tailed eagle", "Common buzzard"], x: "The common buzzard is Germany's most common bird of prey, often seen perched on fence posts by fields.", k: "Common buzzard: Germany's commonest raptor" }, fr: { q: "Quel est le rapace le plus commun en Allemagne ?", a: ["Milan royal", "Autour des palombes", "Pygargue à queue blanche", "Buse variable"], x: "La buse variable est le rapace le plus commun d'Allemagne, souvent perchée sur des piquets au bord des champs.", k: "Buse variable : rapace le plus courant en Allemagne" }, es: { q: "¿Cuál es el ave rapaz más común en Alemania?", a: ["Milano real", "Azor común", "Pigargo europeo", "Busardo ratonero"], x: "El busardo ratonero es la rapaz más común de Alemania; suele posarse en postes junto a los campos.", k: "Busardo ratonero: rapaz más común en Alemania" }, pt: { q: "Qual é a ave de rapina mais comum na Alemanha?", a: ["Milhafre-real", "Açor", "Águia-rabalva", "Águia-de-asa-redonda"], x: "A águia-de-asa-redonda é a ave de rapina mais comum da Alemanha; costuma pousar em postes ao lado dos campos.", k: "Águia-de-asa-redonda: rapina mais comum na Alemanha" }, ja: { q: "ドイツでいちばん多い猛禽類は？", a: ["アカトビ", "オオタカ", "オジロワシ", "ヨーロッパノスリ"], x: "ヨーロッパノスリはドイツでいちばん多い猛禽類。畑のそばの杭によくとまっています。", k: "ヨーロッパノスリ：ドイツでいちばん多い猛禽" }, it: { q: "Qual è il rapace più comune in Germania?", a: ["Nibbio reale", "Astore", "Aquila di mare", "Poiana"], x: "La poiana è il rapace più comune in Germania; la si vede spesso sui pali ai margini dei campi.", k: "Poiana: rapace più comune in Germania" } } },
  { id: "a11", lvl: 1, type: "tf", right: 1, t: { de: { q: "Das Reh ist das Weibchen des Hirsches.", a: ["Wahr", "Falsch"], x: "Falsch! Reh und Rothirsch sind zwei verschiedene Arten. Das Rehmännchen heißt Rehbock, das Weibchen Ricke.", k: "Reh: nicht die Frau vom Hirsch" }, en: { q: "The roe deer is the female of the red deer.", a: ["True", "False"], x: "False! Roe deer and red deer are two separate species. Roe deer are much smaller than red deer.", k: "Roe deer: not the female of the red deer" }, fr: { q: "Le chevreuil est la femelle du cerf.", a: ["Vrai", "Faux"], x: "Faux ! Chevreuil et cerf élaphe sont deux espèces différentes. La femelle du cerf s'appelle la biche.", k: "Chevreuil : pas la femelle du cerf" }, es: { q: "El corzo es la hembra del ciervo.", a: ["Verdadero", "Falso"], x: "¡Falso! El corzo y el ciervo rojo son dos especies distintas. El corzo es mucho más pequeño.", k: "Corzo: no es la hembra del ciervo" }, pt: { q: "O corço é a fêmea do veado.", a: ["Verdadeiro", "Falso"], x: "Falso! O corço e o veado-vermelho são duas espécies diferentes. O corço é bem menor.", k: "Corço: não é a fêmea do veado" }, ja: { q: "正しい？まちがい？ ノロジカはアカシカのメスのこと。", a: ["正しい", "まちがい"], x: "まちがい！ノロジカとアカシカは別の種。ノロジカはアカシカよりずっと小さいです。", k: "ノロジカ：アカシカのメスではない" }, it: { q: "Vero o falso? Il capriolo è la femmina del cervo.", a: ["Vero", "Falso"], x: "Falso! Capriolo e cervo nobile sono due specie diverse. Il capriolo è molto più piccolo del cervo.", k: "Capriolo: non è la femmina del cervo" } } },
  { id: "a12", lvl: 1, type: "text", right: 0, t: { de: { q: "Welches ist die größte Hirschart der Welt?", a: ["Elch", "Rothirsch", "Rentier", "Damhirsch"], x: "Der Elch ist der größte Hirsch der Welt. Große Bullen erreichen etwa 2 m Schulterhöhe und tragen schaufelförmige Geweihe.", k: "Elch: größter Hirsch der Welt" }, en: { q: "Which is the largest species of deer in the world?", a: ["Moose (elk)", "Red deer", "Reindeer", "Fallow deer"], x: "The moose is the largest deer in the world. Big bulls reach about 2 m at the shoulder and carry broad, flat antlers.", k: "Moose: largest deer in the world" }, fr: { q: "Quelle est la plus grande espèce de cerf au monde ?", a: ["Élan", "Cerf élaphe", "Renne", "Daim"], x: "L'élan est le plus grand cervidé du monde. Les grands mâles atteignent environ 2 m au garrot et portent des bois en pelle.", k: "Élan : plus grand cerf du monde" }, es: { q: "¿Cuál es la especie de ciervo más grande del mundo?", a: ["Alce", "Ciervo rojo", "Reno", "Gamo"], x: "El alce es el cérvido más grande del mundo. Los machos grandes alcanzan unos 2 m a la cruz y tienen astas en forma de pala.", k: "Alce: mayor ciervo del mundo" }, pt: { q: "Qual é a maior espécie de cervo do mundo?", a: ["Alce", "Veado-vermelho", "Rena", "Gamo"], x: "O alce é o maior cervídeo do mundo. Os machos grandes chegam a uns 2 m na cernelha e têm chifres em forma de pá.", k: "Alce: maior cervo do mundo" }, ja: { q: "世界最大のシカは？", a: ["ヘラジカ", "アカシカ", "トナカイ", "ダマジカ"], x: "ヘラジカは世界最大のシカ。大きなオスは肩の高さが約2メートルで、幅広い平らな角をもちます。", k: "ヘラジカ：世界最大のシカ" }, it: { q: "Qual è la specie di cervo più grande del mondo?", a: ["Alce", "Cervo nobile", "Renna", "Daino"], x: "L’alce è il cervo più grande del mondo. I grandi maschi arrivano a circa 2 m al garrese e hanno palchi larghi e piatti.", k: "Alce: il cervo più grande del mondo" } } },
  { id: "a13", lvl: 1, type: "text", right: 2, t: { de: { q: "Welche ist die größte Eule Europas?", a: ["Waldkauz", "Schleiereule", "Uhu", "Waldohreule"], x: "Der Uhu ist Europas größte Eule, mit bis zu etwa 1,8 m Flügelspannweite. Er jagt sogar Igel.", k: "Uhu: größte Eule Europas" }, en: { q: "Which is the largest owl in Europe?", a: ["Tawny owl", "Barn owl", "Eurasian eagle-owl", "Long-eared owl"], x: "The eagle-owl is Europe's largest owl, with a wingspan of up to about 1.8 m. It even hunts hedgehogs.", k: "Eagle-owl: largest owl in Europe" }, fr: { q: "Quel est le plus grand rapace nocturne d'Europe ?", a: ["Chouette hulotte", "Effraie des clochers", "Grand-duc d'Europe", "Hibou moyen-duc"], x: "Le grand-duc est le plus grand rapace nocturne d'Europe : jusqu'à environ 1,8 m d'envergure. Il chasse même le hérisson.", k: "Grand-duc : plus grande chouette d’Europe" }, es: { q: "¿Cuál es el búho más grande de Europa?", a: ["Cárabo común", "Lechuza común", "Búho real", "Búho chico"], x: "El búho real es el mayor búho de Europa, con hasta unos 1,8 m de envergadura. Incluso caza erizos.", k: "Búho real: mayor búho de Europa" }, pt: { q: "Qual é a maior coruja da Europa?", a: ["Coruja-do-mato", "Suindara", "Bufo-real", "Bufo-pequeno"], x: "O bufo-real é a maior coruja da Europa, com até uns 1,8 m de envergadura. Ele caça até ouriços.", k: "Bufo-real: maior coruja da Europa" }, ja: { q: "ヨーロッパ最大のフクロウは？", a: ["モリフクロウ", "メンフクロウ", "ワシミミズク", "トラフズク"], x: "ワシミミズクはヨーロッパ最大のフクロウで、翼を広げると最大約1.8メートル。ハリネズミまで狩ります。", k: "ワシミミズク：ヨーロッパ最大のフクロウ" }, it: { q: "Qual è il gufo più grande d’Europa?", a: ["Allocco", "Barbagianni", "Gufo reale", "Gufo comune"], x: "Il gufo reale è il più grande d’Europa, con un’apertura alare fino a circa 1,8 m. Caccia persino i ricci.", k: "Gufo reale: il gufo più grande d’Europa" } } },
  { id: "a14", lvl: 1, type: "text", right: 1, t: { de: { q: "Welches dieser Tiere hält einen echten Winterschlaf?", a: ["Dachs", "Siebenschläfer", "Eichhörnchen", "Reh"], x: "Der Siebenschläfer schläft bis zu etwa 7 Monate. Dachs und Eichhörnchen halten nur Winterruhe, Rehe bleiben aktiv.", k: "Siebenschläfer: schläft bis zu 7 Monate" }, en: { q: "Which of these animals truly hibernates?", a: ["Badger", "Edible dormouse", "Red squirrel", "Roe deer"], x: "The edible dormouse sleeps for up to about 7 months. Badgers and squirrels only rest more; roe deer stay active.", k: "Edible dormouse: sleeps up to 7 months" }, fr: { q: "Lequel de ces animaux hiberne vraiment ?", a: ["Blaireau", "Loir gris", "Écureuil roux", "Chevreuil"], x: "Le loir dort jusqu’à environ 7 mois. Le blaireau et l’écureuil ne font qu’un repos hivernal, le chevreuil reste actif.", k: "Loir : dort jusqu’à 7 mois" }, es: { q: "¿Cuál de estos animales hiberna de verdad?", a: ["Tejón", "Lirón gris", "Ardilla roja", "Corzo"], x: "El lirón gris duerme hasta unos 7 meses. El tejón y la ardilla solo reducen su actividad; el corzo sigue activo.", k: "Lirón gris: duerme hasta 7 meses" }, pt: { q: "Qual destes animais hiberna de verdade?", a: ["Texugo", "Arganaz", "Esquilo-vermelho", "Corço"], x: "O arganaz dorme até uns 7 meses. O texugo e o esquilo só diminuem a atividade; o corço continua ativo.", k: "Arganaz: dorme até 7 meses" }, ja: { q: "本当の冬眠をするのはどれ？", a: ["アナグマ", "オオヤマネ", "キタリス", "ノロジカ"], x: "オオヤマネは最大約7か月眠ります。アナグマやリスは休む時間が増えるだけ、ノロジカは冬も活動します。", k: "オオヤマネ：最大7か月眠る" }, it: { q: "Quale di questi animali va davvero in letargo?", a: ["Tasso", "Ghiro", "Scoiattolo rosso", "Capriolo"], x: "Il ghiro dorme fino a circa 7 mesi. Tassi e scoiattoli riposano solo di più; i caprioli restano attivi.", k: "Ghiro: dorme fino a 7 mesi" } } },
  { id: "a15", lvl: 1, type: "text", right: 3, t: { de: { q: "Was passiert jedes Jahr mit dem Geweih eines Rothirsches?", a: ["Es wächst einfach weiter", "Es färbt sich weiß", "Es bleibt für immer gleich", "Es wird abgeworfen und wächst neu"], x: "Hirsche werfen ihr Geweih jedes Jahr ab. Das neue wächst in wenigen Monaten nach, geschützt von einer Haut, dem „Bast“.", k: "Hirsche: werfen jedes Jahr ihr Geweih ab" }, en: { q: "What happens to a red deer stag's antlers every year?", a: ["They keep growing longer", "They turn white", "They never change", "They are shed and regrow"], x: "Deer shed their antlers every year. New ones grow back within a few months, covered in skin called velvet.", k: "Deer: shed their antlers every year" }, fr: { q: "Que se passe-t-il chaque année avec les bois du cerf ?", a: ["Ils continuent de s'allonger", "Ils deviennent blancs", "Ils ne changent jamais", "Ils tombent et repoussent"], x: "Le cerf perd ses bois chaque année. De nouveaux repoussent en quelques mois, couverts d'une peau appelée velours.", k: "Cerfs : perdent leurs bois chaque année" }, es: { q: "¿Qué le pasa cada año a la cornamenta del ciervo?", a: ["Sigue creciendo sin parar", "Se vuelve blanca", "Nunca cambia", "Se cae y vuelve a crecer"], x: "Los ciervos pierden la cornamenta cada año. La nueva crece en pocos meses, cubierta de una piel llamada terciopelo.", k: "Ciervos: mudan la cornamenta cada año" }, pt: { q: "O que acontece todo ano com os chifres do veado?", a: ["Continuam crescendo sem parar", "Ficam brancos", "Nunca mudam", "Caem e crescem de novo"], x: "Os veados perdem os chifres todo ano. Os novos crescem em poucos meses, cobertos por uma pele chamada veludo.", k: "Veados: trocam a galhada todo ano" }, ja: { q: "アカシカのオスの角は毎年どうなる？", a: ["どんどん長くなる", "白くなる", "変わらない", "落ちてまた生える"], x: "シカは毎年角を落とします。新しい角は数か月で生え、袋角と呼ばれる皮ふにおおわれています。", k: "シカ：毎年角が生えかわる" }, it: { q: "Cosa succede ogni anno ai palchi del cervo maschio?", a: ["Continuano ad allungarsi", "Diventano bianchi", "Non cambiano mai", "Cadono e ricrescono"], x: "I cervi perdono i palchi ogni anno. Quelli nuovi ricrescono in pochi mesi, coperti da una pelle chiamata velluto.", k: "Cervi: perdono i palchi ogni anno" } } },
  { id: "a16", lvl: 2, type: "text", right: 1, t: { de: { q: "In welchem Land brütet etwa die Hälfte aller Rotmilane der Welt?", a: ["Spanien", "Deutschland", "Frankreich", "Polen"], x: "Etwa die Hälfte aller Rotmilane brütet in Deutschland. Man erkennt ihn am tief gegabelten, rostroten Schwanz.", k: "Rotmilan: die Hälfte brütet in Deutschland" }, en: { q: "In which country do about half of the world's red kites breed?", a: ["Spain", "Germany", "France", "Poland"], x: "About half of all red kites breed in Germany. You can recognise it by its deeply forked, rusty-red tail.", k: "Red kite: half of them breed in Germany" }, fr: { q: "Dans quel pays niche environ la moitié des milans royaux du monde ?", a: ["Espagne", "Allemagne", "France", "Pologne"], x: "Environ la moitié des milans royaux nichent en Allemagne. On le reconnaît à sa queue rousse profondément fourchue.", k: "Milan royal : la moitié niche en Allemagne" }, es: { q: "¿En qué país cría aproximadamente la mitad de los milanos reales del mundo?", a: ["España", "Alemania", "Francia", "Polonia"], x: "Cerca de la mitad de los milanos reales cría en Alemania. Se reconoce por su cola rojiza muy ahorquillada.", k: "Milano real: la mitad cría en Alemania" }, pt: { q: "Em que país se reproduz mais ou menos a metade dos milhafres-reais do mundo?", a: ["Espanha", "Alemanha", "França", "Polônia"], x: "Cerca de metade dos milhafres-reais se reproduz na Alemanha. Ele é reconhecido pela cauda avermelhada bem bifurcada.", k: "Milhafre-real: metade se reproduz na Alemanha" }, ja: { q: "世界のアカトビの約半分が繁殖している国は？", a: ["スペイン", "ドイツ", "フランス", "ポーランド"], x: "アカトビの約半分はドイツで繁殖します。深く切れこんだ赤さび色の尾が目印です。", k: "アカトビ：半分がドイツで繁殖" }, it: { q: "In quale paese nidifica circa metà dei nibbi reali del mondo?", a: ["Spagna", "Germania", "Francia", "Polonia"], x: "Circa metà dei nibbi reali nidifica in Germania. Si riconosce dalla coda rosso ruggine profondamente forcuta.", k: "Nibbio reale: metà nidifica in Germania" } } },
  { id: "a17", lvl: 2, type: "text", right: 2, t: { de: { q: "Wie lange können Mauersegler ohne Landung in der Luft bleiben?", a: ["Höchstens einen Tag", "Etwa eine Woche", "Bis zu etwa 10 Monate", "Ihr ganzes Leben lang"], x: "Manche Mauersegler bleiben bis zu etwa 10 Monate ununterbrochen in der Luft. Sie fressen und trinken im Flug und landen nur zum Brüten.", k: "Mauersegler: bis zu 10 Monate in der Luft" }, en: { q: "How long can common swifts stay in the air without landing?", a: ["One day at most", "About a week", "Up to about 10 months", "Their whole life"], x: "Some swifts stay airborne for up to about 10 months non-stop. They eat and drink in flight and land only to breed.", k: "Swifts: up to 10 months in the air" }, fr: { q: "Combien de temps les martinets noirs peuvent-ils rester en l'air sans se poser ?", a: ["Un jour au maximum", "Environ une semaine", "Jusqu'à environ 10 mois", "Toute leur vie"], x: "Certains martinets restent jusqu'à environ 10 mois en vol sans arrêt. Ils mangent et boivent en vol et ne se posent que pour nicher.", k: "Martinets : jusqu’à 10 mois en vol" }, es: { q: "¿Cuánto tiempo pueden pasar los vencejos comunes en el aire sin posarse?", a: ["Un día como máximo", "Una semana más o menos", "Hasta unos 10 meses", "Toda su vida"], x: "Algunos vencejos pasan hasta unos 10 meses volando sin parar. Comen y beben en vuelo y solo se posan para criar.", k: "Vencejos: hasta 10 meses en el aire" }, pt: { q: "Quanto tempo os andorinhões-pretos podem passar no ar sem pousar?", a: ["No máximo um dia", "Mais ou menos uma semana", "Até uns 10 meses", "A vida inteira"], x: "Alguns andorinhões passam até uns 10 meses voando sem parar. Comem e bebem em voo e só pousam para se reproduzir.", k: "Andorinhões: até 10 meses no ar" }, ja: { q: "ヨーロッパアマツバメは、着地せずにどれくらい空にいられる？", a: ["最大1日", "約1週間", "最大約10か月", "一生ずっと"], x: "最大約10か月、休まず飛び続けるアマツバメもいます。飛びながら食べて飲み、着地するのは子育てのときだけ。", k: "アマツバメ：最大10か月空の上" }, it: { q: "Per quanto tempo i rondoni comuni restano in aria senza posarsi?", a: ["Al massimo un giorno", "Circa una settimana", "Fino a circa 10 mesi", "Tutta la vita"], x: "Alcuni rondoni restano in volo fino a circa 10 mesi senza sosta. Mangiano e bevono in volo e si posano solo per nidificare.", k: "Rondoni: fino a 10 mesi in volo" } } },
  { id: "a18", lvl: 2, type: "text", right: 0, t: { de: { q: "Warum sind die Nagezähne des Bibers orange?", a: ["Eisen im Zahnschmelz", "Farbstoff aus Baumrinde", "Eine Zahnkrankheit", "Sie sind mit Blut gefüllt"], x: "Eingelagertes Eisen färbt den Zahnschmelz orange und macht ihn besonders hart – ideal zum Fällen von Bäumen.", k: "Biber: orange Zähne dank Eisen" }, en: { q: "Why are a beaver's front teeth orange?", a: ["Iron in the enamel", "Dye from tree bark", "A tooth disease", "They are full of blood"], x: "Iron in the enamel turns it orange and makes it extra hard – perfect for felling trees.", k: "Beaver: orange teeth thanks to iron" }, fr: { q: "Pourquoi les incisives du castor sont-elles orange ?", a: ["Du fer dans l'émail", "Un pigment de l'écorce", "Une maladie dentaire", "Elles sont pleines de sang"], x: "Le fer présent dans l'émail le colore en orange et le rend très dur, idéal pour abattre des arbres.", k: "Castor : dents orange grâce au fer" }, es: { q: "¿Por qué los incisivos del castor son naranjas?", a: ["Hierro en el esmalte", "Tinte de la corteza", "Una enfermedad dental", "Están llenos de sangre"], x: "El hierro del esmalte lo vuelve naranja y muy duro, ideal para talar árboles.", k: "Castor: dientes naranjas por el hierro" }, pt: { q: "Por que os dentes da frente do castor são laranja?", a: ["Ferro no esmalte", "Tinta da casca das árvores", "Uma doença dental", "Estão cheios de sangue"], x: "O ferro no esmalte deixa os dentes laranja e muito duros – ideais para derrubar árvores.", k: "Castor: dentes laranja por causa do ferro" }, ja: { q: "ビーバーの前歯がオレンジ色なのはなぜ？", a: ["エナメル質に鉄がふくまれる", "木の皮の色がつく", "歯の病気", "血がつまっている"], x: "エナメル質の鉄でオレンジ色になり、とてもかたくなります。木を切りたおすのにぴったり。", k: "ビーバー：鉄で歯がオレンジ色" }, it: { q: "Perché gli incisivi del castoro sono arancioni?", a: ["Ferro nello smalto", "Colore della corteccia", "Una malattia dei denti", "Sono pieni di sangue"], x: "Il ferro nello smalto lo rende arancione ed extra duro: perfetto per abbattere alberi.", k: "Castoro: denti arancioni grazie al ferro" } } },
  { id: "a19", lvl: 2, type: "text", right: 3, t: { de: { q: "Warum fliegen Weißstörche auf dem Weg nach Afrika nicht einfach übers Mittelmeer?", a: ["Sie haben Angst vor Möwen", "Sie können nicht schwimmen", "Über dem Meer ist es zu kalt", "Über Wasser fehlen warme Aufwinde"], x: "Störche segeln in warmen Aufwinden, die über Land entstehen, kaum aber über dem Meer. Daher ziehen sie über Gibraltar oder den Bosporus.", k: "Störche: meiden den Flug übers Meer" }, en: { q: "Why don't white storks simply fly across the Mediterranean to Africa?", a: ["They fear seagulls", "They cannot swim", "It is too cold over the sea", "There are no rising warm air currents"], x: "Storks soar on rising warm air (thermals), which forms over land but hardly over sea. So they detour via Gibraltar or the Bosporus.", k: "Storks: avoid flying over the sea" }, fr: { q: "Pourquoi les cigognes blanches ne traversent-elles pas simplement la Méditerranée ?", a: ["Elles ont peur des mouettes", "Elles ne savent pas nager", "Il fait trop froid sur la mer", "Il n'y a pas d'ascendances chaudes"], x: "Les cigognes planent sur l'air chaud ascendant, présent sur terre mais rare sur la mer. Elles passent donc par Gibraltar ou le Bosphore.", k: "Cigognes : évitent de survoler la mer" }, es: { q: "¿Por qué las cigüeñas blancas no cruzan directamente el Mediterráneo?", a: ["Temen a las gaviotas", "No saben nadar", "Hace demasiado frío sobre el mar", "Faltan corrientes de aire cálido"], x: "Las cigüeñas planean con corrientes térmicas, que se forman sobre tierra y apenas sobre el mar. Por eso pasan por Gibraltar o el Bósforo.", k: "Cigüeñas: evitan volar sobre el mar" }, pt: { q: "Por que as cegonhas-brancas não atravessam direto o Mediterrâneo?", a: ["Têm medo das gaivotas", "Não sabem nadar", "É frio demais sobre o mar", "Faltam correntes de ar quente"], x: "As cegonhas planam com correntes térmicas, que se formam sobre a terra e quase não sobre o mar. Por isso passam por Gibraltar ou pelo Bósforo.", k: "Cegonhas: evitam voar sobre o mar" }, ja: { q: "シュバシコウが地中海をまっすぐ渡ってアフリカへ行かないのはなぜ？", a: ["カモメがこわい", "泳げない", "海の上は寒すぎる", "上昇する暖かい空気がない"], x: "コウノトリは上昇気流に乗って飛びます。上昇気流は陸の上ではできますが、海の上ではほとんどできません。だからジブラルタルやボスポラスを回り道します。", k: "コウノトリ：海の上を飛ぶのを避ける" }, it: { q: "Perché le cicogne bianche non attraversano semplicemente il Mediterraneo verso l’Africa?", a: ["Hanno paura dei gabbiani", "Non sanno nuotare", "Sul mare fa troppo freddo", "Mancano le correnti d’aria calda ascendenti"], x: "Le cicogne planano sulle correnti ascensionali calde, che si formano sulla terra ma quasi non sul mare. Per questo fanno il giro da Gibilterra o dal Bosforo.", k: "Cicogne: evitano di volare sul mare" } } },
  { id: "a20", lvl: 2, type: "text", right: 1, t: { de: { q: "Welcher Vogel „pflanzt“ durch vergessene Wintervorräte viele neue Eichen?", a: ["Buntspecht", "Eichelhäher", "Amsel", "Ringeltaube"], x: "Der Eichelhäher versteckt im Herbst tausende Eicheln im Boden. Was er nicht wiederfindet, kann zu neuen Eichen keimen.", k: "Eichelhäher: pflanzt Eichen durch Vergessen" }, en: { q: "Which bird 'plants' many new oak trees through forgotten winter stores?", a: ["Great spotted woodpecker", "Eurasian jay", "Blackbird", "Wood pigeon"], x: "In autumn the jay hides thousands of acorns in the ground. Those it never finds again can sprout into new oaks.", k: "Jay: plants oaks by forgetting acorns" }, fr: { q: "Quel oiseau « plante » de nombreux chênes grâce à ses réserves oubliées ?", a: ["Pic épeiche", "Geai des chênes", "Merle noir", "Pigeon ramier"], x: "En automne, le geai cache des milliers de glands dans le sol. Ceux qu'il oublie peuvent germer et devenir des chênes.", k: "Geai : plante des chênes en oubliant ses glands" }, es: { q: "¿Qué ave «planta» muchos robles nuevos con sus despensas olvidadas?", a: ["Pico picapinos", "Arrendajo", "Mirlo común", "Paloma torcaz"], x: "En otoño, el arrendajo esconde miles de bellotas en el suelo. Las que olvida pueden germinar y convertirse en robles.", k: "Arrendajo: planta robles al olvidar bellotas" }, pt: { q: "Que ave “planta” muitos carvalhos novos com suas despensas esquecidas?", a: ["Pica-pau-malhado-grande", "Gaio", "Melro", "Pombo-torcaz"], x: "No outono, o gaio esconde milhares de bolotas no chão. As que ele esquece podem germinar e virar carvalhos.", k: "Gaio: planta carvalhos ao esquecer bolotas" }, ja: { q: "冬のたくわえを忘れることで、たくさんのカシの木を「植える」鳥は？", a: ["アカゲラ", "カケス", "クロウタドリ", "モリバト"], x: "カケスは秋に何千個ものドングリを地面にかくします。見つけられなかったドングリが芽を出し、新しいカシになります。", k: "カケス：ドングリを忘れてカシを植える" }, it: { q: "Quale uccello «pianta» molte nuove querce grazie alle provviste invernali dimenticate?", a: ["Picchio rosso maggiore", "Ghiandaia", "Merlo", "Colombaccio"], x: "In autunno la ghiandaia nasconde migliaia di ghiande nel terreno. Quelle che non ritrova possono germogliare in nuove querce.", k: "Ghiandaia: pianta querce dimenticando le ghiande" } } },
  { id: "a21", lvl: 2, type: "text", right: 2, t: { de: { q: "Wo brütet der Eisvogel?", a: ["In einem Nest im Schilf", "In einer Baumhöhle", "In einer selbst gegrabenen Erdröhre", "In einer Mulde am Strand"], x: "Der Eisvogel gräbt mit dem Schnabel eine oft fast meterlange Röhre in steile Uferwände. Am Ende liegt die Brutkammer.", k: "Eisvogel: gräbt Tunnel ins Ufer" }, en: { q: "Where does the kingfisher nest?", a: ["In a reed nest", "In a tree hole", "In a burrow it digs itself", "In a hollow on the beach"], x: "The kingfisher digs a tunnel, often almost a metre long, into steep riverbanks with its bill. The nest chamber is at the end.", k: "Kingfisher: digs tunnels into riverbanks" }, fr: { q: "Où niche le martin-pêcheur ?", a: ["Dans un nid de roseaux", "Dans un trou d'arbre", "Dans un terrier qu'il creuse", "Dans un creux sur la plage"], x: "Le martin-pêcheur creuse avec son bec un tunnel souvent long de près d'un mètre dans une berge abrupte. Le nid est au fond.", k: "Martin-pêcheur : creuse un tunnel dans la berge" }, es: { q: "¿Dónde cría el martín pescador?", a: ["En un nido entre juncos", "En el hueco de un árbol", "En un túnel que excava él mismo", "En un hoyo en la playa"], x: "El martín pescador excava con el pico un túnel de casi un metro en taludes de ríos. Al fondo está el nido.", k: "Martín pescador: excava túneles en la orilla" }, pt: { q: "Onde o guarda-rios faz o ninho?", a: ["Num ninho entre juncos", "No oco de uma árvore", "Num túnel que ele mesmo cava", "Num buraco na praia"], x: "O guarda-rios cava com o bico um túnel de quase um metro em barrancos de rios. No fundo fica o ninho.", k: "Martim-pescador: cava túneis no barranco" }, ja: { q: "カワセミはどこに巣を作る？", a: ["ヨシの巣", "木の穴", "自分で掘ったトンネル", "砂浜のくぼみ"], x: "カワセミはくちばしで川のがけに、長さ1メートル近いトンネルを掘ります。巣は一番奥にあります。", k: "カワセミ：川岸にトンネルを掘る" }, it: { q: "Dove nidifica il martin pescatore?", a: ["In un nido di canne", "In un buco d’albero", "In una galleria che scava da sé", "In una buca sulla spiaggia"], x: "Il martin pescatore scava col becco una galleria, spesso lunga quasi un metro, nelle rive ripide. La camera del nido è in fondo.", k: "Martin pescatore: scava gallerie nelle rive" } } },
  { id: "a22", lvl: 2, type: "text", right: 0, t: { de: { q: "Warum können Fledermäuse kopfüber hängend schlafen, ohne sich anzustrengen?", a: ["Ihr Gewicht schließt die Krallen", "Sie kleben mit Speichel fest", "Sie haben Saugnäpfe an den Füßen", "Sie spannen dauernd die Muskeln an"], x: "Ein Sehnen-Mechanismus hält die Zehen geschlossen, solange das Körpergewicht daran zieht. So kostet das Hängen keine Kraft.", k: "Fledermäuse: hängen ohne Kraft kopfüber" }, en: { q: "Why can bats sleep hanging upside down without any effort?", a: ["Their weight locks their claws", "They stick on with saliva", "They have suction pads on their feet", "They keep their muscles tensed"], x: "A tendon mechanism keeps the toes closed while the body weight pulls on them, so hanging costs no effort.", k: "Bats: hang upside down effortlessly" }, fr: { q: "Pourquoi les chauves-souris peuvent-elles dormir suspendues sans effort ?", a: ["Leur poids verrouille leurs griffes", "Elles se collent avec leur salive", "Elles ont des ventouses aux pieds", "Elles gardent les muscles contractés"], x: "Un mécanisme de tendons garde les orteils fermés tant que le poids du corps tire dessus : rester suspendue ne coûte aucun effort.", k: "Chauves-souris : pendues sans effort" }, es: { q: "¿Por qué los murciélagos pueden dormir colgados sin hacer esfuerzo?", a: ["Su peso bloquea sus garras", "Se pegan con saliva", "Tienen ventosas en las patas", "Tensan los músculos todo el rato"], x: "Un mecanismo de tendones mantiene los dedos cerrados mientras el peso del cuerpo tira de ellos: colgar no les cuesta esfuerzo.", k: "Murciélagos: cuelgan sin esfuerzo" }, pt: { q: "Por que os morcegos conseguem dormir pendurados sem fazer força?", a: ["O peso deles trava as garras", "Grudam-se com saliva", "Têm ventosas nos pés", "Contraem os músculos o tempo todo"], x: "Um mecanismo de tendões mantém os dedos fechados enquanto o peso do corpo puxa: ficar pendurado não custa esforço.", k: "Morcegos: ficam de cabeça para baixo sem esforço" }, ja: { q: "コウモリが力を使わずに逆さまにぶら下がって眠れるのはなぜ？", a: ["体重でつめがロックされる", "唾液でくっつく", "足に吸盤がある", "筋肉に力を入れ続ける"], x: "腱のしくみで、体重がかかると指が閉じたままになります。だからぶら下がるのに力がいらないのです。", k: "コウモリ：力を使わずぶら下がる" }, it: { q: "Perché i pipistrelli dormono appesi a testa in giù senza fatica?", a: ["Il loro peso blocca gli artigli", "Si attaccano con la saliva", "Hanno ventose sui piedi", "Tengono i muscoli in tensione"], x: "Un meccanismo dei tendini tiene le dita chiuse mentre il peso del corpo tira: stare appesi non costa fatica.", k: "Pipistrelli: appesi senza fatica" } } },
  { id: "a23", lvl: 2, type: "text", right: 2, t: { de: { q: "Wie viele Stacheln hat ein erwachsener Igel ungefähr?", a: ["Etwa 70", "Etwa 700", "Etwa 7.000", "Etwa 70.000"], x: "Ein erwachsener Igel trägt etwa 6.000 bis 8.000 Stacheln. Das sind umgewandelte Haare.", k: "Igel: haben rund 7.000 Stacheln" }, en: { q: "About how many spines does an adult hedgehog have?", a: ["About 70", "About 700", "About 7,000", "About 70,000"], x: "An adult hedgehog has about 6,000 to 8,000 spines. They are actually modified hairs.", k: "Hedgehogs: have about 7,000 spines" }, fr: { q: "Combien de piquants un hérisson adulte a-t-il environ ?", a: ["Environ 70", "Environ 700", "Environ 7 000", "Environ 70 000"], x: "Un hérisson adulte porte environ 6 000 à 8 000 piquants. Ce sont des poils transformés.", k: "Hérissons : environ 7 000 piquants" }, es: { q: "¿Aproximadamente cuántas púas tiene un erizo adulto?", a: ["Unas 70", "Unas 700", "Unas 7.000", "Unas 70.000"], x: "Un erizo adulto tiene unas 6.000 a 8.000 púas. Son pelos modificados.", k: "Erizos: unas 7.000 púas" }, pt: { q: "Mais ou menos quantos espinhos tem um ouriço adulto?", a: ["Uns 70", "Uns 700", "Uns 7.000", "Uns 70.000"], x: "Um ouriço adulto tem uns 6.000 a 8.000 espinhos. São pelos modificados.", k: "Ouriços: uns 7.000 espinhos" }, ja: { q: "大人のハリネズミのトゲはだいたい何本？", a: ["約70本", "約700本", "約7000本", "約7万本"], x: "大人のハリネズミには約6000〜8000本のトゲがあります。トゲは毛が変化したものです。", k: "ハリネズミ：トゲは約7000本" }, it: { q: "Quanti aculei ha più o meno un riccio adulto?", a: ["Circa 70", "Circa 700", "Circa 7.000", "Circa 70.000"], x: "Un riccio adulto ha circa 6.000–8.000 aculei. In realtà sono peli trasformati.", k: "Ricci: circa 7.000 aculei" } } },
  { id: "a24", lvl: 2, type: "text", right: 3, t: { de: { q: "Mit welchem dieser Tiere ist die Spitzmaus am nächsten verwandt?", a: ["Hausmaus", "Eichhörnchen", "Wildkaninchen", "Maulwurf"], x: "Spitzmäuse sind trotz des Namens keine Nagetiere. Sie gehören wie Maulwurf und Igel zu den Insektenfressern.", k: "Spitzmaus: keine Maus, sondern Insektenfresser" }, en: { q: "Which of these animals is the shrew most closely related to?", a: ["House mouse", "Red squirrel", "Rabbit", "Mole"], x: "Despite looking like mice, shrews aren't rodents. Like moles and hedgehogs, they belong to the insectivores.", k: "Shrew: not a mouse but an insectivore" }, fr: { q: "De quel animal la musaraigne est-elle la plus proche parente ?", a: ["Souris domestique", "Écureuil roux", "Lapin", "Taupe"], x: "Malgré leur air de souris, les musaraignes ne sont pas des rongeurs. Comme la taupe et le hérisson, ce sont des insectivores.", k: "Musaraigne : pas une souris, un insectivore" }, es: { q: "¿Con cuál de estos animales está más emparentada la musaraña?", a: ["Ratón doméstico", "Ardilla roja", "Conejo", "Topo"], x: "Aunque parezcan ratones, las musarañas no son roedores. Como el topo y el erizo, son insectívoros.", k: "Musaraña: no es un ratón, sino un insectívoro" }, pt: { q: "Com qual destes animais o musaranho é mais aparentado?", a: ["Camundongo", "Esquilo-vermelho", "Coelho", "Toupeira"], x: "Embora pareçam ratos, os musaranhos não são roedores. Como a toupeira e o ouriço, são insetívoros.", k: "Musaranho: não é rato, é insetívoro" }, ja: { q: "トガリネズミにいちばん近い親せきは？", a: ["ハツカネズミ", "キタリス", "ウサギ", "モグラ"], x: "ネズミに似ていますが、トガリネズミはげっ歯類ではありません。モグラやハリネズミと同じ食虫類の仲間です。", k: "トガリネズミ：ネズミではなく食虫類" }, it: { q: "Di quale di questi animali è più vicino parente il toporagno?", a: ["Topo domestico", "Scoiattolo rosso", "Coniglio", "Talpa"], x: "Anche se sembrano topi, i toporagni non sono roditori. Come talpe e ricci, appartengono agli insettivori.", k: "Toporagno: non è un topo ma un insettivoro" } } },
  { id: "a25", lvl: 2, type: "text", right: 0, t: { de: { q: "Was unterscheidet junge Feldhasen bei der Geburt von jungen Wildkaninchen?", a: ["Hasen haben Fell und offene Augen", "Hasen sind nackt und blind", "Hasen schlüpfen aus Eiern", "Es gibt keinen Unterschied"], x: "Junghasen kommen behaart und sehend in einer offenen Mulde zur Welt. Kaninchen werden nackt und blind im Bau geboren.", k: "Junghasen: mit Fell und offenen Augen geboren" }, en: { q: "How do newborn brown hares differ from newborn rabbits?", a: ["Hares have fur and open eyes", "Hares are naked and blind", "Hares hatch from eggs", "There is no difference"], x: "Young hares are born furred and with open eyes in a shallow hollow. Rabbits are born naked and blind in a burrow.", k: "Young hares: born furry with open eyes" }, fr: { q: "En quoi les levrauts nouveau-nés diffèrent-ils des lapereaux ?", a: ["Ils ont du poil et les yeux ouverts", "Ils sont nus et aveugles", "Ils sortent d'un œuf", "Il n'y a aucune différence"], x: "Les levrauts naissent poilus et les yeux ouverts dans un simple creux. Les lapereaux naissent nus et aveugles dans un terrier.", k: "Levrauts : naissent poilus, yeux ouverts" }, es: { q: "¿En qué se diferencian los lebratos recién nacidos de las crías de conejo?", a: ["Tienen pelo y ojos abiertos", "Nacen desnudos y ciegos", "Salen de un huevo", "No hay ninguna diferencia"], x: "Los lebratos nacen con pelo y ojos abiertos en un simple hoyo. Los conejos nacen desnudos y ciegos en una madriguera.", k: "Lebratos: nacen con pelo y ojos abiertos" }, pt: { q: "Em que os filhotes de lebre recém-nascidos são diferentes dos filhotes de coelho?", a: ["Têm pelo e olhos abertos", "Nascem pelados e cegos", "Saem de um ovo", "Não há diferença"], x: "Os filhotes de lebre nascem com pelo e olhos abertos num buraco simples. Os de coelho nascem pelados e cegos numa toca.", k: "Filhotes de lebre: nascem com pelo e olhos abertos" }, ja: { q: "生まれたてのヤブノウサギは、アナウサギの赤ちゃんとどうちがう？", a: ["毛があって目が開いている", "毛がなく目が見えない", "卵からかえる", "ちがいはない"], x: "ノウサギの赤ちゃんは、浅いくぼみで毛が生えて目が開いた状態で生まれます。アナウサギは巣穴で、毛がなく目も見えない状態で生まれます。", k: "ノウサギの赤ちゃん：毛があり目も開いて生まれる" }, it: { q: "In cosa differiscono i leprotti appena nati dai coniglietti?", a: ["I leprotti hanno pelo e occhi aperti", "I leprotti sono nudi e ciechi", "I leprotti nascono da uova", "Non c’è differenza"], x: "I leprotti nascono con il pelo e gli occhi aperti in una piccola conca. I conigli nascono nudi e ciechi in una tana.", k: "Leprotti: nascono col pelo e occhi aperti" } } },
  { id: "a26", lvl: 2, type: "text", right: 1, t: { de: { q: "Wie hält sich der Fischotter im kalten Wasser warm?", a: ["Mit einer dicken Speckschicht", "Mit extrem dichtem Fell", "Durch ständiges Zittern", "Gar nicht – er friert"], x: "Der Otter hat kaum Speck, aber eines der dichtesten Felle aller Tiere. Darin hält sich eine isolierende Luftschicht.", k: "Fischotter: eines der dichtesten Felle der Welt" }, en: { q: "How does the Eurasian otter keep warm in cold water?", a: ["A thick layer of blubber", "Extremely dense fur", "Constant shivering", "It doesn't – it just freezes"], x: "Otters have little fat but one of the densest furs of any animal. It traps an insulating layer of air.", k: "Otter: one of the densest furs on Earth" }, fr: { q: "Comment la loutre d'Europe se protège-t-elle de l'eau froide ?", a: ["Une épaisse couche de graisse", "Une fourrure extrêmement dense", "En frissonnant sans cesse", "Elle ne se protège pas"], x: "La loutre a peu de graisse, mais l'une des fourrures les plus denses du règne animal, qui retient une couche d'air isolante.", k: "Loutre : une des fourrures les plus denses" }, es: { q: "¿Cómo se mantiene caliente la nutria europea en el agua fría?", a: ["Una gruesa capa de grasa", "Un pelaje densísimo", "Tiritando sin parar", "No lo hace: pasa frío"], x: "La nutria apenas tiene grasa, pero sí uno de los pelajes más densos del reino animal, que atrapa una capa de aire aislante.", k: "Nutria: uno de los pelajes más densos" }, pt: { q: "Como a lontra-europeia se mantém aquecida na água fria?", a: ["Uma grossa camada de gordura", "Um pelo densíssimo", "Tremendo sem parar", "Não se mantém: passa frio"], x: "A lontra quase não tem gordura, mas tem um dos pelos mais densos do reino animal, que prende uma camada de ar isolante.", k: "Lontra: um dos pelos mais densos do mundo" }, ja: { q: "ユーラシアカワウソは冷たい水の中でどうやって体を温める？", a: ["厚い脂肪の層", "とても密な毛皮", "ずっとふるえている", "温めない。ただ寒がる"], x: "カワウソは脂肪が少ないかわりに、動物でもトップクラスに密な毛皮をもっています。毛の間に空気の層をためて断熱します。", k: "カワウソ：世界有数の密な毛皮" }, it: { q: "Come si tiene al caldo la lontra nell’acqua fredda?", a: ["Uno spesso strato di grasso", "Una pelliccia fittissima", "Tremando di continuo", "Non lo fa: ha solo freddo"], x: "Le lontre hanno poco grasso ma una delle pellicce più fitte del regno animale, che trattiene uno strato isolante d’aria.", k: "Lontra: una delle pellicce più fitte" } } },
  { id: "a27", lvl: 2, type: "text", right: 2, t: { de: { q: "Woher stammt der Marderhund, der heute auch in Deutschland lebt?", a: ["Nordamerika", "Südamerika", "Ostasien", "Australien"], x: "Der Marderhund stammt aus Ostasien. Er wurde in Osteuropa als Pelztier ausgesetzt und breitete sich bis zu uns aus.", k: "Marderhund: stammt aus Ostasien" }, en: { q: "Where does the raccoon dog, now also living in Germany, originally come from?", a: ["North America", "South America", "East Asia", "Australia"], x: "The raccoon dog comes from East Asia. It was released in Eastern Europe for its fur and spread west as far as Germany.", k: "Raccoon dog: comes from East Asia" }, fr: { q: "D'où vient à l'origine le chien viverrin, présent aujourd'hui en Allemagne ?", a: ["Amérique du Nord", "Amérique du Sud", "Asie de l'Est", "Australie"], x: "Le chien viverrin vient d'Asie de l'Est. Relâché en Europe de l'Est pour sa fourrure, il s'est répandu jusqu'en Allemagne.", k: "Chien viverrin : vient d’Asie de l’Est" }, es: { q: "¿De dónde procede el perro mapache, que hoy vive también en Alemania?", a: ["Norteamérica", "Sudamérica", "Asia oriental", "Australia"], x: "El perro mapache procede de Asia oriental. Se liberó en Europa del Este por su piel y se extendió hasta Alemania.", k: "Perro mapache: viene de Asia oriental" }, pt: { q: "De onde vem o cão-guaxinim, que hoje também vive na Alemanha?", a: ["América do Norte", "América do Sul", "Ásia Oriental", "Austrália"], x: "O cão-guaxinim vem da Ásia Oriental. Foi solto no Leste Europeu por causa da pele e se espalhou até a Alemanha.", k: "Cão-guaxinim: vem do Leste Asiático" }, ja: { q: "いまドイツにもすむタヌキは、もともとどこから来た？", a: ["北アメリカ", "南アメリカ", "東アジア", "オーストラリア"], x: "タヌキは東アジア原産。毛皮のために東ヨーロッパに放され、西へ広がってドイツまで来ました。", k: "タヌキ：東アジア生まれ" }, it: { q: "Da dove viene in origine il cane procione, che oggi vive anche in Germania?", a: ["Nord America", "Sud America", "Asia orientale", "Australia"], x: "Il cane procione viene dall’Asia orientale. Fu liberato in Europa orientale per la pelliccia e si è diffuso verso ovest fino alla Germania.", k: "Cane procione: viene dall’Asia orientale" } } },
  { id: "a28", lvl: 2, type: "text", right: 0, t: { de: { q: "Welcher Vogel ist – gemeinsam mit einem nahen Verwandten – der kleinste Vogel Europas?", a: ["Wintergoldhähnchen", "Zaunkönig", "Blaumeise", "Rotkehlchen"], x: "Winter- und Sommergoldhähnchen wiegen nur etwa 5 bis 6 Gramm. Der Zaunkönig ist etwas schwerer.", k: "Wintergoldhähnchen: wiegt nur 5 Gramm" }, en: { q: "Which bird is – together with a close relative – the smallest bird in Europe?", a: ["Goldcrest", "Wren", "Blue tit", "Robin"], x: "The goldcrest and its relative the firecrest weigh only about 5 to 6 grams. The wren is a bit heavier.", k: "Goldcrest: weighs just 5 grams" }, fr: { q: "Quel oiseau est, avec un proche parent, le plus petit oiseau d'Europe ?", a: ["Roitelet huppé", "Troglodyte mignon", "Mésange bleue", "Rougegorge familier"], x: "Le roitelet huppé et le roitelet à triple bandeau ne pèsent qu'environ 5 à 6 grammes. Le troglodyte est un peu plus lourd.", k: "Roitelet : pèse seulement 5 grammes" }, es: { q: "¿Qué ave es, junto con un pariente cercano, la más pequeña de Europa?", a: ["Reyezuelo sencillo", "Chochín común", "Herrerillo común", "Petirrojo"], x: "El reyezuelo sencillo y el listado pesan solo unos 5 o 6 gramos. El chochín es algo más pesado.", k: "Reyezuelo: pesa solo 5 gramos" }, pt: { q: "Qual ave é, junto com um parente próximo, a menor da Europa?", a: ["Estrelinha-de-poupa", "Carriça", "Chapim-azul", "Pisco-de-peito-ruivo"], x: "A estrelinha-de-poupa e a estrelinha-real pesam só uns 5 ou 6 gramas. A carriça é um pouco mais pesada.", k: "Estrelinha: pesa só 5 gramas" }, ja: { q: "近い親せきと並んで、ヨーロッパでいちばん小さい鳥は？", a: ["キクイタダキ", "ミソサザイ", "アオガラ", "ヨーロッパコマドリ"], x: "キクイタダキと親せきのマミジロキクイタダキは、わずか5〜6グラム。ミソサザイはもう少し重いです。", k: "キクイタダキ：たった5グラム" }, it: { q: "Quale uccello è, insieme a un parente stretto, il più piccolo d’Europa?", a: ["Regolo", "Scricciolo", "Cinciarella", "Pettirosso"], x: "Il regolo e il suo parente fiorrancino pesano solo 5–6 grammi. Lo scricciolo è un po’ più pesante.", k: "Regolo: pesa solo 5 grammi" } } },
  { id: "a29", lvl: 2, type: "text", right: 3, t: { de: { q: "Welcher dieser Vögel legt jedes Jahr die längste Zugstrecke zurück?", a: ["Weißstorch", "Kuckuck", "Rauchschwalbe", "Küstenseeschwalbe"], x: "Die Küstenseeschwalbe pendelt jedes Jahr zwischen Arktis und Antarktis – oft mehrere zehntausend Kilometer.", k: "Küstenseeschwalbe: fliegt jedes Jahr Arktis–Antarktis" }, en: { q: "Which of these birds flies the longest migration every year?", a: ["White stork", "Cuckoo", "Barn swallow", "Arctic tern"], x: "The Arctic tern travels between the Arctic and the Antarctic every year – often tens of thousands of kilometres.", k: "Arctic tern: flies Arctic–Antarctic every year" }, fr: { q: "Lequel de ces oiseaux fait chaque année la plus longue migration ?", a: ["Cigogne blanche", "Coucou gris", "Hirondelle rustique", "Sterne arctique"], x: "La sterne arctique fait chaque année l'aller-retour entre Arctique et Antarctique : souvent des dizaines de milliers de kilomètres.", k: "Sterne arctique : Arctique–Antarctique chaque année" }, es: { q: "¿Cuál de estas aves realiza cada año la migración más larga?", a: ["Cigüeña blanca", "Cuco común", "Golondrina común", "Charrán ártico"], x: "El charrán ártico viaja cada año entre el Ártico y la Antártida: a menudo decenas de miles de kilómetros.", k: "Charrán ártico: Ártico–Antártida cada año" }, pt: { q: "Qual destas aves faz a migração mais longa todo ano?", a: ["Cegonha-branca", "Cuco", "Andorinha-das-chaminés", "Andorinha-do-mar-ártica"], x: "A andorinha-do-mar-ártica viaja todo ano entre o Ártico e a Antártida: muitas vezes dezenas de milhares de quilômetros.", k: "Trinta-réis-ártico: Ártico–Antártida todo ano" }, ja: { q: "毎年いちばん長い距離を渡る鳥は？", a: ["シュバシコウ", "カッコウ", "ツバメ", "キョクアジサシ"], x: "キョクアジサシは毎年北極と南極の間を行き来します。何万キロにもなることがよくあります。", k: "キョクアジサシ：毎年北極と南極を往復" }, it: { q: "Quale di questi uccelli compie ogni anno la migrazione più lunga?", a: ["Cicogna bianca", "Cuculo", "Rondine", "Sterna artica"], x: "La sterna artica viaggia ogni anno tra Artide e Antartide: spesso decine di migliaia di chilometri.", k: "Sterna artica: Artide–Antartide ogni anno" } } },
  { id: "a30", lvl: 2, type: "text", right: 0, t: { de: { q: "Welches ist das schwerste wild lebende Landsäugetier Europas?", a: ["Wisent", "Elch", "Braunbär", "Rothirsch"], x: "Wisentbullen werden bis zu etwa 900 kg schwer. In freier Wildbahn war der Wisent ausgestorben und wurde mit Zootieren gerettet.", k: "Wisent: Europas schwerstes Landtier" }, en: { q: "Which is the heaviest wild land mammal in Europe?", a: ["European bison", "Moose", "Brown bear", "Red deer"], x: "European bison bulls can weigh up to about 900 kg. Once extinct in the wild, the species was saved with zoo animals.", k: "European bison: Europe's heaviest land animal" }, fr: { q: "Quel est le plus lourd mammifère terrestre sauvage d'Europe ?", a: ["Bison d'Europe", "Élan", "Ours brun", "Cerf élaphe"], x: "Les mâles du bison d'Europe pèsent jusqu'à environ 900 kg. Disparu à l'état sauvage, il a été sauvé grâce aux zoos.", k: "Bison d’Europe : animal terrestre le plus lourd d’Europe" }, es: { q: "¿Cuál es el mamífero terrestre salvaje más pesado de Europa?", a: ["Bisonte europeo", "Alce", "Oso pardo", "Ciervo rojo"], x: "Los machos de bisonte europeo pesan hasta unos 900 kg. Se extinguió en libertad y se salvó gracias a animales de zoo.", k: "Bisonte europeo: el animal terrestre más pesado de Europa" }, pt: { q: "Qual é o mamífero terrestre selvagem mais pesado da Europa?", a: ["Bisão-europeu", "Alce", "Urso-pardo", "Veado-vermelho"], x: "Os machos de bisão-europeu pesam até uns 900 kg. Ele foi extinto na natureza e salvo graças a animais de zoológico.", k: "Bisão-europeu: o animal terrestre mais pesado da Europa" }, ja: { q: "ヨーロッパでいちばん重い野生の陸上哺乳類は？", a: ["ヨーロッパバイソン", "ヘラジカ", "ヒグマ", "アカシカ"], x: "ヨーロッパバイソンのオスは最大約900キロ。一度は野生で絶滅しましたが、動物園の個体で救われました。", k: "ヨーロッパバイソン：ヨーロッパ最重の陸上動物" }, it: { q: "Qual è il mammifero terrestre selvatico più pesante d’Europa?", a: ["Bisonte europeo", "Alce", "Orso bruno", "Cervo nobile"], x: "I maschi di bisonte europeo possono pesare fino a circa 900 kg. Estinto in natura, è stato salvato grazie agli animali degli zoo.", k: "Bisonte europeo: l’animale terrestre più pesante d’Europa" } } },
  { id: "a31", lvl: 2, type: "tf", right: 0, t: { de: { q: "Der Kolkrabe gehört zu den Singvögeln.", a: ["Wahr", "Falsch"], x: "Stimmt! Rabenvögel zählen zu den Singvögeln. Der Kolkrabe ist sogar der größte Singvogel der Welt.", k: "Kolkrabe: der größte Singvogel der Welt" }, en: { q: "The common raven is a songbird.", a: ["True", "False"], x: "True! Crows and ravens belong to the songbirds. The raven is even the largest songbird in the world.", k: "Raven: the largest songbird in the world" }, fr: { q: "Le grand corbeau fait partie des oiseaux chanteurs.", a: ["Vrai", "Faux"], x: "Vrai ! Les corvidés sont des oiseaux chanteurs. Le grand corbeau est même le plus grand oiseau chanteur du monde.", k: "Grand corbeau : plus grand oiseau chanteur" }, es: { q: "El cuervo grande es un ave cantora.", a: ["Verdadero", "Falso"], x: "¡Cierto! Los córvidos son aves cantoras. El cuervo grande es incluso el ave cantora más grande del mundo.", k: "Cuervo grande: mayor ave cantora del mundo" }, pt: { q: "O corvo é uma ave canora.", a: ["Verdadeiro", "Falso"], x: "Certo! Os corvídeos são aves canoras. O corvo é até a maior ave canora do mundo.", k: "Corvo: maior ave canora do mundo" }, ja: { q: "正しい？まちがい？ ワタリガラスは鳴禽類（スズメ目の歌う鳥）である。", a: ["正しい", "まちがい"], x: "正しい！カラスの仲間は鳴禽類に入ります。ワタリガラスは世界最大の鳴禽類です。", k: "ワタリガラス：世界最大の鳴禽類" }, it: { q: "Vero o falso? Il corvo imperiale è un uccello canoro.", a: ["Vero", "Falso"], x: "Vero! Corvi e cornacchie sono uccelli canori. Il corvo imperiale è addirittura il più grande uccello canoro del mondo.", k: "Corvo imperiale: il più grande uccello canoro" } } },
  { id: "a32", lvl: 2, type: "tf", right: 0, t: { de: { q: "Ein Rehkitz, das allein im hohen Gras liegt, ist meist nicht verlassen.", a: ["Wahr", "Falsch"], x: "Stimmt! Die Mutter lässt es absichtlich liegen und kommt zum Säugen zurück. Bitte nicht anfassen – sonst riecht es nach Mensch.", k: "Rehkitz allein im Gras: nicht verlassen" }, en: { q: "A fawn lying alone in tall grass has usually not been abandoned.", a: ["True", "False"], x: "True! The mother leaves it there on purpose and comes back to feed it. Please don’t touch it – or it will smell of humans.", k: "Fawn alone in the grass: not abandoned" }, fr: { q: "Un faon couché seul dans les hautes herbes n’est en général pas abandonné.", a: ["Vrai", "Faux"], x: "Vrai ! Sa mère le laisse là exprès et revient l’allaiter. Surtout ne pas le toucher – sinon il sent l’humain.", k: "Faon seul dans l’herbe : pas abandonné" }, es: { q: "Un corzo bebé tumbado solo en la hierba alta normalmente no está abandonado.", a: ["Verdadero", "Falso"], x: "¡Verdadero! La madre lo deja allí a propósito y vuelve a amamantarlo. Por favor, no lo toques: olería a humano.", k: "Cervatillo solo en la hierba: no está abandonado" }, pt: { q: "Um filhote de corço deitado sozinho no capim alto normalmente não foi abandonado.", a: ["Verdadeiro", "Falso"], x: "Verdadeiro! A mãe o deixa ali de propósito e volta para amamentá-lo. Por favor, não toque: ele ficaria com cheiro de gente.", k: "Filhote de corço sozinho: não foi abandonado" }, ja: { q: "正しい？まちがい？ 高い草の中にひとりでいるシカの赤ちゃんは、たいてい見捨てられたわけではない。", a: ["正しい", "まちがい"], x: "正しい！母親はわざとそこに置いていき、お乳をあげにもどってきます。さわらないでね。人のにおいがついてしまいます。", k: "草むらにひとりのシカの子：見捨てられていない" }, it: { q: "Vero o falso? Un cerbiatto da solo nell’erba alta di solito non è stato abbandonato.", a: ["Vero", "Falso"], x: "Vero! La madre lo lascia lì apposta e torna ad allattarlo. Non toccarlo, altrimenti prende l’odore umano.", k: "Cerbiatto da solo nell’erba: non è abbandonato" } } },
  { id: "a33", lvl: 2, type: "tf", right: 1, t: { de: { q: "Hasen und Kaninchen gehören zu den Nagetieren.", a: ["Wahr", "Falsch"], x: "Falsch! Sie bilden eine eigene Gruppe, die Hasenartigen. Hinter den oberen Nagezähnen haben sie ein zweites Paar kleiner Zähne.", k: "Hasen: keine Nagetiere" }, en: { q: "Hares and rabbits are rodents.", a: ["True", "False"], x: "False! They form their own order, the lagomorphs. Behind their upper incisors they have a second pair of small teeth.", k: "Hares: not rodents" }, fr: { q: "Les lièvres et les lapins sont des rongeurs.", a: ["Vrai", "Faux"], x: "Faux ! Ce sont des lagomorphes. Derrière leurs incisives supérieures, ils ont une seconde paire de petites dents.", k: "Lièvres : pas des rongeurs" }, es: { q: "Las liebres y los conejos son roedores.", a: ["Verdadero", "Falso"], x: "¡Falso! Son lagomorfos. Detrás de los incisivos superiores tienen un segundo par de pequeños dientes.", k: "Liebres: no son roedores" }, pt: { q: "Lebres e coelhos são roedores.", a: ["Verdadeiro", "Falso"], x: "Falso! São lagomorfos. Atrás dos dentes da frente de cima, eles têm um segundo par de dentinhos.", k: "Lebres: não são roedores" }, ja: { q: "正しい？まちがい？ ノウサギやアナウサギはげっ歯類である。", a: ["正しい", "まちがい"], x: "まちがい！ウサギは独自のグループ、ウサギ目です。上の前歯の後ろに、小さな歯がもう1対あります。", k: "ウサギ：げっ歯類ではない" }, it: { q: "Vero o falso? Lepri e conigli sono roditori.", a: ["Vero", "Falso"], x: "Falso! Formano un ordine a sé, i lagomorfi. Dietro gli incisivi superiori hanno un secondo paio di dentini.", k: "Lepri: non sono roditori" } } },
  { id: "a34", lvl: 2, type: "tf", right: 1, t: { de: { q: "Unter seinem weißen Fell hat der Eisbär ebenfalls weiße Haut.", a: ["Wahr", "Falsch"], x: "Falsch! Die Haut des Eisbären ist schwarz. Seine Haare sind eigentlich farblos und durchsichtig und wirken nur weiß.", k: "Eisbär: hat schwarze Haut" }, en: { q: "Under its white fur, a polar bear also has white skin.", a: ["True", "False"], x: "False! A polar bear's skin is black. Its hairs are actually colourless and see-through; they only look white.", k: "Polar bear: has black skin" }, fr: { q: "Sous sa fourrure blanche, l'ours polaire a aussi la peau blanche.", a: ["Vrai", "Faux"], x: "Faux ! Sa peau est noire. Ses poils sont en fait incolores et transparents : ils paraissent seulement blancs.", k: "Ours polaire : peau noire" }, es: { q: "Bajo su pelaje blanco, el oso polar también tiene la piel blanca.", a: ["Verdadero", "Falso"], x: "¡Falso! Su piel es negra. Sus pelos son en realidad incoloros y transparentes; solo parecen blancos.", k: "Oso polar: piel negra" }, pt: { q: "Debaixo do pelo branco, o urso-polar também tem a pele branca.", a: ["Verdadeiro", "Falso"], x: "Falso! A pele dele é preta. Os pelos, na verdade, são incolores e transparentes; só parecem brancos.", k: "Urso-polar: pele preta" }, ja: { q: "正しい？まちがい？ ホッキョクグマは白い毛の下の皮ふも白い。", a: ["正しい", "まちがい"], x: "まちがい！ホッキョクグマの皮ふは黒。毛は本当は無色で透き通っていて、白く見えるだけです。", k: "ホッキョクグマ：皮ふは黒い" }, it: { q: "Vero o falso? Sotto la pelliccia bianca, l’orso polare ha anche la pelle bianca.", a: ["Vero", "Falso"], x: "Falso! La pelle dell’orso polare è nera. I peli in realtà sono incolori e trasparenti; sembrano solo bianchi.", k: "Orso polare: pelle nera" } } },
  { id: "a35", lvl: 2, type: "tf", right: 0, t: { de: { q: "Schleiereulen können Mäuse in völliger Dunkelheit allein nach Gehör fangen.", a: ["Wahr", "Falsch"], x: "Stimmt! Der herzförmige Gesichtsschleier lenkt Geräusche zu den leicht versetzten Ohren. So orten sie Beute punktgenau.", k: "Schleiereule: jagt im Dunkeln nach Gehör" }, en: { q: "Barn owls can catch mice in total darkness by hearing alone.", a: ["True", "False"], x: "True! The heart-shaped facial disc funnels sound to their slightly offset ears, so they can pinpoint prey.", k: "Barn owl: hunts in the dark by hearing" }, fr: { q: "L'effraie des clochers peut attraper une souris dans le noir complet, rien qu'à l'ouïe.", a: ["Vrai", "Faux"], x: "Vrai ! Son disque facial en cœur dirige les sons vers ses oreilles décalées, ce qui lui permet de localiser la proie avec précision.", k: "Effraie : chasse dans le noir à l’oreille" }, es: { q: "La lechuza común puede cazar ratones en total oscuridad solo con el oído.", a: ["Verdadero", "Falso"], x: "¡Cierto! Su disco facial en forma de corazón dirige el sonido a sus oídos asimétricos y localiza la presa con precisión.", k: "Lechuza común: caza a oscuras por el oído" }, pt: { q: "A suindara consegue caçar ratos no escuro total só pela audição.", a: ["Verdadeiro", "Falso"], x: "Certo! O disco facial em forma de coração leva o som aos ouvidos assimétricos e localiza a presa com precisão.", k: "Suindara: caça no escuro pela audição" }, ja: { q: "正しい？まちがい？ メンフクロウは真っ暗やみでも、音だけでネズミをつかまえられる。", a: ["正しい", "まちがい"], x: "正しい！ハート形の顔が音を集め、左右で少しずれた位置にある耳へ届けます。だから獲物の位置がぴたりとわかります。", k: "メンフクロウ：暗やみでも音だけで狩る" }, it: { q: "Vero o falso? I barbagianni catturano i topi nel buio totale solo con l’udito.", a: ["Vero", "Falso"], x: "Vero! Il disco facciale a forma di cuore convoglia i suoni verso orecchie poste a altezze leggermente diverse: così localizzano la preda.", k: "Barbagianni: caccia al buio con l’udito" } } },
  { id: "a36", lvl: 3, type: "text", right: 2, t: { de: { q: "Wo liegt die extrem lange Zunge des Grünspechts, wenn er sie nicht benutzt?", a: ["Aufgerollt im Kehlsack", "Gefaltet im Schnabel", "Um den Schädel herum gewickelt", "Im Magen"], x: "Die Zunge sitzt auf langen Knochenspangen, die hinten um den ganzen Schädel laufen. So kann er tief in Ameisennester stoßen.", k: "Grünspecht: Zunge um den Schädel gewickelt" }, en: { q: "Where is the green woodpecker's extremely long tongue kept when not in use?", a: ["Coiled in a throat pouch", "Folded in its bill", "Wrapped around its skull", "In its stomach"], x: "The tongue sits on long bony rods that loop around the back of the skull. This lets it probe deep into ant nests.", k: "Green woodpecker: tongue wraps around its skull" }, fr: { q: "Où se range la langue extrêmement longue du pic vert au repos ?", a: ["Enroulée dans la gorge", "Pliée dans le bec", "Enroulée autour du crâne", "Dans l'estomac"], x: "La langue repose sur de longues tiges osseuses qui font le tour du crâne. Le pic vert peut ainsi fouiller loin dans les fourmilières.", k: "Pic vert : langue enroulée autour du crâne" }, es: { q: "¿Dónde guarda el pito real su larguísima lengua cuando no la usa?", a: ["Enrollada en la garganta", "Doblada dentro del pico", "Enrollada alrededor del cráneo", "En el estómago"], x: "La lengua se apoya en largos huesos que rodean el cráneo por detrás. Así puede hurgar a fondo en los hormigueros.", k: "Pito real: lengua enrollada en el cráneo" }, pt: { q: "Onde o peto-real guarda a língua comprida quando não está usando?", a: ["Enrolada na garganta", "Dobrada dentro do bico", "Enrolada em volta do crânio", "No estômago"], x: "A língua se apoia em ossos longos que contornam o crânio por trás. Assim ele consegue fuçar fundo nos formigueiros.", k: "Peto-verde: língua enrolada no crânio" }, ja: { q: "ヨーロッパアオゲラのとても長い舌は、使わないときどこにしまわれている？", a: ["のどの袋に巻いて", "くちばしの中に折りたたんで", "頭の骨のまわりに巻きつけて", "胃の中に"], x: "舌は長い骨の棒にのっていて、頭の骨の後ろをぐるりと回っています。だからアリの巣の奥まで届くのです。", k: "アオゲラ：舌が頭の骨を一周する" }, it: { q: "Dove tiene il picchio verde la sua lunghissima lingua quando non la usa?", a: ["Arrotolata in una sacca della gola", "Piegata nel becco", "Avvolta intorno al cranio", "Nello stomaco"], x: "La lingua poggia su lunghi bastoncini ossei che girano intorno al retro del cranio. Così arriva in fondo ai formicai.", k: "Picchio verde: lingua avvolta intorno al cranio" } } },
  { id: "a37", lvl: 3, type: "text", right: 1, t: { de: { q: "Rehe paaren sich im Hochsommer, die Kitze kommen aber erst im nächsten Mai oder Juni. Warum?", a: ["Die Ricke trägt zwei Kitze nacheinander", "Der Embryo macht monatelang Pause", "Die Kitze wachsen extrem langsam", "Sie paaren sich im Frühling erneut"], x: "Beim Reh ruht der Keim nach der Befruchtung bis etwa Dezember (Keimruhe). So kommen die Kitze, wenn es viel Futter gibt.", k: "Reh: der Embryo macht monatelang Pause" }, en: { q: "Roe deer mate in midsummer, but fawns are only born the next May or June. Why?", a: ["The doe carries two fawns in turn", "The embryo pauses for months", "The fawns grow extremely slowly", "They mate again in spring"], x: "In roe deer the embryo rests until around December (delayed implantation), so fawns arrive when food is plentiful.", k: "Roe deer: embryo pauses for months" }, fr: { q: "Les chevreuils s'accouplent en plein été, mais les faons naissent en mai ou juin suivant. Pourquoi ?", a: ["La chevrette porte deux faons à la suite", "L'embryon reste en pause des mois", "Les faons grandissent très lentement", "Ils s'accouplent à nouveau au printemps"], x: "Chez le chevreuil, l'embryon reste en pause jusque vers décembre (implantation différée). Les faons naissent quand la nourriture abonde.", k: "Chevreuil : l’embryon fait une pause de plusieurs mois" }, es: { q: "Los corzos se aparean en pleno verano, pero las crías nacen en mayo o junio. ¿Por qué?", a: ["La hembra gesta dos crías seguidas", "El embrión se detiene durante meses", "Las crías crecen muy despacio", "Vuelven a aparearse en primavera"], x: "En el corzo, el embrión queda en pausa hasta diciembre (implantación diferida); así las crías nacen cuando abunda el alimento.", k: "Corzo: el embrión hace una pausa de meses" }, pt: { q: "Os corços acasalam em pleno verão, mas os filhotes nascem em maio ou junho. Por quê?", a: ["A fêmea gesta dois filhotes seguidos", "O embrião fica parado por meses", "Os filhotes crescem muito devagar", "Eles acasalam de novo na primavera"], x: "No corço, o embrião fica em pausa até dezembro (implantação tardia); assim os filhotes nascem quando há bastante comida.", k: "Corço: o embrião pausa por meses" }, ja: { q: "ノロジカは真夏に交尾するのに、赤ちゃんが生まれるのは翌年の5〜6月。なぜ？", a: ["メスが2頭を順番におなかで育てる", "胚が何か月も休む", "赤ちゃんの成長がとてもゆっくり", "春にもう一度交尾する"], x: "ノロジカでは、胚が12月ごろまで休みます（着床遅延）。だから赤ちゃんはえさの多い時期に生まれます。", k: "ノロジカ：胚が何か月も休む" }, it: { q: "I caprioli si accoppiano in piena estate, ma i piccoli nascono solo a maggio o giugno dell’anno dopo. Perché?", a: ["La femmina porta due piccoli a turno", "L’embrione si ferma per mesi", "I piccoli crescono lentissimi", "Si accoppiano di nuovo in primavera"], x: "Nel capriolo l’embrione resta a riposo fino a circa dicembre (impianto ritardato): così i piccoli nascono quando c’è molto cibo.", k: "Capriolo: l’embrione si ferma per mesi" } } },
  { id: "a38", lvl: 3, type: "text", right: 2, t: { de: { q: "In welchem Jahr wurden in Deutschland erstmals wieder wilde Wolfswelpen geboren?", a: ["1975", "1990", "2000", "2015"], x: "Im Jahr 2000 zog ein Wolfspaar in der Lausitz in Sachsen Junge groß – nach über 100 Jahren ohne Wolfsnachwuchs in Deutschland.", k: "Wolf: seit 2000 wieder Welpen in Deutschland" }, en: { q: "In which year were wild wolf pups born in Germany again for the first time?", a: ["1975", "1990", "2000", "2015"], x: "In 2000 a wolf pair raised pups in Lusatia, Saxony – after more than 100 years without wolves breeding in Germany.", k: "Wolves: pups in Germany again since 2000" }, fr: { q: "En quelle année des louveteaux sauvages sont-ils de nouveau nés en Allemagne ?", a: ["1975", "1990", "2000", "2015"], x: "En 2000, un couple de loups a élevé des petits en Lusace (Saxe), après plus de 100 ans sans reproduction de loups en Allemagne.", k: "Loups : de nouveau des louveteaux en Allemagne depuis 2000" }, es: { q: "¿En qué año volvieron a nacer lobeznos salvajes en Alemania por primera vez?", a: ["1975", "1990", "2000", "2015"], x: "En 2000 una pareja de lobos crió cachorros en Lusacia (Sajonia), tras más de 100 años sin lobos criando en Alemania.", k: "Lobos: cachorros en Alemania de nuevo desde 2000" }, pt: { q: "Em que ano nasceram de novo filhotes de lobo selvagens na Alemanha pela primeira vez?", a: ["1975", "1990", "2000", "2015"], x: "Em 2000, um casal de lobos criou filhotes na Lusácia (Saxônia), depois de mais de 100 anos sem lobos se reproduzindo na Alemanha.", k: "Lobos: filhotes na Alemanha de novo desde 2000" }, ja: { q: "ドイツで野生のオオカミの子どもが再び生まれたのは何年？", a: ["1975年", "1990年", "2000年", "2015年"], x: "2000年、ザクセン州ラウジッツでオオカミのペアが子育てをしました。ドイツでオオカミが繁殖しなかった100年以上を経てのことです。", k: "オオカミ：2000年からドイツで再び子育て" }, it: { q: "In che anno sono nati di nuovo cuccioli di lupo selvatici in Germania?", a: ["1975", "1990", "2000", "2015"], x: "Nel 2000 una coppia di lupi ha allevato i cuccioli in Lusazia, in Sassonia, dopo oltre 100 anni senza lupi riprodotti in Germania.", k: "Lupi: di nuovo cuccioli in Germania dal 2000" } } },
  { id: "a39", lvl: 3, type: "text", right: 3, t: { de: { q: "Woran unterscheidet man eine Europäische Wildkatze von einer getigerten Hauskatze?", a: ["An Pinseln auf den Ohren", "An weißen Pfoten", "Am langen, dünnen Schwanz", "Dicker Schwanz, stumpfe schwarze Spitze"], x: "Die Wildkatze hat einen dicken, buschigen Schwanz mit schwarzen Ringen und stumpfem schwarzem Ende. Pinselohren hat der Luchs.", k: "Wildkatze: buschiger Schwanz mit schwarzem Ende" }, en: { q: "What helps tell a European wildcat from a tabby house cat?", a: ["Tufts on its ears", "White paws", "A long, thin tail", "Bushy tail with a blunt black tip"], x: "The wildcat has a thick, bushy tail with black rings and a blunt black end. Ear tufts belong to the lynx.", k: "Wildcat: bushy tail with a black tip" }, fr: { q: "Qu'est-ce qui distingue le chat forestier d'un chat domestique tigré ?", a: ["Des pinceaux aux oreilles", "Des pattes blanches", "Une queue longue et fine", "Queue touffue à bout noir arrondi"], x: "Le chat forestier a une queue épaisse et touffue, annelée de noir, au bout noir arrondi. Les pinceaux aux oreilles, c'est le lynx.", k: "Chat sauvage : queue touffue au bout noir" }, es: { q: "¿Qué distingue al gato montés europeo de un gato doméstico atigrado?", a: ["Pinceles en las orejas", "Patas blancas", "Una cola larga y fina", "Cola tupida con punta negra roma"], x: "El gato montés tiene una cola gruesa y tupida, con anillos negros y punta negra roma. Los pinceles en las orejas son del lince.", k: "Gato montés: cola peluda con punta negra" }, pt: { q: "O que diferencia o gato-selvagem-europeu de um gato doméstico tigrado?", a: ["Tufos nas orelhas", "Patas brancas", "Uma cauda longa e fina", "Cauda peluda com ponta preta arredondada"], x: "O gato-selvagem tem uma cauda grossa e peluda, com anéis pretos e ponta preta arredondada. Os tufos nas orelhas são do lince.", k: "Gato-selvagem: cauda peluda com ponta preta" }, ja: { q: "ヨーロッパヤマネコとトラ柄の飼いネコの見分け方は？", a: ["耳の先の房毛", "白い足", "長くて細いしっぽ", "ふさふさで先が黒く丸いしっぽ"], x: "ヤマネコのしっぽは太くふさふさで、黒い輪があり、先が黒く丸くなっています。耳の房毛はオオヤマネコの特徴です。", k: "ヤマネコ：太いしっぽの先が黒い" }, it: { q: "Cosa aiuta a distinguere il gatto selvatico europeo da un gatto domestico tigrato?", a: ["Ciuffi sulle orecchie", "Zampe bianche", "Una coda lunga e sottile", "Coda folta con la punta nera e arrotondata"], x: "Il gatto selvatico ha una coda folta con anelli neri e la punta nera smussata. I ciuffi sulle orecchie sono della lince.", k: "Gatto selvatico: coda folta con punta nera" } } },
  { id: "a40", lvl: 3, type: "text", right: 1, t: { de: { q: "In welchem Jahr wurden in Deutschland erstmals Waschbären gezielt in der Natur ausgesetzt?", a: ["1834", "1934", "1974", "1994"], x: "1934 wurden am Edersee in Hessen zwei Waschbärpaare freigelassen. Heute leben in Deutschland sehr viele dieser Nordamerikaner.", k: "Waschbär: 1934 in Hessen ausgesetzt" }, en: { q: "In which year were raccoons first deliberately released into the wild in Germany?", a: ["1834", "1934", "1974", "1994"], x: "In 1934 two pairs of raccoons were released at Lake Edersee in Hesse. Today these North Americans are very common in Germany.", k: "Raccoons: released in Germany in 1934" }, fr: { q: "En quelle année des ratons laveurs ont-ils été relâchés exprès pour la première fois en Allemagne ?", a: ["1834", "1934", "1974", "1994"], x: "En 1934, deux couples ont été relâchés au lac d'Edersee (Hesse). Aujourd'hui, ces Nord-Américains sont très nombreux en Allemagne.", k: "Ratons laveurs : lâchés en Allemagne en 1934" }, es: { q: "¿En qué año se soltaron a propósito los primeros mapaches en la naturaleza en Alemania?", a: ["1834", "1934", "1974", "1994"], x: "En 1934 se liberaron dos parejas junto al lago Edersee (Hesse). Hoy estos norteamericanos son muy abundantes en Alemania.", k: "Mapaches: liberados en Alemania en 1934" }, pt: { q: "Em que ano os primeiros guaxinins foram soltos de propósito na natureza na Alemanha?", a: ["1834", "1934", "1974", "1994"], x: "Em 1934, dois casais foram soltos perto do lago Edersee (Hesse). Hoje esses norte-americanos são muito comuns na Alemanha.", k: "Guaxinins: soltos na Alemanha em 1934" }, ja: { q: "ドイツでアライグマが初めて意図的に野に放されたのは何年？", a: ["1834年", "1934年", "1974年", "1994年"], x: "1934年、ヘッセン州のエーダー湖でアライグマ2組が放されました。いまでは北アメリカ生まれのアライグマがドイツでとても多くなっています。", k: "アライグマ：1934年にドイツで放された" }, it: { q: "In che anno i procioni furono liberati di proposito in natura in Germania per la prima volta?", a: ["1834", "1934", "1974", "1994"], x: "Nel 1934 due coppie di procioni furono liberate presso il lago Edersee, in Assia. Oggi questi nordamericani sono comunissimi in Germania.", k: "Procioni: liberati in Germania nel 1934" } } },
  { id: "a41", lvl: 3, type: "text", right: 2, t: { de: { q: "Welches ist das größte wild lebende Raubtier Deutschlands?", a: ["Wolf", "Luchs", "Kegelrobbe", "Seehund"], x: "Robben zählen zu den Raubtieren. Kegelrobben-Männchen an Nord- und Ostsee werden bis zu etwa 300 kg schwer.", k: "Kegelrobbe: größtes Raubtier Deutschlands" }, en: { q: "Which is the largest wild carnivore in Germany?", a: ["Wolf", "Lynx", "Grey seal", "Harbour seal"], x: "Seals belong to the carnivores. Male grey seals on the North Sea and Baltic coasts weigh up to about 300 kg.", k: "Grey seal: Germany's largest carnivore" }, fr: { q: "Quel est le plus grand carnivore sauvage d'Allemagne ?", a: ["Loup", "Lynx", "Phoque gris", "Phoque veau-marin"], x: "Les phoques font partie des carnivores. Les mâles du phoque gris, en mer du Nord et Baltique, pèsent jusqu'à environ 300 kg.", k: "Phoque gris : plus grand carnivore d’Allemagne" }, es: { q: "¿Cuál es el mayor carnívoro salvaje de Alemania?", a: ["Lobo", "Lince", "Foca gris", "Foca común"], x: "Las focas pertenecen a los carnívoros. Los machos de foca gris del mar del Norte y el Báltico pesan hasta unos 300 kg.", k: "Foca gris: mayor carnívoro de Alemania" }, pt: { q: "Qual é o maior carnívoro selvagem da Alemanha?", a: ["Lobo", "Lince", "Foca-cinzenta", "Foca-comum"], x: "As focas pertencem aos carnívoros. Os machos de foca-cinzenta do mar do Norte e do Báltico pesam até uns 300 kg.", k: "Foca-cinzenta: maior carnívoro da Alemanha" }, ja: { q: "ドイツ最大の野生の肉食動物は？", a: ["オオカミ", "オオヤマネコ", "ハイイロアザラシ", "ゼニガタアザラシ"], x: "アザラシは食肉目の仲間。北海とバルト海の沿岸にいるハイイロアザラシのオスは最大約300キロです。", k: "ハイイロアザラシ：ドイツ最大の肉食動物" }, it: { q: "Qual è il carnivoro selvatico più grande della Germania?", a: ["Lupo", "Lince", "Foca grigia", "Foca comune"], x: "Le foche appartengono ai carnivori. I maschi di foca grigia sulle coste del Mare del Nord e del Baltico pesano fino a circa 300 kg.", k: "Foca grigia: il carnivoro più grande della Germania" } } },
  { id: "a42", lvl: 3, type: "text", right: 0, t: { de: { q: "Womit füttern Tauben ihre frisch geschlüpften Jungen?", a: ["Mit „Kropfmilch“", "Mit zerkauten Insekten", "Mit Regenwürmern", "Mit Blütennektar"], x: "Beide Eltern bilden im Kropf eine nahrhafte, käseartige „Kropfmilch“. Das ist bei Vögeln eine große Ausnahme.", k: "Tauben: füttern Junge mit Kropfmilch" }, en: { q: "What do pigeons feed their newly hatched chicks?", a: ["'Crop milk'", "Chewed-up insects", "Earthworms", "Flower nectar"], x: "Both parents produce a nutritious, cheese-like 'crop milk' in their crop – very unusual for birds.", k: "Pigeons: feed their chicks crop milk" }, fr: { q: "De quoi les pigeons nourrissent-ils leurs petits tout juste éclos ?", a: ["Du « lait de jabot »", "Des insectes mâchés", "Des vers de terre", "Du nectar de fleurs"], x: "Les deux parents produisent dans leur jabot un « lait » nourrissant, semblable à du fromage. C'est très rare chez les oiseaux.", k: "Pigeons : nourrissent au lait de jabot" }, es: { q: "¿Con qué alimentan las palomas a sus pichones recién nacidos?", a: ["Con «leche de buche»", "Con insectos masticados", "Con lombrices", "Con néctar de flores"], x: "Ambos padres producen en el buche una «leche» nutritiva, parecida al queso. Es algo muy raro entre las aves.", k: "Palomas: alimentan con leche de buche" }, pt: { q: "Com o que os pombos alimentam os filhotes recém-nascidos?", a: ["Com “leite de papo”", "Com insetos mastigados", "Com minhocas", "Com néctar de flores"], x: "Os dois pais produzem no papo um “leite” nutritivo, parecido com queijo. Isso é muito raro entre as aves.", k: "Pombos: alimentam com leite de papo" }, ja: { q: "ハトはかえったばかりのひなに何をあげる？", a: ["「ピジョンミルク」", "かみくだいた虫", "ミミズ", "花の蜜"], x: "両親とも、そのうでチーズのような栄養たっぷりの「ピジョンミルク」を作ります。鳥としてはとてもめずらしいことです。", k: "ハト：ピジョンミルクでひなを育てる" }, it: { q: "Cosa danno i piccioni ai pulcini appena nati?", a: ["«Latte di gozzo»", "Insetti masticati", "Lombrichi", "Nettare"], x: "Entrambi i genitori producono nel gozzo un nutriente «latte di gozzo» simile a formaggio: molto insolito per gli uccelli.", k: "Piccioni: nutrono i piccoli col latte di gozzo" } } },
  { id: "a43", lvl: 3, type: "text", right: 1, t: { de: { q: "Welche Tiere sind die nächsten lebenden Verwandten des Flusspferds?", a: ["Schweine", "Wale", "Nashörner", "Elefanten"], x: "Erbgut-Vergleiche zeigen: Flusspferde sind am engsten mit Walen und Delfinen verwandt – nicht mit Schweinen, wie man lange dachte.", k: "Flusspferd: nächster Verwandter der Wale" }, en: { q: "Which animals are the hippopotamus's closest living relatives?", a: ["Pigs", "Whales", "Rhinos", "Elephants"], x: "DNA studies show that hippos are most closely related to whales and dolphins – not to pigs, as was long believed.", k: "Hippo: closest relative of whales" }, fr: { q: "Quels animaux sont les plus proches parents vivants de l'hippopotame ?", a: ["Les cochons", "Les baleines", "Les rhinocéros", "Les éléphants"], x: "L'ADN le montre : les hippopotames sont les plus proches parents des baleines et dauphins, et non des cochons comme on l'a longtemps cru.", k: "Hippopotame : plus proche parent des baleines" }, es: { q: "¿Qué animales son los parientes vivos más cercanos del hipopótamo?", a: ["Los cerdos", "Las ballenas", "Los rinocerontes", "Los elefantes"], x: "El ADN lo demuestra: los hipopótamos están más emparentados con ballenas y delfines que con los cerdos, como se creyó mucho tiempo.", k: "Hipopótamo: pariente más cercano de las ballenas" }, pt: { q: "Quais animais são os parentes vivos mais próximos do hipopótamo?", a: ["Os porcos", "As baleias", "Os rinocerontes", "Os elefantes"], x: "O DNA mostra: os hipopótamos são mais aparentados com baleias e golfinhos do que com os porcos, como se pensou por muito tempo.", k: "Hipopótamo: parente mais próximo das baleias" }, ja: { q: "カバにいちばん近い現生の親せきは？", a: ["ブタ", "クジラ", "サイ", "ゾウ"], x: "DNAを調べると、カバにいちばん近いのはクジラやイルカ。長い間信じられていたブタではありません。", k: "カバ：クジラにいちばん近い" }, it: { q: "Quali animali sono i parenti viventi più stretti dell’ippopotamo?", a: ["Maiali", "Balene", "Rinoceronti", "Elefanti"], x: "Gli studi sul DNA mostrano che gli ippopotami sono più vicini a balene e delfini, non ai maiali come si è creduto a lungo.", k: "Ippopotamo: parente più stretto delle balene" } } },
  { id: "a44", lvl: 3, type: "text", right: 3, t: { de: { q: "Wie wirbt das Zaunkönig-Männchen um ein Weibchen?", a: ["Es bringt ihr Beeren", "Es tanzt auf dem Wasser", "Es färbt sein Gefieder rot", "Es baut mehrere Nester zur Auswahl"], x: "Das Männchen baut mehrere kugelige Rohbau-Nester. Das Weibchen sucht sich eines aus und polstert es dann weich aus.", k: "Zaunkönig: baut mehrere Nester zur Auswahl" }, en: { q: "How does a male wren win over a female?", a: ["He brings her berries", "He dances on the water", "His plumage turns red", "He builds several nests to choose from"], x: "The male builds several unfinished, ball-shaped nests. The female chooses one and lines it with soft material.", k: "Wren: builds several nests to choose from" }, fr: { q: "Comment le troglodyte mâle séduit-il une femelle ?", a: ["Il lui apporte des baies", "Il danse sur l'eau", "Son plumage devient rouge", "Il construit plusieurs nids au choix"], x: "Le mâle construit plusieurs nids en boule inachevés. La femelle en choisit un et le garnit de matériaux doux.", k: "Troglodyte : construit plusieurs nids au choix" }, es: { q: "¿Cómo conquista el macho de chochín a una hembra?", a: ["Le lleva bayas", "Baila sobre el agua", "Su plumaje se vuelve rojo", "Construye varios nidos para elegir"], x: "El macho construye varios nidos esféricos sin terminar. La hembra elige uno y lo forra con material blando.", k: "Chochín: construye varios nidos para elegir" }, pt: { q: "Como o macho da carriça conquista uma fêmea?", a: ["Leva frutinhas para ela", "Dança sobre a água", "Sua plumagem fica vermelha", "Constrói vários ninhos para ela escolher"], x: "O macho constrói vários ninhos redondos inacabados. A fêmea escolhe um e o forra com material macio.", k: "Carriça: faz vários ninhos para escolher" }, ja: { q: "ミソサザイのオスはどうやってメスの気を引く？", a: ["ベリーを運ぶ", "水の上で踊る", "羽が赤くなる", "巣をいくつも作って選ばせる"], x: "オスは未完成のボール形の巣をいくつも作ります。メスがひとつを選び、中にやわらかい材料をしきます。", k: "ミソサザイ：巣をいくつも作って選ばせる" }, it: { q: "Come conquista una femmina il maschio di scricciolo?", a: ["Le porta bacche", "Danza sull’acqua", "Il suo piumaggio diventa rosso", "Costruisce più nidi tra cui scegliere"], x: "Il maschio costruisce diversi nidi a palla non finiti. La femmina ne sceglie uno e lo imbottisce di materiale morbido.", k: "Scricciolo: costruisce più nidi tra cui scegliere" } } },
  { id: "a45", lvl: 3, type: "text", right: 2, t: { de: { q: "Was passiert mit Stockenten während der Mauser im Sommer?", a: ["Sie verlieren ihre Stimme", "Sie werden ganz weiß", "Sie können wochenlang nicht fliegen", "Sie halten einen Sommerschlaf"], x: "Enten verlieren alle Schwungfedern auf einmal und sind etwa 3 bis 4 Wochen flugunfähig. Erpel tragen dann ein schlichtes Kleid.", k: "Stockenten: im Sommer wochenlang flugunfähig" }, en: { q: "What happens to mallards during their summer moult?", a: ["They lose their voice", "They turn completely white", "They can't fly for weeks", "They sleep through the summer"], x: "Ducks shed all their flight feathers at once and can't fly for about 3–4 weeks. Drakes then wear a plain, dull plumage.", k: "Mallards: can't fly for weeks in summer" }, fr: { q: "Que se passe-t-il chez le canard colvert lors de la mue d'été ?", a: ["Il perd sa voix", "Il devient tout blanc", "Il ne vole plus pendant des semaines", "Il dort tout l'été"], x: "Les canards perdent toutes leurs rémiges d'un coup et ne volent plus pendant 3 à 4 semaines. Le mâle prend alors un plumage terne.", k: "Colverts : sans vol pendant des semaines l’été" }, es: { q: "¿Qué les ocurre a los ánades reales durante la muda de verano?", a: ["Pierden la voz", "Se vuelven totalmente blancos", "No pueden volar durante semanas", "Duermen todo el verano"], x: "Los patos pierden todas las plumas de vuelo a la vez y no vuelan durante 3 o 4 semanas. Los machos lucen entonces un plumaje apagado.", k: "Ánades reales: semanas sin volar en verano" }, pt: { q: "O que acontece com os patos-reais durante a muda de verão?", a: ["Perdem a voz", "Ficam totalmente brancos", "Não conseguem voar por semanas", "Dormem o verão inteiro"], x: "Os patos perdem todas as penas de voo ao mesmo tempo e não voam por 3 ou 4 semanas. Os machos ficam então com uma plumagem sem graça.", k: "Patos-reais: semanas sem voar no verão" }, ja: { q: "夏の換羽の時期、マガモはどうなる？", a: ["声が出なくなる", "真っ白になる", "何週間も飛べなくなる", "夏の間ずっと眠る"], x: "カモは風切羽が一度に全部ぬけ、3〜4週間ほど飛べなくなります。オスはその間、地味な羽の色になります。", k: "マガモ：夏に何週間も飛べなくなる" }, it: { q: "Cosa succede ai germani reali durante la muta estiva?", a: ["Perdono la voce", "Diventano tutti bianchi", "Per settimane non possono volare", "Dormono tutta l’estate"], x: "Le anatre perdono tutte le penne remiganti insieme e per circa 3–4 settimane non volano. I maschi in quel periodo hanno un piumaggio semplice e spento.", k: "Germani reali: settimane senza volare d’estate" } } },
  { id: "a46", lvl: 3, type: "text", right: 0, t: { de: { q: "Welche Tiergruppe gehört zu den nächsten lebenden Verwandten der Elefanten?", a: ["Seekühe", "Nashörner", "Flusspferde", "Tapire"], x: "Elefanten sind eng mit Seekühen (Manatis und Dugongs) verwandt – und mit den kleinen Klippschliefern.", k: "Elefanten: verwandt mit Seekühen" }, en: { q: "Which group of animals is among the elephant's closest living relatives?", a: ["Sea cows (manatees)", "Rhinos", "Hippos", "Tapirs"], x: "Elephants are closely related to sea cows (manatees and dugongs) – and to the small rock hyraxes.", k: "Elephants: related to sea cows" }, fr: { q: "Quel groupe d'animaux compte parmi les plus proches parents des éléphants ?", a: ["Les siréniens (lamantins)", "Les rhinocéros", "Les hippopotames", "Les tapirs"], x: "Les éléphants sont proches parents des siréniens (lamantins et dugongs) et des petits damans.", k: "Éléphants : parents des siréniens" }, es: { q: "¿Qué grupo de animales está entre los parientes más cercanos de los elefantes?", a: ["Los sirenios (manatíes)", "Los rinocerontes", "Los hipopótamos", "Los tapires"], x: "Los elefantes están emparentados con los sirenios (manatíes y dugongos) y con los pequeños damanes.", k: "Elefantes: parientes de los manatíes" }, pt: { q: "Que grupo de animais está entre os parentes mais próximos dos elefantes?", a: ["Os sirênios (peixes-boi)", "Os rinocerontes", "Os hipopótamos", "As antas"], x: "Os elefantes são aparentados com os sirênios (peixes-boi e dugongos) e com os pequenos híraces.", k: "Elefantes: parentes dos peixes-boi" }, ja: { q: "ゾウにいちばん近い現生の親せきのグループは？", a: ["海牛（マナティーなど）", "サイ", "カバ", "バク"], x: "ゾウはマナティーやジュゴンなどの海牛と近い親せき。小さなハイラックスとも親せきです。", k: "ゾウ：マナティーの親せき" }, it: { q: "Quale gruppo di animali è tra i parenti viventi più stretti dell’elefante?", a: ["Sirenii (lamantini)", "Rinoceronti", "Ippopotami", "Tapiri"], x: "Gli elefanti sono parenti stretti dei sirenii (lamantini e dugonghi) e dei piccoli irace delle rocce.", k: "Elefanti: parenti dei lamantini" } } },
  { id: "a47", lvl: 3, type: "tf", right: 1, t: { de: { q: "Mauersegler sind eng mit den Schwalben verwandt.", a: ["Wahr", "Falsch"], x: "Falsch! Sie sehen Schwalben nur ähnlich. Mauersegler sind näher mit den Kolibris verwandt als mit Schwalben.", k: "Mauersegler: eher mit Kolibris als mit Schwalben verwandt" }, en: { q: "Common swifts are closely related to swallows.", a: ["True", "False"], x: "False! They only look similar. Swifts are more closely related to hummingbirds than to swallows.", k: "Swifts: closer to hummingbirds than swallows" }, fr: { q: "Le martinet noir est un proche parent des hirondelles.", a: ["Vrai", "Faux"], x: "Faux ! Ils se ressemblent seulement. Les martinets sont plus proches des colibris que des hirondelles.", k: "Martinets : plus proches des colibris que des hirondelles" }, es: { q: "El vencejo común es pariente cercano de las golondrinas.", a: ["Verdadero", "Falso"], x: "¡Falso! Solo se parecen. Los vencejos están más emparentados con los colibríes que con las golondrinas.", k: "Vencejos: más cerca de los colibríes que de las golondrinas" }, pt: { q: "O andorinhão-preto é parente próximo das andorinhas.", a: ["Verdadeiro", "Falso"], x: "Falso! Eles só se parecem. Os andorinhões são mais aparentados com os beija-flores do que com as andorinhas.", k: "Andorinhões: mais perto dos beija-flores que das andorinhas" }, ja: { q: "正しい？まちがい？ ヨーロッパアマツバメはツバメの近い親せきである。", a: ["正しい", "まちがい"], x: "まちがい！似ているだけです。アマツバメはツバメよりハチドリに近い親せきです。", k: "アマツバメ：ツバメよりハチドリに近い" }, it: { q: "Vero o falso? I rondoni comuni sono parenti stretti delle rondini.", a: ["Vero", "Falso"], x: "Falso! Si somigliano soltanto. I rondoni sono più vicini ai colibrì che alle rondini.", k: "Rondoni: più vicini ai colibrì che alle rondini" } } },
  { id: "a48", lvl: 3, type: "tf", right: 0, t: { de: { q: "Es gibt einen heimischen Singvogel, der tauchen und unter Wasser am Bachgrund entlanglaufen kann.", a: ["Wahr", "Falsch"], x: "Stimmt! Die Wasseramsel taucht in schnellen Bächen nach Insektenlarven und läuft dabei sogar über den Grund.", k: "Wasseramsel: läuft unter Wasser am Bachgrund" }, en: { q: "There is a Central European songbird that can dive and walk along a stream bed underwater.", a: ["True", "False"], x: "True! The white-throated dipper dives in fast streams for insect larvae and even walks along the bottom.", k: "Dipper: walks underwater along the stream bed" }, fr: { q: "Il existe un oiseau chanteur d'Europe centrale qui plonge et marche sous l'eau au fond des ruisseaux.", a: ["Vrai", "Faux"], x: "Vrai ! Le cincle plongeur plonge dans les torrents pour chercher des larves d'insectes et marche même sur le fond.", k: "Cincle : marche sous l’eau au fond du ruisseau" }, es: { q: "Existe un ave cantora centroeuropea que bucea y camina bajo el agua por el fondo de los arroyos.", a: ["Verdadero", "Falso"], x: "¡Cierto! El mirlo acuático bucea en arroyos rápidos buscando larvas de insectos e incluso camina por el fondo.", k: "Mirlo acuático: camina bajo el agua por el fondo" }, pt: { q: "Existe uma ave canora da Europa Central que mergulha e anda debaixo d’água no fundo dos riachos.", a: ["Verdadeiro", "Falso"], x: "Certo! O melro-d’água mergulha em riachos rápidos procurando larvas de insetos e até caminha pelo fundo.", k: "Melro-d’água: anda debaixo d’água no riacho" }, ja: { q: "正しい？まちがい？ 中央ヨーロッパには、水に潜って川底を歩ける鳴禽類がいる。", a: ["正しい", "まちがい"], x: "正しい！ムナジロカワガラスは流れの速い川に潜って虫の幼虫をとり、川底を歩くこともできます。", k: "カワガラス：水の中で川底を歩く" }, it: { q: "Vero o falso? Esiste un uccello canoro dell’Europa centrale che si tuffa e cammina sott’acqua sul fondo del torrente.", a: ["Vero", "Falso"], x: "Vero! Il merlo acquaiolo si tuffa nei torrenti veloci per cercare larve di insetti e cammina persino sul fondo.", k: "Merlo acquaiolo: cammina sott’acqua sul fondo" } } },
  { id: "a49", lvl: 3, type: "tf", right: 0, t: { de: { q: "Maulwürfe legen Vorratskammern mit lebenden Regenwürmern an, die sie durch einen Biss lähmen.", a: ["Wahr", "Falsch"], x: "Stimmt! Ein Biss in den Kopf macht die Würmer bewegungsunfähig. So bleiben sie als frischer Vorrat für den Winter erhalten.", k: "Maulwurf: legt Vorräte lebender Regenwürmer an" }, en: { q: "Moles keep larders of live earthworms that they have paralysed with a bite.", a: ["True", "False"], x: "True! A bite to the head immobilises the worms, keeping them fresh as a winter food supply.", k: "Mole: keeps a larder of live earthworms" }, fr: { q: "Les taupes stockent des vers de terre vivants, paralysés par une morsure.", a: ["Vrai", "Faux"], x: "Vrai ! Une morsure à la tête immobilise les vers, qui restent frais comme réserve pour l'hiver.", k: "Taupe : garde des vers de terre vivants en réserve" }, es: { q: "Los topos almacenan lombrices vivas que han paralizado con un mordisco.", a: ["Verdadero", "Falso"], x: "¡Cierto! Un mordisco en la cabeza inmoviliza las lombrices, que se conservan frescas como reserva para el invierno.", k: "Topo: guarda lombrices vivas como despensa" }, pt: { q: "As toupeiras guardam minhocas vivas que paralisaram com uma mordida.", a: ["Verdadeiro", "Falso"], x: "Certo! Uma mordida na cabeça imobiliza as minhocas, que ficam frescas como reserva para o inverno.", k: "Toupeira: guarda minhocas vivas na despensa" }, ja: { q: "正しい？まちがい？ モグラは、かんでまひさせた生きたミミズを貯蔵庫にたくわえる。", a: ["正しい", "まちがい"], x: "正しい！頭をかまれたミミズは動けなくなり、冬の食料として新鮮なまま保たれます。", k: "モグラ：生きたミミズをたくわえる" }, it: { q: "Vero o falso? Le talpe tengono dispense di lombrichi vivi paralizzati con un morso.", a: ["Vero", "Falso"], x: "Vero! Un morso alla testa immobilizza i vermi, che restano freschi come scorta di cibo per l’inverno.", k: "Talpa: tiene lombrichi vivi in dispensa" } } },
  { id: "a50", lvl: 3, type: "tf", right: 0, t: { de: { q: "Bei Rotkehlchen singen im Herbst und Winter auch die Weibchen.", a: ["Wahr", "Falsch"], x: "Stimmt! Im Winter verteidigen auch Rotkehlchen-Weibchen ein eigenes Revier – und tun das mit Gesang.", k: "Rotkehlchen: auch die Weibchen singen" }, en: { q: "In autumn and winter, female robins sing too.", a: ["True", "False"], x: "True! In winter, female robins also defend their own territory – and they do it by singing.", k: "Robins: females sing too" }, fr: { q: "En automne et en hiver, les femelles de rougegorge chantent aussi.", a: ["Vrai", "Faux"], x: "Vrai ! En hiver, les femelles de rougegorge défendent elles aussi leur propre territoire, et elles le font en chantant.", k: "Rouges-gorges : les femelles chantent aussi" }, es: { q: "En otoño e invierno, las hembras de petirrojo también cantan.", a: ["Verdadero", "Falso"], x: "¡Cierto! En invierno, las hembras de petirrojo también defienden su propio territorio, y lo hacen cantando.", k: "Petirrojos: las hembras también cantan" }, pt: { q: "No outono e no inverno, as fêmeas do pisco-de-peito-ruivo também cantam.", a: ["Verdadeiro", "Falso"], x: "Certo! No inverno, as fêmeas também defendem seu próprio território – e fazem isso cantando.", k: "Piscos-de-peito-ruivo: as fêmeas também cantam" }, ja: { q: "正しい？まちがい？ 秋と冬には、ヨーロッパコマドリのメスもさえずる。", a: ["正しい", "まちがい"], x: "正しい！冬はコマドリのメスも自分のなわばりを守ります。その方法がさえずりなのです。", k: "ヨーロッパコマドリ：メスもさえずる" }, it: { q: "Vero o falso? In autunno e in inverno cantano anche le femmine di pettirosso.", a: ["Vero", "Falso"], x: "Vero! D’inverno anche le femmine di pettirosso difendono un proprio territorio, e lo fanno cantando.", k: "Pettirossi: cantano anche le femmine" } } },
  { id: "d01", lvl: 1, type: "pic", right: 0, img: ["q-tr-fox"], t: { de: { q: "Wessen Spur ist das?", a: ["Fuchs", "Reh", "Dachs", "Hase"], x: "Vier Zehen mit Krallen und ein kleiner Ballen: ein Fuchs. Typisch ist das schmale Oval – zwischen Ballen und Zehen bleibt ein freier Raum in X-Form.", k: "Fuchs-Spur: schmales Oval mit 4 Zehen" }, en: { q: "Whose track is this?", a: ["Fox", "Roe deer", "Badger", "Hare"], x: "Four toes with claws and a small pad: a fox. Typical is the narrow oval – between the pad and the toes there is an empty X-shaped space.", k: "Fox track: narrow oval with 4 toes" }, fr: { q: "À qui est cette empreinte ?", a: ["Renard", "Chevreuil", "Blaireau", "Lièvre"], x: "Quatre doigts avec griffes et une petite pelote : un renard. L’ovale étroit est typique – entre la pelote et les doigts reste un espace libre en forme de X.", k: "Trace de renard : ovale étroit, 4 doigts" }, es: { q: "¿De quién es esta huella?", a: ["Zorro", "Corzo", "Tejón", "Liebre"], x: "Cuatro dedos con uñas y una almohadilla pequeña: un zorro. Es típico el óvalo estrecho: entre la almohadilla y los dedos queda un hueco en forma de X.", k: "Huella de zorro: óvalo estrecho, 4 dedos" }, pt: { q: "De quem é esta pegada?", a: ["Raposa", "Corço", "Texugo", "Lebre"], x: "Quatro dedos com unhas e uma almofadinha pequena: uma raposa. O típico é o oval estreito: entre a almofadinha e os dedos fica um vão em forma de X.", k: "Pegada de raposa: oval estreito, 4 dedos" }, ja: { q: "これはだれの足あと？", a: ["キツネ", "ノロジカ", "アナグマ", "ノウサギ"], x: "つめのある4本の指と小さな肉球：キツネです。細長い楕円形が特徴で、肉球と指の間にX字のすき間があります。", k: "キツネの足あと：細長い楕円に指4本" }, it: { q: "Di chi è questa impronta?", a: ["Volpe", "Capriolo", "Tasso", "Lepre"], x: "Quattro dita con unghie e un piccolo cuscinetto: una volpe. Tipico è l’ovale stretto: tra cuscinetto e dita resta uno spazio vuoto a forma di X.", k: "Impronta di volpe: ovale stretto, 4 dita" } } },
  { id: "d02", lvl: 2, type: "pic", right: 1, img: ["q-tr-deer"], t: { de: { q: "Wer ist hier durch den Matsch gelaufen?", a: ["Wildschwein", "Reh", "Hund", "Dachs"], x: "Zwei schmale, spitze Hufhälften: das Trittsiegel eines Rehs. Das Wildschwein hat breitere Hufe und dahinter meist zwei Abdrücke der Afterklauen.", k: "Reh-Spur: zwei schmale, spitze Hufe" }, en: { q: "Who walked through the mud here?", a: ["Wild boar", "Roe deer", "Dog", "Badger"], x: "Two narrow, pointed hoof halves: the print of a roe deer. A wild boar has wider hooves and usually two dewclaw marks behind them.", k: "Roe deer track: two narrow, pointed hooves" }, fr: { q: "Qui est passé dans la boue ici ?", a: ["Sanglier", "Chevreuil", "Chien", "Blaireau"], x: "Deux moitiés de sabot étroites et pointues : l’empreinte d’un chevreuil. Le sanglier a des sabots plus larges et, derrière, souvent deux marques d’ergots.", k: "Trace de chevreuil : deux sabots fins et pointus" }, es: { q: "¿Quién ha pasado por el barro?", a: ["Jabalí", "Corzo", "Perro", "Tejón"], x: "Dos mitades de pezuña estrechas y puntiagudas: la huella de un corzo. El jabalí tiene pezuñas más anchas y, detrás, casi siempre dos marcas de los espolones.", k: "Huella de corzo: dos pezuñas finas y puntiagudas" }, pt: { q: "Quem passou pela lama?", a: ["Javali", "Corço", "Cachorro", "Texugo"], x: "Duas metades de casco estreitas e pontudas: a pegada de um corço. O javali tem cascos mais largos e, atrás, quase sempre duas marcas dos dedos de trás.", k: "Pegada de corço: dois cascos finos e pontudos" }, ja: { q: "ここのぬかるみを歩いたのはだれ？", a: ["イノシシ", "ノロジカ", "イヌ", "アナグマ"], x: "細くてとがった2つに分かれたひづめ：ノロジカの足あとです。イノシシはひづめが太く、後ろにたいてい副蹄のあとが2つあります。", k: "ノロジカの足あと：細くとがった2つのひづめ" }, it: { q: "Chi è passato nel fango qui?", a: ["Cinghiale", "Capriolo", "Cane", "Tasso"], x: "Due metà di zoccolo strette e appuntite: l’impronta di un capriolo. Il cinghiale ha zoccoli più larghi e di solito dietro i segni di due speroni.", k: "Impronta di capriolo: due zoccoli stretti e appuntiti" } } },
  { id: "d03", lvl: 3, type: "pic", right: 2, img: ["q-tr-boar"], t: { de: { q: "Zwei Hufe und dahinter zwei Punkte – wer war das?", a: ["Reh", "Rothirsch", "Wildschwein", "Gämse"], x: "Die zwei Punkte sind die Afterklauen. Beim Wildschwein sitzen sie tief und weit außen und drücken sich fast immer mit ab – bei Reh und Hirsch meist nur in weichem Boden.", k: "Wildschwein-Spur: zwei Punkte hinter den Hufen" }, en: { q: "Two hooves and two dots behind them – who was it?", a: ["Roe deer", "Red deer", "Wild boar", "Chamois"], x: "The two dots are dewclaws. On a wild boar they sit low and wide and almost always leave a mark – on deer usually only in soft ground.", k: "Wild boar track: two dots behind the hooves" }, fr: { q: "Deux sabots et deux points derrière – qui est-ce ?", a: ["Chevreuil", "Cerf", "Sanglier", "Chamois"], x: "Les deux points sont les ergots. Chez le sanglier, ils sont bas et écartés et marquent presque toujours – chez le chevreuil et le cerf, surtout en sol mou.", k: "Trace de sanglier : deux points derrière les sabots" }, es: { q: "Dos pezuñas y dos puntos detrás: ¿quién fue?", a: ["Corzo", "Ciervo", "Jabalí", "Rebeco"], x: "Los dos puntos son los espolones. En el jabalí están bajos y separados y casi siempre se marcan; en corzos y ciervos, normalmente solo en suelo blando.", k: "Huella de jabalí: dos puntos tras las pezuñas" }, pt: { q: "Dois cascos e dois pontos atrás: quem foi?", a: ["Corço", "Veado", "Javali", "Camurça"], x: "Os dois pontos são os dedos de trás. No javali eles ficam baixos e afastados e quase sempre marcam; em corços e veados, normalmente só em chão mole.", k: "Pegada de javali: dois pontos atrás dos cascos" }, ja: { q: "ひづめが2つと、後ろに点が2つ。だれのもの？", a: ["ノロジカ", "アカシカ", "イノシシ", "シャモア"], x: "2つの点は副蹄です。イノシシでは低く広い位置にあって、ほぼ必ずあとが残ります。シカではふつう、やわらかい地面のときだけです。", k: "イノシシの足あと：ひづめの後ろに点2つ" }, it: { q: "Due zoccoli e due puntini dietro: chi era?", a: ["Capriolo", "Cervo nobile", "Cinghiale", "Camoscio"], x: "I due puntini sono gli speroni. Nel cinghiale sono bassi e larghi e lasciano quasi sempre il segno; nei cervidi di solito solo su terreno morbido.", k: "Impronta di cinghiale: due puntini dietro gli zoccoli" } } },
  { id: "d04", lvl: 2, type: "pic", right: 1, img: ["q-tr-badger"], t: { de: { q: "Wessen Spur ist das?", a: ["Fuchs", "Dachs", "Fischotter", "Hase"], x: "Fünf Zehen fast in einer Reihe vor einem breiten Ballen: ein Dachs. Mit den langen Krallen der Vorderpfoten gräbt er seine riesigen Baue.", k: "Dachs-Spur: fünf Zehen in einer Reihe" }, en: { q: "Whose track is this?", a: ["Fox", "Badger", "Otter", "Hare"], x: "Five toes almost in a row in front of a wide pad: a badger. With the long claws on its front paws it digs huge burrows.", k: "Badger track: five toes in a row" }, fr: { q: "À qui est cette empreinte ?", a: ["Renard", "Blaireau", "Loutre", "Lièvre"], x: "Cinq doigts presque alignés devant une large pelote : un blaireau. Avec les longues griffes de ses pattes avant, il creuse d’immenses terriers.", k: "Trace de blaireau : cinq doigts alignés" }, es: { q: "¿De quién es esta huella?", a: ["Zorro", "Tejón", "Nutria", "Liebre"], x: "Cinco dedos casi en fila delante de una almohadilla ancha: un tejón. Con las largas uñas de las patas delanteras excava enormes madrigueras.", k: "Huella de tejón: cinco dedos en fila" }, pt: { q: "De quem é esta pegada?", a: ["Raposa", "Texugo", "Lontra", "Lebre"], x: "Cinco dedos quase em fila na frente de uma almofada larga: um texugo. Com as unhas compridas das patas da frente ele cava tocas enormes.", k: "Pegada de texugo: cinco dedos em fila" }, ja: { q: "これはだれの足あと？", a: ["キツネ", "アナグマ", "カワウソ", "ノウサギ"], x: "幅広い肉球の前に、5本の指がほぼ一列に並んでいます：アナグマです。前足の長いつめで、大きな巣穴を掘ります。", k: "アナグマの足あと：指5本が一列" }, it: { q: "Di chi è questa impronta?", a: ["Volpe", "Tasso", "Lontra", "Lepre"], x: "Cinque dita quasi in fila davanti a un largo cuscinetto: un tasso. Con le lunghe unghie delle zampe anteriori scava tane enormi.", k: "Impronta di tasso: cinque dita in fila" } } },
  { id: "d05", lvl: 3, type: "pic", right: 1, img: ["q-tr-hare"], t: { de: { q: "Diese Spuren im Schnee (Laufrichtung nach oben): wer ist hier gehoppelt?", a: ["Eichhörnchen", "Hase", "Reh", "Fuchs"], x: "Beim Hasen landen die langen Hinterpfoten vor den Vorderpfoten, und die Vorderpfoten stehen hintereinander. Beim Eichhörnchen stehen auch die Vorderpfoten nebeneinander.", k: "Hasen-Spur: Hinterpfoten landen vorne" }, en: { q: "These tracks in the snow (moving upwards): who hopped here?", a: ["Squirrel", "Hare", "Roe deer", "Fox"], x: "A hare’s long hind feet land in front of its front feet, and the front feet land one behind the other. A squirrel puts its front feet side by side too.", k: "Hare track: hind feet land in front" }, fr: { q: "Ces traces dans la neige (direction vers le haut) : qui a sautillé ici ?", a: ["Écureuil", "Lièvre", "Chevreuil", "Renard"], x: "Chez le lièvre, les longues pattes arrière se posent devant les pattes avant, et celles-ci se suivent l’une derrière l’autre. L’écureuil pose aussi ses pattes avant côte à côte.", k: "Trace de lièvre : pattes arrière devant" }, es: { q: "Estas huellas en la nieve (dirección hacia arriba): ¿quién ha saltado aquí?", a: ["Ardilla", "Liebre", "Corzo", "Zorro"], x: "La liebre apoya sus largas patas traseras delante de las delanteras, y las delanteras quedan una detrás de otra. La ardilla pone también las delanteras una al lado de la otra.", k: "Huella de liebre: patas traseras delante" }, pt: { q: "Estas pegadas na neve (direção para cima): quem saltou aqui?", a: ["Esquilo", "Lebre", "Corço", "Raposa"], x: "A lebre apoia as patas traseiras compridas na frente das dianteiras, e as dianteiras ficam uma atrás da outra. O esquilo põe também as dianteiras uma ao lado da outra.", k: "Pegada de lebre: patas de trás na frente" }, ja: { q: "雪の上のこの足あと（上へ進んでいる）。はねたのはだれ？", a: ["リス", "ノウサギ", "ノロジカ", "キツネ"], x: "ノウサギは長い後ろ足を前足より前につき、前足は前後に並びます。リスは前足も左右に並べてつきます。", k: "ノウサギの足あと：後ろ足が前に着く" }, it: { q: "Queste tracce sulla neve (direzione verso l’alto): chi ha saltato qui?", a: ["Scoiattolo", "Lepre", "Capriolo", "Volpe"], x: "La lepre appoggia le lunghe zampe posteriori davanti a quelle anteriori, e le anteriori una dietro l’altra. Lo scoiattolo mette anche le anteriori affiancate.", k: "Impronta di lepre: zampe posteriori davanti" } } },
  { id: "d06", lvl: 1, type: "pic", right: 2, img: ["q-tr-duck"], t: { de: { q: "Wer hat am Ufer diese Spur hinterlassen?", a: ["Krähe", "Taube", "Stockente", "Graureiher"], x: "Drei Zehen nach vorn, verbunden mit Schwimmhäuten: eine Ente. Krähe, Taube und Reiher haben keine Schwimmhäute.", k: "Enten-Spur: Schwimmhäute zwischen den Zehen" }, en: { q: "Who left this track on the shore?", a: ["Crow", "Pigeon", "Mallard", "Grey heron"], x: "Three toes pointing forward, joined by webbing: a duck. Crows, pigeons and herons have no webbed feet.", k: "Duck track: webbing between the toes" }, fr: { q: "Qui a laissé cette trace sur la rive ?", a: ["Corneille", "Pigeon", "Canard colvert", "Héron cendré"], x: "Trois doigts vers l’avant reliés par une palmure : un canard. La corneille, le pigeon et le héron n’ont pas de pattes palmées.", k: "Trace de canard : palmures entre les doigts" }, es: { q: "¿Quién dejó esta huella en la orilla?", a: ["Corneja", "Paloma", "Ánade real", "Garza real"], x: "Tres dedos hacia delante unidos por membranas: un pato. Cornejas, palomas y garzas no tienen membranas.", k: "Huella de pato: membranas entre los dedos" }, pt: { q: "Quem deixou esta pegada na margem?", a: ["Gralha", "Pombo", "Pato-real", "Garça-real"], x: "Três dedos para a frente unidos por membranas: um pato. Gralhas, pombos e garças não têm membranas.", k: "Pegada de pato: membranas entre os dedos" }, ja: { q: "岸にこの足あとを残したのはだれ？", a: ["カラス", "ハト", "マガモ", "アオサギ"], x: "前向きの3本の指が水かきでつながっています：カモです。カラス、ハト、サギには水かきがありません。", k: "カモの足あと：指の間に水かき" }, it: { q: "Chi ha lasciato questa impronta sulla riva?", a: ["Cornacchia", "Piccione", "Germano reale", "Airone cenerino"], x: "Tre dita in avanti unite da una membrana: un’anatra. Cornacchie, piccioni e aironi non hanno piedi palmati.", k: "Impronta di anatra: membrana tra le dita" } } },
  { id: "d07", lvl: 2, type: "pic", right: 1, img: ["q-tr-crow"], t: { de: { q: "Welcher Vogel hat diesen Abdruck hinterlassen?", a: ["Stockente", "Rabenkrähe", "Höckerschwan", "Blässhuhn"], x: "Drei dünne Zehen nach vorn und eine lange nach hinten: typisch für Vögel wie die Krähe, die damit Äste umklammern. Enten und Schwäne haben Schwimmhäute, das Blässhuhn Schwimmlappen.", k: "Krähen-Spur: drei Zehen vorn, eine hinten" }, en: { q: "Which bird left this print?", a: ["Mallard", "Carrion crow", "Mute swan", "Coot"], x: "Three thin toes forward and a long one backwards: typical of birds like the crow, which use it to grip branches. Ducks and swans have webbed feet, coots have lobed toes.", k: "Crow track: three toes forward, one back" }, fr: { q: "Quel oiseau a laissé cette empreinte ?", a: ["Canard colvert", "Corneille noire", "Cygne tuberculé", "Foulque"], x: "Trois doigts fins vers l’avant et un long vers l’arrière : typique des oiseaux comme la corneille, qui s’agrippent ainsi aux branches. Canards et cygnes ont des palmures, la foulque des lobes.", k: "Trace de corneille : trois doigts devant, un derrière" }, es: { q: "¿Qué ave dejó esta huella?", a: ["Ánade real", "Corneja", "Cisne vulgar", "Focha"], x: "Tres dedos finos hacia delante y uno largo hacia atrás: típico de aves como la corneja, que así se agarran a las ramas. Patos y cisnes tienen membranas, la focha lóbulos.", k: "Huella de corneja: tres dedos delante, uno detrás" }, pt: { q: "Que ave deixou esta pegada?", a: ["Pato-real", "Gralha", "Cisne-branco", "Galeirão"], x: "Três dedos finos para a frente e um comprido para trás: típico de aves como a gralha, que assim se agarram aos galhos. Patos e cisnes têm membranas, o galeirão tem lobos.", k: "Pegada de gralha: três dedos à frente, um atrás" }, ja: { q: "この足あとを残した鳥は？", a: ["マガモ", "ハシボソガラス", "コブハクチョウ", "オオバン"], x: "前に細い指が3本、後ろに長い指が1本：枝をつかむカラスのような鳥の特徴です。カモやハクチョウには水かき、オオバンには弁足があります。", k: "カラスの足あと：前に3本、後ろに1本" }, it: { q: "Quale uccello ha lasciato questa impronta?", a: ["Germano reale", "Cornacchia nera", "Cigno reale", "Folaga"], x: "Tre dita sottili in avanti e una lunga indietro: tipico di uccelli come la cornacchia, che così si aggrappano ai rami. Anatre e cigni hanno piedi palmati, la folaga dita lobate.", k: "Impronta di cornacchia: tre dita avanti, una dietro" } } },
  { id: "d08", lvl: 2, type: "pic", right: 1, img: ["q-si-buzzard"], t: { de: { q: "Wer kreist da über dem Feld?", a: ["Rotmilan", "Mäusebussard", "Weißstorch", "Mauersegler"], x: "Breite Flügel mit gespreizten „Fingern“ und ein kurzer, runder Schwanz: der Mäusebussard. Oft sitzt er auch auf Zaunpfählen am Feldrand und späht nach Mäusen. Der Rotmilan hätte einen tief gegabelten Schwanz.", k: "Mäusebussard: kurzer, runder Schwanz" }, en: { q: "Who is circling over the field?", a: ["Red kite", "Common buzzard", "White stork", "Common swift"], x: "Broad wings with spread “fingers” and a short, round tail: the common buzzard. It often sits on fence posts at the edge of fields, watching for mice. A red kite would have a deeply forked tail.", k: "Common buzzard: short, round tail" }, fr: { q: "Qui tournoie au-dessus du champ ?", a: ["Milan royal", "Buse variable", "Cigogne blanche", "Martinet noir"], x: "De larges ailes aux « doigts » écartés et une queue courte et ronde : la buse variable. Elle guette souvent les souris perchée sur un piquet au bord des champs. Le milan royal aurait une queue profondément fourchue.", k: "Buse variable : queue courte et ronde" }, es: { q: "¿Quién vuela en círculos sobre el campo?", a: ["Milano real", "Busardo ratonero", "Cigüeña blanca", "Vencejo común"], x: "Alas anchas con los «dedos» abiertos y una cola corta y redonda: el busardo ratonero. A menudo acecha ratones posado en un poste junto a los campos. El milano real tendría la cola muy ahorquillada.", k: "Busardo ratonero: cola corta y redonda" }, pt: { q: "Quem voa em círculos sobre o campo?", a: ["Milhafre-real", "Águia-de-asa-redonda", "Cegonha-branca", "Andorinhão-preto"], x: "Asas largas com os “dedos” abertos e uma cauda curta e redonda: a águia-de-asa-redonda. Muitas vezes espreita ratos pousada num poste ao lado dos campos. O milhafre-real teria a cauda bem bifurcada.", k: "Águia-de-asa-redonda: cauda curta e redonda" }, ja: { q: "畑の上で輪をえがいて飛んでいるのはだれ？", a: ["アカトビ", "ヨーロッパノスリ", "シュバシコウ", "ヨーロッパアマツバメ"], x: "幅広い翼の先に広がった「指」、短くて丸い尾：ヨーロッパノスリです。畑のふちの杭にとまってネズミを探していることもよくあります。アカトビなら尾が深く切れこんでいます。", k: "ヨーロッパノスリ：短く丸い尾" }, it: { q: "Chi volteggia sopra il campo?", a: ["Nibbio reale", "Poiana", "Cicogna bianca", "Rondone comune"], x: "Ali larghe con le «dita» aperte e coda corta e arrotondata: la poiana. Spesso sta sui pali ai margini dei campi a spiare i topi. Il nibbio reale avrebbe la coda profondamente forcuta.", k: "Poiana: coda corta e arrotondata" } } },
  { id: "d09", lvl: 2, type: "pic", right: 1, img: ["q-si-kite"], t: { de: { q: "Wer ist das? Achte auf den Schwanz!", a: ["Mäusebussard", "Rotmilan", "Turmfalke", "Habicht"], x: "Der tief gegabelte Schwanz verrät den Rotmilan. Beim Segeln dreht er ihn ständig hin und her und steuert damit wie mit einem Ruder.", k: "Rotmilan: tief gegabelter Schwanz" }, en: { q: "Who is this? Look at the tail!", a: ["Common buzzard", "Red kite", "Kestrel", "Goshawk"], x: "The deeply forked tail gives away the red kite. While gliding, it keeps twisting it and steers with it like a rudder.", k: "Red kite: deeply forked tail" }, fr: { q: "Qui est-ce ? Regarde la queue !", a: ["Buse variable", "Milan royal", "Faucon crécerelle", "Autour des palombes"], x: "La queue profondément fourchue trahit le milan royal. En planant, il la tourne sans cesse et s’en sert comme d’un gouvernail.", k: "Milan royal : queue très fourchue" }, es: { q: "¿Quién es? ¡Fíjate en la cola!", a: ["Busardo ratonero", "Milano real", "Cernícalo", "Azor"], x: "La cola muy ahorquillada delata al milano real. Al planear la gira sin parar y la usa como un timón.", k: "Milano real: cola muy ahorquillada" }, pt: { q: "Quem é? Repare na cauda!", a: ["Águia-de-asa-redonda", "Milhafre-real", "Peneireiro", "Açor"], x: "A cauda bem bifurcada denuncia o milhafre-real. Ao planar, ele a gira sem parar e a usa como leme.", k: "Milhafre-real: cauda bem bifurcada" }, ja: { q: "これはだれ？ 尾に注目！", a: ["ヨーロッパノスリ", "アカトビ", "チョウゲンボウ", "オオタカ"], x: "深く切れこんだ尾でアカトビとわかります。滑空中は尾をくるくる動かし、舵のように使います。", k: "アカトビ：深く切れこんだ尾" }, it: { q: "Chi è? Guarda la coda!", a: ["Poiana", "Nibbio reale", "Gheppio", "Astore"], x: "La coda profondamente forcuta tradisce il nibbio reale. Mentre plana la gira di continuo e la usa come timone.", k: "Nibbio reale: coda molto forcuta" } } },
  { id: "d10", lvl: 2, type: "pic", right: 1, img: ["q-si-stork"], t: { de: { q: "Wer fliegt da mit lang gestrecktem Hals?", a: ["Graureiher", "Weißstorch", "Höckerschwan", "Mäusebussard"], x: "Langer Hals nach vorn, lange Beine nach hinten: der Weißstorch. Der Graureiher zieht im Flug den Hals ein, der Schwan hat kurze Beine.", k: "Storch: fliegt mit gestrecktem Hals" }, en: { q: "Who is flying with its neck stretched out?", a: ["Grey heron", "White stork", "Mute swan", "Common buzzard"], x: "Long neck forward, long legs back: the white stork. A grey heron pulls its neck in while flying, and a swan has short legs.", k: "Stork: flies with its neck stretched out" }, fr: { q: "Qui vole le cou tendu ?", a: ["Héron cendré", "Cigogne blanche", "Cygne tuberculé", "Buse variable"], x: "Long cou vers l’avant, longues pattes vers l’arrière : la cigogne blanche. Le héron rentre le cou en vol, et le cygne a des pattes courtes.", k: "Cigogne : vole cou tendu" }, es: { q: "¿Quién vuela con el cuello estirado?", a: ["Garza real", "Cigüeña blanca", "Cisne vulgar", "Busardo ratonero"], x: "Cuello largo hacia delante y patas largas hacia atrás: la cigüeña blanca. La garza recoge el cuello al volar y el cisne tiene patas cortas.", k: "Cigüeña: vuela con el cuello estirado" }, pt: { q: "Quem voa com o pescoço esticado?", a: ["Garça-real", "Cegonha-branca", "Cisne-branco", "Águia-de-asa-redonda"], x: "Pescoço comprido para a frente e pernas compridas para trás: a cegonha-branca. A garça recolhe o pescoço ao voar e o cisne tem pernas curtas.", k: "Cegonha: voa com o pescoço esticado" }, ja: { q: "首をまっすぐのばして飛んでいるのはだれ？", a: ["アオサギ", "シュバシコウ", "コブハクチョウ", "ヨーロッパノスリ"], x: "長い首は前へ、長い脚は後ろへ：シュバシコウです。アオサギは飛ぶとき首を縮め、ハクチョウは脚が短いです。", k: "コウノトリ：首をのばして飛ぶ" }, it: { q: "Chi vola con il collo disteso?", a: ["Airone cenerino", "Cicogna bianca", "Cigno reale", "Poiana"], x: "Collo lungo in avanti, zampe lunghe indietro: la cicogna bianca. L’airone in volo ritrae il collo e il cigno ha le zampe corte.", k: "Cicogna: vola col collo disteso" } } },
  { id: "d11", lvl: 3, type: "pic", right: 2, img: ["q-si-heron"], t: { de: { q: "Lange Beine nach hinten, aber der Hals ist eingezogen. Wer ist das?", a: ["Weißstorch", "Kranich", "Graureiher", "Kormoran"], x: "Reiher legen den Hals im Flug in eine S-Kurve und ziehen den Kopf ein. Störche und Kraniche fliegen mit gestrecktem Hals.", k: "Graureiher: fliegt mit eingezogenem Hals" }, en: { q: "Long legs trailing, but the neck is pulled in. Who is it?", a: ["White stork", "Common crane", "Grey heron", "Cormorant"], x: "Herons fold their neck into an S-shape and pull in their head while flying. Storks and cranes fly with their necks stretched out.", k: "Grey heron: flies with its neck pulled in" }, fr: { q: "Longues pattes vers l’arrière, mais le cou rentré. Qui est-ce ?", a: ["Cigogne blanche", "Grue cendrée", "Héron cendré", "Grand cormoran"], x: "En vol, les hérons plient le cou en S et rentrent la tête. Cigognes et grues volent le cou tendu.", k: "Héron cendré : vole cou rentré" }, es: { q: "Patas largas hacia atrás, pero el cuello recogido. ¿Quién es?", a: ["Cigüeña blanca", "Grulla común", "Garza real", "Cormorán"], x: "Las garzas doblan el cuello en forma de S y recogen la cabeza al volar. Cigüeñas y grullas vuelan con el cuello estirado.", k: "Garza real: vuela con el cuello recogido" }, pt: { q: "Pernas compridas para trás, mas o pescoço recolhido. Quem é?", a: ["Cegonha-branca", "Grou-comum", "Garça-real", "Corvo-marinho"], x: "As garças dobram o pescoço em forma de S e recolhem a cabeça ao voar. Cegonhas e grous voam com o pescoço esticado.", k: "Garça-real: voa com o pescoço recolhido" }, ja: { q: "長い脚は後ろへのびているのに、首は縮めている。だれ？", a: ["シュバシコウ", "クロヅル", "アオサギ", "カワウ"], x: "サギは飛ぶとき首をS字に折りたたみ、頭を引っこめます。コウノトリやツルは首をのばして飛びます。", k: "アオサギ：首を縮めて飛ぶ" }, it: { q: "Zampe lunghe indietro, ma il collo ritratto. Chi è?", a: ["Cicogna bianca", "Gru cenerina", "Airone cenerino", "Cormorano"], x: "Gli aironi piegano il collo a S e ritirano la testa in volo. Cicogne e gru volano con il collo disteso.", k: "Airone cenerino: vola col collo ritratto" } } },
  { id: "d12", lvl: 3, type: "pic", right: 1, img: ["q-si-swift"], t: { de: { q: "Wer saust da mit sichelförmigen Flügeln über die Dächer?", a: ["Rauchschwalbe", "Mauersegler", "Mehlschwalbe", "Turmfalke"], x: "Sichelflügel und ein kurzer Gabelschwanz: der Mauersegler. Seine Füße sind winzig – auf den Boden setzt er sich fast nie, er krallt sich lieber an Mauern fest.", k: "Mauersegler: sichelförmige Flügel" }, en: { q: "Who is racing over the rooftops with sickle-shaped wings?", a: ["Barn swallow", "Common swift", "House martin", "Kestrel"], x: "Sickle wings and a short forked tail: the common swift. Its feet are tiny – it almost never lands on the ground and prefers to cling to walls.", k: "Swift: sickle-shaped wings" }, fr: { q: "Qui file au-dessus des toits avec des ailes en faucille ?", a: ["Hirondelle rustique", "Martinet noir", "Hirondelle de fenêtre", "Faucon crécerelle"], x: "Des ailes en faucille et une courte queue fourchue : le martinet noir. Ses pattes sont minuscules – il ne se pose presque jamais au sol et s’agrippe plutôt aux murs.", k: "Martinet : ailes en faucille" }, es: { q: "¿Quién pasa volando sobre los tejados con alas en forma de hoz?", a: ["Golondrina común", "Vencejo común", "Avión común", "Cernícalo"], x: "Alas en forma de hoz y una cola corta ahorquillada: el vencejo común. Sus patas son diminutas: casi nunca se posa en el suelo y prefiere agarrarse a las paredes.", k: "Vencejo: alas en forma de hoz" }, pt: { q: "Quem passa voando sobre os telhados com asas em forma de foice?", a: ["Andorinha-das-chaminés", "Andorinhão-preto", "Andorinha-dos-beirais", "Peneireiro"], x: "Asas em forma de foice e cauda curta bifurcada: o andorinhão-preto. As patas são minúsculas: quase nunca pousa no chão e prefere se agarrar às paredes.", k: "Andorinhão: asas em forma de foice" }, ja: { q: "かま形の翼で屋根の上をびゅんびゅん飛ぶのはだれ？", a: ["ツバメ", "ヨーロッパアマツバメ", "ニシイワツバメ", "チョウゲンボウ"], x: "かま形の翼と、短く切れこんだ尾：ヨーロッパアマツバメです。足はとても小さく、地面にはほとんど降りず、壁にしがみつくほうが得意です。", k: "アマツバメ：かま形の翼" }, it: { q: "Chi sfreccia sopra i tetti con ali a forma di falce?", a: ["Rondine", "Rondone comune", "Balestruccio", "Gheppio"], x: "Ali a falce e coda corta e forcuta: il rondone comune. Le zampe sono minuscole: non si posa quasi mai a terra e preferisce aggrapparsi ai muri.", k: "Rondone: ali a falce" } } },
  { id: "d13", lvl: 3, type: "pic", right: 1, img: ["q-si-swallow"], t: { de: { q: "Lange Schwanzspieße und spitze Flügel – wer ist das?", a: ["Mauersegler", "Rauchschwalbe", "Rotmilan", "Kuckuck"], x: "Die langen Schwanzspieße gehören der Rauchschwalbe. Der Mauersegler hat längere, sichelförmige Flügel und einen kurzen Schwanz.", k: "Rauchschwalbe: lange Schwanzspieße" }, en: { q: "Long tail streamers and pointed wings – who is it?", a: ["Common swift", "Barn swallow", "Red kite", "Cuckoo"], x: "The long tail streamers belong to the barn swallow. A swift has longer, sickle-shaped wings and a short tail.", k: "Barn swallow: long tail streamers" }, fr: { q: "De longs filets à la queue et des ailes pointues – qui est-ce ?", a: ["Martinet noir", "Hirondelle rustique", "Milan royal", "Coucou"], x: "Les longs filets de la queue sont ceux de l’hirondelle rustique. Le martinet a des ailes plus longues en faucille et une queue courte.", k: "Hirondelle rustique : longs filets de queue" }, es: { q: "Largas plumas en la cola y alas puntiagudas: ¿quién es?", a: ["Vencejo común", "Golondrina común", "Milano real", "Cuco"], x: "Las largas plumas de la cola son de la golondrina común. El vencejo tiene alas más largas en forma de hoz y la cola corta.", k: "Golondrina: largas plumas en la cola" }, pt: { q: "Penas compridas na cauda e asas pontudas: quem é?", a: ["Andorinhão-preto", "Andorinha-das-chaminés", "Milhafre-real", "Cuco"], x: "As penas compridas da cauda são da andorinha-das-chaminés. O andorinhão tem asas mais longas em forma de foice e a cauda curta.", k: "Andorinha: penas longas na cauda" }, ja: { q: "長い尾羽ととがった翼。だれ？", a: ["ヨーロッパアマツバメ", "ツバメ", "アカトビ", "カッコウ"], x: "長くのびた尾羽はツバメのもの。アマツバメの翼はもっと長いかま形で、尾は短めです。", k: "ツバメ：長い尾羽" }, it: { q: "Lunghe penne della coda e ali appuntite: chi è?", a: ["Rondone comune", "Rondine", "Nibbio reale", "Cuculo"], x: "Le lunghe penne della coda sono della rondine. Il rondone ha ali più lunghe a falce e la coda corta.", k: "Rondine: lunghe penne della coda" } } },
  { id: "d14", lvl: 1, type: "pic", right: 0, img: ["q-fi-beaver"], t: { de: { q: "Wer hat diesen Baum so angenagt?", a: ["Biber", "Wildschwein", "Specht", "Eichhörnchen"], x: "Die Sanduhr-Form ist typisch für den Biber, die Späne liegen drum herum. Er fällt Bäume vor allem, um an Rinde, Zweige und Knospen zu kommen – sein Futter.", k: "Biber: nagt Bäume wie eine Sanduhr" }, en: { q: "Who gnawed this tree like that?", a: ["Beaver", "Wild boar", "Woodpecker", "Squirrel"], x: "The hourglass shape is typical of a beaver, with chips lying all around. It fells trees mainly to reach the bark, twigs and buds – its food.", k: "Beaver: gnaws trees into an hourglass" }, fr: { q: "Qui a rongé cet arbre ainsi ?", a: ["Castor", "Sanglier", "Pic", "Écureuil"], x: "La forme de sablier est typique du castor, avec des copeaux tout autour. Il abat surtout les arbres pour atteindre l’écorce, les rameaux et les bourgeons – sa nourriture.", k: "Castor : ronge les arbres en sablier" }, es: { q: "¿Quién ha roído este árbol así?", a: ["Castor", "Jabalí", "Pájaro carpintero", "Ardilla"], x: "La forma de reloj de arena es típica del castor, con las virutas alrededor. Derriba árboles sobre todo para llegar a la corteza, las ramitas y los brotes: su comida.", k: "Castor: roe los árboles como un reloj de arena" }, pt: { q: "Quem roeu esta árvore assim?", a: ["Castor", "Javali", "Pica-pau", "Esquilo"], x: "A forma de ampulheta é típica do castor, com as lascas em volta. Ele derruba árvores sobretudo para alcançar a casca, os raminhos e os brotos – sua comida.", k: "Castor: rói árvores em forma de ampulheta" }, ja: { q: "この木をこんなふうにかじったのはだれ？", a: ["ビーバー", "イノシシ", "キツツキ", "リス"], x: "砂時計の形はビーバーの特徴で、まわりに木くずが散らばります。木をたおすのは、主にえさの樹皮や小枝、芽を食べるためです。", k: "ビーバー：木を砂時計の形にかじる" }, it: { q: "Chi ha rosicchiato così quest’albero?", a: ["Castoro", "Cinghiale", "Picchio", "Scoiattolo"], x: "La forma a clessidra è tipica del castoro, con i trucioli tutto intorno. Abbatte gli alberi soprattutto per arrivare a corteccia, rametti e gemme, il suo cibo.", k: "Castoro: rosicchia gli alberi a clessidra" } } },
  { id: "d15", lvl: 2, type: "pic", right: 1, img: ["q-fi-mole"], t: { de: { q: "Wer hat diese Erdhügel in der Wiese aufgeworfen?", a: ["Wühlmaus", "Maulwurf", "Igel", "Dachs"], x: "Maulwurfshügel sind hoch und rund, der Gang führt senkrecht in der Mitte nach unten. Hügel von Wühlmäusen sind flacher, ihr Gang liegt seitlich.", k: "Maulwurf: hohe, runde Erdhügel" }, en: { q: "Who threw up these mounds of earth in the meadow?", a: ["Vole", "Mole", "Hedgehog", "Badger"], x: "Molehills are high and round, with the tunnel going straight down in the middle. Vole mounds are flatter and their tunnel is off to the side.", k: "Mole: high, round molehills" }, fr: { q: "Qui a fait ces monticules de terre dans le pré ?", a: ["Campagnol", "Taupe", "Hérisson", "Blaireau"], x: "Les taupinières sont hautes et rondes, la galerie descend tout droit au milieu. Les monticules du campagnol sont plus plats, avec la galerie sur le côté.", k: "Taupe : taupinières hautes et rondes" }, es: { q: "¿Quién ha levantado estos montículos de tierra en el prado?", a: ["Topillo", "Topo", "Erizo", "Tejón"], x: "Las toperas son altas y redondas, y el túnel baja recto por el centro. Los montículos del topillo son más planos y su túnel queda a un lado.", k: "Topo: montículos altos y redondos" }, pt: { q: "Quem levantou estes montinhos de terra no gramado?", a: ["Rato-do-campo", "Toupeira", "Ouriço", "Texugo"], x: "Os montes da toupeira são altos e redondos, e o túnel desce reto pelo meio. Os montinhos do rato-do-campo são mais baixos e o túnel fica de lado.", k: "Toupeira: montes altos e redondos" }, ja: { q: "草地にこの土の山を作ったのはだれ？", a: ["ハタネズミ", "モグラ", "ハリネズミ", "アナグマ"], x: "モグラ塚は高く丸く、トンネルは真ん中からまっすぐ下へのびています。ハタネズミの山は平たく、トンネルは横にずれています。", k: "モグラ：高く丸い土の山" }, it: { q: "Chi ha sollevato questi mucchi di terra nel prato?", a: ["Arvicola", "Talpa", "Riccio", "Tasso"], x: "I cumuli della talpa sono alti e rotondi, con la galleria che scende dritta nel mezzo. Quelli dell’arvicola sono più piatti e la galleria è di lato.", k: "Talpa: cumuli alti e rotondi" } } },
  { id: "d16", lvl: 2, type: "pic", right: 2, img: ["q-fi-woodpecker"], t: { de: { q: "Wer hat dieses runde Loch in den Stamm gezimmert?", a: ["Eichhörnchen", "Waldkauz", "Buntspecht", "Kleiber"], x: "Spechte zimmern sich jedes Jahr neue Höhlen. Die alten werden zur Wohnung für viele andere: Meisen, Kleiber, Fledermäuse oder Eichhörnchen.", k: "Buntspecht: zimmert jedes Jahr neue Höhlen" }, en: { q: "Who carved this round hole into the trunk?", a: ["Squirrel", "Tawny owl", "Great spotted woodpecker", "Nuthatch"], x: "Woodpeckers carve new holes every year. The old ones become homes for many others: tits, nuthatches, bats or squirrels.", k: "Woodpecker: carves new holes every year" }, fr: { q: "Qui a creusé ce trou rond dans le tronc ?", a: ["Écureuil", "Chouette hulotte", "Pic épeiche", "Sittelle"], x: "Les pics creusent de nouvelles loges chaque année. Les anciennes servent de logement à bien d’autres : mésanges, sittelles, chauves-souris ou écureuils.", k: "Pic épeiche : creuse de nouvelles loges chaque année" }, es: { q: "¿Quién ha hecho este agujero redondo en el tronco?", a: ["Ardilla", "Cárabo", "Pico picapinos", "Trepador azul"], x: "Los pájaros carpinteros excavan nidos nuevos cada año. Los viejos sirven de hogar a muchos otros: carboneros, trepadores, murciélagos o ardillas.", k: "Pico picapinos: excava agujeros nuevos cada año" }, pt: { q: "Quem fez este buraco redondo no tronco?", a: ["Esquilo", "Coruja-do-mato", "Pica-pau-malhado-grande", "Trepadeira-azul"], x: "Os pica-paus cavam ninhos novos todo ano. Os velhos viram lar de muitos outros: chapins, trepadeiras, morcegos ou esquilos.", k: "Pica-pau: cava ninhos novos todo ano" }, ja: { q: "幹にこの丸い穴をあけたのはだれ？", a: ["リス", "モリフクロウ", "アカゲラ", "ゴジュウカラ"], x: "キツツキは毎年新しい穴を掘ります。古い穴は、シジュウカラ、ゴジュウカラ、コウモリ、リスなど、たくさんの生きものの家になります。", k: "キツツキ：毎年新しい穴を掘る" }, it: { q: "Chi ha scavato questo buco rotondo nel tronco?", a: ["Scoiattolo", "Allocco", "Picchio rosso maggiore", "Picchio muratore"], x: "I picchi scavano nidi nuovi ogni anno. Quelli vecchi diventano casa per molti altri: cince, picchi muratori, pipistrelli o scoiattoli.", k: "Picchio rosso: scava nidi nuovi ogni anno" } } },
  { id: "d17", lvl: 2, type: "pic", right: 2, img: ["q-fi-wasp"], t: { de: { q: "Woraus bauen Wespen so ein Nest?", a: ["Bienenwachs", "Lehm", "Zerkautem Holz", "Spinnenseide"], x: "Wespen raspeln Holz ab, kauen es mit Speichel durch und bauen daraus papierartige Wände. Wespen waren die ersten Papiermacher.", k: "Wespen: bauen Nester aus Papier" }, en: { q: "What do wasps build a nest like this from?", a: ["Beeswax", "Clay", "Chewed wood", "Spider silk"], x: "Wasps scrape off wood, chew it with saliva and build paper-like walls from it. Wasps were the first paper makers.", k: "Wasps: build nests from paper" }, fr: { q: "Avec quoi les guêpes construisent-elles un tel nid ?", a: ["De la cire", "De l’argile", "Du bois mâché", "De la soie d’araignée"], x: "Les guêpes râpent du bois, le mâchent avec leur salive et en font des parois comme du papier. Les guêpes ont été les premières à fabriquer du papier.", k: "Guêpes : nids en papier" }, es: { q: "¿Con qué construyen las avispas un nido así?", a: ["Cera de abeja", "Barro", "Madera masticada", "Seda de araña"], x: "Las avispas raspan madera, la mastican con saliva y construyen paredes como de papel. Las avispas fueron las primeras en fabricar papel.", k: "Avispas: nidos de papel" }, pt: { q: "Com o que as vespas constroem um ninho assim?", a: ["Cera de abelha", "Barro", "Madeira mastigada", "Seda de aranha"], x: "As vespas raspam madeira, mastigam com saliva e constroem paredes como de papel. As vespas foram as primeiras a fabricar papel.", k: "Vespas: ninhos de papel" }, ja: { q: "ハチ（スズメバチ）はこんな巣を何で作る？", a: ["ミツロウ", "粘土", "かみくだいた木", "クモの糸"], x: "スズメバチは木をけずり、だ液とかみまぜて、紙のような壁を作ります。紙を最初に作ったのはスズメバチなのです。", k: "スズメバチ：紙の巣を作る" }, it: { q: "Con cosa costruiscono le vespe un nido così?", a: ["Cera d’api", "Argilla", "Legno masticato", "Seta di ragno"], x: "Le vespe raschiano il legno, lo masticano con la saliva e ne fanno pareti simili a carta. Le vespe sono state le prime a fare la carta.", k: "Vespe: nidi di carta" } } },
  { id: "d18", lvl: 1, type: "pic", right: 1, img: ["q-fi-ants"], t: { de: { q: "Wer baut solche Hügel aus Nadeln und Zweigen?", a: ["Maulwurf", "Rote Waldameise", "Wildschwein", "Borkenkäfer"], x: "In einem großen Waldameisenhügel können bis zu einer Million Ameisen leben. Unter dem Hügel reicht das Nest oft genauso tief in die Erde.", k: "Waldameisen: bis zu 1 Million in einem Haufen" }, en: { q: "Who builds mounds like this from needles and twigs?", a: ["Mole", "Red wood ant", "Wild boar", "Bark beetle"], x: "Up to a million ants can live in a big wood ant mound. Beneath the mound, the nest often reaches just as deep into the ground.", k: "Wood ants: up to 1 million in one mound" }, fr: { q: "Qui construit de tels dômes d’aiguilles et de brindilles ?", a: ["Taupe", "Fourmi rousse des bois", "Sanglier", "Scolyte"], x: "Jusqu’à un million de fourmis peuvent vivre dans une grande fourmilière. Sous le dôme, le nid s’enfonce souvent aussi profond dans le sol.", k: "Fourmis des bois : jusqu’à 1 million par dôme" }, es: { q: "¿Quién construye montículos así con agujas y ramitas?", a: ["Topo", "Hormiga roja de bosque", "Jabalí", "Escarabajo de la corteza"], x: "En un gran hormiguero de hormigas de bosque pueden vivir hasta un millón de hormigas. Bajo el montículo, el nido suele llegar igual de hondo en la tierra.", k: "Hormigas rojas: hasta 1 millón por hormiguero" }, pt: { q: "Quem constrói montes assim com agulhas e raminhos?", a: ["Toupeira", "Formiga-ruiva-da-floresta", "Javali", "Besouro-da-casca"], x: "Num grande formigueiro de formigas-da-floresta podem viver até um milhão de formigas. Embaixo do monte, o ninho costuma descer o mesmo tanto na terra.", k: "Formigas-da-floresta: até 1 milhão num formigueiro" }, ja: { q: "針葉や小枝でこんな山を作るのはだれ？", a: ["モグラ", "ヨーロッパアカヤマアリ", "イノシシ", "キクイムシ"], x: "大きなヤマアリの塚には最大100万匹がすみます。塚の下には、同じくらいの深さまで巣が続いていることも。", k: "ヤマアリ：1つの塚に最大100万匹" }, it: { q: "Chi costruisce mucchi così con aghi e rametti?", a: ["Talpa", "Formica rossa dei boschi", "Cinghiale", "Bostrico"], x: "In un grande formicaio delle formiche dei boschi possono vivere fino a un milione di formiche. Sotto il cumulo, spesso il nido scende altrettanto nel terreno.", k: "Formiche dei boschi: fino a 1 milione per formicaio" } } },
  { id: "d19", lvl: 3, type: "pic", right: 1, img: ["q-fi-spittle"], t: { de: { q: "Was versteckt sich in diesem Schaum am Grashalm?", a: ["Spucke vom Kuckuck", "Larve einer Schaumzikade", "Eier einer Schnecke", "Ein Spinnennest"], x: "Die Larve der Schaumzikade bläst Luft in ihren Saft und baut sich so ein Schaumversteck – gegen Austrocknen und Feinde. Mit dem Kuckuck hat die „Kuckucksspucke“ nichts zu tun.", k: "Kuckucksspucke: Versteck einer Zikaden-Larve" }, en: { q: "What is hiding in this foam on the grass stem?", a: ["Cuckoo spit from a bird", "A froghopper larva", "Snail eggs", "A spider nest"], x: "The froghopper larva blows air into its sap and builds a foam hideout – against drying out and enemies. Despite the name “cuckoo spit”, cuckoos have nothing to do with it.", k: "Cuckoo spit: hideout of a froghopper larva" }, fr: { q: "Qui se cache dans cette mousse sur la tige ?", a: ["De la salive de coucou", "Une larve de cercope", "Des œufs d’escargot", "Un nid d’araignée"], x: "La larve du cercope souffle de l’air dans sa sève et se fabrique une cachette de mousse – contre le dessèchement et les ennemis. Le « crachat de coucou » n’a rien à voir avec le coucou.", k: "Crachat de coucou : cachette d’une larve de cercope" }, es: { q: "¿Qué se esconde en esta espuma del tallo?", a: ["Saliva de cuco", "Una larva de cercópido", "Huevos de caracol", "Un nido de araña"], x: "La larva del cercópido sopla aire en su savia y se construye un escondite de espuma, contra la sequedad y los enemigos. La llamada «saliva de cuco» no tiene nada que ver con el cuco.", k: "Saliva de cuco: escondite de una larva de cercópido" }, pt: { q: "O que se esconde nesta espuma no caule?", a: ["Saliva de cuco", "Uma larva de cigarrinha-espumosa", "Ovos de caracol", "Um ninho de aranha"], x: "A larva da cigarrinha-espumosa sopra ar na própria seiva e constrói um esconderijo de espuma contra o ressecamento e os inimigos. A tal “saliva de cuco” não tem nada a ver com o cuco.", k: "Espuma no capim: esconderijo de cigarrinha" }, ja: { q: "草の茎についたこの泡の中にかくれているのは？", a: ["鳥のカッコウのつば", "アワフキムシの幼虫", "カタツムリの卵", "クモの巣"], x: "アワフキムシの幼虫は、自分の出す汁に空気を吹きこんで泡の隠れ家を作ります。乾燥と敵から身を守るためです。ヨーロッパでは「カッコウのつば」と呼ばれますが、カッコウとは無関係です。", k: "草の泡：アワフキムシの幼虫の隠れ家" }, it: { q: "Cosa si nasconde in questa schiuma sullo stelo?", a: ["Sputo di cuculo", "Una larva di sputacchina", "Uova di chiocciola", "Un nido di ragno"], x: "La larva della sputacchina soffia aria nella sua linfa e si costruisce un rifugio di schiuma contro la secchezza e i nemici. Nonostante il nome «sputo di cuculo», il cuculo non c’entra.", k: "Sputo di cuculo: rifugio di una sputacchina" } } },
  { id: "d20", lvl: 3, type: "pic", right: 1, img: ["q-fi-gall"], t: { de: { q: "Wer wohnt in dieser Kugel am Eichenblatt?", a: ["Raupe eines Falters", "Larve einer Gallwespe", "Junge Spinne", "Überwinternder Käfer"], x: "Die Gallwespe legt ihr Ei ins Blatt, die Eiche bildet darum diese „Galle“. Darin wohnt und frisst die Larve. Aus Galläpfeln machte man früher Tinte.", k: "Gallwespe: Larve lebt in der Eichen-Galle" }, en: { q: "Who lives in this ball on the oak leaf?", a: ["A moth caterpillar", "A gall wasp larva", "A young spider", "A beetle spending the winter"], x: "The gall wasp lays its egg in the leaf, and the oak grows this “gall” around it. The larva lives and feeds inside. Oak galls were once used to make ink.", k: "Gall wasp: larva lives in the oak gall" }, fr: { q: "Qui habite dans cette boule sur la feuille de chêne ?", a: ["Une chenille de papillon", "Une larve de cynips", "Une jeune araignée", "Un coléoptère qui hiverne"], x: "Le cynips pond son œuf dans la feuille, et le chêne forme autour cette « galle ». La larve y vit et s’y nourrit. On fabriquait autrefois de l’encre avec les galles.", k: "Cynips : la larve vit dans la galle du chêne" }, es: { q: "¿Quién vive en esta bola de la hoja de roble?", a: ["Una oruga de mariposa", "Una larva de avispa de las agallas", "Una araña joven", "Un escarabajo que pasa el invierno"], x: "La avispa de las agallas pone su huevo en la hoja y el roble forma a su alrededor esta «agalla». Dentro vive y come la larva. Antes se hacía tinta con las agallas.", k: "Avispa de las agallas: larva dentro de la agalla" }, pt: { q: "Quem vive nesta bolinha na folha do carvalho?", a: ["Uma lagarta de borboleta", "Uma larva de vespa-das-galhas", "Uma aranha jovem", "Um besouro passando o inverno"], x: "A vespa-das-galhas põe o ovo na folha, e o carvalho forma em volta essa “galha”. Lá dentro a larva vive e come. Antigamente se fazia tinta com as galhas.", k: "Vespa-das-galhas: larva dentro da galha" }, ja: { q: "カシの葉についたこの玉の中にすんでいるのは？", a: ["ガの幼虫", "タマバチの幼虫", "子グモ", "冬を越す甲虫"], x: "タマバチが葉に卵を産むと、カシがそのまわりにこの「虫こぶ」を作ります。幼虫は中で暮らして食べます。昔は虫こぶからインクを作りました。", k: "タマバチ：幼虫は虫こぶの中で暮らす" }, it: { q: "Chi vive in questa pallina sulla foglia di quercia?", a: ["Un bruco di falena", "Una larva di cinipide", "Un ragnetto", "Un coleottero che sverna"], x: "Il cinipide depone l’uovo nella foglia e la quercia ci forma intorno questa «galla». La larva ci vive e si nutre. Un tempo con le galle si faceva l’inchiostro.", k: "Cinipide: la larva vive nella galla" } } },
  { id: "d21", lvl: 2, type: "pic", right: 1, img: ["q-fi-pellet"], t: { de: { q: "Grau, fellig, mit kleinen Knochen: Was hast du unter dem Baum gefunden?", a: ["Kot vom Fuchs", "Gewölle einer Eule", "Nest einer Maus", "Haarballen einer Katze"], x: "Ein Gewölle: Fell und Knochen, die die Eule wieder hochgewürgt hat. Aus den winzigen Schädeln darin kann man sogar bestimmen, welche Mäusearten in der Gegend leben.", k: "Gewölle: verrät, welche Mäuse in der Gegend leben" }, en: { q: "Grey, furry, with tiny bones: what did you find under the tree?", a: ["Fox droppings", "An owl pellet", "A mouse nest", "A cat’s hairball"], x: "An owl pellet: fur and bones the owl coughed back up. From the tiny skulls inside you can even tell which kinds of mice live in the area.", k: "Owl pellets: reveal which mice live nearby" }, fr: { q: "Gris, poilu, avec de petits os : qu’as-tu trouvé sous l’arbre ?", a: ["Une crotte de renard", "Une pelote de réjection de chouette", "Un nid de souris", "Une boule de poils de chat"], x: "Une pelote de réjection : poils et os recrachés par la chouette. Grâce aux minuscules crânes, on peut même savoir quelles espèces de souris vivent dans le coin.", k: "Pelotes : révèlent les souris du coin" }, es: { q: "Gris, peludo y con huesecillos: ¿qué has encontrado bajo el árbol?", a: ["Excremento de zorro", "Una egagrópila de búho", "Un nido de ratón", "Una bola de pelo de gato"], x: "Una egagrópila: pelo y huesos que el búho ha regurgitado. Por los diminutos cráneos se puede saber incluso qué especies de ratones viven en la zona.", k: "Egagrópilas: revelan los ratones de la zona" }, pt: { q: "Cinza, peludo e com ossinhos: o que você encontrou debaixo da árvore?", a: ["Cocô de raposa", "Uma egagrópila de coruja", "Um ninho de rato", "Uma bola de pelo de gato"], x: "Uma egagrópila: pelos e ossos que a coruja regurgitou. Pelos crânios minúsculos dá até para saber quais espécies de ratos vivem na região.", k: "Egagrópilas: revelam os ratos da região" }, ja: { q: "灰色で毛だらけ、中に小さな骨。木の下で見つけたのは？", a: ["キツネのフン", "フクロウのペリット", "ネズミの巣", "ネコの毛玉"], x: "フクロウのペリット：フクロウが吐きもどした毛と骨です。中の小さな頭の骨から、その地域にどんなネズミがすんでいるかまでわかります。", k: "ペリット：近くにすむネズミがわかる" }, it: { q: "Grigia, pelosa e con ossicini: cosa hai trovato sotto l’albero?", a: ["Escrementi di volpe", "Una borra di gufo", "Un nido di topo", "Un bolo di pelo di gatto"], x: "Una borra di gufo: pelo e ossa rigurgitati. Dai minuscoli crani dentro si capisce persino quali topi vivono nella zona.", k: "Borre: rivelano i topi della zona" } } },
  { id: "c01", lvl: 2, type: "text", right: 1, t: { de: { q: "Welches dieser Tiere hat drei Herzen?", a: ["Krabbe", "Krake", "Hai", "Schnecke"], x: "Kraken haben zwei Kiemenherzen und ein Körperherz, das ihr blaues Blut durch den Körper pumpt.", k: "Krake: hat drei Herzen" }, en: { q: "Which of these animals has three hearts?", a: ["Crab", "Octopus", "Shark", "Snail"], x: "Octopuses have two gill hearts and one main heart that pumps their blue blood around the body.", k: "Octopus: has three hearts" }, fr: { q: "Lequel de ces animaux a trois cœurs ?", a: ["Crabe", "Pieuvre", "Requin", "Escargot"], x: "La pieuvre a deux cœurs branchiaux et un cœur principal qui pompe son sang bleu dans le corps.", k: "Pieuvre : trois cœurs" }, es: { q: "¿Cuál de estos animales tiene tres corazones?", a: ["Cangrejo", "Pulpo", "Tiburón", "Caracol"], x: "El pulpo tiene dos corazones branquiales y uno principal que bombea su sangre azul por el cuerpo.", k: "Pulpo: tres corazones" }, pt: { q: "Qual destes animais tem três corações?", a: ["Caranguejo", "Polvo", "Tubarão", "Caracol"], x: "O polvo tem dois corações das brânquias e um principal, que bombeia o sangue azul pelo corpo.", k: "Polvo: três corações" }, ja: { q: "心臓が3つある動物は？", a: ["カニ", "タコ", "サメ", "カタツムリ"], x: "タコには、えらの心臓が2つと、青い血を全身に送る本体の心臓が1つあります。", k: "タコ：心臓が3つ" }, it: { q: "Quale di questi animali ha tre cuori?", a: ["Granchio", "Polpo", "Squalo", "Chiocciola"], x: "I polpi hanno due cuori branchiali e un cuore principale che pompa il loro sangue blu in tutto il corpo.", k: "Polpo: tre cuori" } } },
  { id: "c02", lvl: 1, type: "text", right: 3, t: { de: { q: "Wer hält einen echten Winterschlaf?", a: ["Eichhörnchen", "Reh", "Fuchs", "Igel"], x: "Im Winterschlaf sinkt die Körpertemperatur des Igels auf etwa 5 °C. Eichhörnchen halten nur Winterruhe.", k: "Igel: Winterschlaf bei 5 °C Körpertemperatur" }, en: { q: "Which animal truly hibernates?", a: ["Squirrel", "Roe deer", "Fox", "Hedgehog"], x: "In hibernation a hedgehog's body temperature drops to about 5 °C. Squirrels only rest and wake often to eat.", k: "Hedgehog: hibernates at 5 °C body temperature" }, fr: { q: "Lequel de ces animaux hiberne vraiment ?", a: ["Écureuil", "Chevreuil", "Renard", "Hérisson"], x: "En hibernation, la température du hérisson descend à environ 5 °C. L'écureuil se réveille souvent pour manger.", k: "Hérisson : hiberne à 5 °C" }, es: { q: "¿Cuál de estos animales hiberna de verdad?", a: ["Ardilla", "Corzo", "Zorro", "Erizo"], x: "Al hibernar, el erizo baja su temperatura a unos 5 °C. La ardilla solo descansa y despierta a menudo para comer.", k: "Erizo: hiberna a 5 °C" }, pt: { q: "Qual destes animais hiberna de verdade?", a: ["Esquilo", "Corço", "Raposa", "Ouriço"], x: "Ao hibernar, o ouriço baixa a temperatura para uns 5 °C. O esquilo só descansa e acorda muitas vezes para comer.", k: "Ouriço: hiberna a 5 °C" }, ja: { q: "本当の冬眠をするのは？", a: ["リス", "ノロジカ", "キツネ", "ハリネズミ"], x: "冬眠中のハリネズミの体温は約5℃まで下がります。リスは休むだけで、よく起きて食べます。", k: "ハリネズミ：冬眠中は体温5℃" }, it: { q: "Quale animale va davvero in letargo?", a: ["Scoiattolo", "Capriolo", "Volpe", "Riccio"], x: "In letargo la temperatura del riccio scende a circa 5 °C. Gli scoiattoli riposano soltanto e si svegliano spesso per mangiare.", k: "Riccio: va in letargo a 5 °C" } } },
  { id: "c03", lvl: 1, type: "text", right: 0, t: { de: { q: "Welches Tier hat genau sechs Beine?", a: ["Marienkäfer", "Krake", "Schnecke", "Krabbe"], x: "Alle Insekten haben sechs Beine – auch der Marienkäfer. Krabben haben zehn Beine, Kraken acht Arme.", k: "Insekten: haben immer sechs Beine" }, en: { q: "Which animal has exactly six legs?", a: ["Ladybird", "Octopus", "Snail", "Crab"], x: "All insects have six legs, including the ladybird. Crabs have ten legs and octopuses eight arms.", k: "Insects: always have six legs" }, fr: { q: "Quel animal a exactement six pattes ?", a: ["Coccinelle", "Pieuvre", "Escargot", "Crabe"], x: "Tous les insectes ont six pattes, coccinelle comprise. Le crabe en a dix et la pieuvre a huit bras.", k: "Insectes : toujours six pattes" }, es: { q: "¿Qué animal tiene exactamente seis patas?", a: ["Mariquita", "Pulpo", "Caracol", "Cangrejo"], x: "Todos los insectos tienen seis patas, también la mariquita. El cangrejo tiene diez y el pulpo ocho brazos.", k: "Insectos: siempre seis patas" }, pt: { q: "Que animal tem exatamente seis patas?", a: ["Joaninha", "Polvo", "Caracol", "Caranguejo"], x: "Todos os insetos têm seis patas, inclusive a joaninha. O caranguejo tem dez e o polvo oito braços.", k: "Insetos: sempre seis patas" }, ja: { q: "脚がちょうど6本の動物は？", a: ["テントウムシ", "タコ", "カタツムリ", "カニ"], x: "昆虫の脚はみんな6本。テントウムシもそうです。カニの脚は10本、タコの腕は8本です。", k: "昆虫：脚はいつも6本" }, it: { q: "Quale animale ha esattamente sei zampe?", a: ["Coccinella", "Polpo", "Chiocciola", "Granchio"], x: "Tutti gli insetti hanno sei zampe, anche la coccinella. I granchi hanno dieci zampe e i polpi otto braccia.", k: "Insetti: sempre sei zampe" } } },
  { id: "c04", lvl: 2, type: "text", right: 1, t: { de: { q: "Wessen Skelett besteht nicht aus Knochen, sondern aus Knorpel?", a: ["Schildkröte", "Hai", "Pinguin", "Frosch"], x: "Haie sind Knorpelfische. Knorpel ist leichter und biegsamer als Knochen – wie in unserer Nase.", k: "Haie: Skelett aus Knorpel" }, en: { q: "Whose skeleton is made of cartilage instead of bone?", a: ["Turtle", "Shark", "Penguin", "Frog"], x: "Sharks are cartilaginous fish. Cartilage is lighter and more flexible than bone – like in our nose.", k: "Sharks: skeleton made of cartilage" }, fr: { q: "Quel animal a un squelette fait de cartilage et non d'os ?", a: ["Tortue", "Requin", "Manchot", "Grenouille"], x: "Le requin est un poisson cartilagineux. Le cartilage est plus léger et souple que l'os, comme dans notre nez.", k: "Requins : squelette en cartilage" }, es: { q: "¿Qué animal tiene un esqueleto de cartílago en vez de hueso?", a: ["Tortuga", "Tiburón", "Pingüino", "Rana"], x: "El tiburón es un pez cartilaginoso. El cartílago es más ligero y flexible que el hueso, como el de la nariz.", k: "Tiburones: esqueleto de cartílago" }, pt: { q: "Que animal tem esqueleto de cartilagem em vez de osso?", a: ["Tartaruga", "Tubarão", "Pinguim", "Rã"], x: "O tubarão é um peixe cartilaginoso. A cartilagem é mais leve e flexível que o osso, como a do nariz.", k: "Tubarões: esqueleto de cartilagem" }, ja: { q: "骨格が骨ではなく軟骨でできているのは？", a: ["カメ", "サメ", "ペンギン", "カエル"], x: "サメは軟骨魚類。軟骨は骨より軽くてしなやか。私たちの鼻と同じです。", k: "サメ：骨格は軟骨" }, it: { q: "Di chi è lo scheletro fatto di cartilagine invece che di osso?", a: ["Tartaruga", "Squalo", "Pinguino", "Rana"], x: "Gli squali sono pesci cartilaginei. La cartilagine è più leggera e flessibile dell’osso, come nel nostro naso.", k: "Squali: scheletro di cartilagine" } } },
  { id: "c05", lvl: 1, type: "text", right: 3, t: { de: { q: "Welcher Vogel verdankt seine Farbe seiner Nahrung?", a: ["Papagei", "Adler", "Eule", "Flamingo"], x: "Flamingos fressen Algen und Kleinkrebse voller Carotinoide. Ohne diese Farbstoffe würden sie blass.", k: "Flamingos: rosa durch ihr Futter" }, en: { q: "Which bird gets its colour from its food?", a: ["Parrot", "Eagle", "Owl", "Flamingo"], x: "Flamingos eat algae and tiny shrimp full of carotenoids. Without these pigments they would turn pale.", k: "Flamingos: pink because of their food" }, fr: { q: "Quel oiseau doit sa couleur à sa nourriture ?", a: ["Perroquet", "Aigle", "Chouette", "Flamant rose"], x: "Le flamant rose mange des algues et petites crevettes riches en caroténoïdes. Sans eux, il pâlirait.", k: "Flamants : roses grâce à leur nourriture" }, es: { q: "¿Qué ave debe su color a su alimento?", a: ["Loro", "Águila", "Búho", "Flamenco"], x: "El flamenco come algas y pequeños crustáceos con carotenoides. Sin esos pigmentos se volvería pálido.", k: "Flamencos: rosas por su comida" }, pt: { q: "Que ave deve sua cor ao alimento?", a: ["Papagaio", "Águia", "Coruja", "Flamingo"], x: "O flamingo come algas e pequenos crustáceos com carotenoides. Sem esses pigmentos, ele ficaria pálido.", k: "Flamingos: rosados pela comida" }, ja: { q: "食べもので体の色が決まる鳥は？", a: ["オウム", "ワシ", "フクロウ", "フラミンゴ"], x: "フラミンゴはカロテノイドをたっぷりふくむ藻や小さなエビを食べます。この色素がないと色があせてしまいます。", k: "フラミンゴ：食べもので体がピンク" }, it: { q: "Quale uccello prende il colore dal cibo?", a: ["Pappagallo", "Aquila", "Gufo", "Fenicottero"], x: "I fenicotteri mangiano alghe e gamberetti pieni di carotenoidi. Senza questi pigmenti diventerebbero pallidi.", k: "Fenicotteri: rosa grazie al cibo" } } },
  { id: "c06", lvl: 2, type: "text", right: 0, t: { de: { q: "Welcher Vogel legt im Verhältnis zu seinem Körper das größte Ei?", a: ["Kiwi", "Strauß", "Haushuhn", "Kaiserpinguin"], x: "Ein Kiwi-Ei wiegt rund ein Fünftel so viel wie das Weibchen selbst. Das Straußenei ist zwar das größte Ei überhaupt, für den riesigen Strauß aber eher klein.", k: "Kiwi: Ei so schwer wie ein Fünftel der Mutter" }, en: { q: "Which bird lays the biggest egg compared to its body?", a: ["Kiwi", "Ostrich", "Chicken", "Emperor penguin"], x: "A kiwi egg weighs about a fifth as much as the female herself. The ostrich egg is the biggest egg of all, but quite small for such a huge bird.", k: "Kiwi: egg weighs a fifth of the mother" }, fr: { q: "Quel oiseau pond le plus gros œuf par rapport à son corps ?", a: ["Kiwi", "Autruche", "Poule", "Manchot empereur"], x: "Un œuf de kiwi pèse environ un cinquième du poids de la femelle. L’œuf d’autruche est le plus gros de tous, mais plutôt petit pour un oiseau aussi grand.", k: "Kiwi : œuf d’un cinquième du poids de la mère" }, es: { q: "¿Qué ave pone el huevo más grande en relación con su cuerpo?", a: ["Kiwi", "Avestruz", "Gallina", "Pingüino emperador"], x: "Un huevo de kiwi pesa alrededor de una quinta parte de lo que pesa la hembra. El de avestruz es el huevo más grande de todos, pero pequeño para un ave tan enorme.", k: "Kiwi: huevo de un quinto del peso de la madre" }, pt: { q: "Que ave põe o maior ovo em relação ao corpo?", a: ["Quiuí", "Avestruz", "Galinha", "Pinguim-imperador"], x: "Um ovo de quiuí pesa cerca de um quinto do peso da fêmea. O de avestruz é o maior ovo de todos, mas pequeno para uma ave tão enorme.", k: "Kiwi: ovo de um quinto do peso da mãe" }, ja: { q: "体の大きさに比べていちばん大きな卵を産む鳥は？", a: ["キーウィ", "ダチョウ", "ニワトリ", "コウテイペンギン"], x: "キーウィの卵はメスの体重の約5分の1。ダチョウの卵は一番大きな卵ですが、あの巨体にしては小さめです。", k: "キーウィ：卵は母親の体重の5分の1" }, it: { q: "Quale uccello depone l’uovo più grande rispetto al corpo?", a: ["Kiwi", "Struzzo", "Gallina", "Pinguino imperatore"], x: "Un uovo di kiwi pesa circa un quinto della femmina. Quello di struzzo è l’uovo più grande in assoluto, ma piccolo per un uccello così enorme.", k: "Kiwi: uovo di un quinto del peso della madre" } } },
  { id: "c07", lvl: 3, type: "text", right: 2, t: { de: { q: "Welches Tier hat einen verlängerten Handgelenksknochen, der wie ein zusätzlicher Daumen wirkt?", a: ["Otter", "Eichhörnchen", "Panda", "Tiger"], x: "Der „Pseudodaumen“ des Pandas ist ein vergrößerter Handgelenksknochen. Damit hält er Bambus fest.", k: "Panda: hat einen falschen Daumen" }, en: { q: "Which animal has an enlarged wrist bone that works like an extra thumb?", a: ["Otter", "Squirrel", "Panda", "Tiger"], x: "The panda's 'pseudo-thumb' is an enlarged wrist bone. It helps the panda grip bamboo stems.", k: "Panda: has a false thumb" }, fr: { q: "Quel animal possède un os du poignet allongé qui sert de pouce supplémentaire ?", a: ["Loutre", "Écureuil", "Panda", "Tigre"], x: "Le « faux pouce » du panda est un os du poignet agrandi. Il l'aide à tenir les tiges de bambou.", k: "Panda : un faux pouce" }, es: { q: "¿Qué animal tiene un hueso de la muñeca alargado que funciona como un pulgar extra?", a: ["Nutria", "Ardilla", "Panda", "Tigre"], x: "El «falso pulgar» del panda es un hueso de la muñeca agrandado. Le sirve para sujetar el bambú.", k: "Panda: tiene un falso pulgar" }, pt: { q: "Que animal tem um osso do punho alongado que funciona como um polegar extra?", a: ["Lontra", "Esquilo", "Panda", "Tigre"], x: "O “falso polegar” do panda é um osso do punho aumentado. Serve para segurar o bambu.", k: "Panda: tem um falso polegar" }, ja: { q: "手首の骨が大きくなって、もう1本の親指のように使える動物は？", a: ["カワウソ", "リス", "パンダ", "トラ"], x: "パンダの「にせの親指」は大きくなった手首の骨。竹の茎をつかむのに役立ちます。", k: "パンダ：にせの親指がある" }, it: { q: "Quale animale ha un osso del polso ingrandito che funziona come un pollice in più?", a: ["Lontra", "Scoiattolo", "Panda", "Tigre"], x: "Il «falso pollice» del panda è un osso del polso ingrandito. Lo aiuta ad afferrare le canne di bambù.", k: "Panda: ha un falso pollice" } } },
  { id: "c08", lvl: 2, type: "text", right: 0, t: { de: { q: "Welches Tier hat eine etwa 45 cm lange, dunkelblaue Zunge?", a: ["Giraffe", "Reh", "Tiger", "Panda"], x: "Die dunkle Farbe schützt die Giraffenzunge vermutlich vor Sonnenbrand, wenn sie Akazienblätter zupft.", k: "Giraffe: blaue Zunge, 45 cm lang" }, en: { q: "Which animal has a dark blue tongue about 45 cm long?", a: ["Giraffe", "Roe deer", "Tiger", "Panda"], x: "The dark colour probably protects the giraffe's tongue from sunburn while it plucks acacia leaves.", k: "Giraffe: blue tongue, 45 cm long" }, fr: { q: "Quel animal a une langue bleu foncé d'environ 45 cm ?", a: ["Girafe", "Chevreuil", "Tigre", "Panda"], x: "Sa couleur sombre protégerait la langue de la girafe du soleil quand elle cueille des feuilles d'acacia.", k: "Girafe : langue bleue de 45 cm" }, es: { q: "¿Qué animal tiene una lengua azul oscuro de unos 45 cm?", a: ["Jirafa", "Corzo", "Tigre", "Panda"], x: "Su color oscuro protegería la lengua de la jirafa del sol mientras arranca hojas de acacia.", k: "Jirafa: lengua azul de 45 cm" }, pt: { q: "Que animal tem uma língua azul-escura de uns 45 cm?", a: ["Girafa", "Corço", "Tigre", "Panda"], x: "A cor escura protegeria a língua da girafa do sol enquanto ela arranca folhas de acácia.", k: "Girafa: língua azul de 45 cm" }, ja: { q: "長さ約45センチの濃い青色の舌をもつ動物は？", a: ["キリン", "ノロジカ", "トラ", "パンダ"], x: "濃い色は、アカシアの葉をむしるときに舌が日焼けしないためと考えられています。", k: "キリン：舌は青くて45センチ" }, it: { q: "Quale animale ha una lingua blu scuro lunga circa 45 cm?", a: ["Giraffa", "Capriolo", "Tigre", "Panda"], x: "Il colore scuro probabilmente protegge la lingua della giraffa dalle scottature mentre strappa le foglie di acacia.", k: "Giraffa: lingua blu di 45 cm" } } },
  { id: "c09", lvl: 2, type: "text", right: 3, t: { de: { q: "Bei welchem Tier ist auch die Haut unter dem Fell gestreift?", a: ["Fuchs", "Reh", "Eichhörnchen", "Tiger"], x: "Unter den dunklen Streifen ist auch die Haut des Tigers dunkel. Rasiert sähe man das Muster noch.", k: "Tiger: auch die Haut ist gestreift" }, en: { q: "Which animal has striped skin underneath its fur too?", a: ["Fox", "Roe deer", "Squirrel", "Tiger"], x: "A tiger's skin is dark under its dark stripes, so the pattern would still show if it were shaved.", k: "Tiger: even its skin is striped" }, fr: { q: "Chez quel animal la peau sous le pelage est-elle aussi rayée ?", a: ["Renard", "Chevreuil", "Écureuil", "Tigre"], x: "Sous les rayures sombres du tigre, la peau est foncée : rasé, il garderait son motif.", k: "Tigre : même sa peau est rayée" }, es: { q: "¿En qué animal también la piel bajo el pelaje tiene rayas?", a: ["Zorro", "Corzo", "Ardilla", "Tigre"], x: "Bajo las rayas oscuras del tigre la piel también es oscura: aunque lo afeitaran, se verían las rayas.", k: "Tigre: hasta la piel es rayada" }, pt: { q: "Em que animal a pele debaixo do pelo também é listrada?", a: ["Raposa", "Corço", "Esquilo", "Tigre"], x: "Debaixo das listras escuras do tigre a pele também é escura: mesmo raspado, as listras apareceriam.", k: "Tigre: até a pele é listrada" }, ja: { q: "毛の下の皮ふにもしまもようがある動物は？", a: ["キツネ", "ノロジカ", "リス", "トラ"], x: "トラの皮ふは黒いしまの下が黒っぽくなっています。毛をそっても、もようが見えるのです。", k: "トラ：皮ふにもしまもよう" }, it: { q: "Quale animale ha la pelle a strisce anche sotto il pelo?", a: ["Volpe", "Capriolo", "Scoiattolo", "Tigre"], x: "La pelle della tigre è scura sotto le strisce scure: il disegno si vedrebbe anche se fosse rasata.", k: "Tigre: anche la pelle è a strisce" } } },
  { id: "c10", lvl: 2, type: "text", right: 1, t: { de: { q: "Wer kann beim Tauchen Ohren und Nasenlöcher verschließen?", a: ["Tiger", "Otter", "Fuchs", "Giraffe"], x: "Otter verschließen unter Wasser Ohren und Nase und können mehrere Minuten lang tauchen.", k: "Fischotter: verschließt beim Tauchen Ohren und Nase" }, en: { q: "Which animal can close its ears and nostrils when diving?", a: ["Tiger", "Otter", "Fox", "Giraffe"], x: "Otters seal their ears and nostrils underwater and can stay down for several minutes.", k: "Otter: closes ears and nose when diving" }, fr: { q: "Quel animal peut fermer ses oreilles et ses narines en plongée ?", a: ["Tigre", "Loutre", "Renard", "Girafe"], x: "La loutre ferme oreilles et narines sous l'eau et peut plonger plusieurs minutes.", k: "Loutre : ferme oreilles et narines en plongée" }, es: { q: "¿Qué animal puede cerrar orejas y fosas nasales al bucear?", a: ["Tigre", "Nutria", "Zorro", "Jirafa"], x: "La nutria cierra orejas y nariz bajo el agua y puede bucear varios minutos.", k: "Nutria: cierra orejas y nariz al bucear" }, pt: { q: "Que animal consegue fechar orelhas e narinas ao mergulhar?", a: ["Tigre", "Lontra", "Raposa", "Girafa"], x: "A lontra fecha orelhas e nariz debaixo d’água e consegue mergulhar por vários minutos.", k: "Lontra: fecha orelhas e narinas ao mergulhar" }, ja: { q: "潜るときに耳と鼻の穴を閉じられる動物は？", a: ["トラ", "カワウソ", "キツネ", "キリン"], x: "カワウソは水中で耳と鼻の穴を閉じ、何分も潜っていられます。", k: "カワウソ：潜るとき耳と鼻を閉じる" }, it: { q: "Quale animale può chiudere orecchie e narici quando si immerge?", a: ["Tigre", "Lontra", "Volpe", "Giraffa"], x: "Sott’acqua le lontre chiudono orecchie e narici e possono restare giù diversi minuti.", k: "Lontra: chiude orecchie e naso in immersione" } } },
  { id: "c11", lvl: 3, type: "text", right: 3, t: { de: { q: "Wer hat über den Augen eine Drüse, die Salz aus Meerwasser ausscheidet?", a: ["Eule", "Otter", "Papagei", "Pinguin"], x: "Pinguine können Meerwasser trinken: Die Salzdrüse filtert das Salz, das dann über den Schnabel abtropft.", k: "Pinguine: können Meerwasser trinken" }, en: { q: "Which animal has a gland above its eyes that removes salt from seawater?", a: ["Owl", "Otter", "Parrot", "Penguin"], x: "Penguins can drink seawater: a salt gland filters out the salt, which then drips off the beak.", k: "Penguins: can drink seawater" }, fr: { q: "Quel animal a au-dessus des yeux une glande qui élimine le sel de l'eau de mer ?", a: ["Chouette", "Loutre", "Perroquet", "Manchot"], x: "Le manchot peut boire de l'eau de mer : une glande filtre le sel, qui s'écoule par le bec.", k: "Manchots : boivent de l’eau de mer" }, es: { q: "¿Qué animal tiene sobre los ojos una glándula que elimina la sal del agua de mar?", a: ["Búho", "Nutria", "Loro", "Pingüino"], x: "El pingüino puede beber agua de mar: una glándula filtra la sal, que luego gotea por el pico.", k: "Pingüinos: pueden beber agua de mar" }, pt: { q: "Que animal tem sobre os olhos uma glândula que tira o sal da água do mar?", a: ["Coruja", "Lontra", "Papagaio", "Pinguim"], x: "O pinguim pode beber água do mar: uma glândula filtra o sal, que depois pinga pelo bico.", k: "Pinguins: bebem água do mar" }, ja: { q: "目の上に、海水から塩をとりのぞく腺がある動物は？", a: ["フクロウ", "カワウソ", "オウム", "ペンギン"], x: "ペンギンは海水を飲めます。塩類腺が塩をこしとり、くちばしからポタポタたらします。", k: "ペンギン：海水を飲める" }, it: { q: "Quale animale ha una ghiandola sopra gli occhi che toglie il sale dall’acqua di mare?", a: ["Gufo", "Lontra", "Pappagallo", "Pinguino"], x: "I pinguini possono bere acqua di mare: una ghiandola del sale filtra il sale, che poi gocciola dal becco.", k: "Pinguini: bevono acqua di mare" } } },
  { id: "c12", lvl: 2, type: "text", right: 0, t: { de: { q: "Wer hat eine Raspelzunge mit Tausenden winziger Zähnchen?", a: ["Schnecke", "Schmetterling", "Schildkröte", "Biene"], x: "Die Raspelzunge (Radula) der Schnecke wirkt wie eine Feile. Abgenutzte Zähnchen wachsen ständig nach.", k: "Schnecken: Zunge mit Tausenden Zähnchen" }, en: { q: "Which animal has a rasping tongue with thousands of tiny teeth?", a: ["Snail", "Butterfly", "Turtle", "Bee"], x: "A snail's radula works like a file. Worn-out teeth are constantly replaced by new ones.", k: "Snails: tongue with thousands of tiny teeth" }, fr: { q: "Quel animal a une langue râpeuse couverte de milliers de petites dents ?", a: ["Escargot", "Papillon", "Tortue", "Abeille"], x: "La radula de l'escargot fonctionne comme une lime. Les dents usées sont sans cesse remplacées.", k: "Escargots : langue à milliers de dents" }, es: { q: "¿Qué animal tiene una lengua raspadora con miles de dientecillos?", a: ["Caracol", "Mariposa", "Tortuga", "Abeja"], x: "La rádula del caracol funciona como una lima. Los dientes gastados se reemplazan continuamente.", k: "Caracoles: lengua con miles de dientecitos" }, pt: { q: "Que animal tem uma língua raspadora com milhares de dentinhos?", a: ["Caracol", "Borboleta", "Tartaruga", "Abelha"], x: "A rádula do caracol funciona como uma lixa. Os dentes gastos são substituídos sem parar.", k: "Caracóis: língua com milhares de dentinhos" }, ja: { q: "何千もの小さな歯が並んだ、やすりのような舌をもつ動物は？", a: ["カタツムリ", "チョウ", "カメ", "ミツバチ"], x: "カタツムリの歯舌はやすりのよう。すり減った歯は、どんどん新しい歯に生えかわります。", k: "カタツムリ：何千もの歯がある舌" }, it: { q: "Quale animale ha una lingua a raspa con migliaia di dentini?", a: ["Chiocciola", "Farfalla", "Tartaruga", "Ape"], x: "La radula della chiocciola funziona come una lima. I denti consumati vengono sostituiti di continuo da nuovi.", k: "Chiocciole: lingua con migliaia di dentini" } } },
  { id: "c13", lvl: 3, type: "text", right: 2, t: { de: { q: "Wer kann die schwachen elektrischen Felder seiner Beute spüren?", a: ["Krake", "Pinguin", "Hai", "Otter"], x: "Haie haben Lorenzinische Ampullen: Poren an der Schnauze, die den Strom der Muskeln versteckter Beute spüren.", k: "Haie: spüren elektrische Felder" }, en: { q: "Which animal can sense the weak electric fields of its prey?", a: ["Octopus", "Penguin", "Shark", "Otter"], x: "Sharks have ampullae of Lorenzini: snout pores that detect electricity from the muscles of hidden prey.", k: "Sharks: sense electric fields" }, fr: { q: "Quel animal perçoit les faibles champs électriques de ses proies ?", a: ["Pieuvre", "Manchot", "Requin", "Loutre"], x: "Le requin a des ampoules de Lorenzini : des pores du museau qui captent l'électricité des proies cachées.", k: "Requins : sentent les champs électriques" }, es: { q: "¿Qué animal percibe los débiles campos eléctricos de sus presas?", a: ["Pulpo", "Pingüino", "Tiburón", "Nutria"], x: "El tiburón tiene ampollas de Lorenzini: poros del hocico que captan la electricidad de presas ocultas.", k: "Tiburones: perciben campos eléctricos" }, pt: { q: "Que animal percebe os fracos campos elétricos das presas?", a: ["Polvo", "Pinguim", "Tubarão", "Lontra"], x: "O tubarão tem ampolas de Lorenzini: poros no focinho que captam a eletricidade de presas escondidas.", k: "Tubarões: sentem campos elétricos" }, ja: { q: "獲物の弱い電気を感じとれる動物は？", a: ["タコ", "ペンギン", "サメ", "カワウソ"], x: "サメにはロレンチーニ器官があります。鼻先の小さな穴で、かくれた獲物の筋肉が出す電気を感じとります。", k: "サメ：電気を感じとる" }, it: { q: "Quale animale percepisce i deboli campi elettrici delle prede?", a: ["Polpo", "Pinguino", "Squalo", "Lontra"], x: "Gli squali hanno le ampolle di Lorenzini: pori sul muso che percepiscono l’elettricità dei muscoli delle prede nascoste.", k: "Squali: percepiscono i campi elettrici" } } },
  { id: "c14", lvl: 1, type: "text", right: 0, t: { de: { q: "Wer zeigt seinen Artgenossen mit einem Tanz, wo es Futter gibt?", a: ["Biene", "Schmetterling", "Marienkäfer", "Krabbe"], x: "Mit dem Schwänzeltanz teilt die Biene Richtung und Entfernung einer Futterquelle mit.", k: "Bienen: zeigen Futter per Tanz" }, en: { q: "Which animal uses a dance to tell others where to find food?", a: ["Bee", "Butterfly", "Ladybird", "Crab"], x: "With its waggle dance, a bee tells its nestmates the direction and distance of a food source.", k: "Bees: show food with a dance" }, fr: { q: "Quel animal indique aux autres par une danse où trouver de la nourriture ?", a: ["Abeille", "Papillon", "Coccinelle", "Crabe"], x: "Par sa danse frétillante, l'abeille indique la direction et la distance d'une source de nourriture.", k: "Abeilles : montrent la nourriture par une danse" }, es: { q: "¿Qué animal indica con un baile dónde hay comida?", a: ["Abeja", "Mariposa", "Mariquita", "Cangrejo"], x: "Con su danza del contoneo, la abeja comunica la dirección y la distancia de una fuente de alimento.", k: "Abejas: indican la comida con un baile" }, pt: { q: "Que animal mostra com uma dança onde há comida?", a: ["Abelha", "Borboleta", "Joaninha", "Caranguejo"], x: "Com a dança do requebrado, a abelha conta a direção e a distância de uma fonte de alimento.", k: "Abelhas: mostram comida dançando" }, ja: { q: "ダンスでえさの場所を仲間に伝える動物は？", a: ["ミツバチ", "チョウ", "テントウムシ", "カニ"], x: "ミツバチは「8の字ダンス」で、えさ場の方向と距離を仲間に伝えます。", k: "ミツバチ：ダンスでえさ場を伝える" }, it: { q: "Quale animale usa una danza per dire agli altri dove trovare cibo?", a: ["Ape", "Farfalla", "Coccinella", "Granchio"], x: "Con la danza dell’addome l’ape comunica alle compagne direzione e distanza di una fonte di cibo.", k: "Api: indicano il cibo con una danza" } } },
  { id: "c15", lvl: 2, type: "text", right: 1, t: { de: { q: "Wer schmeckt mit den Füßen?", a: ["Eule", "Schmetterling", "Frosch", "Eidechse"], x: "Schmetterlinge haben Geschmackssinneszellen an den Füßen. So prüfen Weibchen, ob eine Pflanze für ihre Eier taugt.", k: "Schmetterlinge: schmecken mit den Füßen" }, en: { q: "Which animal tastes with its feet?", a: ["Owl", "Butterfly", "Frog", "Lizard"], x: "Butterflies have taste sensors on their feet. Females use them to check if a plant suits their eggs.", k: "Butterflies: taste with their feet" }, fr: { q: "Quel animal goûte avec ses pattes ?", a: ["Chouette", "Papillon", "Grenouille", "Lézard"], x: "Le papillon a des capteurs du goût sur les pattes. La femelle vérifie ainsi si une plante convient à ses œufs.", k: "Papillons : goûtent avec les pattes" }, es: { q: "¿Qué animal saborea con las patas?", a: ["Búho", "Mariposa", "Rana", "Lagarto"], x: "La mariposa tiene sensores del gusto en las patas. Así la hembra comprueba si una planta sirve para sus huevos.", k: "Mariposas: saborean con las patas" }, pt: { q: "Que animal sente o gosto com as patas?", a: ["Coruja", "Borboleta", "Rã", "Lagarto"], x: "A borboleta tem sensores de gosto nas patas. Assim a fêmea confere se uma planta serve para os ovos.", k: "Borboletas: sentem gosto com os pés" }, ja: { q: "足で味を感じる動物は？", a: ["フクロウ", "チョウ", "カエル", "トカゲ"], x: "チョウの足には味を感じるセンサーがあります。メスはそれで、卵を産むのにいい植物か確かめます。", k: "チョウ：足で味を感じる" }, it: { q: "Quale animale sente i sapori con i piedi?", a: ["Gufo", "Farfalla", "Rana", "Lucertola"], x: "Le farfalle hanno sensori del gusto sulle zampe. Le femmine li usano per capire se una pianta va bene per le uova.", k: "Farfalle: sentono i sapori con i piedi" } } },
  { id: "c16", lvl: 3, type: "text", right: 3, t: { de: { q: "Wer presst bei Gefahr bitteres, gelbes Blut aus seinen Beingelenken?", a: ["Biene", "Schmetterling", "Schnecke", "Marienkäfer"], x: "Dieses „Reflexbluten“ schreckt Fressfeinde ab: Die gelbe Flüssigkeit des Marienkäfers schmeckt bitter.", k: "Marienkäfer: bluten bei Gefahr bitteres Gelb" }, en: { q: "Which animal squeezes bitter yellow blood from its leg joints when threatened?", a: ["Bee", "Butterfly", "Snail", "Ladybird"], x: "This 'reflex bleeding' deters predators: the ladybird's yellow fluid tastes bitter and smells bad.", k: "Ladybirds: bleed bitter yellow when threatened" }, fr: { q: "Quel animal fait sortir un sang jaune et amer de ses articulations en cas de danger ?", a: ["Abeille", "Papillon", "Escargot", "Coccinelle"], x: "Ce « saignement réflexe » repousse les prédateurs : le liquide jaune de la coccinelle est amer.", k: "Coccinelles : saignent un jaune amer" }, es: { q: "¿Qué animal expulsa sangre amarilla y amarga por las articulaciones de las patas ante un peligro?", a: ["Abeja", "Mariposa", "Caracol", "Mariquita"], x: "Este «sangrado reflejo» ahuyenta a los depredadores: el líquido amarillo de la mariquita es amargo.", k: "Mariquitas: sangran un líquido amarillo amargo" }, pt: { q: "Que animal solta sangue amarelo e amargo pelas articulações das patas quando está em perigo?", a: ["Abelha", "Borboleta", "Caracol", "Joaninha"], x: "Esse “sangramento reflexo” espanta os predadores: o líquido amarelo da joaninha é amargo.", k: "Joaninhas: soltam um líquido amarelo amargo" }, ja: { q: "危険を感じると、脚の関節から苦い黄色い血を出す動物は？", a: ["ミツバチ", "チョウ", "カタツムリ", "テントウムシ"], x: "この「反射出血」で敵を追いはらいます。テントウムシの黄色い液は苦くて、いやなにおいがします。", k: "テントウムシ：苦い黄色い液を出す" }, it: { q: "Quale animale, se minacciato, spreme dalle articolazioni delle zampe un sangue giallo e amaro?", a: ["Ape", "Farfalla", "Chiocciola", "Coccinella"], x: "Questo «sanguinamento riflesso» scoraggia i predatori: il liquido giallo della coccinella è amaro e puzza.", k: "Coccinelle: sanguinano un giallo amaro" } } },
  { id: "c17", lvl: 1, type: "text", right: 2, t: { de: { q: "Wer kann bei Gefahr seinen Schwanz abwerfen?", a: ["Schildkröte", "Igel", "Eidechse", "Papagei"], x: "Der abgeworfene Eidechsenschwanz zappelt weiter und lenkt den Feind ab. Er wächst nach, aber kürzer.", k: "Eidechsen: werfen bei Gefahr den Schwanz ab" }, en: { q: "Which animal can shed its tail when in danger?", a: ["Turtle", "Hedgehog", "Lizard", "Parrot"], x: "A lizard's dropped tail keeps wriggling to distract the enemy. It grows back, but shorter.", k: "Lizards: drop their tail in danger" }, fr: { q: "Quel animal peut abandonner sa queue en cas de danger ?", a: ["Tortue", "Hérisson", "Lézard", "Perroquet"], x: "La queue du lézard continue de gigoter pour distraire l'ennemi. Elle repousse, mais plus courte.", k: "Lézards : lâchent leur queue en danger" }, es: { q: "¿Qué animal puede soltar su cola ante un peligro?", a: ["Tortuga", "Erizo", "Lagarto", "Loro"], x: "La cola del lagarto sigue moviéndose y distrae al enemigo. Vuelve a crecer, pero más corta.", k: "Lagartijas: sueltan la cola ante el peligro" }, pt: { q: "Que animal consegue soltar a cauda quando está em perigo?", a: ["Tartaruga", "Ouriço", "Lagarto", "Papagaio"], x: "A cauda do lagarto continua se mexendo e distrai o inimigo. Ela cresce de novo, mas mais curta.", k: "Lagartixas: soltam o rabo no perigo" }, ja: { q: "危ないとき、しっぽを切りはなせる動物は？", a: ["カメ", "ハリネズミ", "トカゲ", "オウム"], x: "切れたトカゲのしっぽはクネクネ動き続け、敵の気をそらします。しっぽはまた生えますが、短くなります。", k: "トカゲ：危ないとしっぽを切る" }, it: { q: "Quale animale può staccare la coda in caso di pericolo?", a: ["Tartaruga", "Riccio", "Lucertola", "Pappagallo"], x: "La coda staccata della lucertola continua a dimenarsi e distrae il nemico. Ricresce, ma più corta.", k: "Lucertole: staccano la coda in pericolo" } } },
  { id: "c18", lvl: 3, type: "text", right: 3, t: { de: { q: "Wer drückt beim Schlucken seine Augen nach innen, um die Beute hinunterzuschieben?", a: ["Eule", "Papagei", "Otter", "Frosch"], x: "Frösche ziehen beim Schlucken die Augäpfel ein. Diese drücken von oben auf den Bissen und schieben ihn in den Schlund.", k: "Frösche: schlucken mit Hilfe der Augen" }, en: { q: "Which animal pulls its eyes inward when swallowing to push food down?", a: ["Owl", "Parrot", "Otter", "Frog"], x: "Frogs retract their eyeballs when swallowing. They press on the food from above and push it down the throat.", k: "Frogs: swallow with help from their eyes" }, fr: { q: "Quel animal enfonce ses yeux en avalant pour pousser sa proie vers le bas ?", a: ["Chouette", "Perroquet", "Loutre", "Grenouille"], x: "En avalant, la grenouille rentre ses yeux. Ils appuient sur la proie et la poussent dans la gorge.", k: "Grenouilles : avalent avec l’aide des yeux" }, es: { q: "¿Qué animal hunde los ojos al tragar para empujar la comida?", a: ["Búho", "Loro", "Nutria", "Rana"], x: "Al tragar, la rana hunde los ojos. Estos presionan el bocado desde arriba y lo empujan a la garganta.", k: "Ranas: tragan con ayuda de los ojos" }, pt: { q: "Que animal afunda os olhos ao engolir para empurrar a comida?", a: ["Coruja", "Papagaio", "Lontra", "Rã"], x: "Ao engolir, a rã afunda os olhos. Eles pressionam o bocado de cima e o empurram para a garganta.", k: "Rãs: engolem com ajuda dos olhos" }, ja: { q: "飲みこむとき、目玉を内側に引っこめて食べものを押しこむ動物は？", a: ["フクロウ", "オウム", "カワウソ", "カエル"], x: "カエルは飲みこむとき目玉を引っこめます。目玉が上から食べものを押して、のどへ送りこむのです。", k: "カエル：目玉を使って飲みこむ" }, it: { q: "Quale animale tira gli occhi verso l’interno quando deglutisce, per spingere giù il cibo?", a: ["Gufo", "Pappagallo", "Lontra", "Rana"], x: "Le rane ritraggono i bulbi oculari quando deglutiscono: premono sul cibo dall’alto e lo spingono in gola.", k: "Rane: deglutiscono con l’aiuto degli occhi" } } },
  { id: "c19", lvl: 2, type: "text", right: 1, t: { de: { q: "Wessen Blut ist durch Kupfer bläulich gefärbt?", a: ["Hai", "Krabbe", "Frosch", "Pinguin"], x: "Krabben transportieren Sauerstoff mit Hämocyanin, das Kupfer enthält. Unser Blut ist durch Eisen rot.", k: "Krebse: Blut ist blau durch Kupfer" }, en: { q: "Whose blood is bluish because of copper?", a: ["Shark", "Crab", "Frog", "Penguin"], x: "Crabs carry oxygen with haemocyanin, which contains copper. Our blood is red because of iron.", k: "Crabs: blue blood thanks to copper" }, fr: { q: "Quel animal a un sang bleuté à cause du cuivre ?", a: ["Requin", "Crabe", "Grenouille", "Manchot"], x: "Le crabe transporte l'oxygène avec l'hémocyanine, qui contient du cuivre. Notre sang est rouge grâce au fer.", k: "Crabes : sang bleu grâce au cuivre" }, es: { q: "¿Qué animal tiene la sangre azulada por el cobre?", a: ["Tiburón", "Cangrejo", "Rana", "Pingüino"], x: "El cangrejo transporta oxígeno con hemocianina, que contiene cobre. Nuestra sangre es roja por el hierro.", k: "Cangrejos: sangre azul por el cobre" }, pt: { q: "Que animal tem sangue azulado por causa do cobre?", a: ["Tubarão", "Caranguejo", "Rã", "Pinguim"], x: "O caranguejo transporta oxigênio com hemocianina, que contém cobre. Nosso sangue é vermelho por causa do ferro.", k: "Caranguejos: sangue azul por causa do cobre" }, ja: { q: "銅のせいで血が青っぽいのは？", a: ["サメ", "カニ", "カエル", "ペンギン"], x: "カニは銅をふくむヘモシアニンで酸素を運びます。私たちの血が赤いのは鉄のおかげです。", k: "カニ：銅で血が青い" }, it: { q: "Di chi è il sangue bluastro a causa del rame?", a: ["Squalo", "Granchio", "Rana", "Pinguino"], x: "I granchi trasportano l’ossigeno con l’emocianina, che contiene rame. Il nostro sangue è rosso per il ferro.", k: "Granchi: sangue blu grazie al rame" } } },
  { id: "c20", lvl: 1, type: "text", right: 0, t: { de: { q: "Wer hat zehn Beine – die Scheren mitgezählt?", a: ["Krabbe", "Biene", "Krake", "Marienkäfer"], x: "Krabben gehören zu den Zehnfußkrebsen. Das vorderste Beinpaar ist zu kräftigen Scheren umgebaut.", k: "Krebse: zehn Beine inklusive Scheren" }, en: { q: "Which animal has ten legs, counting its claws?", a: ["Crab", "Bee", "Octopus", "Ladybird"], x: "Crabs are decapods ('ten-footed'). Their front pair of legs has become strong claws.", k: "Crabs: ten legs, claws included" }, fr: { q: "Quel animal a dix pattes, pinces comprises ?", a: ["Crabe", "Abeille", "Pieuvre", "Coccinelle"], x: "Le crabe est un décapode (« dix pieds »). Sa première paire de pattes forme de puissantes pinces.", k: "Crabes : dix pattes, pinces comprises" }, es: { q: "¿Qué animal tiene diez patas, contando las pinzas?", a: ["Cangrejo", "Abeja", "Pulpo", "Mariquita"], x: "El cangrejo es un decápodo («diez pies»). Su primer par de patas se ha convertido en fuertes pinzas.", k: "Cangrejos: diez patas, pinzas incluidas" }, pt: { q: "Que animal tem dez patas, contando as pinças?", a: ["Caranguejo", "Abelha", "Polvo", "Joaninha"], x: "O caranguejo é um decápode (“dez pés”). Seu primeiro par de patas virou pinças fortes.", k: "Caranguejos: dez patas, pinças incluídas" }, ja: { q: "はさみも数えると脚が10本の動物は？", a: ["カニ", "ミツバチ", "タコ", "テントウムシ"], x: "カニは十脚類（10本の脚）。いちばん前の1対が強いはさみになっています。", k: "カニ：はさみも入れて脚10本" }, it: { q: "Quale animale ha dieci zampe, contando le chele?", a: ["Granchio", "Ape", "Polpo", "Coccinella"], x: "I granchi sono decapodi («dieci piedi»). Il primo paio di zampe è diventato due chele robuste.", k: "Granchi: dieci zampe, chele comprese" } } },
  { id: "c21", lvl: 1, type: "text", right: 0, t: { de: { q: "Wer passt durch ein Loch, das kaum größer ist als sein Schnabel?", a: ["Krake", "Hai", "Krabbe", "Schildkröte"], x: "Kraken haben keine Knochen. Nur ihr harter Schnabel bestimmt, durch welche Öffnung sie schlüpfen können.", k: "Krake: passt durch fast jedes Loch" }, en: { q: "Which animal can squeeze through a hole barely bigger than its beak?", a: ["Octopus", "Shark", "Crab", "Turtle"], x: "Octopuses have no bones. Only their hard beak limits which openings they can slip through.", k: "Octopus: fits through almost any hole" }, fr: { q: "Quel animal peut passer par un trou à peine plus grand que son bec ?", a: ["Pieuvre", "Requin", "Crabe", "Tortue"], x: "La pieuvre n'a pas d'os. Seul son bec dur limite les ouvertures par lesquelles elle peut se faufiler.", k: "Pieuvre : passe par presque tous les trous" }, es: { q: "¿Qué animal cabe por un agujero apenas mayor que su pico?", a: ["Pulpo", "Tiburón", "Cangrejo", "Tortuga"], x: "El pulpo no tiene huesos. Solo su pico duro limita las aberturas por las que puede colarse.", k: "Pulpo: pasa por casi cualquier agujero" }, pt: { q: "Que animal passa por um buraco pouco maior que o seu bico?", a: ["Polvo", "Tubarão", "Caranguejo", "Tartaruga"], x: "O polvo não tem ossos. Só o bico duro limita as aberturas por onde ele consegue passar.", k: "Polvo: passa por quase qualquer buraco" }, ja: { q: "くちばしよりほんの少し大きいだけの穴を通りぬけられる動物は？", a: ["タコ", "サメ", "カニ", "カメ"], x: "タコには骨がありません。通れる穴の大きさを決めるのは、かたいくちばしだけです。", k: "タコ：ほとんどどんな穴も通れる" }, it: { q: "Quale animale passa da un buco appena più grande del suo becco?", a: ["Polpo", "Squalo", "Granchio", "Tartaruga"], x: "I polpi non hanno ossa. Solo il loro becco duro limita le aperture in cui possono infilarsi.", k: "Polpo: passa da quasi ogni buco" } } },
  { id: "c22", lvl: 3, type: "text", right: 3, t: { de: { q: "Bei welchem Vogel zeigen zwei Zehen nach vorn und zwei nach hinten?", a: ["Adler", "Flamingo", "Pinguin", "Papagei"], x: "Papageien haben Kletterfüße. Damit greifen sie Äste und halten ihr Futter wie mit einer Hand.", k: "Papageien: zwei Zehen vorn, zwei hinten" }, en: { q: "Which bird has two toes pointing forward and two pointing back?", a: ["Eagle", "Flamingo", "Penguin", "Parrot"], x: "Parrots have zygodactyl feet to grip branches and hold food as if with a hand.", k: "Parrots: two toes forward, two back" }, fr: { q: "Chez quel oiseau deux doigts pointent vers l'avant et deux vers l'arrière ?", a: ["Aigle", "Flamant rose", "Manchot", "Perroquet"], x: "Le perroquet a des pieds zygodactyles : il agrippe les branches et tient sa nourriture comme une main.", k: "Perroquets : deux doigts devant, deux derrière" }, es: { q: "¿En qué ave dos dedos apuntan hacia delante y dos hacia atrás?", a: ["Águila", "Flamenco", "Pingüino", "Loro"], x: "El loro tiene patas zigodáctilas: se agarra a las ramas y sujeta la comida como con una mano.", k: "Loros: dos dedos delante, dos detrás" }, pt: { q: "Em que ave dois dedos apontam para a frente e dois para trás?", a: ["Águia", "Flamingo", "Pinguim", "Papagaio"], x: "O papagaio tem pés zigodáctilos: agarra-se aos galhos e segura a comida como se fosse uma mão.", k: "Papagaios: dois dedos para a frente, dois para trás" }, ja: { q: "指が2本前、2本後ろを向いている鳥は？", a: ["ワシ", "フラミンゴ", "ペンギン", "オウム"], x: "オウムの足は対趾足。枝をつかんだり、手のように食べものを持ったりできます。", k: "オウム：指が前に2本、後ろに2本" }, it: { q: "Quale uccello ha due dita rivolte in avanti e due indietro?", a: ["Aquila", "Fenicottero", "Pinguino", "Pappagallo"], x: "I pappagalli hanno piedi zigodattili per afferrare i rami e tenere il cibo come con una mano.", k: "Pappagalli: due dita avanti, due indietro" } } },
  { id: "c23", lvl: 2, type: "text", right: 2, t: { de: { q: "Welcher Vogel hat schwere, massive Knochen statt luftgefüllter?", a: ["Adler", "Eule", "Pinguin", "Papagei"], x: "Flugvögel haben hohle Knochen. Pinguine brauchen schwere Knochen, damit sie beim Tauchen nicht auftreiben.", k: "Pinguine: schwere, volle Knochen" }, en: { q: "Which bird has heavy, solid bones instead of air-filled ones?", a: ["Eagle", "Owl", "Penguin", "Parrot"], x: "Flying birds have hollow bones. Penguins need heavy bones so they don't float up while diving.", k: "Penguins: heavy, solid bones" }, fr: { q: "Quel oiseau a des os lourds et pleins au lieu d'os remplis d'air ?", a: ["Aigle", "Chouette", "Manchot", "Perroquet"], x: "Les oiseaux volants ont des os creux. Le manchot a besoin d'os lourds pour ne pas remonter en plongée.", k: "Manchots : os lourds et pleins" }, es: { q: "¿Qué ave tiene huesos pesados y macizos en lugar de huecos?", a: ["Águila", "Búho", "Pingüino", "Loro"], x: "Las aves voladoras tienen huesos huecos. El pingüino necesita huesos pesados para no flotar al bucear.", k: "Pingüinos: huesos pesados y macizos" }, pt: { q: "Que ave tem ossos pesados e maciços em vez de ocos?", a: ["Águia", "Coruja", "Pinguim", "Papagaio"], x: "As aves que voam têm ossos ocos. O pinguim precisa de ossos pesados para não boiar ao mergulhar.", k: "Pinguins: ossos pesados e maciços" }, ja: { q: "空気の入った骨ではなく、重くて中身のつまった骨をもつ鳥は？", a: ["ワシ", "フクロウ", "ペンギン", "オウム"], x: "飛ぶ鳥の骨は中が空洞です。ペンギンは潜るとき浮き上がらないように、重い骨が必要なのです。", k: "ペンギン：重くて中身のつまった骨" }, it: { q: "Quale uccello ha ossa pesanti e piene invece che piene d’aria?", a: ["Aquila", "Gufo", "Pinguino", "Pappagallo"], x: "Gli uccelli che volano hanno ossa cave. I pinguini hanno bisogno di ossa pesanti per non risalire mentre si immergono.", k: "Pinguini: ossa pesanti e piene" } } },
  { id: "c24", lvl: 2, type: "text", right: 0, t: { de: { q: "Welches dieser Säugetiere hat den höchsten Blutdruck?", a: ["Giraffe", "Tiger", "Bär", "Panda"], x: "Das Giraffenherz wiegt etwa 11 kg und muss das Blut rund 2 Meter hoch bis zum Kopf pumpen.", k: "Giraffe: höchster Blutdruck" }, en: { q: "Which of these mammals has the highest blood pressure?", a: ["Giraffe", "Tiger", "Bear", "Panda"], x: "A giraffe's heart weighs about 11 kg and must pump blood some 2 metres up to its head.", k: "Giraffe: highest blood pressure" }, fr: { q: "Lequel de ces mammifères a la pression artérielle la plus élevée ?", a: ["Girafe", "Tigre", "Ours", "Panda"], x: "Le cœur de la girafe pèse environ 11 kg et doit pomper le sang à près de 2 mètres jusqu'à la tête.", k: "Girafe : tension la plus élevée" }, es: { q: "¿Cuál de estos mamíferos tiene la presión arterial más alta?", a: ["Jirafa", "Tigre", "Oso", "Panda"], x: "El corazón de la jirafa pesa unos 11 kg y debe bombear la sangre unos 2 metros hasta la cabeza.", k: "Jirafa: la presión arterial más alta" }, pt: { q: "Qual destes mamíferos tem a pressão arterial mais alta?", a: ["Girafa", "Tigre", "Urso", "Panda"], x: "O coração da girafa pesa uns 11 kg e precisa bombear o sangue uns 2 metros até a cabeça.", k: "Girafa: a pressão arterial mais alta" }, ja: { q: "この中でいちばん血圧が高い哺乳類は？", a: ["キリン", "トラ", "クマ", "パンダ"], x: "キリンの心臓は約11キロ。約2メートル上の頭まで血を送らなければなりません。", k: "キリン：いちばん高い血圧" }, it: { q: "Quale di questi mammiferi ha la pressione sanguigna più alta?", a: ["Giraffa", "Tigre", "Orso", "Panda"], x: "Il cuore della giraffa pesa circa 11 kg e deve pompare il sangue fino alla testa, circa 2 metri più in alto.", k: "Giraffa: la pressione sanguigna più alta" } } },
  { id: "c25", lvl: 3, type: "text", right: 2, t: { de: { q: "Wer hat auffällige weiße Flecken auf der Rückseite der Ohren?", a: ["Panda", "Fuchs", "Tiger", "Bär"], x: "Die weißen Ohrflecken des Tigers dienen vermutlich als Signal für die Jungen, die der Mutter folgen.", k: "Tiger: weiße Flecken hinter den Ohren" }, en: { q: "Which animal has striking white spots on the back of its ears?", a: ["Panda", "Fox", "Tiger", "Bear"], x: "A tiger's white ear spots probably act as a signal for cubs following their mother.", k: "Tiger: white spots behind the ears" }, fr: { q: "Quel animal a des taches blanches bien visibles à l'arrière des oreilles ?", a: ["Panda", "Renard", "Tigre", "Ours"], x: "Les taches blanches derrière les oreilles du tigre serviraient de repère aux petits qui suivent leur mère.", k: "Tigre : taches blanches derrière les oreilles" }, es: { q: "¿Qué animal tiene llamativas manchas blancas detrás de las orejas?", a: ["Panda", "Zorro", "Tigre", "Oso"], x: "Las manchas blancas de las orejas del tigre servirían de señal a las crías que siguen a su madre.", k: "Tigre: manchas blancas tras las orejas" }, pt: { q: "Que animal tem manchas brancas chamativas atrás das orelhas?", a: ["Panda", "Raposa", "Tigre", "Urso"], x: "As manchas brancas nas orelhas do tigre serviriam de sinal para os filhotes que seguem a mãe.", k: "Tigre: manchas brancas atrás das orelhas" }, ja: { q: "耳の後ろに目立つ白い点がある動物は？", a: ["パンダ", "キツネ", "トラ", "クマ"], x: "トラの耳の白い点は、母親についていく子どもへの目印になっていると考えられています。", k: "トラ：耳の後ろに白い点" }, it: { q: "Quale animale ha vistose macchie bianche sul retro delle orecchie?", a: ["Panda", "Volpe", "Tigre", "Orso"], x: "Le macchie bianche sulle orecchie della tigre probabilmente fanno da segnale per i cuccioli che seguono la madre.", k: "Tigre: macchie bianche dietro le orecchie" } } },
  { id: "c26", lvl: 3, type: "text", right: 3, t: { de: { q: "Wessen Neugeborenes wiegt nur etwa ein Neunhundertstel seiner Mutter?", a: ["Giraffe", "Tiger", "Otter", "Panda"], x: "Ein Pandababy wiegt bei der Geburt nur rund 100 g – etwa so viel wie eine Tafel Schokolade.", k: "Panda-Baby: wiegt nur 100 g" }, en: { q: "Whose newborn weighs only about 1/900 of its mother?", a: ["Giraffe", "Tiger", "Otter", "Panda"], x: "A newborn panda weighs only about 100 g – roughly as much as a bar of chocolate.", k: "Panda cub: weighs only 100 g" }, fr: { q: "Quel nouveau-né ne pèse qu'environ 1/900 du poids de sa mère ?", a: ["Girafe", "Tigre", "Loutre", "Panda"], x: "Un bébé panda pèse environ 100 g à la naissance, à peu près le poids d'une tablette de chocolat.", k: "Bébé panda : pèse 100 g" }, es: { q: "¿Qué cría recién nacida pesa solo 1/900 de lo que pesa su madre?", a: ["Jirafa", "Tigre", "Nutria", "Panda"], x: "Un panda recién nacido pesa unos 100 g, más o menos lo que una tableta de chocolate.", k: "Cría de panda: pesa solo 100 g" }, pt: { q: "Qual filhote recém-nascido pesa só 1/900 do peso da mãe?", a: ["Girafa", "Tigre", "Lontra", "Panda"], x: "Um panda recém-nascido pesa uns 100 g – mais ou menos o mesmo que uma barra de chocolate.", k: "Filhote de panda: pesa só 100 g" }, ja: { q: "生まれたての赤ちゃんが母親の約900分の1の重さしかないのは？", a: ["キリン", "トラ", "カワウソ", "パンダ"], x: "生まれたてのパンダはわずか約100グラム。板チョコ1枚くらいの重さです。", k: "パンダの赤ちゃん：たった100グラム" }, it: { q: "Di chi è il cucciolo appena nato che pesa solo circa 1/900 della madre?", a: ["Giraffa", "Tigre", "Lontra", "Panda"], x: "Un panda appena nato pesa solo circa 100 g, più o meno come una tavoletta di cioccolato.", k: "Cucciolo di panda: pesa solo 100 g" } } },
  { id: "c27", lvl: 2, type: "text", right: 1, t: { de: { q: "Wer ist ein Sohlengänger und setzt beim Gehen die ganze Fußsohle auf?", a: ["Fuchs", "Bär", "Tiger", "Reh"], x: "Bären laufen wie wir auf der ganzen Sohle. Fuchs und Tiger sind Zehengänger, das Reh geht auf Hufen.", k: "Bären: laufen auf ganzer Sohle" }, en: { q: "Which animal walks flat-footed, placing its whole sole on the ground?", a: ["Fox", "Bear", "Tiger", "Roe deer"], x: "Bears walk on their whole soles like us. Foxes and tigers walk on their toes, roe deer on hooves.", k: "Bears: walk on their whole soles" }, fr: { q: "Quel animal est plantigrade et pose toute la plante du pied en marchant ?", a: ["Renard", "Ours", "Tigre", "Chevreuil"], x: "L'ours marche sur toute la plante comme nous. Renard et tigre marchent sur les doigts, le chevreuil sur ses sabots.", k: "Ours : marchent sur toute la plante" }, es: { q: "¿Qué animal es plantígrado y apoya toda la planta del pie al caminar?", a: ["Zorro", "Oso", "Tigre", "Corzo"], x: "El oso camina sobre toda la planta, como nosotros. Zorro y tigre apoyan los dedos; el corzo, las pezuñas.", k: "Osos: pisan con toda la planta" }, pt: { q: "Que animal é plantígrado e apoia a planta inteira do pé ao andar?", a: ["Raposa", "Urso", "Tigre", "Corço"], x: "O urso anda sobre a planta inteira do pé, como nós. Raposa e tigre apoiam os dedos; o corço, os cascos.", k: "Ursos: pisam com a sola inteira" }, ja: { q: "足の裏全体を地面につけて歩く動物は？", a: ["キツネ", "クマ", "トラ", "ノロジカ"], x: "クマは私たちと同じように足の裏全体で歩きます。キツネやトラはつま先で、ノロジカはひづめで歩きます。", k: "クマ：足の裏全体で歩く" }, it: { q: "Quale animale cammina appoggiando a terra tutta la pianta del piede?", a: ["Volpe", "Orso", "Tigre", "Capriolo"], x: "Gli orsi camminano sull’intera pianta come noi. Volpi e tigri camminano sulle dita, i caprioli sugli zoccoli.", k: "Orsi: camminano su tutta la pianta" } } },
  { id: "c28", lvl: 1, type: "text", right: 0, t: { de: { q: "Welches Tier zählt zu den Raubtieren, frisst aber fast nur Pflanzen?", a: ["Panda", "Otter", "Tiger", "Fuchs"], x: "Der Panda gehört zu den Bären, frisst aber zu 99 % Bambus – bis zu 12 Stunden am Tag.", k: "Panda: Raubtier, das fast nur Bambus frisst" }, en: { q: "Which animal belongs to the carnivores but eats almost only plants?", a: ["Panda", "Otter", "Tiger", "Fox"], x: "The panda is a bear, yet 99% of its diet is bamboo – it eats for up to 12 hours a day.", k: "Panda: a carnivore that eats almost only bamboo" }, fr: { q: "Quel animal fait partie des carnivores mais mange presque uniquement des plantes ?", a: ["Panda", "Loutre", "Tigre", "Renard"], x: "Le panda est un ours, mais il se nourrit à 99 % de bambou, jusqu'à 12 heures par jour.", k: "Panda : carnivore qui mange presque que du bambou" }, es: { q: "¿Qué animal pertenece a los carnívoros pero come casi solo plantas?", a: ["Panda", "Nutria", "Tigre", "Zorro"], x: "El panda es un oso, pero el 99 % de su dieta es bambú: come hasta 12 horas al día.", k: "Panda: carnívoro que come casi solo bambú" }, pt: { q: "Que animal pertence aos carnívoros, mas come quase só plantas?", a: ["Panda", "Lontra", "Tigre", "Raposa"], x: "O panda é um urso, mas 99 % da dieta dele é bambu: ele come até 12 horas por dia.", k: "Panda: carnívoro que come quase só bambu" }, ja: { q: "食肉目なのに、ほとんど植物しか食べない動物は？", a: ["パンダ", "カワウソ", "トラ", "キツネ"], x: "パンダはクマの仲間ですが、食べものの99%は竹。1日に最大12時間も食べ続けます。", k: "パンダ：肉食動物なのにほぼ竹だけ" }, it: { q: "Quale animale appartiene ai carnivori ma mangia quasi solo piante?", a: ["Panda", "Lontra", "Tigre", "Volpe"], x: "Il panda è un orso, eppure il 99% della sua dieta è bambù: mangia fino a 12 ore al giorno.", k: "Panda: carnivoro che mangia quasi solo bambù" } } },
  { id: "c29", lvl: 1, type: "text", right: 0, t: { de: { q: "Welcher Vogel sieht etwa vier- bis fünfmal schärfer als ein Mensch?", a: ["Adler", "Flamingo", "Eule", "Pinguin"], x: "Adler haben viel dichter gepackte Sehzellen als wir und erkennen Beute schon aus großer Höhe.", k: "Adler: sieht 4- bis 5-mal schärfer als wir" }, en: { q: "Which bird sees about four to five times more sharply than a human?", a: ["Eagle", "Flamingo", "Owl", "Penguin"], x: "Eagles have far more densely packed visual cells than we do and spot prey from great heights.", k: "Eagle: sees 4 to 5 times sharper than us" }, fr: { q: "Quel oiseau voit environ quatre à cinq fois plus net qu'un humain ?", a: ["Aigle", "Flamant rose", "Chouette", "Manchot"], x: "L'aigle a des cellules visuelles bien plus serrées que les nôtres et repère ses proies de très haut.", k: "Aigle : voit 4 à 5 fois plus net que nous" }, es: { q: "¿Qué ave ve unas cuatro o cinco veces más nítido que un humano?", a: ["Águila", "Flamenco", "Búho", "Pingüino"], x: "El águila tiene células visuales mucho más densas que las nuestras y detecta presas desde gran altura.", k: "Águila: ve 4 a 5 veces más nítido que nosotros" }, pt: { q: "Que ave enxerga umas quatro ou cinco vezes mais nítido que um humano?", a: ["Águia", "Flamingo", "Coruja", "Pinguim"], x: "A águia tem células visuais muito mais densas que as nossas e avista presas de grandes alturas.", k: "Águia: enxerga 4 a 5 vezes melhor que nós" }, ja: { q: "人間の4〜5倍くっきり見える鳥は？", a: ["ワシ", "フラミンゴ", "フクロウ", "ペンギン"], x: "ワシの目には、視細胞が私たちよりずっと密に並んでいます。高い空から獲物を見つけられます。", k: "ワシ：人の4〜5倍くっきり見える" }, it: { q: "Quale uccello vede circa quattro o cinque volte più nitido di un essere umano?", a: ["Aquila", "Fenicottero", "Gufo", "Pinguino"], x: "Le aquile hanno cellule visive molto più fitte delle nostre e avvistano le prede da grandi altezze.", k: "Aquila: vede 4–5 volte più nitido di noi" } } },
  { id: "c30", lvl: 2, type: "text", right: 1, t: { de: { q: "Wer baut riesige Nester aus Ästen, die oft viele Jahre genutzt werden?", a: ["Eule", "Adler", "Flamingo", "Papagei"], x: "Adlerhorste werden jedes Jahr weiter ausgebaut und können über 2 m breit und sehr schwer werden.", k: "Adlerhorste: werden über 2 m breit" }, en: { q: "Which bird builds huge stick nests that are often used for many years?", a: ["Owl", "Eagle", "Flamingo", "Parrot"], x: "Eagles add to their nests (eyries) every year; they can grow over 2 m wide and very heavy.", k: "Eagle nests: over 2 m wide" }, fr: { q: "Quel oiseau construit d'énormes nids de branches souvent utilisés pendant des années ?", a: ["Chouette", "Aigle", "Flamant rose", "Perroquet"], x: "L'aigle agrandit son aire chaque année ; elle peut dépasser 2 m de large et devenir très lourde.", k: "Aires d’aigle : plus de 2 m de large" }, es: { q: "¿Qué ave construye enormes nidos de ramas que usa durante muchos años?", a: ["Búho", "Águila", "Flamenco", "Loro"], x: "El águila amplía su nido cada año; puede superar los 2 m de ancho y llegar a pesar muchísimo.", k: "Nidos de águila: más de 2 m de ancho" }, pt: { q: "Que ave constrói enormes ninhos de galhos que usa por muitos anos?", a: ["Coruja", "Águia", "Flamingo", "Papagaio"], x: "A águia aumenta o ninho todo ano; ele pode passar de 2 m de largura e chegar a pesar muitíssimo.", k: "Ninhos de águia: mais de 2 m de largura" }, ja: { q: "枝で巨大な巣を作り、何年も使い続けることが多い鳥は？", a: ["フクロウ", "ワシ", "フラミンゴ", "オウム"], x: "ワシは毎年巣を増築します。幅2メートル以上、とても重くなることもあります。", k: "ワシの巣：幅2メートル以上" }, it: { q: "Quale uccello costruisce enormi nidi di rami, spesso usati per molti anni?", a: ["Gufo", "Aquila", "Fenicottero", "Pappagallo"], x: "Le aquile ingrandiscono il nido ogni anno: può superare i 2 m di larghezza e diventare pesantissimo.", k: "Nidi d’aquila: oltre 2 m di larghezza" } } },
  { id: "c31", lvl: 1, type: "text", right: 3, t: { de: { q: "Welcher Vogel fliegt fast lautlos?", a: ["Adler", "Papagei", "Flamingo", "Eule"], x: "Kammartig gezackte Federkanten verwirbeln die Luft leise – so hört die Maus die Eule nicht kommen.", k: "Eulen: fliegen fast lautlos" }, en: { q: "Which bird flies almost silently?", a: ["Eagle", "Parrot", "Flamingo", "Owl"], x: "Comb-like edges on its feathers soften the air flow, so a mouse can't hear the owl coming.", k: "Owls: fly almost silently" }, fr: { q: "Quel oiseau vole presque sans bruit ?", a: ["Aigle", "Perroquet", "Flamant rose", "Chouette"], x: "Le bord en peigne de ses plumes adoucit le flux d'air : la souris n'entend pas arriver la chouette.", k: "Chouettes : volent presque sans bruit" }, es: { q: "¿Qué ave vuela casi en silencio?", a: ["Águila", "Loro", "Flamenco", "Búho"], x: "Los bordes en forma de peine de sus plumas suavizan el aire: el ratón no oye llegar al búho.", k: "Búhos: vuelan casi en silencio" }, pt: { q: "Que ave voa quase em silêncio?", a: ["Águia", "Papagaio", "Flamingo", "Coruja"], x: "As bordas das penas em forma de pente suavizam o ar: o rato não ouve a coruja chegar.", k: "Corujas: voam quase sem ruído" }, ja: { q: "ほとんど音を立てずに飛ぶ鳥は？", a: ["ワシ", "オウム", "フラミンゴ", "フクロウ"], x: "羽のふちがくしのようになっていて、空気の流れをやわらげます。だからネズミはフクロウが来ても気づきません。", k: "フクロウ：ほぼ無音で飛ぶ" }, it: { q: "Quale uccello vola quasi in silenzio?", a: ["Aquila", "Pappagallo", "Fenicottero", "Gufo"], x: "I bordi a pettine delle penne ammorbidiscono il flusso d’aria: così il topo non sente arrivare il gufo.", k: "Gufi: volano quasi in silenzio" } } },
  { id: "c32", lvl: 3, type: "text", right: 1, t: { de: { q: "Wer hat MEHR Halswirbel als der Mensch?", a: ["Giraffe", "Eule", "Tiger", "Otter"], x: "Eulen haben 14 Halswirbel. Giraffen haben trotz ihres langen Halses wie fast alle Säugetiere nur 7.", k: "Eulen: 14 Halswirbel, Giraffen nur 7" }, en: { q: "Which animal has MORE neck vertebrae than a human?", a: ["Giraffe", "Owl", "Tiger", "Otter"], x: "Owls have 14 neck vertebrae. Despite its long neck, a giraffe has only 7, like almost all mammals.", k: "Owls: 14 neck vertebrae, giraffes only 7" }, fr: { q: "Lequel a PLUS de vertèbres cervicales que l'humain ?", a: ["Girafe", "Chouette", "Tigre", "Loutre"], x: "La chouette en a 14. Malgré son long cou, la girafe n'en a que 7, comme presque tous les mammifères.", k: "Chouettes : 14 vertèbres cervicales, girafe 7" }, es: { q: "¿Quién tiene MÁS vértebras cervicales que el ser humano?", a: ["Jirafa", "Búho", "Tigre", "Nutria"], x: "El búho tiene 14. Pese a su largo cuello, la jirafa solo tiene 7, como casi todos los mamíferos.", k: "Búhos: 14 vértebras cervicales, la jirafa 7" }, pt: { q: "Quem tem MAIS vértebras no pescoço que o ser humano?", a: ["Girafa", "Coruja", "Tigre", "Lontra"], x: "A coruja tem 14. Apesar do pescoço comprido, a girafa tem só 7, como quase todos os mamíferos.", k: "Corujas: 14 vértebras no pescoço, girafa 7" }, ja: { q: "人間より首の骨が多い動物は？", a: ["キリン", "フクロウ", "トラ", "カワウソ"], x: "フクロウの首の骨は14個。首の長いキリンも、ほとんどの哺乳類と同じく7個しかありません。", k: "フクロウ：首の骨14個、キリンは7個" }, it: { q: "Quale animale ha PIÙ vertebre cervicali di un essere umano?", a: ["Giraffa", "Gufo", "Tigre", "Lontra"], x: "I gufi hanno 14 vertebre cervicali. La giraffa, nonostante il collo lungo, ne ha solo 7, come quasi tutti i mammiferi.", k: "Gufi: 14 vertebre cervicali, giraffa 7" } } },
  { id: "c33", lvl: 1, type: "text", right: 1, t: { de: { q: "Wer pflanzt unabsichtlich Bäume, weil er Vorräte vergräbt und vergisst?", a: ["Igel", "Eichhörnchen", "Reh", "Schnecke"], x: "Eichhörnchen vergraben im Herbst Nüsse und Samen. Vergessene Vorräte keimen und werden zu neuen Bäumen.", k: "Eichhörnchen: pflanzen aus Versehen Bäume" }, en: { q: "Which animal plants trees by accident by burying and forgetting food?", a: ["Hedgehog", "Squirrel", "Roe deer", "Snail"], x: "Squirrels bury nuts and seeds in autumn. Forgotten stores sprout and grow into new trees.", k: "Squirrels: plant trees by accident" }, fr: { q: "Quel animal plante des arbres sans le vouloir en oubliant ses réserves enterrées ?", a: ["Hérisson", "Écureuil", "Chevreuil", "Escargot"], x: "L'écureuil enterre noix et graines en automne. Les réserves oubliées germent et deviennent des arbres.", k: "Écureuils : plantent des arbres par oubli" }, es: { q: "¿Qué animal planta árboles sin querer al enterrar y olvidar sus provisiones?", a: ["Erizo", "Ardilla", "Corzo", "Caracol"], x: "La ardilla entierra nueces y semillas en otoño. Las reservas olvidadas germinan y se vuelven árboles.", k: "Ardillas: plantan árboles sin querer" }, pt: { q: "Que animal planta árvores sem querer ao enterrar e esquecer suas provisões?", a: ["Ouriço", "Esquilo", "Corço", "Caracol"], x: "O esquilo enterra nozes e sementes no outono. As reservas esquecidas germinam e viram árvores.", k: "Esquilos: plantam árvores sem querer" }, ja: { q: "食べものを埋めて忘れることで、うっかり木を植える動物は？", a: ["ハリネズミ", "リス", "ノロジカ", "カタツムリ"], x: "リスは秋に木の実や種を埋めます。忘れられたたくわえが芽を出し、新しい木に育ちます。", k: "リス：うっかり木を植える" }, it: { q: "Quale animale pianta alberi per sbaglio, seppellendo e dimenticando il cibo?", a: ["Riccio", "Scoiattolo", "Capriolo", "Chiocciola"], x: "In autunno gli scoiattoli seppelliscono noci e semi. Le provviste dimenticate germogliano e diventano nuovi alberi.", k: "Scoiattoli: piantano alberi per sbaglio" } } },
  { id: "c34", lvl: 2, type: "text", right: 0, t: { de: { q: "Wessen Schneidezähne wachsen ein Leben lang nach?", a: ["Eichhörnchen", "Igel", "Fuchs", "Otter"], x: "Eichhörnchen sind Nagetiere. Ihre Nagezähne wachsen ständig und werden beim Nagen abgeschliffen.", k: "Eichhörnchen: Zähne wachsen ein Leben lang" }, en: { q: "Whose front teeth keep growing throughout life?", a: ["Squirrel", "Hedgehog", "Fox", "Otter"], x: "Squirrels are rodents. Their incisors grow constantly and are worn down by gnawing.", k: "Squirrels: teeth grow for life" }, fr: { q: "Quel animal a des incisives qui poussent toute sa vie ?", a: ["Écureuil", "Hérisson", "Renard", "Loutre"], x: "L'écureuil est un rongeur. Ses incisives poussent sans cesse et s'usent en rongeant.", k: "Écureuils : dents qui poussent toute la vie" }, es: { q: "¿Qué animal tiene incisivos que crecen toda la vida?", a: ["Ardilla", "Erizo", "Zorro", "Nutria"], x: "La ardilla es un roedor. Sus incisivos crecen sin parar y se desgastan al roer.", k: "Ardillas: dientes que crecen toda la vida" }, pt: { q: "Que animal tem dentes da frente que crescem a vida toda?", a: ["Esquilo", "Ouriço", "Raposa", "Lontra"], x: "O esquilo é um roedor. Os dentes da frente crescem sem parar e se desgastam ao roer.", k: "Esquilos: dentes crescem a vida toda" }, ja: { q: "前歯が一生のびつづけるのは？", a: ["リス", "ハリネズミ", "キツネ", "カワウソ"], x: "リスはげっ歯類。前歯はずっとのび続け、かじることですり減ります。", k: "リス：前歯が一生のびる" }, it: { q: "Di chi sono gli incisivi che crescono per tutta la vita?", a: ["Scoiattolo", "Riccio", "Volpe", "Lontra"], x: "Gli scoiattoli sono roditori. I loro incisivi crescono sempre e si consumano rosicchiando.", k: "Scoiattoli: denti che crescono per tutta la vita" } } },
  { id: "c35", lvl: 2, type: "text", right: 3, t: { de: { q: "Wer kann kopfüber einen Baumstamm hinunterlaufen?", a: ["Otter", "Igel", "Reh", "Eichhörnchen"], x: "Eichhörnchen drehen ihre Hinterfüße nach hinten und krallen sich so beim Abstieg kopfüber fest.", k: "Eichhörnchen: klettern kopfüber hinunter" }, en: { q: "Which animal can run head-first down a tree trunk?", a: ["Otter", "Hedgehog", "Roe deer", "Squirrel"], x: "Squirrels rotate their hind feet backwards so their claws can grip while climbing down head-first.", k: "Squirrels: climb down head-first" }, fr: { q: "Quel animal peut descendre un tronc d'arbre la tête la première ?", a: ["Loutre", "Hérisson", "Chevreuil", "Écureuil"], x: "L'écureuil tourne ses pattes arrière vers l'arrière pour s'agripper en descendant la tête en bas.", k: "Écureuils : descendent tête en bas" }, es: { q: "¿Qué animal puede bajar por un tronco cabeza abajo?", a: ["Nutria", "Erizo", "Corzo", "Ardilla"], x: "La ardilla gira sus patas traseras hacia atrás para agarrarse con las uñas al bajar cabeza abajo.", k: "Ardillas: bajan cabeza abajo" }, pt: { q: "Que animal consegue descer um tronco de cabeça para baixo?", a: ["Lontra", "Ouriço", "Corço", "Esquilo"], x: "O esquilo gira as patas traseiras para trás para se agarrar com as unhas ao descer de cabeça para baixo.", k: "Esquilos: descem de cabeça para baixo" }, ja: { q: "頭を下にして木の幹をかけ下りられる動物は？", a: ["カワウソ", "ハリネズミ", "ノロジカ", "リス"], x: "リスは後ろ足を後ろ向きに回せるので、頭を下にしてもつめでしっかりつかめます。", k: "リス：頭を下にして幹をかけ下りる" }, it: { q: "Quale animale sa correre giù da un tronco a testa in giù?", a: ["Lontra", "Riccio", "Capriolo", "Scoiattolo"], x: "Gli scoiattoli ruotano le zampe posteriori all’indietro, così gli artigli fanno presa anche scendendo a testa in giù.", k: "Scoiattoli: scendono a testa in giù" } } },
  { id: "c36", lvl: 3, type: "text", right: 1, t: { de: { q: "Wer kaut manchmal fremde Stoffe zu Schaum und reibt ihn sich auf den Rücken?", a: ["Fuchs", "Igel", "Reh", "Eichhörnchen"], x: "Dieses „Selbstbespeicheln“ des Igels ist noch rätselhaft – vielleicht Schutz oder ein Duftsignal.", k: "Igel: reiben sich mit Schaum ein" }, en: { q: "Which animal sometimes chews strange substances into foam and spreads it on its back?", a: ["Fox", "Hedgehog", "Roe deer", "Squirrel"], x: "This 'self-anointing' by hedgehogs is still a mystery – maybe protection or a scent signal.", k: "Hedgehogs: anoint themselves with foam" }, fr: { q: "Quel animal mâche parfois des substances jusqu'à faire de la mousse et l'étale sur son dos ?", a: ["Renard", "Hérisson", "Chevreuil", "Écureuil"], x: "Cette « auto-onction » du hérisson reste un mystère : protection ou signal olfactif ?", k: "Hérissons : s’enduisent de mousse" }, es: { q: "¿Qué animal mastica a veces sustancias hasta hacer espuma y se la unta en el lomo?", a: ["Zorro", "Erizo", "Corzo", "Ardilla"], x: "Esta «autounción» del erizo sigue siendo un misterio: quizá protección o una señal de olor.", k: "Erizos: se untan con espuma" }, pt: { q: "Que animal às vezes mastiga substâncias até fazer espuma e a espalha nas costas?", a: ["Raposa", "Ouriço", "Corço", "Esquilo"], x: "Essa “autounção” do ouriço ainda é um mistério: talvez proteção ou um sinal de cheiro.", k: "Ouriços: se besuntam de espuma" }, ja: { q: "ときどき変なものをかんで泡にし、背中にぬりつける動物は？", a: ["キツネ", "ハリネズミ", "ノロジカ", "リス"], x: "ハリネズミのこの「アンティング」はまだなぞ。身を守るためか、においの合図かもしれません。", k: "ハリネズミ：泡を背中にぬる" }, it: { q: "Quale animale a volte mastica sostanze strane fino a farne schiuma e se la spalma sul dorso?", a: ["Volpe", "Riccio", "Capriolo", "Scoiattolo"], x: "Questa «auto-unzione» dei ricci è ancora un mistero: forse protezione, forse un segnale olfattivo.", k: "Ricci: si spalmano di schiuma" } } },
  { id: "c37", lvl: 1, type: "text", right: 1, t: { de: { q: "Wer wirft jedes Jahr sein Geweih ab und bildet ein neues?", a: ["Giraffe", "Reh", "Panda", "Tiger"], x: "Der Rehbock wirft sein Geweih im Herbst ab. Das neue aus Knochen wächst unter einer Basthaut nach.", k: "Rehbock: wirft jedes Jahr das Geweih ab" }, en: { q: "Which animal sheds its antlers every year and grows new ones?", a: ["Giraffe", "Roe deer", "Panda", "Tiger"], x: "Roe bucks shed their antlers in autumn. New bony antlers grow back under a soft skin called velvet.", k: "Roe buck: sheds its antlers every year" }, fr: { q: "Quel animal perd ses bois chaque année et en refait de nouveaux ?", a: ["Girafe", "Chevreuil", "Panda", "Tigre"], x: "Le brocard perd ses bois en automne. Les nouveaux, en os, repoussent sous une peau appelée velours.", k: "Chevreuil mâle : perd ses bois chaque année" }, es: { q: "¿Qué animal pierde su cornamenta cada año y le crece una nueva?", a: ["Jirafa", "Corzo", "Panda", "Tigre"], x: "El corzo macho pierde la cornamenta en otoño. La nueva, de hueso, crece bajo una piel llamada terciopelo.", k: "Corzo macho: muda la cornamenta cada año" }, pt: { q: "Que animal perde os chifres todo ano e ganha chifres novos?", a: ["Girafa", "Corço", "Panda", "Tigre"], x: "O corço macho perde os chifres no outono. Os novos, de osso, crescem debaixo de uma pele chamada veludo.", k: "Corço macho: troca a galhada todo ano" }, ja: { q: "毎年角を落として、新しく生やす動物は？", a: ["キリン", "ノロジカ", "パンダ", "トラ"], x: "ノロジカのオスは秋に角を落とします。新しい骨の角が、袋角と呼ばれるやわらかい皮ふの下で育ちます。", k: "ノロジカのオス：毎年角を落とす" }, it: { q: "Quale animale perde i palchi ogni anno e ne fa crescere di nuovi?", a: ["Giraffa", "Capriolo", "Panda", "Tigre"], x: "I caprioli maschi perdono i palchi in autunno. I nuovi palchi ossei ricrescono sotto una pelle morbida chiamata velluto.", k: "Capriolo maschio: perde i palchi ogni anno" } } },
  { id: "c38", lvl: 2, type: "text", right: 0, t: { de: { q: "Welches Tier „bellt“ im Wald, wenn es sich erschreckt?", a: ["Reh", "Wildschwein", "Dachs", "Eichhörnchen"], x: "Rehe stoßen bei Gefahr laute, bellende Rufe aus – das „Schrecken“. Viele Spaziergänger denken dann an einen Hund.", k: "Reh: bellt bei Schreck" }, en: { q: "Which animal “barks” in the forest when it gets startled?", a: ["Roe deer", "Wild boar", "Badger", "Squirrel"], x: "Roe deer give loud, barking calls when alarmed. Many walkers think it’s a dog.", k: "Roe deer: barks when startled" }, fr: { q: "Quel animal « aboie » en forêt quand il est surpris ?", a: ["Chevreuil", "Sanglier", "Blaireau", "Écureuil"], x: "Le chevreuil pousse des cris forts, comme des aboiements, quand il sent un danger. Beaucoup de promeneurs pensent à un chien.", k: "Chevreuil : aboie quand il a peur" }, es: { q: "¿Qué animal «ladra» en el bosque cuando se asusta?", a: ["Corzo", "Jabalí", "Tejón", "Ardilla"], x: "El corzo lanza fuertes gritos parecidos a ladridos cuando siente peligro. Muchos paseantes creen que es un perro.", k: "Corzo: ladra cuando se asusta" }, pt: { q: "Que animal “late” na floresta quando se assusta?", a: ["Corço", "Javali", "Texugo", "Esquilo"], x: "O corço solta gritos fortes parecidos com latidos quando sente perigo. Muita gente que passeia acha que é um cachorro.", k: "Corço: late quando se assusta" }, ja: { q: "森でおどろくと「ほえる」動物は？", a: ["ノロジカ", "イノシシ", "アナグマ", "リス"], x: "ノロジカはおどろくと、大きなほえるような声を出します。イヌだと思う人も多いのです。", k: "ノロジカ：おどろくとほえる" }, it: { q: "Quale animale «abbaia» nel bosco quando si spaventa?", a: ["Capriolo", "Cinghiale", "Tasso", "Scoiattolo"], x: "I caprioli, quando si allarmano, emettono forti versi simili a latrati. Molti escursionisti pensano a un cane.", k: "Capriolo: abbaia quando si spaventa" } } },
  { id: "c39", lvl: 2, type: "text", right: 2, t: { de: { q: "Wessen Panzer ist mit Wirbelsäule und Rippen verwachsen?", a: ["Krabbe", "Igel", "Schildkröte", "Schnecke"], x: "Eine Schildkröte kann ihren Panzer nie verlassen: Er besteht aus Knochen und ist fest mit dem Skelett verbunden.", k: "Schildkröte: Panzer gehört zum Skelett" }, en: { q: "Whose shell is fused to its spine and ribs?", a: ["Crab", "Hedgehog", "Turtle", "Snail"], x: "A turtle can never leave its shell: it is made of bone and firmly joined to the skeleton.", k: "Turtle: shell is part of its skeleton" }, fr: { q: "Quel animal a une carapace soudée à sa colonne vertébrale et à ses côtes ?", a: ["Crabe", "Hérisson", "Tortue", "Escargot"], x: "La tortue ne peut jamais quitter sa carapace : elle est en os et soudée au squelette.", k: "Tortue : carapace soudée au squelette" }, es: { q: "¿Qué animal tiene el caparazón unido a la columna y las costillas?", a: ["Cangrejo", "Erizo", "Tortuga", "Caracol"], x: "La tortuga nunca puede salir de su caparazón: es de hueso y está unido al esqueleto.", k: "Tortuga: caparazón unido al esqueleto" }, pt: { q: "Que animal tem a carapaça ligada à coluna e às costelas?", a: ["Caranguejo", "Ouriço", "Tartaruga", "Caracol"], x: "A tartaruga nunca pode sair da carapaça: ela é de osso e ligada ao esqueleto.", k: "Tartaruga: casco preso ao esqueleto" }, ja: { q: "甲羅が背骨やろっ骨とくっついているのは？", a: ["カニ", "ハリネズミ", "カメ", "カタツムリ"], x: "カメは甲羅からぬけ出せません。甲羅は骨でできていて、骨格としっかりつながっています。", k: "カメ：甲羅は骨格の一部" }, it: { q: "Di chi è il guscio saldato alla colonna vertebrale e alle costole?", a: ["Granchio", "Riccio", "Tartaruga", "Chiocciola"], x: "La tartaruga non può mai uscire dal guscio: è fatto di osso e saldamente unito allo scheletro.", k: "Tartaruga: guscio saldato allo scheletro" } } },
  { id: "c40", lvl: 2, type: "text", right: 1, t: { de: { q: "Wer hat keine Zähne, sondern einen scharfen Hornschnabel?", a: ["Eidechse", "Schildkröte", "Hai", "Tiger"], x: "Schildkröten haben seit Millionen Jahren keine Zähne. Ihr Hornschnabel schneidet Pflanzen und Beute.", k: "Schildkröten: Hornschnabel statt Zähne" }, en: { q: "Which animal has no teeth but a sharp horny beak?", a: ["Lizard", "Turtle", "Shark", "Tiger"], x: "Turtles have had no teeth for millions of years. Their horny beak cuts plants and prey.", k: "Turtles: horny beak instead of teeth" }, fr: { q: "Quel animal n'a pas de dents mais un bec corné tranchant ?", a: ["Lézard", "Tortue", "Requin", "Tigre"], x: "La tortue n'a plus de dents depuis des millions d'années. Son bec corné coupe plantes et proies.", k: "Tortues : bec corné au lieu de dents" }, es: { q: "¿Qué animal no tiene dientes sino un pico córneo afilado?", a: ["Lagarto", "Tortuga", "Tiburón", "Tigre"], x: "La tortuga no tiene dientes desde hace millones de años. Su pico córneo corta plantas y presas.", k: "Tortugas: pico córneo en vez de dientes" }, pt: { q: "Que animal não tem dentes, e sim um bico córneo afiado?", a: ["Lagarto", "Tartaruga", "Tubarão", "Tigre"], x: "A tartaruga não tem dentes há milhões de anos. O bico córneo corta plantas e presas.", k: "Tartarugas: bico córneo em vez de dentes" }, ja: { q: "歯がなく、するどい角質のくちばしをもつ動物は？", a: ["トカゲ", "カメ", "サメ", "トラ"], x: "カメは何百万年も前から歯がありません。角質のくちばしで植物や獲物を切ります。", k: "カメ：歯のかわりにくちばし" }, it: { q: "Quale animale non ha denti ma un becco corneo affilato?", a: ["Lucertola", "Tartaruga", "Squalo", "Tigre"], x: "Le tartarughe non hanno denti da milioni di anni. Il loro becco corneo taglia piante e prede.", k: "Tartarughe: becco corneo invece dei denti" } } },
  { id: "c41", lvl: 2, type: "text", right: 2, t: { de: { q: "Wer ist ein Weichtier und damit mit dem Kraken verwandt?", a: ["Krabbe", "Marienkäfer", "Schnecke", "Schildkröte"], x: "Schnecken, Muscheln und Kraken gehören zu den Weichtieren. Krabben sind dagegen Krebstiere.", k: "Schnecken: mit dem Kraken verwandt" }, en: { q: "Which animal is a mollusc and therefore related to the octopus?", a: ["Crab", "Ladybird", "Snail", "Turtle"], x: "Snails, clams and octopuses are all molluscs. Crabs, on the other hand, are crustaceans.", k: "Snails: related to octopuses" }, fr: { q: "Quel animal est un mollusque, donc un parent de la pieuvre ?", a: ["Crabe", "Coccinelle", "Escargot", "Tortue"], x: "Escargots, moules et pieuvres sont des mollusques. Le crabe, lui, est un crustacé.", k: "Escargots : parents des pieuvres" }, es: { q: "¿Qué animal es un molusco y, por tanto, pariente del pulpo?", a: ["Cangrejo", "Mariquita", "Caracol", "Tortuga"], x: "Caracoles, almejas y pulpos son moluscos. El cangrejo, en cambio, es un crustáceo.", k: "Caracoles: parientes del pulpo" }, pt: { q: "Que animal é um molusco e, portanto, parente do polvo?", a: ["Caranguejo", "Joaninha", "Caracol", "Tartaruga"], x: "Caracóis, mexilhões e polvos são moluscos. O caranguejo, por outro lado, é um crustáceo.", k: "Caracóis: parentes do polvo" }, ja: { q: "軟体動物で、タコの親せきなのは？", a: ["カニ", "テントウムシ", "カタツムリ", "カメ"], x: "カタツムリ、二枚貝、タコはみんな軟体動物。カニは甲殻類です。", k: "カタツムリ：タコの親せき" }, it: { q: "Quale animale è un mollusco e quindi parente del polpo?", a: ["Granchio", "Coccinella", "Chiocciola", "Tartaruga"], x: "Chiocciole, vongole e polpi sono tutti molluschi. I granchi invece sono crostacei.", k: "Chiocciole: parenti del polpo" } } },
  { id: "c42", lvl: 2, type: "text", right: 1, t: { de: { q: "Wer stellt mit Drüsen am Hinterleib Wachs her?", a: ["Schmetterling", "Biene", "Marienkäfer", "Schnecke"], x: "Arbeiterinnen schwitzen Wachsplättchen aus Drüsen am Bauch aus und bauen daraus die Waben.", k: "Bienen: schwitzen Wachs aus" }, en: { q: "Which animal makes wax with glands on its abdomen?", a: ["Butterfly", "Bee", "Ladybird", "Snail"], x: "Worker bees secrete wax flakes from glands on their abdomen and use them to build honeycomb.", k: "Bees: sweat out wax" }, fr: { q: "Quel animal fabrique de la cire grâce à des glandes sur son abdomen ?", a: ["Papillon", "Abeille", "Coccinelle", "Escargot"], x: "Les ouvrières sécrètent des écailles de cire par des glandes du ventre et bâtissent ainsi leurs rayons.", k: "Abeilles : sécrètent de la cire" }, es: { q: "¿Qué animal produce cera con glándulas en el abdomen?", a: ["Mariposa", "Abeja", "Mariquita", "Caracol"], x: "Las obreras segregan escamas de cera por glándulas del abdomen y con ellas construyen los panales.", k: "Abejas: segregan cera" }, pt: { q: "Que animal produz cera com glândulas no abdômen?", a: ["Borboleta", "Abelha", "Joaninha", "Caracol"], x: "As operárias soltam escamas de cera por glândulas do abdômen e constroem os favos com elas.", k: "Abelhas: produzem cera" }, ja: { q: "おなかの腺でロウを作る動物は？", a: ["チョウ", "ミツバチ", "テントウムシ", "カタツムリ"], x: "働きバチはおなかの腺からロウのうすい板を出し、それで巣を作ります。", k: "ミツバチ：ロウを出す" }, it: { q: "Quale animale produce cera con ghiandole sull’addome?", a: ["Farfalla", "Ape", "Coccinella", "Chiocciola"], x: "Le api operaie secernono scagliette di cera da ghiandole sull’addome e con queste costruiscono i favi.", k: "Api: producono cera" } } },
  { id: "c43", lvl: 3, type: "text", right: 3, t: { de: { q: "Wer durchläuft eine Verwandlung mit Puppenstadium?", a: ["Frosch", "Krabbe", "Eidechse", "Marienkäfer"], x: "Marienkäfer entwickeln sich über Ei, Larve und Puppe zum Käfer. Kaulquappen werden ohne Puppe zum Frosch.", k: "Marienkäfer: entwickelt sich über eine Puppe" }, en: { q: "Which animal goes through a metamorphosis with a pupal stage?", a: ["Frog", "Crab", "Lizard", "Ladybird"], x: "Ladybirds go from egg to larva to pupa to beetle. Tadpoles turn into frogs without a pupa.", k: "Ladybird: develops through a pupa" }, fr: { q: "Quel animal passe par une métamorphose avec un stade de nymphe ?", a: ["Grenouille", "Crabe", "Lézard", "Coccinelle"], x: "La coccinelle passe de l'œuf à la larve, à la nymphe puis à l'adulte. Le têtard devient grenouille sans nymphe.", k: "Coccinelle : passe par une nymphe" }, es: { q: "¿Qué animal pasa por una metamorfosis con fase de pupa?", a: ["Rana", "Cangrejo", "Lagarto", "Mariquita"], x: "La mariquita pasa de huevo a larva, pupa y adulto. El renacuajo se convierte en rana sin pupa.", k: "Mariquita: pasa por una pupa" }, pt: { q: "Que animal passa por uma metamorfose com fase de pupa?", a: ["Rã", "Caranguejo", "Lagarto", "Joaninha"], x: "A joaninha passa de ovo a larva, pupa e adulto. O girino vira rã sem pupa.", k: "Joaninha: passa por uma pupa" }, ja: { q: "さなぎの時期がある変態をする動物は？", a: ["カエル", "カニ", "トカゲ", "テントウムシ"], x: "テントウムシは卵、幼虫、さなぎ、成虫と変わります。オタマジャクシはさなぎにならずにカエルになります。", k: "テントウムシ：さなぎを経て成虫に" }, it: { q: "Quale animale passa per una metamorfosi con lo stadio di pupa?", a: ["Rana", "Granchio", "Lucertola", "Coccinella"], x: "Le coccinelle passano da uovo a larva, pupa e coleottero. I girini diventano rane senza pupa.", k: "Coccinella: passa per lo stadio di pupa" } } },
  { id: "c44", lvl: 2, type: "text", right: 2, t: { de: { q: "Wessen Flügel sind mit winzigen Schuppen bedeckt?", a: ["Biene", "Marienkäfer", "Schmetterling", "Papagei"], x: "Schmetterlinge heißen „Schuppenflügler“. Ihre Farben entstehen durch Tausende winzige Schuppen.", k: "Schmetterlinge: Flügel voller Schuppen" }, en: { q: "Whose wings are covered with tiny scales?", a: ["Bee", "Ladybird", "Butterfly", "Parrot"], x: "Butterflies belong to the Lepidoptera, the 'scale wings'. Their colours come from thousands of tiny scales.", k: "Butterflies: wings covered in scales" }, fr: { q: "Quel animal a des ailes couvertes de minuscules écailles ?", a: ["Abeille", "Coccinelle", "Papillon", "Perroquet"], x: "Les papillons sont des lépidoptères, « ailes à écailles ». Leurs couleurs viennent de milliers d'écailles.", k: "Papillons : ailes couvertes d’écailles" }, es: { q: "¿Qué animal tiene las alas cubiertas de diminutas escamas?", a: ["Abeja", "Mariquita", "Mariposa", "Loro"], x: "Las mariposas son lepidópteros, «alas con escamas». Sus colores vienen de miles de escamas diminutas.", k: "Mariposas: alas cubiertas de escamas" }, pt: { q: "Que animal tem as asas cobertas de escamas minúsculas?", a: ["Abelha", "Joaninha", "Borboleta", "Papagaio"], x: "As borboletas são lepidópteros, “asas com escamas”. As cores vêm de milhares de escamas minúsculas.", k: "Borboletas: asas cobertas de escamas" }, ja: { q: "羽が小さなうろこでおおわれているのは？", a: ["ミツバチ", "テントウムシ", "チョウ", "オウム"], x: "チョウはチョウ目（鱗翅目＝うろこの羽）。色は何千もの小さなうろこから生まれます。", k: "チョウ：羽はうろこでおおわれている" }, it: { q: "Di chi sono le ali coperte di minuscole squame?", a: ["Ape", "Coccinella", "Farfalla", "Pappagallo"], x: "Le farfalle sono lepidotteri, cioè «ali a squame». I loro colori vengono da migliaia di squamette.", k: "Farfalle: ali coperte di squame" } } },
  { id: "c45", lvl: 3, type: "text", right: 1, t: { de: { q: "Wer hat senkrechte Schlitzpupillen?", a: ["Tiger", "Fuchs", "Bär", "Otter"], x: "Füchse haben Schlitzpupillen wie Hauskatzen. Große Katzen wie der Tiger haben dagegen runde Pupillen.", k: "Fuchs: Schlitzpupillen wie eine Katze" }, en: { q: "Which animal has vertical slit pupils?", a: ["Tiger", "Fox", "Bear", "Otter"], x: "Foxes have slit pupils like house cats. Big cats such as tigers, however, have round pupils.", k: "Fox: slit pupils like a cat" }, fr: { q: "Quel animal a des pupilles verticales en fente ?", a: ["Tigre", "Renard", "Ours", "Loutre"], x: "Le renard a des pupilles en fente comme le chat. Les grands félins comme le tigre ont des pupilles rondes.", k: "Renard : pupilles fendues comme un chat" }, es: { q: "¿Qué animal tiene pupilas verticales en forma de rendija?", a: ["Tigre", "Zorro", "Oso", "Nutria"], x: "El zorro tiene pupilas de rendija como el gato. Los grandes felinos como el tigre las tienen redondas.", k: "Zorro: pupilas rasgadas como un gato" }, pt: { q: "Que animal tem pupilas verticais em fenda?", a: ["Tigre", "Raposa", "Urso", "Lontra"], x: "A raposa tem pupilas em fenda, como o gato. Os grandes felinos, como o tigre, têm pupilas redondas.", k: "Raposa: pupilas em fenda como gato" }, ja: { q: "縦長の瞳をもつ動物は？", a: ["トラ", "キツネ", "クマ", "カワウソ"], x: "キツネの瞳は飼いネコのように縦長。でもトラなどの大型のネコ科は瞳が丸いのです。", k: "キツネ：ネコのような縦長の瞳" }, it: { q: "Quale animale ha pupille verticali a fessura?", a: ["Tigre", "Volpe", "Orso", "Lontra"], x: "Le volpi hanno pupille a fessura come i gatti di casa. I grandi felini come la tigre, invece, hanno pupille rotonde.", k: "Volpe: pupille a fessura come un gatto" } } },
  { id: "c46", lvl: 1, type: "text", right: 3, t: { de: { q: "Wer gehört zur Familie der Hunde?", a: ["Otter", "Panda", "Tiger", "Fuchs"], x: "Füchse gehören wie Wolf und Haushund zu den Hunden. Otter sind Marder, Pandas Bären, Tiger Katzen.", k: "Fuchs: gehört zu den Hunden" }, en: { q: "Which animal belongs to the dog family?", a: ["Otter", "Panda", "Tiger", "Fox"], x: "Foxes are canids, like wolves and pet dogs. Otters are mustelids, pandas are bears and tigers are cats.", k: "Fox: belongs to the dog family" }, fr: { q: "Quel animal appartient à la famille des chiens ?", a: ["Loutre", "Panda", "Tigre", "Renard"], x: "Le renard est un canidé comme le loup et le chien. La loutre est un mustélidé, le panda un ours, le tigre un félin.", k: "Renard : de la famille du chien" }, es: { q: "¿Qué animal pertenece a la familia de los perros?", a: ["Nutria", "Panda", "Tigre", "Zorro"], x: "El zorro es un cánido, como el lobo y el perro. La nutria es un mustélido, el panda un oso y el tigre un félido.", k: "Zorro: de la familia del perro" }, pt: { q: "Que animal pertence à família dos cães?", a: ["Lontra", "Panda", "Tigre", "Raposa"], x: "A raposa é um canídeo, como o lobo e o cachorro. A lontra é um mustelídeo, o panda um urso e o tigre um felino.", k: "Raposa: da família dos cães" }, ja: { q: "イヌ科の動物は？", a: ["カワウソ", "パンダ", "トラ", "キツネ"], x: "キツネはオオカミや飼いイヌと同じイヌ科。カワウソはイタチ科、パンダはクマ科、トラはネコ科です。", k: "キツネ：イヌ科" }, it: { q: "Quale animale appartiene alla famiglia dei cani?", a: ["Lontra", "Panda", "Tigre", "Volpe"], x: "Le volpi sono canidi, come lupi e cani. Le lontre sono mustelidi, i panda orsi e le tigri felini.", k: "Volpe: della famiglia dei cani" } } },
  { id: "c47", lvl: 2, type: "text", right: 2, t: { de: { q: "Wer gehört zur Familie der Marder?", a: ["Fuchs", "Eichhörnchen", "Otter", "Panda"], x: "Otter sind ans Wasser angepasste Marder – verwandt mit Dachs, Iltis und Wiesel.", k: "Fischotter: gehört zu den Mardern" }, en: { q: "Which animal belongs to the weasel family?", a: ["Fox", "Squirrel", "Otter", "Panda"], x: "Otters are mustelids adapted to water – relatives of badgers, polecats and weasels.", k: "Otter: belongs to the weasel family" }, fr: { q: "Quel animal appartient à la famille des mustélidés ?", a: ["Renard", "Écureuil", "Loutre", "Panda"], x: "La loutre est un mustélidé adapté à l'eau, parente du blaireau, du putois et de la belette.", k: "Loutre : de la famille des mustélidés" }, es: { q: "¿Qué animal pertenece a la familia de los mustélidos?", a: ["Zorro", "Ardilla", "Nutria", "Panda"], x: "La nutria es un mustélido adaptado al agua, pariente del tejón, el turón y la comadreja.", k: "Nutria: de la familia de los mustélidos" }, pt: { q: "Que animal pertence à família dos mustelídeos?", a: ["Raposa", "Esquilo", "Lontra", "Panda"], x: "A lontra é um mustelídeo adaptado à água, parente do texugo, do furão e da doninha.", k: "Lontra: da família dos mustelídeos" }, ja: { q: "イタチ科の動物は？", a: ["キツネ", "リス", "カワウソ", "パンダ"], x: "カワウソは水にくらしに合わせたイタチ科の仲間。アナグマやケナガイタチ、イタチの親せきです。", k: "カワウソ：イタチ科" }, it: { q: "Quale animale appartiene ai mustelidi?", a: ["Volpe", "Scoiattolo", "Lontra", "Panda"], x: "Le lontre sono mustelidi adattati all’acqua, parenti di tassi, puzzole e donnole.", k: "Lontra: della famiglia dei mustelidi" } } },
  { id: "c48", lvl: 3, type: "text", right: 3, t: { de: { q: "Wessen Haut ist mit winzigen „Hautzähnchen“ bedeckt?", a: ["Eidechse", "Schildkröte", "Frosch", "Hai"], x: "Haihaut trägt Placoidschuppen, gebaut wie kleine Zähne. Gegen den Strich fühlt sie sich an wie Schleifpapier.", k: "Haut der Haie: winzige Hautzähne" }, en: { q: "Whose skin is covered with tiny 'skin teeth'?", a: ["Lizard", "Turtle", "Frog", "Shark"], x: "Shark skin has placoid scales built like tiny teeth. Stroked the wrong way it feels like sandpaper.", k: "Shark skin: tiny skin teeth" }, fr: { q: "Quel animal a la peau couverte de minuscules « denticules » ?", a: ["Lézard", "Tortue", "Grenouille", "Requin"], x: "La peau du requin porte des écailles placoïdes, faites comme de petites dents. À rebrousse-poil, elle râpe.", k: "Peau de requin : minuscules dents cutanées" }, es: { q: "¿Qué animal tiene la piel cubierta de diminutos «dentículos»?", a: ["Lagarto", "Tortuga", "Rana", "Tiburón"], x: "La piel del tiburón tiene escamas placoideas, como dientes diminutos. A contrapelo parece papel de lija.", k: "Piel de tiburón: diminutos dientes dérmicos" }, pt: { q: "Que animal tem a pele coberta de minúsculos “dentinhos”?", a: ["Lagarto", "Tartaruga", "Rã", "Tubarão"], x: "A pele do tubarão tem escamas placoides, como dentes minúsculos. Passando a mão ao contrário, parece lixa.", k: "Pele de tubarão: minúsculos dentículos" }, ja: { q: "皮ふが小さな「皮歯」でおおわれているのは？", a: ["トカゲ", "カメ", "カエル", "サメ"], x: "サメの皮ふには、小さな歯のような楯鱗があります。逆向きになでると紙やすりのようです。", k: "サメの皮ふ：小さな歯のようなうろこ" }, it: { q: "Di chi è la pelle coperta di minuscoli «denti cutanei»?", a: ["Lucertola", "Tartaruga", "Rana", "Squalo"], x: "La pelle dello squalo ha scaglie placoidi fatte come dentini. Accarezzata contropelo sembra carta vetrata.", k: "Pelle di squalo: minuscoli dentini cutanei" } } },
  { id: "c49", lvl: 3, type: "text", right: 3, t: { de: { q: "Wer trinkt nicht mit dem Maul, sondern nimmt Wasser über die Haut auf?", a: ["Eidechse", "Schildkröte", "Igel", "Frosch"], x: "Frösche trinken nicht: Sie nehmen Wasser über die Haut auf, vor allem über eine dünne Stelle am Bauch.", k: "Frösche: trinken über die Haut" }, en: { q: "Which animal doesn't drink with its mouth but absorbs water through its skin?", a: ["Lizard", "Turtle", "Hedgehog", "Frog"], x: "Frogs don't drink: they soak up water through their skin, especially a thin patch on the belly.", k: "Frogs: drink through their skin" }, fr: { q: "Quel animal ne boit pas par la bouche mais absorbe l'eau par la peau ?", a: ["Lézard", "Tortue", "Hérisson", "Grenouille"], x: "La grenouille ne boit pas : elle absorbe l'eau par la peau, surtout par une zone fine du ventre.", k: "Grenouilles : boivent par la peau" }, es: { q: "¿Qué animal no bebe por la boca sino que absorbe agua por la piel?", a: ["Lagarto", "Tortuga", "Erizo", "Rana"], x: "La rana no bebe: absorbe el agua por la piel, sobre todo por una zona fina del vientre.", k: "Ranas: beben por la piel" }, pt: { q: "Que animal não bebe pela boca, mas absorve água pela pele?", a: ["Lagarto", "Tartaruga", "Ouriço", "Rã"], x: "A rã não bebe: absorve a água pela pele, sobretudo por uma área fina da barriga.", k: "Rãs: bebem pela pele" }, ja: { q: "口で飲まずに、皮ふから水を吸収する動物は？", a: ["トカゲ", "カメ", "ハリネズミ", "カエル"], x: "カエルは水を飲みません。皮ふ、特におなかのうすい部分から水を吸いこみます。", k: "カエル：皮ふから水を飲む" }, it: { q: "Quale animale non beve con la bocca ma assorbe l’acqua con la pelle?", a: ["Lucertola", "Tartaruga", "Riccio", "Rana"], x: "Le rane non bevono: assorbono l’acqua con la pelle, soprattutto da una zona sottile sulla pancia.", k: "Rane: bevono con la pelle" } } },
  { id: "c50", lvl: 1, type: "text", right: 2, t: { de: { q: "Welches dieser Tiere ist ein Reptil?", a: ["Frosch", "Krake", "Schildkröte", "Otter"], x: "Schildkröten sind Reptilien mit trockener, schuppiger Haut. Frösche sind Amphibien, Kraken Weichtiere.", k: "Schildkröten: sind Reptilien" }, en: { q: "Which of these animals is a reptile?", a: ["Frog", "Octopus", "Turtle", "Otter"], x: "Turtles are reptiles with dry, scaly skin. Frogs are amphibians and octopuses are molluscs.", k: "Turtles: are reptiles" }, fr: { q: "Lequel de ces animaux est un reptile ?", a: ["Grenouille", "Pieuvre", "Tortue", "Loutre"], x: "La tortue est un reptile à peau sèche et écailleuse. La grenouille est un amphibien, la pieuvre un mollusque.", k: "Tortues : des reptiles" }, es: { q: "¿Cuál de estos animales es un reptil?", a: ["Rana", "Pulpo", "Tortuga", "Nutria"], x: "La tortuga es un reptil de piel seca y escamosa. La rana es un anfibio y el pulpo un molusco.", k: "Tortugas: son reptiles" }, pt: { q: "Qual destes animais é um réptil?", a: ["Rã", "Polvo", "Tartaruga", "Lontra"], x: "A tartaruga é um réptil de pele seca e escamosa. A rã é um anfíbio e o polvo um molusco.", k: "Tartarugas: são répteis" }, ja: { q: "この中で爬虫類はどれ？", a: ["カエル", "タコ", "カメ", "カワウソ"], x: "カメはかわいたうろこの皮ふをもつ爬虫類。カエルは両生類、タコは軟体動物です。", k: "カメ：爬虫類" }, it: { q: "Quale di questi animali è un rettile?", a: ["Rana", "Polpo", "Tartaruga", "Lontra"], x: "Le tartarughe sono rettili con la pelle secca e squamosa. Le rane sono anfibi e i polpi molluschi.", k: "Tartarughe: sono rettili" } } },
];
